#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI channel and pins
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Global variables for graceful shutdown
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                  // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel, Baud rate, Flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            // Get current timestamp
            time_t current_time;
            struct tm *time_info;
            char time_string[20];

            time(&current_time);
            time_info = localtime(&current_time);
            strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

            // Log timestamp and ADC value to console
            printf("%s - ADC Value: %d\n", time_string, adc_value);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

