#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_GAIN 64.0  // Gain setting for ADS1115
#define ADS1115_RESOLUTION 4.096 // Resolution in V
#define FIRE_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_MS 100
#define BUZZER_DURATION_MS 2000

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int init_logging();
void cleanup();
void signal_handler(int signal);
int read_flame_sensor();
float read_temperature_sensor();
void activate_buzzer();
void log_event(const char *message);

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended channel 0, 4.096V range, continuous conversion
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3; // Single-ended AIN0, +/-4.096V, Continuous conversion
    config[2] = 0x83; // 128 SPS, Disable comparator

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    return 0;
}

