void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

