int read_flame_sensor() {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        if (gpioRead(FLAME_SENSOR_GPIO) == 0) { // Assuming 0 means flame detected
            count++;
        }
        gpioDelay(DEBOUNCE_MS * 1000); // Delay in microseconds
    }
    return (count == 5) ? 1 : 0;
}

// Function to read temperature sensor
float read_temperature_sensor() {
    char data[2];
    int16_t raw_value;

    // Read two bytes from the conversion register
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1000.0; // Indicate error with a very low value
    }

    raw_value = (data[0] << 8) | data[1];

    // Convert raw value to voltage
    float voltage = (float)raw_value * ADS1115_RESOLUTION / 32768.0;

    return voltage;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    gpioDelay(BUZZER_DURATION_MS * 1000); // Delay in microseconds
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
}

// Function to log events
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize resources
    if (init_gpio() != 0 || init_i2c() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        float temperature = read_temperature_sensor();

        if (flame_detected) {
            log_event("Flame detected!");
        } else if (temperature > FIRE_THRESHOLD) {
            char temp_str[50];
            snprintf(temp_str, sizeof(temp_str), "Temperature: %.2f °C", temperature);
            log_event(temp_str);
        } else if (temperature > -999.0) {
            //Temperature below threshold
        } else {
            fprintf(stderr, "Error reading temperature sensor\n");
        }

        gpioDelay(POLL_MS * 1000); // Delay in microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

