#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <stdint.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define CURRENT_THRESHOLD 5.0 // Amperes
#define FAN_GPIO 18 // BCM numbering
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for SPI configuration
typedef struct {
    char device[20];
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int read_adc(int channel);
float calculate_current(int adc_value);
void log_data(float current);
void control_fan(float current);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(spi_config_t *config) {
    spi_fd = open(config->device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate current from ADC value (example linear conversion)
float calculate_current(int adc_value) {
    // Assuming 0-1023 corresponds to 0-10 Amperes
    return (float)adc_value * (CURRENT_THRESHOLD / 1023.0);
}

// Log data to file
void log_data(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written immediately
}

// Control cooling fan
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(FAN_GPIO, 0); // Ensure fan is OFF
    gpioTerminate();
}

int main() {
    spi_config_t spi_config = {
        .device = SPI_DEVICE,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init(&spi_config) != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Attempt to re-initialize SPI
            close(spi_fd);
            if (spi_init(&spi_config) != 0) {
                fprintf(stderr, "SPI re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                break;
            }
            continue; // Skip to the next iteration
        }

        // Calculate current
        float current = calculate_current(adc_value);

        // Log data
        log_data(current);

        // Control fan
        control_fan(current);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

