#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4  // GPIO4 (BCM)
#define MCP3008_CS_PIN 8   // GPIO8 (BCM)
#define MCP3008_SCLK_PIN 11 // GPIO11 (BCM)
#define MCP3008_MOSI_PIN 10 // GPIO10 (BCM)
#define MCP3008_MISO_PIN 9  // GPIO9 (BCM)

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define CSV file name
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_temperature_sensor();
int log_data(int flame_detected, int temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int flame_pin;
    int cs_pin;
    int clk_pin;
    int mosi_pin;
    int miso_pin;
    int spi_channel;
    int spi_speed;
    char *csv_file;
} config_t;

config_t config = {
    FLAME_SENSOR_PIN,
    MCP3008_CS_PIN,
    MCP3008_SCLK_PIN,
    MCP3008_MOSI_PIN,
    MCP3008_MISO_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    CSV_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int temperature = read_temperature_sensor();

        if (flame_detected == -1 || temperature == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        } else {
            if (log_data(flame_detected, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.cs_pin, PI_OUTPUT);
    gpioSetMode(config.clk_pin, PI_OUTPUT);
    gpioSetMode(config.mosi_pin, PI_OUTPUT);
    gpioSetMode(config.miso_pin, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen(config.csv_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Flame_Detected,Temperature\n");
    }
    rewind(fp);

    return 0;
}

int read_flame_sensor() {
    int flame_detected = gpioRead(config.flame_pin);
    if (flame_detected < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1;
    }
    return flame_detected;
}

int read_temperature_sensor() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // MCP3008 configuration for single-ended channel 0
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config.cs_pin, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.cs_pin, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Convert ADC value to temperature (example linear conversion)
    int temperature = (int)(((float)adc_value / 1023.0) * 50.0); // Assuming 0-5V range

    return temperature;
}

int log_data(int flame_detected, int temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

