#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x49
#define CO_THRESHOLD 25.0
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
float convert_to_ppm(uint16_t raw_value);
int log_data(float co_ppm);
int check_alert(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[4];
    sensor_data_t sensor_values;
    float co_ppm;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Extract CO and NO2 values
            sensor_values.ox = (sensor_data[0] << 8) | sensor_data[1];
            sensor_values.red = (sensor_data[2] << 8) | sensor_data[3];

            // Convert CO to ppm
            co_ppm = convert_to_ppm(sensor_values.ox);

            // Log data
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for alert
            if (check_alert(co_ppm) != 0) {
                fprintf(stderr, "Failed to check alert\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read data from I2C: %d\n", bytes_read);
        return 1;
    }
    return 0;
}

// Convert raw value to ppm (CO only)
float convert_to_ppm(uint16_t raw_value) {
    // Implement the conversion formula from the MICS-4514 datasheet
    // This is a placeholder; replace with the actual formula
    return (float)raw_value * 0.1; // Example conversion
}

// Log data to file
int log_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

// Check for alert condition
int check_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open alert log file\n");
        return 1;
    }

    if (co_ppm >= CO_THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO concentration exceeded threshold (%.2f ppm > %.2f ppm)\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, CO_THRESHOLD);
        fclose(fp);
    }
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

