// Define GPIO pins for I2C emulation
#define I2C_SDA_1 2
#define I2C_SCL_1 3
#define I2C_SDA_2 4
#define I2C_SCL_2 5

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x68
#define MIC2_ADDR 0x69

// Define the sampling rate (in Hz)
#define SAMPLING_RATE 100

// Define the number of samples to average
#define NUM_SAMPLES 10

// Global variables for I2C handles and program state
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_microphone(int i2c_handle);
float calculate_average_level(int *samples, int num_samples);
void log_data(float avg_level);
void signal_handler(int signal);

// Structure to hold microphone data
typedef struct {
    int sda_pin;
    int scl_pin;
    int address;
    int handle;
} microphone_t;

// Function to read a single sample from a microphone
int read_microphone(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -999; // Indicate an error
    }

    // Combine the two bytes into a 16-bit value
    int16_t sample = (buf[0] << 8) | buf[1];

    // Scale the sample to a reasonable range (adjust as needed)
    return sample;
}

// Function to calculate the average SPL from an array of samples
float calculate_average_level(int *samples, int num_samples) {
    double sum = 0.0;
    int count = 0;

    for (int i = 0; i < num_samples; i++) {
        if (samples[i] > 0) { // Exclude error values
            sum += samples[i];
            count++;
        }
    }

    if (count > 0) {
        return (float)(sum / count); // Calculate average
    } else {
        return -999.0; // Return error value if no valid samples
    }
}

// Function to log the timestamp and average SPL to a file
void log_data(float avg_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening audio_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, avg_level);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to ALT0 mode for I2C emulation
    gpioSetMode(I2C_SDA_1, PI_ALT0);
    gpioSetMode(I2C_SCL_1, PI_ALT0);
    gpioSetMode(I2C_SDA_2, PI_ALT0);
    gpioSetMode(I2C_SCL_2, PI_ALT0);

    // Open I2C handles for both microphones
    i2c_handle_1 = i2cOpen(1, MIC1_ADDR, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(1, MIC2_ADDR, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int samples1[NUM_SAMPLES];
    int samples2[NUM_SAMPLES];
    int sample_index = 0;

    // Main loop
    while (program_running) {
        // Read samples from microphone 1
        int sample1 = read_microphone(i2c_handle_1);
        samples1[sample_index] = sample1;

        // Read samples from microphone 2
        int sample2 = read_microphone(i2c_handle_2);
        samples2[sample_index] = sample2;

        // Calculate the average SPL
        float avg_level1 = calculate_average_level(samples1, NUM_SAMPLES);
        float avg_level2 = calculate_average_level(samples2, NUM_SAMPLES);

        // Log the data
        log_data(avg_level1);
        log_data(avg_level2);

        // Increment the sample index and wait for the next sample
        sample_index = (sample_index + 1) % NUM_SAMPLES;
        gpioDelay(1000000 / SAMPLING_RATE); // Delay for 100ms (10Hz sampling rate)
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

