#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MIC1_CS 8  // GPIO8 (CE0)
#define MIC2_CS 9  // GPIO9 (CE1)
#define LED_PIN 27 // GPIO27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define sampling window
#define SAMPLING_WINDOW 100 // 100 ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t samples[SAMPLING_WINDOW];
    int index;
} MicrophoneData;

MicrophoneData mic1_data = {.samples = {0}, .index = 0};
MicrophoneData mic2_data = {.samples = {0}, .index = 0};

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int16_t *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                  // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                  // Don't care

    gpioWrite(MIC1_CS, 0); // Select MIC1
    gpioWrite(MIC2_CS, 1); // Deselect MIC2

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    gpioWrite(MIC1_CS, 1); // Deselect MIC1
    gpioWrite(MIC2_CS, 0); // Select MIC2

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC1_CS, PI_OUTPUT);
    gpioSetMode(MIC2_CS, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set CS pins high initially
    gpioWrite(MIC1_CS, 1);
    gpioWrite(MIC2_CS, 1);
    gpioWrite(LED_PIN, 0);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read samples from MIC1
        int adc_value1 = read_mcp3008(0);
        if (adc_value1 < 0) {
            fprintf(stderr, "Error reading MIC1, retrying...\n");
            gpioDelay(1); // Small delay before retry
            continue;
        }
        mic1_data.samples[mic1_data.index] = (int16_t)adc_value1; // Store as signed 16-bit integer
        mic1_data.index = (mic1_data.index + 1) % SAMPLING_WINDOW;

        // Read samples from MIC2
        int adc_value2 = read_mcp3008(1);
        if (adc_value2 < 0) {
            fprintf(stderr, "Error reading MIC2, retrying...\n");
            gpioDelay(1); // Small delay before retry
            continue;
        }
        mic2_data.samples[mic2_data.index] = (int16_t)adc_value2; // Store as signed 16-bit integer
        mic2_data.index = (mic2_data.index + 1) % SAMPLING_WINDOW;

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_data.samples, SAMPLING_WINDOW);
        double mic2_rms = calculate_rms(mic2_data.samples, SAMPLING_WINDOW);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check if RMS exceeds threshold
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500);         // Keep LED on for 500 ms
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    cleanup();
    return 0;
}

