        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read samples from MIC1
        int adc_value1 = read_mcp3008(0);
        if (adc_value1 < 0) {
            fprintf(stderr, "Error reading MIC1, retrying...\n");
            gpioDelay(1); // Small delay before retry
            continue;
        }
        mic1_data.samples[mic1_data.index] = (int16_t)adc_value1; // Store as signed 16-bit integer
        mic1_data.index = (mic1_data.index + 1) % SAMPLING_WINDOW;

        // Read samples from MIC2
        int adc_value2 = read_mcp3008(1);
        if (adc_value2 < 0) {
            fprintf(stderr, "Error reading MIC2, retrying...\n");
            gpioDelay(1); // Small delay before retry
            continue;
        }
        mic2_data.samples[mic2_data.index] = (int16_t)adc_value2; // Store as signed 16-bit integer
        mic2_data.index = (mic2_data.index + 1) % SAMPLING_WINDOW;

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_data.samples, SAMPLING_WINDOW);
        double mic2_rms = calculate_rms(mic2_data.samples, SAMPLING_WINDOW);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check if RMS exceeds threshold
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500);         // Keep LED on for 500 ms
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    cleanup();
    return 0;
}

