#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amperes
#define SENSITIVITY 0.1 // V/A
#define ZERO_CURRENT_VOLTAGE 2.5 // Volts

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(int on);
void signal_handler(int signal);
void init_circular_buffer();

// Initialize circular buffer
void init_circular_buffer() {
    current_buffer.head = 0;
    current_buffer.count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        current_buffer.buffer[i] = 0.0;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended channel A0, 4.096V range, continuous conversion mode
    uint16_t config = 0x4083; // 0b0100000010000011
    uint8_t write_buffer[3];
    write_buffer[0] = CONFIG_REG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, (char *)write_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    uint8_t read_buffer[2];
    int result = i2cReadDevice(i2c_handle, (char *)read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *raw_value = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Convert raw ADC value to current in Amperes
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // 4.096V range
    float current = (voltage - ZERO_CURRENT_VOLTAGE) / SENSITIVITY;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % BUFFER_SIZE;
    if (current_buffer.count < BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate average current from circular buffer
float calculate_average() {
    if (current_buffer.count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Starting current monitoring...\n");

    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);

            float average_current = calculate_average();
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

            if (average_current > CURRENT_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_led(0); // Turn LED off
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

