#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the TCS34725 sensor
int tcs34725_init() {
    int status;

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Verify sensor ID
    status = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading ID register: %d\n", status);
        return -1;
    }
    if (status != 0x44) {
        fprintf(stderr, "Incorrect ID value: 0x%02X\n", status);
        return -1;
    }

    return 0;
}

// Read color data from the TCS34725 sensor
int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int status;

    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        return -1;
    }
    *clear = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        return -1;
    }
    *red = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        return -1;
    }
    *green = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        return -1;
    }
    *blue = (uint16_t)status;

    return 0;
}

// Log data to CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);
}

int main() {
    int status;
    uint16_t clear, red, green, blue;
    int consecutive_failures = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        status = tcs34725_read_data(&clear, &red, &green, &blue);
        if (status == 0) {
            log_data(clear, red, green, blue);
            consecutive_failures = 0; // Reset failure count
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive failures, exiting\n");
                terminate = 1;
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

