#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MOTOR_SHUTDOWN_PIN 17
#define OVER_CURRENT_THRESHOLD 10.0 // Amperes
#define ADC_MAX_VALUE 1023.0
#define VREF 3.3 // Reference voltage for MCP3008

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void over_current_handler();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (count = 0; count < 3; count++) {
        rx_buffer[count] = 0; // Initialize receive buffer
    }

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed. Retrying...\n");
        gpioDelay(1000); // Wait 1ms before retry
        return -1; // Indicate failure
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to current in Amperes
float adc_to_current(int adc_value) {
    float current = (adc_value / ADC_MAX_VALUE) * VREF / (VREF / OVER_CURRENT_THRESHOLD);
    return current;
}

// Function to log current data to a file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("current_log.csv", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return;
        }
        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Current (A)\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
}

// Function to handle over-current condition
void over_current_handler() {
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Disable motor
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,OVER CURRENT DETECTED\n", timestamp);
    fflush(log_file);

    gpioDelay(1000000); // Wait 1 second
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Re-enable motor
    fprintf(log_file, "%s,MOTOR RE-ENABLED\n", timestamp);
    fflush(log_file);
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Initially enable the motor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float current = adc_to_current(adc_value);
            log_current(current);

            if (current > OVER_CURRENT_THRESHOLD) {
                over_current_handler();
            }
        } else {
            fprintf(stderr, "Failed to read ADC value. Skipping logging.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is disabled on exit
    gpioTerminate();

    return 0;
}

