// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int channel) {
    // Configure ADS1115 for single-ended mode, 4.096V range, continuous conversion
    uint16_t config = 0x4003; // Single-ended AIN0, 4.096V, Continuous, 128 SPS
    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
