    // Wait for conversion to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    // Read conversion register
    int16_t adc_value = i2cReadWordData(i2c_handle, ADS1115_REG_CONVERT);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    return adc_value;
}

