    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure and Temperature Monitoring Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read pressure and temperature
        int adc_pressure = read_ads1115(0);
        int adc_temperature = read_ads1115(1);

        if (adc_pressure < 0 || adc_temperature < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        float pressure = convert_to_pressure(adc_pressure);
        float temperature = convert_to_temperature(adc_temperature);

        // Print pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control the LED based on pressure
        control_led(pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

