#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MOTOR_SHUTDOWN_PIN 27
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_current(int adc_value);
void log_current(float current);
void overcurrent_handler();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to calculate current from ADC value
float calculate_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a known reference voltage (VREF).
    // Example: 0-1023 ADC value corresponds to 0-10 Amperes.
    // You'll need to calibrate this based on your sensor and ADC.
    float current = (float)adc_value * (10.0 / 1023.0);
    return current;
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle overcurrent condition
void overcurrent_handler() {
    fprintf(stderr, "OVERCURRENT DETECTED!\n");
    fprintf(log_file, "OVERCURRENT DETECTED!\n");
    fflush(log_file);

    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Set GPIO HIGH to shut down motor
    fprintf(stderr, "Motor shutdown initiated!\n");

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    exit(1); // Exit with an error code
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Shutting down...\n", signal);

    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Set GPIO LOW to allow motor to start again
    fprintf(stderr, "Motor shutdown pin reset to LOW.\n");

    if (log_file != NULL) {
        fclose(log_file);
        fprintf(stderr, "Log file closed.\n");
    }

    spiClose(spi_handle);
    fprintf(stderr, "SPI closed.\n");

    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure MOTOR_SHUTDOWN_PIN as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Initially LOW

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float current = calculate_current(adc_value);
            log_current(current);

            if (current > OVERCURRENT_THRESHOLD) {
                overcurrent_handler();
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(100); // Sample every 100 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Ensure motor is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

