#include <wiringPiSPI.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define VREF (VDD)
#define VREF 3.3

// Define alarm threshold (ppm)
#define ALARM_THRESHOLD 1000.0

// Global variable for file pointer
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_methane_concentration(int adc_value);
void log_methane_concentration(float concentration);
void check_alarm(float concentration);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    // Construct SPI message
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Extract ADC value from response
    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to calculate methane concentration (ppm) from ADC value
float calculate_methane_concentration(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float concentration = (voltage - 0.2) / 0.004 * 1000.0;
    return concentration;
}

