#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V range
#define SENSITIVITY 0.0625 // kPa/LSB (example value, check datasheet)
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int16_t read_ads1115();
float convert_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initializes the ADS1115
int initialize_ads1115() {
    // Configuration register settings (example: single-shot mode, AIN0, +/-4.096V, 128 SPS)
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS

    // Write the configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads the ADC value from the ADS1115
int16_t read_ads1115() {
    // Trigger a single conversion
    uint16_t config = 0x8003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS

    // Write the configuration register to trigger conversion
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger conversion: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    buf[0] = CONVERSION_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return -1;
    }

    // Combine the bytes to form the 16-bit ADC value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Converts the ADC value to pressure in kPa
float convert_to_pressure(int16_t adc_value) {
    return (float)adc_value * REF_VOLTAGE * SENSITIVITY;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Logs the pressure reading to a file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting pressure monitoring...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_ads1115();
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Try again
        }

        // Convert to pressure
        float pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Log pressure
            log_pressure(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

