    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    buf[0] = CONVERSION_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return -1;
    }

    // Combine the bytes to form the 16-bit ADC value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Converts the ADC value to pressure in kPa
float convert_to_pressure(int16_t adc_value) {
    return (float)adc_value * REF_VOLTAGE * SENSITIVITY;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Logs the pressure reading to a file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting pressure monitoring...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_ads1115();
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Try again
        }

        // Convert to pressure
        float pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Log pressure
            log_pressure(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

