// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3208
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3208

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formula
    float humidity = 100.0 * (adc_value / 4095.0);
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet formula
    float temperature = 165.0 * (adc_value / 4095.0) - 40.0;
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

