void send_email_alert(float humidity) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Humidity exceeded threshold! Humidity: %.2f%%\" | ssmtp %s", humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to execute ssmtp command\n");
    } else {
        printf("Email alert sent.\n");
    }
}

