#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TMP36_SCALE 0.01
#define TMP36_OFFSET 0.5
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_MS 1000 // 1 Hz

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
int spi_init(int channel, int speed);
int read_adc(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);

// SPI Initialization
int spi_init(int channel, int speed) {
    if (wiringPiSPISetup(channel, speed) < 0) {
        fprintf(stderr, "SPI setup failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3208
int read_adc(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI data transfer failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 4095.0;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;

    if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -999.0; // Indicate an error
    }

    return temperature;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (logFile == NULL) {
        logFile = fopen(LOG_FILE, "a");
        if (logFile == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
        fprintf(logFile, "timestamp,temperature_celsius\n"); // Write header
    }

    fprintf(logFile, "%s,%.2f\n", timestamp, temperature);
    fflush(logFile); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    keepRunning = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_CHANNEL, SPI_SPEED) == -1) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        int adc_value = read_adc(MCP3208_CHANNEL);
        if (adc_value != -1) {
            float temperature = convert_to_celsius(adc_value);
            if (temperature != -999.0) {
                log_temperature(temperature);
                printf("Temperature: %.2f \u00b0C\n", temperature);
            }
        }
        delay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    if (logFile != NULL) {
        fclose(logFile);
    }

    printf("Exiting.\n");
    return 0;
}

