#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2
#define SAMPLE_RATE 100 // Hz
#define IMPACT_THRESHOLD 500
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_spi_device();
int read_mcp3008(int channel);
int validate_adc_reading(int reading);
int log_data(int x, int y, int z);
int detect_impact(int x, int y, int z);
void signal_handler(int signal);
void cleanup();

// Structure for holding accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI device
    if (open_spi_device() != 0) {
        fprintf(stderr, "Failed to open SPI device. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x = read_mcp3008(X_CHANNEL);
        int y = read_mcp3008(Y_CHANNEL);
        int z = read_mcp3008(Z_CHANNEL);

        // Validate ADC readings
        if (validate_adc_reading(x) != 0 || validate_adc_reading(y) != 0 || validate_adc_reading(z) != 0) {
            fprintf(stderr, "Invalid ADC reading. Skipping.\n");
            gpioDelay(10); // Small delay to prevent flooding errors
            continue;
        }

        // Log data
        if (log_data(x, y, z) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Detect impact
        if (detect_impact(x, y, z)) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file); // Ensure immediate write to file
        }

        // Delay for sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI device
int open_spi_device() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
