#include <string.h>

// Define the I2C bus and address for the Si1172 sensor
#define I2C_BUS 1
#define SI1172_ADDR 0x49

// Define register addresses for Si1172 (replace with actual values from datasheet)
#define SI1172_REG_PART_ID 0x00
#define SI1172_REG_HW_REV 0x01
#define SI1172_REG_SEQ_ID 0x02
#define SI1172_REG_INT_CFG 0x03
#define SI1172_REG_INT_EN 0x04
#define SI1172_REG_RSP0_CFG 0x07
#define SI1172_REG_RSP1_CFG 0x08
#define SI1172_REG_RSP2_CFG 0x09
#define SI1172_REG_RSP3_CFG 0x0A
#define SI1172_REG_RSP0_DATA0 0x10
#define SI1172_REG_RSP0_DATA1 0x11
#define SI1172_REG_RSP1_DATA0 0x12
#define SI1172_REG_RSP1_DATA1 0x13
#define SI1172_REG_RSP2_DATA0 0x14
#define SI1172_REG_RSP2_DATA1 0x15
#define SI1172_REG_RSP3_DATA0 0x16
#define SI1172_REG_RSP3_DATA1 0x17

// Define error codes
#define ERROR_OK 0
#define ERROR_I2C 1
#define ERROR_SENSOR_ABSENT 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ir_adc;
    uint16_t red_adc;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1172 sensor
int initialize_sensor() {
    // Check if the sensor is present by reading a register
    int part_id = i2cReadByteData(i2c_handle, SI1172_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return ERROR_SENSOR_ABSENT;
    }

    // Basic initialization sequence (replace with actual initialization sequence from datasheet)
    if (i2cWriteByteData(i2c_handle, SI1172_REG_INT_CFG, 0x01) < 0) return ERROR_I2C;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_INT_EN, 0x01) < 0) return ERROR_I2C;

    printf("Sensor initialized successfully.\n");
    return ERROR_OK;
}

// Function to read raw sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    data.error_flag = ERROR_OK;

    // Read IR and RED ADC values from the appropriate registers
    int ir_low = i2cReadByteData(i2c_handle, SI1172_REG_RSP0_DATA0);
    int ir_high = i2cReadByteData(i2c_handle, SI1172_REG_RSP0_DATA1);
    int red_low = i2cReadByteData(i2c_handle, SI1172_REG_RSP1_DATA0);
    int red_high = i2cReadByteData(i2c_handle, SI1172_REG_RSP1_DATA1);

    if (ir_low < 0 || ir_high < 0 || red_low < 0 || red_high < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        data.error_flag = ERROR_I2C;
        data.ir_adc = 0; // Set default values in case of error
        data.red_adc = 0;
        return data;
    }

    data.ir_adc = (uint16_t)((ir_high << 8) | ir_low);
    data.red_adc = (uint16_t)((red_high << 8) | red_low);

    return data;
}

// Function to log sensor data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.ir_adc, data.red_adc, data.error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    int init_result = initialize_sensor();
    if (init_result != ERROR_OK) {
        fprintf(stderr, "Sensor initialization failed with error code: %d\n", init_result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR_ADC,RED_ADC,Error_Flag\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log the data
        log_data(data);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    printf("Program finished.\n");
    return 0;
}

