#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FLOW_SENSOR_MIN 0.0
#define FLOW_SENSOR_MAX 5.0
#define FLOW_SENSOR_FULL_SCALE 1023.0 // 10-bit ADC
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    if (adc_value < 0 || adc_value > FLOW_SENSOR_FULL_SCALE) {
        fprintf(stderr, "Error: ADC value %d is out of range (0-%d)\n", adc_value, FLOW_SENSOR_FULL_SCALE);
        return -1.0;
    }

    float flow_rate = (adc_value / FLOW_SENSOR_FULL_SCALE) * FLOW_SENSOR_MAX;
    return flow_rate;
}

// Function to log flow rate with timestamp
void log_flow_rate(float flow_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (flow_rate < FLOW_SENSOR_MIN || flow_rate > FLOW_SENSOR_MAX) {
        fprintf(stderr, "Error: Flow rate %.2f L/min is out of range (%.2f-%2.0f)\n", flow_rate, FLOW_SENSOR_MIN, FLOW_SENSOR_MAX);
    }

    fprintf(log_file, "%lld,%.2f\n", timestamp_us, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flow sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);
        if (flow_rate < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to flow rate\n");
            continue; // Skip to the next iteration
        }

        // Log flow rate
        log_flow_rate(flow_rate);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

