#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define GPIO pins for SPI communication
#define SPI_CE 8       // Chip Enable (GPIO8)
#define SPI_MOSI 10      // Master Out Slave In (GPIO10)
#define SPI_MISO 9       // Master In Slave Out (GPIO9)
#define SPI_SCLK 11      // Serial Clock (GPIO11)

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Global variable for SPI handle
int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read ADC value from MCP3008
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

int main(int argc, char *argv[])
{
    // Check for correct number of command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        fprintf(stderr, "  <mic1_gain>: Gain value for microphone 1 (0.0 to 1.0, e.g., 0.5)\n");
        fprintf(stderr, "  <mic2_gain>: Gain value for microphone 2 (0.0 to 1.0, e.g., 0.5)\n");
        return 1;
    }

    // Parse command-line arguments
    float mic1_gain = atof(argv[1]);
    float mic2_gain = atof(argv[2]);

    // Validate gain values
    if (mic1_gain < 0.0 || mic1_gain > 1.0) {
        fprintf(stderr, "Error: Invalid gain value for microphone 1: %f\n", mic1_gain);
        return 1;
    }

    if (mic2_gain < 0.0 || mic2_gain > 1.0) {
        fprintf(stderr, "Error: Invalid gain value for microphone 2: %f\n", mic2_gain);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC values from microphones
        int mic1_value = read_mcp3008(MIC1_CHANNEL);
        int mic2_value = read_mcp3008(MIC2_CHANNEL);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break; // Exit loop on error
        }

        // Apply noise cancellation
        int16_t diff = (int16_t)((mic1_value * mic1_gain) - (mic2_value * mic2_gain));

        // Print the result to the terminal
        printf("%d,%d\n", mic1_value, mic2_value);

        // Delay for a short period
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

