#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FLAME_SENSOR_CHANNEL 0
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define FLAME_LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float temperature_compensation(float voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (start bit, single-ended mode, dummy byte)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed!\n");
        if (log_file != NULL) {
            fprintf(log_file, "SPI transfer failed!\n");
        }
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to perform temperature compensation
float temperature_compensation(float voltage) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    float temperature = 25.0; // Default temperature

    if (fp != NULL) {
        if (fscanf(fp, "%f", &temperature) != 1) {
            fprintf(stderr, "Error reading temperature from file!\n");
            if (log_file != NULL) {
                fprintf(log_file, "Error reading temperature from file!\n");
            }
            fclose(fp);
            return temperature; // Use default temperature
        }
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening temperature file!\n");
        if (log_file != NULL) {
            fprintf(log_file, "Error opening temperature file!\n");
        }
    }

    // Simplified compensation (linear approximation)
    return voltage; // No compensation for now
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.3f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed!\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially OFF

    // Open log file
    log_file = fopen(FLAME_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_adc = -1;
        int retries = 3;

        // Retry loop for ADC reading
        while (retries > 0) {
            raw_adc = read_mcp3008(FLAME_SENSOR_CHANNEL);
            if (raw_adc >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "ADC read failed, retrying... (%d retries left)\n", retries - 1);
                if (log_file != NULL) {
                    fprintf(log_file, "ADC read failed, retrying... (%d retries left)\n", retries - 1);
                }
                gpioDelay(100); // Wait before retrying
                retries--;
            }
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read ADC after multiple retries!\n");
            if (log_file != NULL) {
                fprintf(log_file, "Failed to read ADC after multiple retries!\n");
            }
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            continue; // Skip to the next iteration
        }

        // Data validation
        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", raw_adc);
            if (log_file != NULL) {
                fprintf(log_file, "Invalid ADC value: %d\n", raw_adc);
            }
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(raw_adc);

        // Perform temperature compensation
        float compensated_voltage = temperature_compensation(voltage);

        // Flame detection logic (example: voltage threshold)
        int flame_detected = (compensated_voltage > 2.5) ? 1 : 0; // Example threshold

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, 25.0, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    if (log_file != NULL) {
        fclose(log_file);
    }
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

