#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_adc_value;
    int max_adc_value;
    float moisture_threshold;
    int logging_interval;
    char email_address[100];
    char msmtp_config_path[100];
} Config;

// Global variables
int spi_handle;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float calculate_moisture_percentage(int adc_value, int min_adc, int max_adc);
void log_data(const char *filename, float moisture_percentage);
void send_email_alert(const char *email_address, float moisture_percentage);
void signal_handler(int signal);
int initialize_pigpio();
void cleanup_pigpio();

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_adc, int max_adc) {
    if (adc_value < min_adc) {
        return 0.0;
    } else if (adc_value > max_adc) {
        return 100.0;
    } else {
        return ((float)(adc_value - min_adc) / (float)(max_adc - min_adc)) * 100.0;
    }
}

// Function to log data to file
void log_data(const char *filename, float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *fp = fopen(filename, "a");

    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", filename);
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_percentage);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(const char *email_address, float moisture_percentage) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Plant moisture is below threshold. Current moisture: %.2f%%\" | msmtp -f %s %s", moisture_percentage, config.email_address, config.msmtp_config_path);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp command\n");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to cleanup pigpio
void cleanup_pigpio() {
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
}

int main(int argc, char *argv[]) {
    // Default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_adc_value = 300;
    config.max_adc_value = 700;
    config.moisture_threshold = 30.0;
    config.logging_interval = 60;
    strcpy(config.email_address, "");
    strcpy(config.msmtp_config_path, "");

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:x:t:i:e:c:")) != -1) {
        switch (opt) {
            case 's':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_adc_value = atoi(optarg);
                break;
            case 'x':
                config.max_adc_value = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atof(optarg);
                break;
            case 'i':
                config.logging_interval = atoi(optarg);
                break;
            case 'e':
                strncpy(config.email_address, optarg, sizeof(config.email_address) - 1);
                config.email_address[sizeof(config.email_address) - 1] = '\0';
                break;
            case 'c':
                strncpy(config.msmtp_config_path, optarg, sizeof(config.msmtp_config_path) - 1);
                config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_adc] [-x max_adc] [-t moisture_threshold] [-i logging_interval] [-e email_address] [-c msmtp_config]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d\n", config.spi_channel);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_handle, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", config.logging_interval);
            sleep(config.logging_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value, config.min_adc_value, config.max_adc_value);

