#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI channel and pins
#define SPI_CHANNEL 0
#define CE0_PIN 8 // GPIO8 (BCM)

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define pressure sensor range (Pascals)
#define PRESSURE_RANGE 100000.0

// Define ADC reference voltage (V)
#define ADC_REF_VOLTAGE 3.3

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_pressure(int adc_value);
void log_pressure(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int ce0_pin;
    float pressure_range;
    float adc_ref_voltage;
} config_t;

config_t config = {
    SPI_CHANNEL,
    CE0_PIN,
    PRESSURE_RANGE,
    ADC_REF_VOLTAGE
};

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure CE0_PIN as output (though pigpio handles it internally)
    gpioSetMode(config.ce0_pin, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, 100000, 0); // Channel, Baud rate, Flags
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Check for errors during ADC reading
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            // Convert ADC value to pressure
            float pressure = adc_to_pressure(adc_value);

            // Log pressure value
            log_pressure(pressure);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Out-of-range ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to convert ADC value to pressure
float adc_to_pressure(int adc_value) {
    // Calculate voltage from ADC value
    float voltage = ((float)adc_value / 1023.0) * config.adc_ref_voltage;

    // Check for sensor absent condition
    if (voltage == 0.0 || voltage == config.adc_ref_voltage) {
        fprintf(stderr, "Sensor absent condition: Voltage = %.2f V\n", voltage);
        return -1.0; // Indicate error
    }

    // Calculate pressure from voltage (linear relationship assumed)
    float pressure = (voltage / config.adc_ref_voltage) * config.pressure_range;

    return pressure;
}

// Function to log pressure value with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Print timestamp and pressure value
    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

