    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen(DATA_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file %s for writing\n", DATA_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Sensor0,Sensor1,Sensor2,Sensor3\n");
    }
    rewind(fp);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int adc_values[NUM_CHANNELS];
        float voltages[NUM_CHANNELS];

        // Read ADC values from all channels
        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] == -1) {
                fprintf(stderr, "Error: Failed to read ADC value from channel %d\n", i);
                continue; // Skip to the next channel
            }
            voltages[i] = convert_to_voltage(adc_values[i]);
        }

        // Log the data
        log_data(voltages[0], voltages[1], voltages[2], voltages[3]);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Closing resources...\n");
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

