#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_entry_t;

log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void print_buffer();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (single-ended mode)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    // pigpio's spiXfer requires a char array, so we need to cast the pointers
    char *tx = (char*)tx_buffer;
    char *rx = (char*)rx_buffer;

    int result = spiXfer(spi_handle, tx, rx, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump ON\n");
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump OFF\n");
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as output for the water pump
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture level from MCP3008
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Control the water pump
        control_pump(moisture_level);

        // Log the data
        log_data(moisture_level, gpioRead(PUMP_GPIO));

        // Print the log buffer
        print_buffer();

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

