#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// MAX30102 I2C address
#define MAX30102_I2C_ADDR 0x57

// Register addresses
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVERFLOW_CTR 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x05
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED_CONFIG_1 0x0C
#define REG_LED_CONFIG_2 0x0D
#define REG_TEMP_INTR 0x1F
#define REG_TEMP_FRAC 0x20
#define REG_TEMP_VALUE 0x21
#define REG_PROX_INT_THRESH 0x30
#define REG_REV_ID 0xFE
#define REG_PART_ID 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_register(int reg, uint8_t *value);
int write_register(int reg, uint8_t value);
int read_sensor_data(sensor_data_t *data);
float calculate_spo2(const sensor_data_t *data);
int calculate_heart_rate(const sensor_data_t *data);
int log_data(float spo2, int heart_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (read_register(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure sensor (example configuration)
    if (write_register(REG_MODE_CONFIG, 0x40) != 0) { // Reset
        fprintf(stderr, "Error writing to MODE_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    if (write_register(REG_MODE_CONFIG, 0x03) != 0) { // HR only mode
        fprintf(stderr, "Error writing to MODE_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (write_register(REG_SPO2_CONFIG, 0x27) != 0) { // ADC range: 4096, Sample rate: 100 Hz, LED pulse width: 400us
        fprintf(stderr, "Error writing to SPO2_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (write_register(REG_LED_CONFIG_1, 0x7F) != 0) { // LED current: ~20mA
        fprintf(stderr, "Error writing to LED_CONFIG_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (write_register(REG_LED_CONFIG_2, 0x7F) != 0) { // LED current: ~20mA
        fprintf(stderr, "Error writing to LED_CONFIG_2 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (write_register(REG_FIFO_CONFIG, 0x0F) != 0) { // FIFO almost full: 17 samples
        fprintf(stderr, "Error writing to FIFO_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Register read function
int read_register(int reg, uint8_t *value) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register value\n");
        return -1;
    }
    return 0;
}

// Register write function
int write_register(int reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register\n");
        return -1;
    }
    return 0;
}

// Sensor data reading function
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    buf[0] = REG_FIFO_DATA | 0x80; // Read FIFO data with auto-increment

    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing FIFO read command\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    data->red = (data->red << 8) | data->red;
    data->ir = (data->ir << 8) | data->ir;

    return 0;
}

// SpO2 calculation function (simplified)
float calculate_spo2(const sensor_data_t *data) {
    // This is a placeholder.  A real implementation would require
    // a more complex algorithm and calibration data.
    // This example just returns a dummy value.
    return 98.0f; // Dummy SpO2 value
}

// Heart rate calculation function (simplified)
int calculate_heart_rate(const sensor_data_t *data) {
    // This is a placeholder.  A real implementation would require
