#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_PIN 17
#define REED_SENSOR_PIN 27
#define LOG_FILE "/var/log/door_events.log"
#define DISTANCE_THRESHOLD 500 // mm
#define RELAY_DURATION_MS 3000
#define CALIBRATION_SAMPLES 10
#define SAMPLE_DELAY_MS 50
#define RUNNING_AVG_WINDOW_MS 200

// Global variables
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *value);
int16_t read_adc(int fd);
float adc_to_distance(int16_t adc_value);
int calibrate_sensor(int fd);
int control_relay(int gpio_pin, int state);
int read_reed_sensor(int gpio_pin);
int log_event(const char *message);
void signal_handler(int sig);

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc(int fd) {
    uint8_t buf[2];
    int16_t adc_value;

    if (i2c_read(fd, ADS1115_REG_CONVERT, &buf[0]) < 0) {
        return -1;
    }
    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Convert ADC value to distance (mm) - Example calibration curve
float adc_to_distance(int16_t adc_value) {
    // This is a placeholder.  You'll need to calibrate the sensor
    // and determine the appropriate formula.
    // Example:  distance = 1000.0 / (adc_value + 10.0);
    return 1000.0 / (adc_value + 10.0); // Example inverse relationship
}

// Calibrate the sensor by taking multiple readings and averaging
int calibrate_sensor(int fd) {
    int16_t adc_values[CALIBRATION_SAMPLES];
    float sum = 0.0;
    int i;

    printf("Calibrating sensor...\n");
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        adc_values[i] = read_adc(fd);
        if (adc_values[i] < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += adc_values[i];
        usleep(SAMPLE_DELAY_MS * 1000); // Delay between samples
    }

    float average_adc = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Average ADC value: %d\n", average_adc);
    return 0;
}

// Control the relay (active-high)
int control_relay(int gpio_pin, int state) {
    if (gpio_pin != GPIO_PIN) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (write(gpio_pin, &state, 1) != 1) {
        perror("GPIO write failed");
        return -1;
    }
    return 0;
}

// Read the reed sensor
int read_reed_sensor(int gpio_pin) {
    if (gpio_pin != REED_SENSOR_PIN) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    uint8_t buf[1];
    if (read(gpio_pin, buf, 1) != 1) {
        perror("GPIO read failed");
        return -1;
    }

    return (buf[0] == 0) ? 0 : 1; // 0 if open, 1 if closed
}

// Log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp); // Ensure immediate write
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Shutting down...\n", sig);
    terminate = 1;
}

int main() {
    int16_t baseline_adc_values[CALIBRATION_SAMPLES];
    int i;
    float sum = 0.0;
    float running_avg = 0.0;
    int reed_state;
    char log_message[256];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    // Calibrate the sensor
    if (calibrate_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        close(i2c_fd);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            log_event("Error reading ADC value");
            usleep(100000); // Wait before retrying
            continue;
        }

        // Update running average
        sum -= baseline_adc_values[i % CALIBRATION_SAMPLES];
        sum += adc_value;
        baseline_adc_values[i % CALIBRATION_SAMPLES] = adc_value;
        running_avg = sum / CALIBRATION_SAMPLES;

        // Check if distance is below threshold
        if (adc_to_distance(adc_value) < DISTANCE_THRESHOLD) {
            printf("Distance below threshold. Activating relay.\n");
            log_event("Distance below threshold. Activating relay.");

            // Activate relay
            if (control_relay(GPIO_PIN, 1) < 0) {
                fprintf(stderr, "Error activating relay\n");
                log_event("Error activating relay");
            }

            // Read reed sensor
            reed_state = read_reed_sensor(REED_SENSOR_PIN);
            if (reed_state < 0) {
                fprintf(stderr, "Error reading reed sensor\n");
                log_event("Error reading reed sensor");
            } else {
                snprintf(log_message, sizeof(log_message), "Door opened (ADC: %d, Reed: %d)", adc_value, reed_state);
                log_event(log_message);
            }

            // Deactivate relay after specified duration
            usleep(RELAY_DURATION_MS * 1000);
            if (control_relay(GPIO_PIN, 0) < 0) {
                fprintf(stderr, "Error deactivating relay\n");
                log_event("Error deactivating relay");
            }

            snprintf(log_message, sizeof(log_message), "Door locked (ADC: %d, Reed: %d)", adc_value, reed_state);
            log_event(log_message);

        } else {
            printf("Distance above threshold. Relay not activated.\n");
            log_event("Distance above threshold. Relay not activated.");
        }

        usleep(RUNNING_AVG_WINDOW_MS * 1000); // Delay between readings
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return EXIT_SUCCESS;
}

