#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for chip select
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int read_mcp3008(int cs_pin);
int write_cs(int cs_pin, int value);
int read_cs(int cs_pin);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} sensor_data_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int cs_pin) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | ((cs_pin == CS0) ? 0 : ((cs_pin == CS1) ? 1 : 2)); // Single-ended mode, channel 0
    tx_buf[2] = 0x00; // Don't care

    // Assert chip select
    if (write_cs(cs_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to assert chip select for pin %d\n", cs_pin);
        return -1;
    }

    // Transfer data
    if (spiXfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for pin %d\n", cs_pin);
        // De-assert chip select on error
        if (write_cs(cs_pin, 1) != 0) {
            fprintf(stderr, "Error: Failed to de-assert chip select for pin %d\n", cs_pin);
        }
        return -1;
    }

    // De-assert chip select
    if (write_cs(cs_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to de-assert chip select for pin %d\n", cs_pin);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to write to chip select pin
int write_cs(int cs_pin, int value) {
    gpioWrite(cs_pin, value);
    return 0;
}

// Function to read chip select pin
int read_cs(int cs_pin) {
    return gpioRead(cs_pin);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }

    // Release GPIO pins
    gpioSetMode(CS0, PI_INPUT); // Set to input to release
    gpioSetMode(CS1, PI_INPUT);
    gpioSetMode(CS2, PI_INPUT);

    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set chip select pins as output
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Initialize chip select pins to high (inactive)
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    // Open SPI device
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1 MHz, Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read sensor values
        int sensor1_value = read_mcp3008(CS0);
        int sensor2_value = read_mcp3008(CS1);
        int sensor3_value = read_mcp3008(CS2);

        // Create CSV file and write header if it's a new file
        FILE *fp = fopen("soil_moisture_log.csv", "a+");
        if (fp == NULL) {
            fprintf(stderr, "Error: Failed to open file\n");
            signal_handler(SIGTERM); // Simulate termination to cleanup
            return 1;
        }

        // Check if the file is newly created
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        if (file_size == 0) {
            fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
        }

        // Write sensor values to CSV file
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);

        // Close file
        fclose(fp);

        // Print sensor values to console
        printf("%s - Sensor 1: %d, Sensor 2: %d, Sensor 3: %d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

