#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (count = 0; count < 3; count++) {
        rx_buffer[count] = 0;
    }

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("SPI communication error. Retrying...");
        gpioDelay(10000); // 10ms delay
        return read_mcp3008(channel); // Retry
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_event(state ? "Pump ON" : "Pump OFF");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Error: Threshold must be between 0 and 100.\n");
                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration < 1 || pump_duration > 3600) {
                    fprintf(stderr, "Error: Pump duration must be between 1 and 3600 seconds.\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval < 1 || sleep_interval > 3600) {
                    fprintf(stderr, "Error: Sleep interval must be between 1 and 3600 seconds.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (running) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        float moisture_percentage = calculate_moisture(adc_value);
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture: %.2f%%, ADC Value: %d", moisture_percentage, adc_value);
        log_event(log_message);

        // Check if moisture is below threshold
        if (moisture_percentage < threshold) {
            log_event("Moisture below threshold, activating pump");
            control_pump(1); // Turn on the pump
            gpioDelay(pump_duration * 1000000); // Wait for pump duration (in microseconds)
            control_pump(0); // Turn off the pump
            log_event("Pump deactivated");
        }

        // Wait before next check
        gpioDelay(sleep_interval * 1000000); // Sleep interval in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    log_event("System exiting");
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

