#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_CHANNEL 0x40

int i2c_fd = -1;

void signal_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Dummy read
        uint8_t dummy_data;
        if (read(i2c_fd, &dummy_data, 1) != 1) {
            perror("read (dummy)");
            close(i2c_fd);
            return 1;
        }

        // Read AIN0
        uint8_t adc_value;
        if (write(i2c_fd, &AIN0_CHANNEL, 1) != 1) {
            perror("write");
            close(i2c_fd);
            return 1;
        }

        if (read(i2c_fd, &adc_value, 1) != 1) {
            perror("read");
            close(i2c_fd);
            return 1;
        }

        printf("%d\n", adc_value);
        usleep(100000); // 100ms
    }

    close(i2c_fd);
    return 0;
}

