#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_PIN 27
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CIRCULAR_BUFFER_SIZE 100
#define THRESHOLD_GAUSS 500.0
#define SENSOR_SENSITIVITY 0.0025 // 2.5 mV/Gauss
#define VREF 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_adc();
float convert_to_voltage(int adc_value);
float calculate_magnetic_field(float voltage);
void update_circular_buffer(CircularBuffer *cb, float value);
float calculate_rolling_average(CircularBuffer *cb);
void check_threshold(float average_field);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

int main() {
    // Initialize syslog
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure it starts LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialisation failed");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer magnetic_field_buffer;
    circular_buffer_init(&magnetic_field_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc();
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Convert to voltage
        float voltage = convert_to_voltage(adc_value);

        // Calculate magnetic field strength
        float magnetic_field = calculate_magnetic_field(voltage);

        // Update circular buffer
        update_circular_buffer(&magnetic_field_buffer, magnetic_field);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average(&magnetic_field_buffer);

        // Check threshold
        check_threshold(rolling_average);

        // Wait for the next sample
        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_handle = open(filename, O_RDWR);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_handle, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion, 128 SPS
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x44; // Single-ended AIN0, 4.096V, continuous conversion
    config[2] = 0x83; // 128 SPS, disable comparator

    if (write(i2c_handle, config, 3) != 3) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        close(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value
int read_adc() {
    uint8_t reg = CONVERSION_REG;
    if (write(i2c_handle, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    uint8_t buffer[2];
    if (read(i2c_handle, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    int16_t adc_value = (buffer[0] << 8) | buffer[1];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    float voltage = (float)adc_value * VREF / 32768.0;
    return voltage;
}

// Calculate magnetic field strength from voltage
float calculate_magnetic_field(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        syslog(LOG_ERR, "Voltage out of range: %f", voltage);
        return 0.0; // Return 0.0 on error
    }
    float magnetic_field = (voltage - 0.5 * VREF) / SENSOR_SENSITIVITY;
    return magnetic_field;
}

// Update circular buffer
void update_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate rolling average
float calculate_rolling_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Check if threshold is exceeded
void check_threshold(float average_field) {
    if (average_field > THRESHOLD_GAUSS) {
        syslog(LOG_WARNING, "Threshold exceeded: %f Gauss", average_field);
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    }
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is LOW
    gpioTerminate();
}

