#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int validate_adc_value(int adc_value);
void control_pump(int state);
void log_event(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to validate ADC value
int validate_adc_value(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    printf("Pump set to %d\n", state);
}

// Function to log watering events
void log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Moisture: %d\n", s, adc_value);
    fclose(fp);
    printf("Event logged: %s, Moisture: %d\n", s, adc_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO18 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and irrigation system started.\n");

    while (1) {
        // Read soil moisture sensor value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        adc_value = validate_adc_value(adc_value);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Invalid ADC value, skipping irrigation\n");
            continue;
        }

        printf("Moisture level: %d\n", adc_value);

        // Check if moisture level is below threshold
        if (adc_value < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold, activating pump.\n");
            control_pump(1); // Turn on the pump
            log_event(adc_value);
            gpioDelay(PUMP_DURATION * 1000000); // Wait for pump duration (in microseconds)
            control_pump(0); // Turn off the pump
            printf("Pump deactivated.\n");
        }

        gpioDelay(60000000); // Wait 60 seconds (in microseconds)
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

