#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_pwm_dutycycle(int dutycycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to set PWM duty cycle
void set_pwm_dutycycle(int dutycycle) {
    if (dutycycle < 0 || dutycycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle value %d\n", dutycycle);
        return;
    }

    gpioPWM(PWM_GPIO, dutycycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure PWM GPIO
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Potentiometer controlled motor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Set PWM duty cycle (map ADC value to duty cycle range)
        int dutycycle = (int)(((float)adc_value / 1023.0) * PWM_RANGE);
        set_pwm_dutycycle(dutycycle);

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, dutycycle);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up and exit
    printf("Stopping motor and cleaning up...\n");
    set_pwm_dutycycle(0); // Stop the motor
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

