#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc();
double convert_to_gauss(int adc_value);
void control_led(int on);
void signal_handler(int signal);
void usage(char *program_name);

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int read_adc() {
    char buf[2];
    int16_t adc_value;

    // Set the ADS1115 to single-shot mode, AIN0, +/-4.096V, 128 SPS
    ads1115_config_t config = {0x8383}; // Single-shot, AIN0, +/-4.096V, 128 SPS
    uint8_t write_buf[3];
    write_buf[0] = ADS1115_REG_CONFIG;
    write_buf[1] = (config.config >> 8) & 0xFF;
    write_buf[2] = config.config & 0xFF;

    if (i2cWriteDevice(i2c_handle, write_buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Function to convert ADC value to Gauss
double convert_to_gauss(int adc_value) {
    // Assuming a linear relationship between ADC value and magnetic field strength
    // and a sensitivity of 0.0025 V/Gauss (typical for SS49E)
    // and a supply voltage of 3.3V
    double sensitivity = 0.0025;
    double supply_voltage = 3.3;
    double gauss = (adc_value * sensitivity * supply_voltage) / 32768.0;
    return gauss;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(GPIO_LED, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Usage function
void usage(char *program_name) {
    fprintf(stderr, "Usage: %s [-t threshold]\n", program_name);
    fprintf(stderr, "  -t threshold   Gauss threshold for magnetic field detection (default: 100.0)\n");
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                usage(argv[0]);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            double gauss = convert_to_gauss(adc_value);
            printf("Magnetic Field Strength: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                control_led(1); // Turn LED on
                gpioDelay(50000); // 50ms
                control_led(0); // Turn LED off
                gpioDelay(50000); // 50ms
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(100000); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

