#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_ON 30
#define MOISTURE_THRESHOLD_OFF 35
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
        return -1.0;
    }

    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump based on moisture
void control_pump(float moisture) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture < MOISTURE_THRESHOLD_ON && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        syslog(LOG_INFO, "Pump turned ON (Moisture: %.2f%%)", moisture);
    } else if (moisture > MOISTURE_THRESHOLD_OFF && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        syslog(LOG_INFO, "Pump turned OFF (Moisture: %.2f%%)", moisture);
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "pump_on") == 0) {
            gpioWrite(PUMP_GPIO, 1);
            syslog(LOG_INFO, "Pump turned ON via MQTT command");
        } else if (strcmp(payload, "pump_off") == 0) {
            gpioWrite(PUMP_GPIO, 0);
            syslog(LOG_INFO, "Pump turned OFF via MQTT command");
        } else {
            syslog(LOG_WARNING, "Unknown MQTT command: %s", payload);
        }
    }
}

// MQTT connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        // Subscribe to the pump control topic
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", MQTT_TOPIC_PUMP_CONTROL);
        } else {
            syslog(LOG_INFO, "Connected to MQTT broker and subscribed to topic: %s", MQTT_TOPIC_PUMP_CONTROL);
        }
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "MQTT disconnected unexpectedly with code: %d", rc);
    } else {
        syslog(LOG_INFO, "MQTT disconnected cleanly.");
    }
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int connect_result = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
        } else {
            float moisture = calculate_moisture(adc_value);
            if (moisture < 0) {
                syslog(LOG_ERR, "Failed to calculate moisture percentage");
            } else {
                syslog(LOG_INFO, "Soil moisture: %.2f%%", moisture);

                // Control the pump
                control_pump(moisture);

                // Publish moisture value to MQTT
                char payload[20];
                snprintf(payload, sizeof(payload), "%.2f", moisture);
                int publish_result = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
                if (publish_result != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(publish_result));
                } else {
                    syslog(LOG_INFO, "Published moisture value to MQTT topic: %s", MQTT_TOPIC_SOIL_MOISTURE);
                }
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

