#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MOTOR_1_GPIO 17
#define MOTOR_2_GPIO 27
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_motor(int gpio, int noise_level);
void log_vibration(void);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control vibration motor
void control_motor(int gpio, int noise_level) {
    if (noise_level > NOISE_THRESHOLD) {
        gpioPWM(gpio, 255); // Full speed
    } else {
        gpioPWM(gpio, 0);   // Off
    }
}

// Function to log vibration event
void log_vibration(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Vibration detected\n", timestamp);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR_1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_2_GPIO, PI_OUTPUT);

    // Initialize PWM for motors
    gpioSetPWMfrequency(MOTOR_1_GPIO, 100); // 100 Hz
    gpioSetPWMfrequency(MOTOR_2_GPIO, 100); // 100 Hz
    gpioSetPWMrange(MOTOR_1_GPIO, 255);
    gpioSetPWMrange(MOTOR_2_GPIO, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int noise_level = read_mcp3008(0); // Read from channel 0
        if (noise_level >= 0) {
            control_motor(MOTOR_1_GPIO, noise_level);
            control_motor(MOTOR_2_GPIO, noise_level);

            if (noise_level > NOISE_THRESHOLD) {
                log_vibration();
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    gpioWrite(MOTOR_1_GPIO, 0); // Turn off motor 1
    gpioWrite(MOTOR_2_GPIO, 0); // Turn off motor 2
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

