#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define SOUND_THRESHOLD 500
#define LOG_FILE "tamper_log.csv"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_bh1750();
void log_data(int sound_level, float light_level, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -2;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to read from BH1750 sensor
float read_bh1750() {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char data[2];

    // Send configuration command
    int result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed with code %d\n", result);
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed with code %d\n", result);
        return -1.0;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float light_level = (float)raw_value / 1.2;
    return light_level;
}

// Function to log data to CSV file
void log_data(int sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed with code %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sound Level,Light Level,Error Code\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int sound_level = read_mcp3008(0);
        float light_level = read_bh1750();
        int error_code = 0;

        if (sound_level == -1) {
            error_code = 1; // ADC read error
            fprintf(stderr, "Error: Failed to read sound level\n");
        }
        if (light_level == -1.0) {
            error_code |= 2; // I2C read error
            fprintf(stderr, "Error: Failed to read light level\n");
        }

        // Log data
        log_data(sound_level, light_level, error_code);

        // Check for tamper event
        if (sound_level > SOUND_THRESHOLD && error_code == 0) {
            printf("Tamper event detected!\n");
            log_data(sound_level, light_level, 4); // Tamper event
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

