#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define NUM_SENSORS 3

// Global variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void control_pump(int state);
void log_data(int sensor_id, float moisture_level);
void signal_handler(int signal);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int retries = 3;
    int delay_ms = 10;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    while (retries > 0) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
            perror("SPI transaction failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        } else {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        }
    }

    fprintf(stderr, "SPI transaction failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Control the water pump
void control_pump(int state) {
    digitalWrite(PUMP_GPIO, state);
    printf("Pump set to %s\n", state ? "ON" : "OFF");
}

// Log data to console
void log_data(int sensor_id, float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: Moisture Level = %.2f%%\n", timestamp, sensor_id, moisture_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
    control_pump(0); // Turn off pump
    close(spi_fd);
    exit(0);
}

int main(void) {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Set pump GPIO as output
    pinMode(PUMP_GPIO, OUTPUT);

    // Initialize SPI
    if (spi_init() == -1) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value != -1) {
                float moisture_level = convert_to_moisture(adc_value);
                log_data(i, moisture_level);

                if (moisture_level < MOISTURE_THRESHOLD) {
                    control_pump(1); // Turn on pump
                } else {
                    control_pump(0); // Turn off pump
                }
            } else {
                fprintf(stderr, "Failed to read sensor %d.\n", i);
            }
        }

        sleep(60);
    }

    return 0;
}

