#define VALVE_GPIO 17
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100      // 0-100%
#define NUM_SAMPLES 3
#define LOG_INTERVAL 5     // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_samples(int *samples, int num_samples);
int set_valve_position(float average);
void log_data(int *samples, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to average samples
float average_samples(int *samples, int num_samples) {
    if (num_samples <= 0) {
        fprintf(stderr, "Error: Number of samples must be positive\n");
        return -1.0;
    }

    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }

    return (float)sum / num_samples;
}

// Function to set valve position using PWM
int set_valve_position(float average) {
    // Map average ADC value (0-1023) to PWM duty cycle (0-100)
    int duty_cycle = (int)(average * (PWM_RANGE / 1023.0));

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    gpioPWM(VALVE_GPIO, duty_cycle);
    return duty_cycle;
}

// Function to log data to file
void log_data(int *samples, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < NUM_SAMPLES; i++) {
        fprintf(log_file, "%d, ", samples[i]);
    }
    fprintf(log_file, "%.2f, %d\n", average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

