    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output and configure PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int samples[NUM_SAMPLES];
    int valve_position;

    // Main loop
    while (!terminate) {
        // Read samples from MCP3008
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int read_value = read_mcp3008(i);
            if (read_value == -1) {
                fprintf(stderr, "Error: Failed to read sample %d\n", i);
                samples[i] = -1; // Mark as invalid
            } else {
                samples[i] = read_value;
            }
        }

        // Calculate average
        float average = average_samples(samples, NUM_SAMPLES);
        if (average < 0) {
            fprintf(stderr, "Error: Invalid average value\n");
            continue; // Skip to the next iteration
        }

        // Set valve position
        valve_position = set_valve_position(average);

        // Log data
        log_data(samples, average, valve_position);

        // Wait for the next logging interval
        sleep(LOG_INTERVAL);
    }

    // Graceful shutdown
    gpioPWM(VALVE_GPIO, 0); // Set valve to 0%
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

