#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define TRIG_PIN 23  // GPIO23 (BCM)
#define ECHO_PIN 24  // GPIO24 (BCM)
#define SPI_CHANNEL 0 // SPI0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_PIN 18 // GPIO18 (BCM)

// Define constants
#define SOUND_SPEED 34300.0 // cm/s
#define MIN_DISTANCE 2.0   // cm
#define MAX_DISTANCE 200.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define MIN_VOLUME 50       // 0-100
#define MAX_VOLUME 1000      // 0-1000

// Global variables
volatile sig_atomic_t program_running = 1;
float last_distance = 100.0; // Default distance
int last_volume = 500;      // Default volume

// Function prototypes
void signal_handler(int signal);
float read_distance();
int read_volume();
float map_distance_to_frequency(float distance);
int map_volume_to_pwm(int volume);
void write_config(float min_distance, float max_distance, int min_volume, int max_volume);
void read_config(float *min_distance, float *max_distance, int *min_volume, int *max_volume);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
        pwmWrite(PWM_PIN, 0); // Stop PWM
        exit(0);
    }
}

// Function to read distance from HC-SR04 sensor
float read_distance() {
    digitalWrite(TRIG_PIN, LOW);
    delayMicroseconds(2);
    digitalWrite(TRIG_PIN, HIGH);
    delayMicroseconds(10);
    digitalWrite(TRIG_PIN, LOW);

    long startTime = micros();
    while (digitalRead(ECHO_PIN) == LOW) {
        if (micros() - startTime > 50000) {
            fprintf(stderr, "Timeout waiting for ECHO HIGH\n");
            return last_distance; // Return last valid distance
        }
    }

    long pulseStart = micros();
    while (digitalRead(ECHO_PIN) == HIGH) {
        if (micros() - pulseStart > 50000) {
            fprintf(stderr, "Timeout waiting for ECHO LOW\n");
            return last_distance; // Return last valid distance
        }
    }
    long pulseEnd = micros();

    long pulseDuration = pulseEnd - pulseStart;
    float distance = (pulseDuration * SOUND_SPEED) / 2000000.0; // in cm

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %f\n", distance);
        return last_distance; // Return last valid distance
    }

    last_distance = distance;
    return distance;
}

// Function to read volume from photoresistor using MCP3008 ADC
int read_volume() {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return last_volume; // Return last valid volume
    }

    last_volume = adc_value;
    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance <= MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance >= MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to map volume to PWM duty cycle
int map_volume_to_pwm(int volume) {
    if (volume < MIN_VOLUME) {
        return 0;
    } else if (volume > MAX_VOLUME) {
        return 1000;
    } else {
        return (int)((volume - MIN_VOLUME) * 1000.0 / (MAX_VOLUME - MIN_VOLUME));
    }
}

// Function to write configuration parameters to file
void write_config(float min_distance, float max_distance, int min_volume, int max_volume) {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%f,%f,%d,%d\n", min_distance, max_distance, min_volume, max_volume);
    fclose(fp);
    printf("Configuration saved to theremin_config.txt\n");
}

// Function to read configuration parameters from file
void read_config(float *min_distance, float *max_distance, int *min_volume, int *max_volume) {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for reading: %s\n", strerror(errno));
        // Initialize with default values if file doesn't exist
        *min_distance = MIN_DISTANCE;
        *max_distance = MAX_DISTANCE;
        *min_volume = MIN_VOLUME;
        *max_volume = MAX_VOLUME;
        return;
    }

    if (fscanf(fp, "%f,%f,%d,%d", min_distance, max_distance, min_volume, max_volume) != 4) {
        fprintf(stderr, "Error reading config file, using default values.\n");
        *min_distance = MIN_DISTANCE;
        *max_distance = MAX_DISTANCE;
        *min_volume = MIN_VOLUME;
        *max_volume = MAX_VOLUME;
    }

    fclose(fp);
    printf("Configuration loaded from theremin_config.txt\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    pinMode(TRIG_PIN, OUTPUT);
    pinMode(ECHO_PIN, INPUT);

    // Set PWM mode and range
    pinMode(PWM_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(1000);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Read configuration parameters
    float min_distance, max_distance;
    int min_volume, max_volume;
    read_config(&min_distance, &max_distance, &min_volume, &max_volume);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor data
        float distance = read_distance();
        int volume = read_volume();

        // Map data to frequency and volume
        float frequency = map_distance_to_frequency(distance);
        int pwm_value = map_volume_to_pwm(volume);

        // Set PWM output
        pwmWrite(PWM_PIN, pwm_value);

        // Print debug information
        printf("Distance: %f cm, Volume: %d, Frequency: %f Hz, PWM: %d\n", distance, volume, frequency, pwm_value);

        delay(50); // Delay for stability
    }

    // Clean up
    pwmWrite(PWM_PIN, 0); // Stop PWM

    return 0;
}

