#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (count = 0; count < MAX_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication error (attempt %d). Retrying...\n", count + 1);
            gpioDelay(1000); // 1-second delay
        }
    }

    fprintf(stderr, "SPI communication failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    spiClose(spi_handle);
    gpioDelay(1000); // Wait before re-initializing
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Re-open SPI
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
        return -1; // Indicate failure
    }
    return -1; // Indicate failure to return
}

// Function to calculate AQI (simplified example)
int calculate_aqi(int adc_value) {
    // This is a placeholder.  A real AQI calculation requires a calibration curve
    // specific to the MQ-135 sensor and the environment it's used in.
    // This example assumes a linear relationship between ADC value and AQI.
    // You'll need to determine the appropriate scaling and offset.
    // For example, you might use a logarithmic or polynomial function.
    // This is just a starting point.
    int aqi = (int)(((float)adc_value / 1023.0) * 500.0); // Scale ADC value to 0-500
    return aqi;
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to file
void log_data(int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
