// Define GPIO pins
#define LED_PIN 17
#define CS_PIN 8

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define noise calibration time (seconds)
#define CALIBRATION_TIME 5

// Define sound level threshold (adjust as needed)
#define SOUND_THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int initialize_gpio();
int read_mcp3008(int channel);
int calibrate_noise_level();
void control_led(int on);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    terminate = 1;
    exit(0);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calibrate noise level
int calibrate_noise_level() {
    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_TIME);
    long sum = 0;
    int samples = 0;
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < CALIBRATION_TIME) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            sum += adc_value;
            samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return 1;
        }
        gpioDelay(1000); // 1 ms delay
    }

    if (samples > 0) {
        long average = sum / samples;
        printf("Calibration complete. Average noise level: %ld\n", average);
        return average;
    } else {
        fprintf(stderr, "No samples collected during calibration\n");
        return 1;
    }
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio()) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level();
    if (baseline < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting sound level monitoring...\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Debounce
        gpioDelay(10000); // 10ms debounce

        // Check if sound level exceeds threshold
        if (adc_value > baseline + SOUND_THRESHOLD) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

