// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "ERROR: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "ERROR: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to airflow (example calibration)
float voltage_to_airflow(int adc_value) {
    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * (3.3 / 1024.0);

    // Apply calibration curve (linear approximation)
    float airflow = A * voltage + B;

    return airflow;
}

// Function to log data to a file
