// Define SPI mode
#define SPI_MODE 0

// Define bits per word
#define SPI_BITS_PER_WORD 8

// Define max speed
#define SPI_MAX_SPEED 1000000 // 1 MHz

// Define ADC channel
#define ADC_CHANNEL 0

// Define log file path
