            perror("Error getting timestamp");
            break;
        }
        timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

        // Read ADC value
        adc_value = adc_read();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Continuing.\n");
            continue;
        }

        // Log data
        if (log_data(timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Sleep for 1 ms
        struct timespec req = {0, 1000000}; // 1 ms
        nanosleep(&req, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Audio sampling stopped.\n");
    return 0;
}

