#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)

// Define ADXL335 sensitivity (300mV/g) and reference voltage (3.3V)
#define SENSITIVITY 0.300
#define VREF 3.3

// Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_estimate = 0.0;
float y_estimate = 0.0;
float z_estimate = 0.0;
float P_xx = 1.0;
float P_xy = 0.0;
float P_xz = 0.0;
float P_yy = 1.0;
float P_yz = 0.0;
float P_zz = 1.0;

// Function prototypes
int initialize_spi();
int read_adc_channel(int channel);
float adc_to_g(int adc_value);
void kalman_filter_update(float z_value);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC channel value
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
