#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the magnetic field sensitivity range (mT)
#define MAGNETIC_FIELD_RANGE 100.0

// Define the voltage range (V)
#define VOLTAGE_RANGE 3.3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the digital state of a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert a digital state to a magnetic field strength (mT)
float convert_to_magnetic_field(int digital_state) {
    if (digital_state == 1) {
        return MAGNETIC_FIELD_RANGE / 2.0; // Assuming 3.3V corresponds to half the range
    } else {
        return 0.0;
    }
}

// Function to log the magnetic field strengths to a file
void log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing\n");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "sensor1_mT,sensor2_mT,sensor3_mT\n");
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the digital states of the sensors
        int sensor1_digital = read_sensor(SENSOR1_GPIO);
        int sensor2_digital = read_sensor(SENSOR2_GPIO);
        int sensor3_digital = read_sensor(SENSOR3_GPIO);

        // Check for errors during GPIO read
        if (sensor1_digital == -1 || sensor2_digital == -1 || sensor3_digital == -1) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the digital states to magnetic field strengths
        float sensor1_mT = convert_to_magnetic_field(sensor1_digital);
        float sensor2_mT = convert_to_magnetic_field(sensor2_digital);
        float sensor3_mT = convert_to_magnetic_field(sensor3_digital);

        // Check for out-of-range magnetic field values
        if (sensor1_mT < -MAGNETIC_FIELD_RANGE || sensor1_mT > MAGNETIC_FIELD_RANGE ||
            sensor2_mT < -MAGNETIC_FIELD_RANGE || sensor2_mT > MAGNETIC_FIELD_RANGE ||
            sensor3_mT < -MAGNETIC_FIELD_RANGE || sensor3_mT > MAGNETIC_FIELD_RANGE) {
            fprintf(stderr, "Warning: Magnetic field value out of range. Skipping logging.\n");
        } else {
            // Log the magnetic field strengths to the file
            log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

