#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

int spi_fd;
FILE *fp;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int adc0, adc1, adc2;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    fp = fopen("sensor_data.csv", "a");
    if (fp == NULL) {
        perror("Error opening sensor_data.csv");
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(fp);

    printf("Starting data acquisition... Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        // Read ADC values
        adc0 = read_mcp3008(0);
        adc1 = read_mcp3008(1);
        adc2 = read_mcp3008(2);

        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to CSV file
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, adc0, adc1, adc2);
        fflush(fp); // Ensure data is written immediately

        printf("%s - Channel 0: %d, Channel 1: %d, Channel 2: %d\n", timestamp, adc0, adc1, adc2);

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    printf("Closing SPI device and CSV file...\n");
    close(spi_fd);
    fclose(fp);

    printf("Exiting.\n");
    return 0;
}

