#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages with timestamps
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Function to parse JSON and extract led_state
int parse_json_led_state(const char *json_string, int *led_state)
{
    json_error_t error;
    json_t *root = json_loads(json_string, 0, &error);

    if (!root) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Error parsing JSON: %s", error.text);
        log_message(error_message);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        log_message("Error: 'led_state' key not found in JSON");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        log_message("Error: 'led_state' value is not a boolean");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// Function to set the LED state
void set_led_state(int led_state)
{
    gpioWrite(LED_GPIO, led_state);
}

// MQTT callback function
void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("MQTT connected successfully");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_connack_string(result));
        log_message(error_message);
    }
}

// MQTT message callback function
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message)
{
    if (message->payloadlen) {
        int led_state;
        if (parse_json_led_state((char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_message("Error parsing JSON or invalid data type");
        }
    } else {
        log_message("Received empty message");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum)
{
    running = 0;
    log_message("Signal received, exiting...");
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn LED off initially

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Error: Out of memory.");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker with exponential backoff
    int rc = 0;
    int reconnect_delay = 1; // Initial delay in seconds
    while (running) {
        rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            log_message("Attempting to connect to MQTT broker...");
            break;
        } else {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Connection failed: %s. Retrying in %d seconds...", mosquitto_strerror(rc), reconnect_delay);
            log_message(error_message);
            sleep(reconnect_delay);
            reconnect_delay *= 2; // Exponential backoff
            if (reconnect_delay > 60) {
                reconnect_delay = 60; // Maximum delay of 60 seconds
            }
        }
    }

    if (!running) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start the MQTT loop
    mosquitto_loop_forever(mosq, -1, 1); // -1 means loop forever, 1 means max 1 message processed at a time

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    log_message("Exiting cleanly");
    return 0;
}

