#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17  // BCM GPIO17
#define ALARM_LED_PIN 18     // BCM GPIO18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    int rc;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    if ((rc = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT)) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", SOUND_SENSOR_PIN, rc);
        gpioTerminate();
        return 1;
    }

    if ((rc = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT)) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", ALARM_LED_PIN, rc);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level == PI_BAD_GPIO)
        {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_PIN);
            gpioTerminate();
            return 1;
        }

        printf("Sound Level: %d\n", sound_level);

        if (sound_level == 0) // Sound detected (LOW signal)
        {
            // Trigger alarm LED
            if (gpioWrite(ALARM_LED_PIN, 1) != 0)
            {
                fprintf(stderr, "Error writing to GPIO%d\n", ALARM_LED_PIN);
                gpioTerminate();
                return 1;
            }
            gpioDelay(1000); // 1 second
            if (gpioWrite(ALARM_LED_PIN, 0) != 0)
            {
                fprintf(stderr, "Error writing to GPIO%d\n", ALARM_LED_PIN);
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(100); // 100 milliseconds
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

