#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio/consumer.h>

#define GPIO_CHIP 0
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    int gpio_fd, event_fd;
    char buffer[64];
    ssize_t bytes_read;
    struct gpio_event_config config;
    struct timespec delay;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO line for consumption
    config.consumer_label = "vibration-monitor";
    config.request_lines = 1;
    config.lines = (unsigned int[]){GPIO_PIN};
    config.flags = 0;

    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, &config) < 0) {
        perror("Error requesting GPIO line");
        close(gpio_fd);
        return 1;
    }

    // Wait for falling edge
    printf("Waiting for falling edge on GPIO %d...\n", GPIO_PIN);
    while (program_running) {
        event_fd = open("/dev/gpiochip0/gpio%d/edge%d", O_RDONLY);
        if (event_fd < 0) {
            perror("Error opening event file");
            close(gpio_fd);
            return 1;
        }

        bytes_read = read(event_fd, buffer, sizeof(buffer) - 1);
        close(event_fd);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Falling edge detected: %s\n", buffer);

            if (log_event("Vibration detected, initiating shutdown.") != 0) {
                fprintf(stderr, "Error logging event.\n");
            }

            system("sudo shutdown -h now");
            break; // Exit the loop after shutdown is initiated
        }
        delay.tv_sec = 0;
        delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // 50ms
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    config.consumer_label = "vibration-monitor";
    config.request_lines = 0;
    config.lines = (unsigned int[]){GPIO_PIN};
    config.flags = 0;

    if (ioctl(gpio_fd, GPIO_RELEASE_LINE, &config) < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    if (close(gpio_fd) < 0) {
        perror("Error closing GPIO chip");
    }

    printf("Program exiting.\n");
    return 0;
}

