#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadI2CBlockData(handle, reg, (char*)value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteI2CBlockData(handle, reg, (char*)&value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int handle, struct bmp280_calib_data *cal) {
    uint8_t data[26];
    int result = i2cReadI2CBlockData(handle, BMP280_REG_CALIB_00, (char*)data, 26);
    if (result != 26) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    cal->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    cal->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    cal->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    cal->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    cal->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    cal->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    cal->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    cal->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    cal->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    cal->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    cal->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    cal->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read the BMP280 chip ID
int read_chip_id(int handle) {
    uint8_t chip_id;
    if (read_register(handle, BMP280_REG_ID, &chip_id) != 0) {
        return -1;
    }
    return (int)chip_id;
}

// Function to read raw temperature and pressure data
int read_raw_data(int handle, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    int result = i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char*)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %s\n", strerror(errno));
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data cal) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)cal.dig_T1) / 1024.0) * ((double)cal.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)cal.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)cal.dig_T1) / 8192.0)) * ((double)cal.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, struct bmp280_calib_data cal) {
    double var1, var2, p;
    double t_fine;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)cal.dig_T1) / 1024.0) * ((double)cal.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)cal.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)cal.dig_T1) / 8192.0)) * ((double)cal.dig_T3);
    t_fine = (var1 + var2);

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)cal.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)cal.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)cal.dig_P4) * 65536.0);
    var1 = (((double)cal.dig_P3) * var1 * var1 / 524288.0 + ((double)cal.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)cal.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)cal.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)cal.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)cal.dig_P7)) / 16.0;

    return (float)p;
}

// Function to calculate altitude
float calculate_altitude(float pressure) {
    float altitude;
    float p0 = 101325.0; // Standard sea level pressure in Pa
    altitude = 44330.0 * (1.0 - pow(pressure / p0, 0.1903));
    return altitude;
}

// Function to log altitude data to a file
int log_altitude(FILE *file, float altitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(file, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read chip ID
    int chip_id = read_chip_id(i2c_handle);
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor (oversampling x1, normal mode)
    if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) == 0) {
            float temperature = compensate_temperature(raw_temperature, calib);
            float pressure = compensate_pressure(raw_pressure, raw_temperature, calib);
            float altitude = calculate_altitude(pressure);

            if (log_altitude(log_file, altitude) != 0) {
                fprintf(stderr, "Error logging altitude data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

