#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define BUFFER_SIZE 120

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int spi_fd = -1;
FILE *fp = NULL;

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int read_adc(int channel);
float convert_to_temperature(int adc_value);
void store_temperature(float temperatures[], int buffer_size, int *head, float temperature);
void print_temperature(float temperature);
int write_buffer_to_file(float temperatures[], int buffer_size, int head, const char *filename);
void signal_handler(int signum);

// SPI initialization function
int spi_init(spi_config_t *config) {
    int ret;

    config->fd = open(SPI_DEVICE, O_RDWR);
    if (config->fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(config->fd, SPI_IOC_WR_MODE, &config->mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_RD_MODE, &config->mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(config->fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(config->fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_RD_BITS_PER_WORD, &config->bits_per_word);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(config->fd);
        return -1;
    }

    // Set max speed
    ret = ioctl(config->fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed);
    if (ret == -1) {
        perror("Error setting max speed");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_RD_MAX_SPEED_HZ, &config->speed);
    if (ret == -1) {
        perror("Error getting max speed");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (LM35: 10mV/°C)
float convert_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = voltage * 100.0; // LM35: 10mV/°C
    return temperature;
}

// Function to store temperature in circular buffer
void store_temperature(float temperatures[], int buffer_size, int *head, float temperature) {
    temperatures[*head] = temperature;
    *head = (*head + 1) % buffer_size;
}

// Function to print temperature
void print_temperature(float temperature) {
    printf("Temperature: %.2f \u00b0C\n", temperature);
}

// Function to write buffer to file
int write_buffer_to_file(float temperatures[], int buffer_size, int head, const char *filename) {
    fp = fopen(filename, "wb+");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    size_t bytes_written = fwrite(temperatures, sizeof(float), buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file: wrote %zu elements, expected %d\n", bytes_written, buffer_size);
        fclose(fp);
        fp = NULL;
        return -1;
    }

    fclose(fp);
    fp = NULL;
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        keep_running = 0;

        if (spi_fd != -1) {
            close(spi_fd);
        }

        if (fp != NULL) {
            fclose(fp);
        }

        exit(0);
    }
}

int main() {
    spi_config_t spi_config;
    float temperatures[BUFFER_SIZE];
    int head = 0;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init(&spi_config) < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }
    spi_fd = spi_config.fd; // Store file descriptor for cleanup

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping.\n");
            sleep(5);
            continue;
        }

        // Convert to temperature
        float temperature = convert_to_temperature(adc_value);

        // Store temperature
        store_temperature(temperatures, BUFFER_SIZE, &head, temperature);

        // Print temperature
        print_temperature(temperature);

        // Write buffer to file
        if (write_buffer_to_file(temperatures, BUFFER_SIZE, head, "temp_log.dat") < 0) {
            fprintf(stderr, "Error writing to file. Continuing.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

