#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Global variables
int i2c_handle = -1;
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750();
int read_mcp3008();
char* format_log_entry(int light_level, int sound_level);
int write_to_log(const char *log_entry);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750
int read_bh1750() {
    char config[1] = {0x10}; // Continuous high resolution mode
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return (int)raw_value;
}

// Read sound level from MCP3008
int read_mcp3008() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message to read from channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Format log entry
char* format_log_entry(int light_level, int sound_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char log_entry[100]; // Static buffer to avoid memory allocation issues
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", t);
    snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), ", Light: %d, Sound: %d", light_level, sound_level);
    return log_entry;
}

// Write to log file
int write_to_log(const char *log_entry) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", log_entry) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C and SPI
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int light_level = read_bh1750();
        int sound_level = read_mcp3008();

        // Check for errors
        if (light_level == -1 || sound_level == -1) {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        } else {
            // Format log entry
            char *log_entry = format_log_entry(light_level, sound_level);

            // Write to log file
            if (write_to_log(log_entry) != 0) {
                fprintf(stderr, "Error writing to log, but continuing...\n");
            }
        }

        // Wait for 1 second
