#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int gpio_status;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    int flame_detected;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log data to CSV file
        fprintf(log_file, "%s,%d,%d\n", timestamp, FLAME_SENSOR_GPIO, flame_detected);
        fflush(log_file); // Ensure data is written to disk immediately

        // Check for flame detection
        if (flame_detected == 1) {
            printf("ALARM: Flame detected on GPIO %d at %s\n", FLAME_SENSOR_GPIO, timestamp);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

