#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x60
#define TMP36_SENSITIVITY 0.01 // V/°C
#define TMP36_OFFSET 0.5 // V
#define SAMPLE_INTERVAL_MS 500
#define DAC_RESOLUTION 4095.0
#define VREF 3.3 // Reference voltage for MCP4725

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_temperature(int adc_value);
int dac_init(void);
int dac_set_voltage(float voltage);
int log_data(int adc_value, float temperature, float dac_voltage);
void signal_handler(int signal);

// SPI initialization function
int spi_init(void) {
    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 500000; // 500 kHz

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit, single-ended mode, channel number (0-7), don't care bit
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = 500000; // 500 kHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Temperature conversion function
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / DAC_RESOLUTION) * VREF;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SENSITIVITY;
    return temperature;
}

// DAC initialization function
int dac_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// DAC set voltage function
int dac_set_voltage(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: DAC voltage out of range (0.0 - %f)\n", VREF);
        return -1;
    }

    uint16_t dac_value = (uint16_t)((voltage / VREF) * DAC_RESOLUTION);
    uint16_t data = (dac_value >> 4) | 0x4000; // Write DAC value, power down mode

    if (write(i2c_fd, &data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Log data function
int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("temperature_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file); // Ensure data is written to disk

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize hardware
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (dac_init() < 0) {
        fprintf(stderr, "DAC initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Set DAC voltage
        float dac_voltage = temperature * TMP36_SENSITIVITY + TMP36_OFFSET; // Calculate voltage for DAC
        if (dac_set_voltage(dac_voltage) < 0) {
            fprintf(stderr, "Error setting DAC voltage. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(adc_value, temperature, dac_voltage) < 0) {
            fprintf(stderr, "Error logging data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

