// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SOUND_THRESHOLD 500
#define LED_GPIO 16
#define DEBOUNCE_DELAY 200 // milliseconds
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_led(int state);
void log_event(int adc_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log events to a file
void log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Sound detected: ADC Value = %d\n", timestamp, adc_value);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (adc_value > SOUND_THRESHOLD) {
            printf("Sound detected! ADC Value: %d\n", adc_value);
            control_led(1); // Turn on LED
            log_event(adc_value); // Log the event
            gpioDelay(500); // Keep LED on for 500ms
            control_led(0); // Turn off LED
            gpioDelay(DEBOUNCE_DELAY); // Debounce delay
        }

        gpioDelay(10); // Sample every 10ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

