#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor direction and speed
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_SPEED 150

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor(int spi_handle);
void control_motor(int direction, int speed);
void log_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read rain sensor data from MCP3008
int read_rain_sensor(int spi_handle) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int rain_level;

    // MCP3008 configuration: single-ended channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (0b10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        if (log_file != NULL) {
            fprintf(log_file, "Error: SPI transfer failed\n");
            fflush(log_file);
        }
        return -1; // Indicate error
    }

    // Extract rain level from the received data
    rain_level = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return rain_level;
}

// Function to control the DC motor
void control_motor(int direction, int speed) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, speed);
        printf("Motor forward\n");
    } else if (direction == MOTOR_REVERSE) {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, speed);
        printf("Motor reverse\n");
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0);
        printf("Motor stopped\n");
    }
}

// Function to log data to file
void log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int spi_handle, rain_level;
    int init_result;

    // Initialize pigpio library
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", init_result);
        return 1;
