    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read rain sensor data from MCP3008
int read_rain_sensor(int spi_handle) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int rain_level;

    // MCP3008 configuration: single-ended channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (0b10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        if (log_file != NULL) {
            fprintf(log_file, "Error: SPI transfer failed\n");
            fflush(log_file);
        }
        return -1; // Indicate error
    }

    // Extract rain level from the received data
    rain_level = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return rain_level;
}

