#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define constants
#define ADC_SAMPLES 100
#define DEBOUNCE_DELAY 50 // milliseconds
#define LED_ON_TIME 500   // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int *adc_values, int num_samples);
void control_led(int on);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int adc_pin;
    int led_pin;
    int num_samples;
    int debounce_delay;
    int led_on_time;
} AppConfig;

AppConfig config = {ADC_PIN, LED_PIN, ADC_SAMPLES, DEBOUNCE_DELAY, LED_ON_TIME};

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int adc_values[config.num_samples];
    int clap_detected = 0;
    time_t last_clap_time = 0;

    printf("Clap detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC samples
        for (int i = 0; i < config.num_samples; i++) {
            adc_values[i] = read_adc();
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading ADC sample %d. Continuing.\n", i);
                adc_values[i] = 0; // Assign a default value to avoid further issues
            }
        }

        // Detect clap
        int current_time = time(NULL);
        if (detect_clap(adc_values, config.num_samples) && !clap_detected && (current_time - last_clap_time) * 1000 >= config.debounce_delay) {
            // Clap detected, turn on LED
            control_led(1);
            print_timestamped_message("Clap detected!");
            clap_detected = 1;
            last_clap_time = current_time;
        } else if (clap_detected && (current_time - last_clap_time) * 1000 < config.debounce_delay) {
            // Debouncing, keep LED on
        } else if (!clap_detected) {
            // No clap detected, turn off LED
            control_led(0);
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.adc_pin, PI_INPUT); // ADC pin as input
    gpioSetMode(config.led_pin, PI_OUTPUT); // LED pin as output

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        gpioSetMode(config.adc_pin, PI_OUTPUT);
        gpioWrite(config.adc_pin, 0); // Start signal
        gpioDelay(1); // Small delay
        gpioSetMode(config.adc_pin, PI_INPUT);
        gpioDelay(1); // Wait for ADC to respond
        sum += gpioRead(config.adc_pin); // Read ADC value
        gpioDelay(1); // Small delay
        gpioWrite(config.adc_pin, 1); // End signal
        gpioDelay(1); // Small delay
    }
    return sum / 10; // Average the readings
}

// Detect clap event
int detect_clap(int *adc_values, int num_samples) {
    // Simple threshold-based clap detection
    // You may need to adjust the threshold based on your environment
    int threshold = 500; // Adjust this value
    for (int i = 0; i < num_samples; i++) {
        if (adc_values[i] > threshold) {
            return 1; // Clap detected
        }
    }
    return 0; // No clap detected
}

// Control LED state
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Print timestamped message
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    control_led(0); // Turn off LED
    printf("Ctrl+C pressed. Exiting.\n");
}

