#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <stdbool.h>

// Define constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
bool pump_state = false;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
float convert_to_percentage(int adc_value);
int control_pump(float moisture_percentage);
int log_data(float moisture_percentage, int pump_status);
void signal_handler(int signal);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_percentage(int adc_value) {
    // Assuming a linear relationship between ADC value and moisture percentage
    // You may need to calibrate these values based on your sensor and soil
    float min_adc = 0;   // ADC value for 0% moisture
    float max_adc = 1023; // ADC value for 100% moisture

    // Ensure ADC value is within the expected range
    if (adc_value < min_adc) {
        adc_value = min_adc;
    } else if (adc_value > max_adc) {
        adc_value = max_adc;
    }

    float percentage = (float)(adc_value - min_adc) / (max_adc - min_adc) * 100.0;
    return percentage;
}

// Function to control the water pump
int control_pump(float moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD && !pump_state) {
        // Turn the pump ON
        int gpio_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (gpio_fd < 0) {
            perror("Error opening GPIO value file");
            return -1;
        }
        if (write(gpio_fd, "1", 1) != 1) {
            perror("Error writing to GPIO value file");
            close(gpio_fd);
            return -1;
        }
        close(gpio_fd);
        pump_state = true;
        printf("Pump turned ON\n");
    } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state) {
        // Turn the pump OFF
        int gpio_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (gpio_fd < 0) {
            perror("Error opening GPIO value file");
            return -1;
        }
