#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Sensor Calibration
#define VOLTAGE_RANGE 5.0  // Volts
#define AMPERES_PER_VOLT 1000.0 // Amperes per Volt

// Global Variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

// Function Prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int spi_open(const char *device);
int spi_close(int fd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void signal_handler(int sig);

// Helper function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
    if (spi_fd != -1) spi_close(spi_fd);
    if (log_fp != NULL) fclose(log_fp);
    gpio_unexport(GPIO_PIN);
    exit(EXIT_FAILURE);
}

// GPIO Functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open /sys/class/gpio/export");
        return -1;
    }
    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open /sys/class/gpio/unexport");
        return -1;
    }
    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open GPIO direction file");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) == -1) {
        handle_error("Failed to set GPIO direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open GPIO value file");
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) == -1) {
        handle_error("Failed to write GPIO value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// SPI Functions
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        handle_error("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        handle_error("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        handle_error("Failed to set SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_close(int fd) {
    if (close(fd) == -1) {
        handle_error("Failed to close SPI device");
        return -1;
    }
    return 0;
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        handle_error("SPI transfer failed");
        return -1;
    }
    return 0;
}

// ADC Function
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "SPI transfer failed for ADC read\n");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Conversion Function
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VOLTAGE_RANGE;
    float current = voltage * AMPERES_PER_VOLT;
    return current;
}

// Logging Function
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            handle_error("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, current);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) == -1) return EXIT_FAILURE;
    if (gpio_set_direction(GPIO_PIN, "out") == -1) return EXIT_FAILURE;
    if (gpio_write(GPIO_PIN, 1) == -1) return EXIT_FAILURE; // Enable sensor power

    // Initialize SPI
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd == -1) return EXIT_FAILURE;

    printf("Current Monitoring Started...\n");

    while (keep_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        if (log_current(current) == -1) {
            fprintf(stderr, "Failed to log current\n");
        }

        printf("Current: %.2f A\n", current);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_write(GPIO_PIN, 0); // Disable sensor power
    spi_close(spi_fd);
    if (log_fp != NULL) fclose(log_fp);
    gpio_unexport(GPIO_PIN);

    printf("Current Monitoring Stopped.\n");
    return EXIT_SUCCESS;
}

