#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_sensor(int gpio) {
    int readings[5];
    for (int i = 0; i < 5; i++) {
        readings[i] = gpioRead(gpio);
        gpioDelay(2000); // 2ms delay
    }

    int majority = 0;
    for (int i = 0; i < 5; i++) {
        if (readings[i] == 0) {
            majority++;
        }
    }

    return (majority >= 3) ? 0 : 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

