#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 500
#define CAPTURE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int pir_value;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    FILE *dir_check;
    int dir_exists = 0;

    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting security camera system...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        pir_value = gpioRead(PIR_GPIO);

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected!");

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(filename, sizeof(filename), "%Y%m%dT%H%M%S", timeinfo);
            snprintf(command, sizeof(command), "cd %s && libcamera-still -o %s.jpg", CAPTURE_DIR, filename);

            if (access(CAPTURE_DIR, F_OK) == 0) {
                dir_exists = 1;
            } else {
                dir_exists = 0;
            }

            if (!dir_exists) {
                syslog(LOG_ERR, "Directory %s does not exist.  Capture aborted.", CAPTURE_DIR);
            } else {
                syslog(LOG_INFO, "Capturing image...");
                int ret = system(command);
                if (ret == 0) {
                    syslog(LOG_INFO, "Image captured successfully.");
                } else {
                    syslog(LOG_ERR, "Image capture failed with code %d.", ret);
                }
            }

            gpioDelay(CAPTURE_DELAY * 1000); // Debounce and delay
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    syslog(LOG_INFO, "Terminating security camera system...");

    gpioTerminate();
    closelog();

    return 0;
}

