#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define CSI_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FRAME_RATE 15
#define BUFFER_COUNT 4

typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

buffer_t *buffers = NULL;
int       fd      = -1;
volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
    printf("Caught signal %d, stopping...\n", sig);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main(int argc, char **argv) {
    int i;
    int fd_camera;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int n_buffers;
    unsigned int i_buffer;
    fd_set fds;
    struct timeval tv;
    int r;
    FILE *fp;
    char filename[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open camera device
    fd_camera = open(CSI_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd_camera < 0) {
        perror("Cannot open device");
        return 1;
    }
    fd = fd_camera;

    // Query capabilities
    if (xioctl(fd_camera, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd_camera);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", CSI_DEVICE);
        close(fd_camera);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", CSI_DEVICE);
        close(fd_camera);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd_camera, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd_camera);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd_camera, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd_camera);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd_camera);
        return 1;
    }

    // Map buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (xioctl(fd_camera, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd_camera);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd_camera, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd_camera);
            return 1;
        }
    }

    // Queue buffers
    for (i_buffer = 0; i_buffer < n_buffers; ++i_buffer) {
        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i_buffer;

        if (xioctl(fd_camera, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            close(fd_camera);
            return 1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd_camera, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(fd_camera);
        return 1;
    }

    printf("Streaming started...\n");

    // Save images
    for (i = 1; i <= n_buffers && !stop; ++i) {
        snprintf(filename, sizeof(filename), "image_%04d.pgm", i);

        fp = fopen(filename, "wb");
        if (!fp) {
            perror("fopen");
            continue; // Continue to the next image
        }

        fprintf(fp, "P2\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);

        // Dequeue buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i_buffer;

        fd_set readfds;
        struct timeval tv;
        int retval;

        FD_ZERO(&readfds);
        FD_SET(fd_camera, &readfds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        retval = select(fd_camera + 1, &readfds, NULL, NULL, &tv);

        if (retval == -1) {
            perror("select");
        } else if (retval) {
            if (xioctl(fd_camera, VIDIOC_DQBUF, &buf) == 0) {
                // Clear the buffer
                if (xioctl(fd_camera, VIDIOC_QBUF, &buf) < 0) {
                    perror("VIDIOC_QBUF");
                }

                // Write frame data to file
                fwrite(buffers[i_buffer].start, 1, buf.bytesused, fp);

                printf("Saved %s (%d bytes)\n", filename, buf.bytesused);
            } else {
                perror("VIDIOC_DQBUF");
            }
        } else {
            fprintf(stderr, "select timeout\n");
        }

        fclose(fp);
    }

    // Stop streaming
    if (xioctl(fd_camera, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }

    printf("Streaming stopped.\n");

    // Unmap buffers
    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("munmap");
        }
    }

    // Free buffer array
    free(buffers);

    // Close device
    close(fd_camera);

    printf("Done.\n");

    return 0;
}

