#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>
#include <sys/time.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define BUFFER_COUNT 4

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
int fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        stop_flag = 1;
    }
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int init_device(int *fd_ptr, buffer **buffers_ptr, FILE **log_file_ptr) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    *fd_ptr = fd;

    struct v4l2_capability cap;
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
