#define BUFFER_COUNT 4
#define MAX_PAYLOAD_SIZE 65000

// Structure to hold device information
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer[BUFFER_COUNT];
    size_t buffer_size;
} device_info_t;

// Global device information
device_info_t device_info;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, exiting gracefully...\n", signum);
    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(device_info.fd, VIDIOC_STREAMOFF, &type);

    // Unmap buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (device_info.buffer[i] != NULL) {
            munmap(device_info.buffer[i], device_info.buffer_size);
        }
    }

    // Close device
    close(device_info.fd);

    exit(0);
}

// Function to initialize the V4L2 device
int init_device(device_info_t *device_info) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    device_info->fd = fd;

    // Query capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    // Set image format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    // Request buffers
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    // Map buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        device_info->buffer[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (device_info->buffer[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }

        device_info->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        device_info->buf.memory = V4L2_MEMORY_MMAP;
        device_info->buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &device_info->buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame and fragment it into UDP packets
int capture_and_fragment(device_info_t *device_info) {
    // Dequeue a buffer
    if (ioctl(device_info->fd, VIDIOC_DQBUF, &device_info->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Allocate memory for the UDP header
    unsigned char *header = (unsigned char *)malloc(sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint32_t));
    if (header == NULL) {
        perror("Error allocating memory for header");
        // Re-queue the buffer
        if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
            perror("Error re-queuing buffer");
            return -1;
        }
        return -1;
    }

    // Populate the UDP header
    uint32_t frame_index = device_info->buf.index;
    uint16_t fragment_index = 0; // First fragment
    uint32_t total_fragments = BUFFER_COUNT;
    uint32_t payload_size = device_info->buf.bytesused; // YUYV frame size

    memcpy(header, &frame_index, sizeof(uint32_t));
    memcpy(header + sizeof(uint32_t), &fragment_index, sizeof(uint16_t));
    memcpy(header + sizeof(uint32_t) + sizeof(uint16_t), &total_fragments, sizeof(uint32_t));
    memcpy(header + sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint32_t), &payload_size, sizeof(uint32_t));

    // Create a socket
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        free(header);
        // Re-queue the buffer
        if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
            perror("Error re-queuing buffer");
            return -1;
        }
        return -1;
    }

    // Configure the destination address
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &dest_addr.sin_addr) <= 0) {
        perror("Error converting IP address");
        close(sockfd);
        free(header);
        // Re-queue the buffer
        if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
            perror("Error re-queuing buffer");
            return -1;
        }
        return -1;
    }

    // Fragment the YUYV frame into smaller payloads
    unsigned char *yuyv_data = (unsigned char *)device_info->buffer[device_info->buf.index];
    size_t yuyv_size = device_info->buf.bytesused;
    size_t fragment_size;
    unsigned char *payload;

    while (yuyv_size >= MAX_PAYLOAD_SIZE) {
        fragment_size = MAX_PAYLOAD_SIZE;
        payload = yuyv_data;

        // Send the UDP packet
        ssize_t sent_bytes = sendto(sockfd, payload, fragment_size, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
        if (sent_bytes < 0) {
            perror("Error sending UDP packet");
            close(sockfd);
            free(header);
            // Re-queue the buffer
            if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
                perror("Error re-queuing buffer");
                return -1;
            }
            return -1;
        }

        // Update the remaining YUYV data
        yuyv_data += fragment_size;
        yuyv_size -= fragment_size;

        // Increment fragment index
        fragment_index++;
    }

    // Send the remaining YUYV data if it's smaller than MAX_PAYLOAD_SIZE
    if (yuyv_size > 0) {
        payload = yuyv_data;
        fragment_size = yuyv_size;
        // Send the UDP packet
        ssize_t sent_bytes = sendto(sockfd, payload, fragment_size, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
        if (sent_bytes < 0) {
            perror("Error sending UDP packet");
            close(sockfd);
            free(header);
            // Re-queue the buffer
            if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
                perror("Error re-queuing buffer");
                return -1;
            }
            return -1;
        }
    }

    // Free the header and close the socket
    close(sockfd);
    free(header);

    // Re-queue the buffer
    if (ioctl(device_info->fd, VIDIOC_QBUF, &device_info->buf) < 0) {
        perror("Error re-queuing buffer");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(&device_info) < 0) {
        fprintf(stderr, "Device initialization failed\n");
        return 1;
    }

    printf("V4L2 UDP Fragmenter started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (capture_and_fragment(&device_info) < 0) {
            fprintf(stderr, "Error capturing and fragmenting\n");
            break;
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(device_info.fd, VIDIOC_STREAMOFF, &type);

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (device_info.buffer[i] != NULL) {
            munmap(device_info.buffer[i], device_info.buffer_size);
        }
    }

    close(device_info.fd);

    return 0;
}

