#include <linux/videodev2.h>
#include <signal.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define BUFFER_COUNT 4

typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

buffer_t *buffers = NULL;
int fd = -1;
FILE *fp = NULL;

void signal_handler(int sig);
int xioctl(int fh, int request, void *arg);
int init_device(int *fd_ptr, unsigned int *pixel_format_ptr);
int start_capturing(int fd);
int stop_capturing(int fd);
int read_frame(int fd, buffer_t *buffers, int buffer_count);
int write_to_file(FILE *fp, buffer_t *buffers, int buffer_count);
int verify_frame(buffer_t *buffer);

int main()
{
    unsigned int pixel_format;
    int fd_local = -1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device(&fd_local, &pixel_format) < 0) {
        fprintf(stderr, "Failed to initialize device.\n");
        return EXIT_FAILURE;
    }

    fd = fd_local;

    if (start_capturing(fd) < 0) {
        fprintf(stderr, "Failed to start capturing.\n");
        goto cleanup;
    }

    if (read_frame(fd, buffers, buffer_count) < 0) {
        fprintf(stderr, "Failed to read frame.\n");
        goto cleanup;
    }

    if (write_to_file(fp, buffers, buffer_count) < 0) {
        fprintf(stderr, "Failed to write to file.\n");
        goto cleanup;
    }

    if (verify_frame(&buffers[0]) < 0) {
        fprintf(stderr, "Failed to verify frame.\n");
        goto cleanup;
    }

cleanup:
    stop_capturing(fd);

    if (buffers) {
        for (int i = 0; i < buffer_count; i++) {
            if (buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }

    if (fp) {
        fclose(fp);
    }

    if (fd != -1) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    stop_capturing(fd);

    if (buffers) {
        for (int i = 0; i < buffer_count; i++) {
