    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(*fd_ptr, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(*fd_ptr);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(*fd_ptr, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        close(*fd_ptr);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd_ptr);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(*fd_ptr);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(*fd_ptr, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(*fd_ptr);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd_ptr, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            perror("mmap");
            close(*fd_ptr);
            free(buffers);
            return -1;
        }
    }

    *pixel_format_ptr = fmt.fmt.pix.pixelformat;
    return 0;
}

int start_capturing(int fd)
{
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

int stop_capturing(int fd)
{
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    return 0;
}

int read_frame(int fd, buffer_t *buffers, int buffer_count)
{
    struct v4l2_buffer buf;
    unsigned int i;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Frame data is empty\n");
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            return -1;
        }
        return 0;
    }

    for (i = 0; i < buffer_count; ++i) {
        if (buffers[i].start == buf.m.start) {
            buffers[i].length = buf.length;
            break;
        }
    }

    if (i == buffer_count) {
        fprintf(stderr, "Unexpected buffer\n");
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            return -1;
        }
        return 0;
    }

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return buf.bytesused;
}

int write_to_file(FILE *fp_ptr, buffer_t *buffers, int buffer_count)
{
    size_t bytes_written;
    size_t total_bytes_written = 0;
    int i;

    fp = fp_ptr;

    for (i = 0; i < buffer_count; ++i) {
        bytes_written = fwrite(buffers[i].start, 1, buffers[i].length, fp);
        if (bytes_written != buffers[i].length) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            return -1;
        }
        total_bytes_written += bytes_written;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing file: %s\n", strerror(errno));
        return -1;
    }

    return total_bytes_written;
}

int verify_frame(buffer_t *buffer)
{
    FILE *fp_local = fopen(IMAGE_FILE, "rb");
    if (!fp_local) {
        perror("fopen");
        return -1;
    }

    size_t bytes_read;
    unsigned char header[4];

    bytes_read = fread(header, 1, 4, fp_local);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading header from file: %s\n", strerror(errno));
        fclose(fp_local);
        return -1;
    }

    if (header[0] != 'J' || header[1] != 'F' || header[2] != 'I' || header[3] != ' ' ||
        header[4] != 'D' || header[5] != 'R' || header[6] != ' ' || header[7] != ' ' ||
        header[8] != 'S' || header[9] != 'O' || header[10] != ' ' || header[11] != ' ' ||
        header[12] != 'T' || header[13] != ' ' || header[14] != 'A' || header[15] != 'P') {
        fprintf(stderr, "Invalid JPEG header\n");
        fclose(fp_local);
        return -1;
    }

    fclose(fp_local);
    printf("JPEG header verified.\n");
    return 0;
}

