#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM frequency and period
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD 20000 // microseconds (20 ms)

// Define duty cycle range
#define MIN_DUTY_CYCLE 50
#define MAX_DUTY_CYCLE 100

// Define servo range
#define MIN_SERVO_ANGLE 25
#define MAX_SERVO_ANGLE 125

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to set the pan servo angle
void set_pan_angle(int angle) {
    // Clamp the angle to the valid range
    if (angle < MIN_SERVO_ANGLE) {
        angle = MIN_SERVO_ANGLE;
    } else if (angle > MAX_SERVO_ANGLE) {
        angle = MAX_SERVO_ANGLE;
    }

    // Calculate the duty cycle (500us - 2000us)
    int duty_cycle = 500 + (int)((angle - MIN_SERVO_ANGLE) * (1000.0 / (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE)));

    // Set the PWM duty cycle
    gpioPWM(PAN_SERVO_PIN, duty_cycle);
}

// Function to set the tilt servo angle
void set_tilt_angle(int angle) {
    // Clamp the angle to the valid range
    if (angle < MIN_SERVO_ANGLE) {
        angle = MIN_SERVO_ANGLE;
    } else if (angle > MAX_SERVO_ANGLE) {
        angle = MAX_SERVO_ANGLE;
    }

    // Calculate the duty cycle (500us - 2000us)
    int duty_cycle = 500 + (int)((angle - MIN_SERVO_ANGLE) * (1000.0 / (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE)));

    // Set the PWM duty cycle
    gpioPWM(TILT_SERVO_PIN, duty_cycle);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output (servo) or input (button)
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Set pull-up resistors for the buttons
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Initialize the servos to the mid-position (75)
    set_pan_angle(75);
    set_tilt_angle(75);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000)
    gpioSetPWMrange(PAN_SERVO_PIN, 1000);
    gpioSetPWMrange(TILT_SERVO_PIN, 1000);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read button states
        int tilt_up_pressed = gpioRead(TILT_UP_BUTTON) == 0;
        int tilt_down_pressed = gpioRead(TILT_DOWN_BUTTON) == 0;
        int pan_left_pressed = gpioRead(PAN_LEFT_BUTTON) == 0;
        int pan_right_pressed = gpioRead(PAN_RIGHT_BUTTON) == 0;

        // Adjust tilt if the tilt-up button is pressed
        if (tilt_up_pressed) {
            int current_tilt_angle = (gpioGetPWMdutycycle(TILT_SERVO_PIN) - 500) * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) / 500 + MIN_SERVO_ANGLE;
            current_tilt_angle += 5;
            if (current_tilt_angle > MAX_SERVO_ANGLE) {
                current_tilt_angle = MAX_SERVO_ANGLE;
            }
            set_tilt_angle(current_tilt_angle);
            gpioDelay(50000); // Debounce delay (50 ms)
        }

        // Adjust tilt if the tilt-down button is pressed
        if (tilt_down_pressed) {
            int current_tilt_angle = (gpioGetPWMdutycycle(TILT_SERVO_PIN) - 500) * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) / 500 + MIN_SERVO_ANGLE;
            current_tilt_angle -= 5;
            if (current_tilt_angle < MIN_SERVO_ANGLE) {
                current_tilt_angle = MIN_SERVO_ANGLE;
            }
            set_tilt_angle(current_tilt_angle);
            gpioDelay(50000); // Debounce delay (50 ms)
        }

        // Adjust pan if the pan-left button is pressed
        if (pan_left_pressed) {
            int current_pan_angle = (gpioGetPWMdutycycle(PAN_SERVO_PIN) - 500) * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) / 500 + MIN_SERVO_ANGLE;
            current_pan_angle -= 5;
            if (current_pan_angle < MIN_SERVO_ANGLE) {
                current_pan_angle = MIN_SERVO_ANGLE;
            }
            set_pan_angle(current_pan_angle);
            gpioDelay(50000); // Debounce delay (50 ms)
        }

        // Adjust pan if the pan-right button is pressed
        if (pan_right_pressed) {
            int current_pan_angle = (gpioGetPWMdutycycle(PAN_SERVO_PIN) - 500) * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) / 500 + MIN_SERVO_ANGLE;
            current_pan_angle += 5;
            if (current_pan_angle > MAX_SERVO_ANGLE) {
                current_pan_angle = MAX_SERVO_ANGLE;
            }
            set_pan_angle(current_pan_angle);
            gpioDelay(50000); // Debounce delay (50 ms)
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10 ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

