#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75

// Structure to hold camera buffers
struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd                  = -1;
static struct buffer         *buffers            = NULL;
static unsigned int          n_buffers          = 0;
static unsigned int          frame_number        = 0;
static FILE                 *jpeg_file           = NULL;
static unsigned char         *blurred_image      = NULL;
static unsigned int          blurred_image_size = 0;
static volatile sig_atomic_t keep_running       = 1;

// Signal handler for Ctrl+C
static void
sigint_handler (int sig)
{
  (void)sig; // Suppress unused parameter warning
  keep_running = 0;
}

// Function to generate a timestamp string
static char*
generate_timestamp ()
{
  time_t rawtime;
  struct tm *timeinfo;
  char *timestamp = (char*)malloc (20 * sizeof (char)); // Allocate memory for the timestamp
  if (timestamp == NULL) {
    perror ("malloc");
    exit (EXIT_FAILURE);
  }

  time (&rawtime);
  timeinfo = localtime (&rawtime);

  strftime (timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
  return timestamp;
}

// Function to convert YUYV to RGB24
static void
yuyv_to_rgb24 (unsigned char *yuyv, unsigned char *rgb, int width, int height)
{
  int i, j;
  unsigned char *py, *pu, *pv;
  unsigned char *pr, *pg, *pb;
  int y, u, v, r, g, b;

  for (i = 0; i < height; i++) {
    for (j = 0; j < width; j += 2) {
      // Get YUYV values
      py = yuyv + (i * width + j) * 2;
      pu = py + 1;
      pv = py + 3;

      // Get RGB values
      y = py[0];
      u = pu[0] - 128;
      v = pv[0] - 128;

      r = y + 1.370705 * v;
      g = y - 0.698001 * v - 0.336331 * u;
      b = y + 1.732446 * u;

      // Clamp RGB values to the range [0, 255]
      if (r < 0) r = 0;
      if (r > 255) r = 255;
      if (g < 0) g = 0;
      if (g > 255) g = 255;
      if (b < 0) b = 0;
      if (b > 255) b = 255;

      // Store RGB values
      pr = rgb + (i * width + j) * 3;
      pg = pr + 1;
      pb = pr + 2;
      pr[0] = r;
      pg[0] = g;
      pb[0] = b;

      // Get YUYV values for the next pixel
      y = py[2];
      u = pu[1] - 128;
      v = pv[1] - 128;

      r = y + 1.370705 * v;
      g = y - 0.698001 * v - 0.336331 * u;
      b = y + 1.732446 * u;

      // Clamp RGB values to the range [0, 255]
      if (r < 0) r = 0;
      if (r > 255) r = 255;
      if (g < 0) g = 0;
      if (g > 255) g = 255;
      if (b < 0) b = 0;
      if (b > 255) b = 255;

      // Store RGB values
      pr = rgb + (i * width + j + 1) * 3;
      pg = pr + 1;
      pb = pr + 2;
      pr[0] = r;
      pg[0] = g;
      pb[0] = b;
    }
  }
}

// Function to apply a Gaussian blur filter
static void
gaussian_blur (unsigned char *image, unsigned char *blurred_image, int width, int height, int radius)
{
  int i, j, x, y, sum, r, g, b;
  unsigned char *pixel;
  unsigned char *image_row;
  unsigned char *blurred_row;

  // Allocate memory for image rows
  image_row = (unsigned char*)malloc (width * 3 * sizeof (unsigned char));
  blurred_row = (unsigned char*)malloc (width * 3 * sizeof (unsigned char));
  if (!image_row || !blurred_row) {
    perror ("malloc");
    exit (EXIT_FAILURE);
  }

  // Copy the original image to the image row buffer
  for (y = 0; y < height; y++) {
    for (x = 0; x < width; x++) {
      pixel = &image[y * width + x * 3];
      for (i = 0; i < 3; i++) {
        image_row[y * width + x * 3 + i] = pixel[i];
      }
    }
  }

  // Blur each pixel
  for (y = 0; y < height; y++) {
    for (x = 0; x < width; x++) {
      sum = 0;
      r = g = b = 0;
      for (i = -radius; i <= radius; i++) {
        for (j = -radius; j <= radius; j++) {
          if (x + i >= 0 && x + i < width && y + j >= 0 && y + j < height) {
            pixel = &image_row[y * width + (x + i) * 3];
            sum += pixel[0] * pixel[0] + pixel[1] * pixel[1] + pixel[2] * pixel[2];
            r += pixel[0];
            g += pixel[1];
            b += pixel[2];
          }
        }
      }
      // Calculate the average RGB value
      r /= (radius * radius * 2 + 1);
      g /= (radius * radius * 2 + 1);
      b /= (radius * radius * 2 + 1);

      // Store the blurred pixel
      blurred_row[y * width + x * 3] = r;
      blurred_row[y * width + (x * 3) + 1] = g;
