    fprintf (stderr, "JPEG encoding failed\n");
    fclose (jpeg_file);
    return -1;
  }

  fclose (jpeg_file);

  printf ("Saved image as %s\n", filename);

  return 0;
}

// Function to stop streaming
static int
stop_streaming ()
{
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  if (ioctl (fd, VIDIOC_STREAMOFF, &type) < 0) {
    perror ("VIDIOC_STREAMOFF");
    return -1;
  }
  return 0;
}

// Function to unmap buffers
static int
unmap_buffers ()
{
  unsigned int i;
  for (i = 0; i < n_buffers; i++) {
    if (munmap (buffers[i].start, buffers[i].length) < 0) {
      perror ("munmap");
      return -1;
    }
  }
  return 0;
}

// Function to free buffers
static int
free_buffers ()
{
  free (buffers);
  return 0;
}

// Function to close the file descriptor
static int
close_fd ()
{
  if (close (fd) < 0) {
    perror ("close");
    return -1;
  }
  return 0;
}

int main ()
{
  unsigned char *frame_data = NULL;
  unsigned long frame_size = 0;
  unsigned char *rgb = NULL;
  unsigned char *blurred_image_temp = NULL;
  unsigned long blurred_image_temp_size = 0;
  int ret;

  // Install signal handler
  signal (SIGINT, sigint_handler);

  // Initialize camera
  if (init_camera () < 0) {
    fprintf (stderr, "Camera initialization failed\n");
    return EXIT_FAILURE;
  }

  // Main loop
  while (keep_running) {
    // Capture frame
    ret = capture_frame (&frame_data, &frame_size);
    if (ret < 0) {
      fprintf (stderr, "Frame capture failed\n");
      break;
    }

    // Process frame
    ret = process_frame (frame_data, rgb, IMAGE_WIDTH, IMAGE_HEIGHT);
    if (ret < 0) {
      fprintf (stderr, "Frame processing failed\n");
      break;
    }

    // Encode JPEG
    ret = encode_jpeg_frame ();
    if (ret < 0) {
      fprintf (stderr, "JPEG encoding failed\n");
      break;
    }

    // Free frame data
    free (frame_data);
    frame_data = NULL;
  }

  // Stop streaming
  if (stop_streaming () < 0) {
    fprintf (stderr, "Stream stopping failed\n");
  }

  // Unmap buffers
  if (unmap_buffers () < 0) {
    fprintf (stderr, "Buffer unmapping failed\n");
  }

  // Free buffers
  if (free_buffers () < 0) {
    fprintf (stderr, "Buffer freeing failed\n");
  }

  // Close file descriptor
  if (close_fd () < 0) {
    fprintf (stderr, "File descriptor closing failed\n");
  }

  // Clean up blurred image
  if(blurred_image != NULL){
    free(blurred_image);
  }

  return EXIT_SUCCESS;
}

