    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_ctrl focus_ctrl;
    enum v4l2_ctrl_type ctrl_type;
    unsigned int index;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);

    printf("Supported Frame Sizes:\n");
    frmsize.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  %d: %d x %d\n", frmsize.type, frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    printf("Supported Frame Intervals:\n");
    frmival.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("  %d: %f fps\n", frmival.type, 1.0 / frmival.discrete.numerator);
        frmival.index++;
    }

    printf("Autofocus Support:\n");
    focus_ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_ctrl) == 0) {
        if (focus_ctrl.type == V4L2_CTRL_TYPE_BOOLEAN) {
            printf("  Yes\n");
        } else {
            printf("  No (Control type: %d)\n", focus_ctrl.type);
        }
    } else {
        printf("  No (ioctl failed)\n");
    }

    close(fd);
    return 0;
}

