#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_RANGE 2000

// Define PWM increment/decrement step (microseconds)
#define PWM_STEP 10

// Define center position (microseconds)
#define CENTER_POSITION 1500

// Global variables
volatile int pan_pulse_width = CENTER_POSITION;
volatile int tilt_pulse_width = CENTER_POSITION;
volatile int running = 1; // Flag to control the main loop

// Function prototypes
void signal_handler(int signal);
void update_servos();
void button_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Stop PWM on both servo pins
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to update servo pulse widths based on button presses
void update_servos() {
    if (gpioRead(UP_BUTTON_PIN) == 0) { // Button is pressed (active low)
        if (pan_pulse_width < PWM_RANGE) {
            pan_pulse_width += PWM_STEP;
            if (pan_pulse_width > PWM_RANGE) pan_pulse_width = PWM_RANGE;
        }
    }
    if (gpioRead(DOWN_BUTTON_PIN) == 0) {
        if (pan_pulse_width > 1000) {
            pan_pulse_width -= PWM_STEP;
            if (pan_pulse_width < 1000) pan_pulse_width = 1000;
        }
    }

    if (gpioRead(LEFT_BUTTON_PIN) == 0) {
        if (tilt_pulse_width < PWM_RANGE) {
            tilt_pulse_width += PWM_STEP;
            if (tilt_pulse_width > PWM_RANGE) tilt_pulse_width = PWM_RANGE;
        }
    }
    if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
        if (tilt_pulse_width > 1000) {
            tilt_pulse_width -= PWM_STEP;
            if (tilt_pulse_width < 1000) tilt_pulse_width = 1000;
        }
    }
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button is pressed (active low)
        update_servos();
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Print startup message
    printf("Servo control program started\n");
    printf("Pan servo (GPIO %d) controls with UP/DOWN buttons (GPIO %d/%d)\n", PAN_SERVO_PIN, UP_BUTTON_PIN, DOWN_BUTTON_PIN);
    printf("Tilt servo (GPIO %d) controls with LEFT/RIGHT buttons (GPIO %d/%d)\n", TILT_SERVO_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit\n");

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Set PWM duty cycle (initial center position)
    gpioPWM(PAN_SERVO_PIN, pan_pulse_width);
    gpioPWM(TILT_SERVO_PIN, tilt_pulse_width);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callbacks for button presses
    gpioSetAlertFunc(UP_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(DOWN_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(LEFT_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(RIGHT_BUTTON_PIN, button_callback);

    // Main loop
    while (running) {
        // Increment PWM pulse widths by 10 microseconds
        pan_pulse_width += 10;
        tilt_pulse_width += 10;

        // Clamp pulse widths to the allowed range
        if (pan_pulse_width > PWM_RANGE) pan_pulse_width = PWM_RANGE;
        if (tilt_pulse_width > PWM_RANGE) tilt_pulse_width = PWM_RANGE;
        if (pan_pulse_width < 1000) pan_pulse_width = 1000;
        if (tilt_pulse_width < 1000) tilt_pulse_width = 1000;

        // Set PWM duty cycles
        gpioPWM(PAN_SERVO_PIN, pan_pulse_width);
        gpioPWM(TILT_SERVO_PIN, tilt_pulse_width);

        // Delay for 50 milliseconds
        gpioDelay(50000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

