#define GPIO_PIN 17
#define DEBOUNCE_DELAY 2000 // milliseconds
#define POLL_DELAY 100      // milliseconds
#define JPEG_QUALITY 85
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080       // Replace with your server port
#define IMAGE_DIR "motion_captures"

static volatile int running = 1;
static int sockfd = -1; // Socket file descriptor

// Structure to hold image data
typedef struct {
    unsigned char *data;
    int width;
    int height;
    int components;
} image_data_t;

// Function prototypes
int init_gpio();
int read_sensor();
int capture_image(image_data_t *image);
int create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, image_data_t image, char *json_payload, size_t json_payload_size);
int post_data(const char *json_payload, image_data_t image);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Capture a JPEG image using libjpeg
int capture_image(image_data_t *image) {
    int width = 640;
    int height = 480;
    int components = 3; // RGB

    image->width = width;
    image->height = height;
    image->components = components;

    image->data = (unsigned char *)malloc(width * height * components);
    if (image->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for image data\n");
        return -1;
    }

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    unsigned char *outbuffer = NULL;
    unsigned long outsize = 0;

    jpeg_mem_dest(&cinfo, &outbuffer, &outsize);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = components;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * components;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image->data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    // Convert RGB to YCbCr (optional, for smaller file size)
    // This is a simplified conversion, not optimized for image quality
    for (int i = 0; i < width * height * components; i++) {
        unsigned char *rgb = &image->data[i];
        unsigned char *yc = &image->data[i];

        int r = rgb[0];
        int g = rgb[1];
        int b = rgb[2];

        int y = (r * 0.299) + (g * 0.587) + (b * 0.114);
        int cb = (r - y) * 0.565;
        int cr = (g - y) * 0.713;

        yc[0] = y;
        yc[1] = cb;
        yc[2] = cr;
    }

    return 0;
}

