int create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, image_data_t image, char *json_payload, size_t json_payload_size) {
    snprintf(json_payload, json_payload_size, 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d, \"image_data\": {\"data\": \"%s\", \"width\": %d, \"height\": %d, \"components\": %d}}",
             filename, timestamp, motion_status, gpio_pin,
             // Base64 encoding of image data would go here, but since we're only using it for filename, we skip it for simplicity.
             filename, image.width, image.height, image.components);
    return 0;
}

