        fprintf(stderr, "Error initializing WiringPi.\n");
        return -1;
    }

    pinMode(PIR_PIN, INPUT);
    pullUpDnControl(PIR_PIN, PUD_DOWN); // Use pull-down resistor

    return 0;
}

