int init_i2c(void) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-1"); // Standard I2C bus on Raspberry Pi
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

