    if (status == -1) {
        log_event("Error executing camera capture command.");
    } else if (WEXITSTATUS(status) != 0) {
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Camera capture failed with exit status %d.", WEXITSTATUS(status));
        log_event(log_message);
    }
}

