            current_pir_state = digitalRead(PIR_PIN); // Re-read after debounce

            if (current_pir_state != last_pir_state) {
                last_pir_state = current_pir_state;

                if (current_pir_state == HIGH) {
                    time_t now = time(NULL);
                    if (difftime(now, last_motion_time) > 1) { // Debounce: only trigger once per second
                        log_event("Motion detected!");
                        capture_image();
                        last_motion_time = now;
                    }
                }
            }
        }

        if (log_fd != -1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Motion sensor reading: %d", current_pir_state);
            dprintf(log_fd, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec, log_message);
        }

        delay(100); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_fd != -1) {
        close(log_fd);
    }

    printf("Exiting.\n");
    return 0;
}

