#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM range (microseconds)
#define PWM_RANGE 2000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    terminate = 1;
}

// Function to set the angle of a servo
int set_servo_angle(int gpio_pin, int angle)
{
    // Validate angle
    if (angle < MIN_ANGLE || angle > MAX_ANGLE)
    {
        fprintf(stderr, "Error: Angle out of range (0-%d)\n", MAX_ANGLE);
        return -1; // Indicate error
    }

    // Calculate pulse width (microseconds)
    int pulse_width = (int)(((float)angle / 180.0) * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(gpio_pin, pulse_width);

    return 0; // Indicate success
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Initialize servos to neutral position (90 degrees)
    if (set_servo_angle(PAN_SERVO_PIN, 90) != 0 || set_servo_angle(TILT_SERVO_PIN, 90) != 0)
    {
        fprintf(stderr, "Error: Failed to set initial servo position\n");
        gpioTerminate(); // Clean up before exiting
        return 1;        // Exit with error code
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (!terminate)
    {
        // Read input from stdin
        input = getchar();

        // Process input
        switch (input)
        {
        case 'a': // Arrow key left (pan)
            if (set_servo_angle(PAN_SERVO_PIN, 90 - 5) != 0)
            {
                fprintf(stderr, "Error: Failed to pan left\n");
            }
            break;
        case 'd': // Arrow key right (pan)
            if (set_servo_angle(PAN_SERVO_PIN, 90 + 5) != 0)
            {
                fprintf(stderr, "Error: Failed to pan right\n");
            }
            break;
        case 'w': // Arrow key up (tilt)
            if (set_servo_angle(TILT_SERVO_PIN, 90 - 5) != 0)
            {
                fprintf(stderr, "Error: Failed to tilt up\n");
            }
            break;
        case 's': // Arrow key down (tilt)
            if (set_servo_angle(TILT_SERVO_PIN, 90 + 5) != 0)
            {
                fprintf(stderr, "Error: Failed to tilt down\n");
            }
            break;
        case 'q': // 'q' character
            printf("Exiting...\n");
            break;
        default:
            // Ignore other characters
            break;
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    set_servo_angle(PAN_SERVO_PIN, 90); // Set pan to neutral
    set_servo_angle(TILT_SERVO_PIN, 90); // Set tilt to neutral
    gpioTerminate();                     // Terminate pigpio
    return 0;                            // Exit with success code
}

