        case 'q': // 'q' character
            printf("Exiting...\n");
            break;
        default:
            // Ignore other characters
            break;
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    set_servo_angle(PAN_SERVO_PIN, 90); // Set pan to neutral
    set_servo_angle(TILT_SERVO_PIN, 90); // Set tilt to neutral
    gpioTerminate();                     // Terminate pigpio
    return 0;                            // Exit with success code
}

