// Helper function to write a command to the OLED display
void oled_write_command(unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C Error: Failed to write command 0x%02X: %s\n", command, strerror(errno));
