// Function to draw a character at the specified position
void draw_char(int x, int y, char ch) {
    if (ch < 32 || ch > 126) ch = 0; // Handle out-of-range characters
    ch -= 32;

    for (int i = 0; i < 5; i++) {
        unsigned char pixel_data = font[ch][i];
        for (int j = 0; j < 8; j++) {
            if ((pixel_data >> j) & 0x01) {
                int byte_index = x + i + (y / 8) * OLED_WIDTH;
                if (byte_index >= 0 && byte_index < sizeof(display_buffer)) {
                    display_buffer[byte_index] |= (1 << (y % 8));
                }
            }
        }
    }
}

// Function to draw a string
void draw_string(int x, int y, const char *str) {
    while (*str) {
        draw_char(x, y, *str);
        x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to update the display with the contents of the buffer
void update_display() {
    oled_write_command(0x21); // Set column address
    oled_write_command(0x00); // Start column
    oled_write_command(OLED_WIDTH - 1); // End column

    oled_write_command(0x22); // Set page address
    oled_write_command(0x00); // Start page
    oled_write_command((OLED_HEIGHT / 8) - 1); // End page

    for (int i = 0; i < sizeof(display_buffer); i++) {
        oled_write_data(display_buffer[i]);
    }
}

// Function to read the CPU temperature from /sys/class/thermal/thermal_zone0/temp
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Failed to read temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Function to read the CPU usage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CPU stats file: %s\n", strerror(errno));
        return -1;
    }

    // Read initial CPU stats
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error: Failed to read initial CPU stats: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    sleep(1); // Wait for 1 second

    // Read CPU stats again
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Failed to read CPU stats: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Calculate CPU usage
    unsigned long long PrevIdle = prev_idle + prev_iowait;
    unsigned long long Idle = idle + iowait;

    unsigned long long PrevNonIdle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    unsigned long long NonIdle = user + nice + system + irq + softirq + steal;

    unsigned long long PrevTotal = PrevIdle + PrevNonIdle;
    unsigned long long Total = Idle + NonIdle;

    unsigned long long totald = Total - PrevTotal;
    unsigned long long idled = Idle - PrevIdle;

    cpu_usage = (float)(totald - idled) / totald;

    return (int)(cpu_usage * 100); // Return CPU usage as percentage
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize OLED display
    oled_init();
    clear_display();
    update_display();

    // Main loop
    while (!terminate) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        if (temp == -1 || usage == -1) {
            fprintf(stderr, "Error: Failed to read temperature or CPU usage. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        char temp_str[20];
        char usage_str[20];

        snprintf(temp_str, sizeof(temp_str), "Temp: %d C", temp);
        snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);

        clear_display();
        draw_string(0, 0, temp_str);
        draw_string(0, 16, usage_str);
        update_display();

        sleep(1); // Update every 1 second
    }

    // Cleanup
    close(i2c_fd);
    clear_display();
    update_display(); // Clear the display before exiting

    return EXIT_SUCCESS;
}

