#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Define constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
void lcd_init();
void lcd_clear();
void lcd_print(const char *message);
void lcd_update();

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH)
    {
        pulse_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }
    exit(0);
}

// LCD initialization function
void lcd_init()
{
    // Initialise display
    uint8_t init_sequence[] = {0x33, 0x32, 0x06, 0x0C, 0x28, 0x01, 0x08};
    for (int i = 0; i < sizeof(init_sequence); i++)
    {
        char buf[2];
        buf[0] = 0x80; // Command mode
        buf[1] = init_sequence[i];
        i2cWriteDevice(i2c_handle, buf, 2);
        gpioDelay(5000); // 5ms delay
    }
    lcd_clear();
}

// LCD clear function
void lcd_clear()
{
    char buf[2];
    buf[0] = 0x80; // Command mode
    buf[1] = 0x01; // Clear display command
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(2000); // 2ms delay
}

// LCD print function
void lcd_print(const char *message)
{
    char buf[17]; // Enough to hold a string and a command byte
    buf[0] = LCD_CHR;
    strncpy(buf + 1, message, LCD_WIDTH - 1);
    buf[LCD_WIDTH] = '\0'; // Ensure null termination

    i2cWriteDevice(i2c_handle, buf, LCD_WIDTH + 1);
}

// LCD update function
void lcd_update()
{
    char buf[17];
    buf[0] = LCD_CMD;
    sprintf(buf + 1, "%.2f ml/min", total_volume / 1000.0 / 60.0);
    buf[LCD_WIDTH + 1] = '\0';
    i2cWriteDevice(i2c_handle, buf, LCD_WIDTH + 1);

    buf[0] = LCD_CHR;
    sprintf(buf + 1, "%.0f L", total_volume / 1000.0);
    buf[LCD_WIDTH + 1] = '\0';
    i2cWriteDevice(i2c_handle, buf, LCD_WIDTH + 1);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Set up interrupt callback for pulse counting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

    // Initialize I2C for LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);
    time_t last_lcd_update = time(NULL);

    // Main loop
    while (running)
    {
        // Calculate flow rate and total volume every second
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1)
        {
            double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0;
            total_volume += (double)pulse_count / PULSES_PER_LITER;
            pulse_count = 0;
            last_log_time = current_time;

            printf("Flow Rate: %.2f ml/min, Total Volume: %.2f L\n", flow_rate, total_volume / 1000.0);
        }

        // Update LCD every ten seconds
        time_t current_time_lcd = time(NULL);
        if (current_time_lcd - last_lcd_update >= 10)
        {
            lcd_clear();
            lcd_print("Flow Rate:");
            char buf[20];
            sprintf(buf, "%.2f ml/min", total_volume / 1000.0 / 60.0);
            lcd_print(buf);
            lcd_update();
            last_lcd_update = current_time_lcd;
        }

        gpioDelay(100); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    i2cClose(i2c_handle);
    return 0;
}

