#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

// Configuration
#define ANEMOMETER_PIN 17 // BCM GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS 1
#define LCD_ADDR 0x27 // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define DIAGNOSTIC_BUFFER_SIZE 64

// Global variables
volatile int pulse_count = 0;
int spi_fd;
int i2c_fd;
FILE *log_file;

// Diagnostic buffer
char diagnostic_buffer[DIAGNOSTIC_BUFFER_SIZE];
int diagnostic_buffer_index = 0;

// Function prototypes
void anemometer_interrupt_handler(void);
float calculate_wind_speed(int pulses);
int read_wind_direction(void);
void lcd_init(void);
void lcd_clear(void);
void lcd_set_cursor(int row, int col);
void lcd_print(const char *text);
void log_message(const char *message);
void signal_handler(int signal);
void send_data_to_server(float wind_speed, int wind_direction);
void handle_i2c_error(int error_code);
void handle_spi_error(int error_code);
void handle_wiringpi_error(int error_code);

// Anemometer interrupt handler
void anemometer_interrupt_handler(void)
{
    pulse_count++;
}

// Calculate wind speed (m/s) from pulse count
float calculate_wind_speed(int pulses)
{
    // Assuming 1 pulse per rotation and 2 seconds for 500ms sample window
    // Pulses per second = pulses / 2
    // Wind speed = pulses / 2 * 2 * 0.44704
    // 0.44704 is the conversion factor from pulses/second to m/s
    return (float)pulses / 2 * 2 * 0.44704;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction(void)
{
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | (SPI_CHANNEL << 4)) << 4; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// LCD initialization
void lcd_init(void)
{
    // Initialization sequence (refer to PCF8574 datasheet)
    delay(50); // Wait for more than 4.1ms after VCC rises to 2.7V
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    delay(5); // Wait for more than 4.1ms
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    delay(1); // Wait for more than 100us
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    delay(1); // Wait for more than 100us
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x0C); // Display control: Display on, cursor off, blink off
    delay(1); // Wait for more than 100us
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x06); // Entry mode set: Increment cursor, no shift
