#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Change if your LCD has a different address
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define PULSE_TIMEOUT_SEC 5

// Global variables
volatile int pulse_count = 0;
int i2c_fd;
int lcd_backlight = 0; // LCD backlight control

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
int lcd_init();
int lcd_clear();
int lcd_write_string(int row, int col, const char *str);
int lcd_write_char(int row, int col, char c);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Count rising edges
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses)
{
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// LCD initialization function
int lcd_init()
{
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x0C); // Display control: Display on, cursor off, blink off
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x06); // Entry mode set: Increment cursor, no shift
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display
    gpioDelay(2); // Delay for clear display command
    return 0;
}

// LCD clear display function
int lcd_clear()
{
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display command
    gpioDelay(2); // Delay for clear display command
    return 0;
}

// LCD write string function
int lcd_write_string(int row, int col, const char *str)
{
    int i;
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x80 | (row * 0x40 + col)); // Set cursor position
    for (i = 0; str[i] != '\0'; i++)
    {
        wiringPiI2CWriteReg8(i2c_fd, 0x00, str[i]);
    }
    return 0;
}

// LCD write character function
int lcd_write_char(int row, int col, char c)
{
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x80 | (row * 0x40 + col)); // Set cursor position
    wiringPiI2CWriteReg8(i2c_fd, 0x00, c);
    return 0;
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate)
{
    char buffer[20];
    lcd_clear();
    lcd_write_string(0, 0, "Flow Rate:");
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_write_string(1, 0, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize wiringPi I2C
    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd == -1)
    {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0)
    {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_pulse_time = time(NULL);
    int no_pulse_count = 0;

    while (1)
    {
        // Measure flow rate over 1-second interval
        int total_pulses = 0;
        time_t start_time = time(NULL);
        while (time(NULL) - start_time < SAMPLE_INTERVAL_SEC)
        {
            if (gpioRead(FLOW_SENSOR_GPIO) == 1) // Check if the sensor is present
            {
                total_pulses++;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(total_pulses);

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Check for sensor absent condition
        time_t current_time = time(NULL);
        if (total_pulses == 0)
        {
            no_pulse_count++;
            if (no_pulse_count * SAMPLE_INTERVAL_SEC >= PULSE_TIMEOUT_SEC)
            {
                lcd_clear();
                lcd_write_string(0, 0, "Sensor Absent!");
                gpioDelay(2000); // Display error for 2 seconds
                lcd_clear();
                no_pulse_count = 0; // Reset counter after displaying error
            }
        } else {
            no_pulse_count = 0; // Reset counter if pulses are detected
        }

        // Delay before next measurement
        gpioDelay(100); // Reduced delay to improve responsiveness
    }

    // Cleanup (should not reach here due to signal handler)
    gpioTerminate();
    return 0;
}

