    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd == -1)
    {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0)
    {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_pulse_time = time(NULL);
    int no_pulse_count = 0;

    while (1)
    {
        // Measure flow rate over 1-second interval
        int total_pulses = 0;
        time_t start_time = time(NULL);
        while (time(NULL) - start_time < SAMPLE_INTERVAL_SEC)
        {
            if (gpioRead(FLOW_SENSOR_GPIO) == 1) // Check if the sensor is present
            {
                total_pulses++;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(total_pulses);

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Check for sensor absent condition
        time_t current_time = time(NULL);
        if (total_pulses == 0)
        {
            no_pulse_count++;
            if (no_pulse_count * SAMPLE_INTERVAL_SEC >= PULSE_TIMEOUT_SEC)
            {
                lcd_clear();
                lcd_write_string(0, 0, "Sensor Absent!");
                gpioDelay(2000); // Display error for 2 seconds
                lcd_clear();
                no_pulse_count = 0; // Reset counter after displaying error
            }
        } else {
            no_pulse_count = 0; // Reset counter if pulses are detected
        }

        // Delay before next measurement
        gpioDelay(100); // Reduced delay to improve responsiveness
    }

    // Cleanup (should not reach here due to signal handler)
    gpioTerminate();
    return 0;
}

