        return 1;
    }

    // Set row pins as outputs
    int row_pins[] = {ROW_1, ROW_2, ROW_3, ROW_4, ROW_5, ROW_6, ROW_7, ROW_8};
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set mode for row pin %d\n", row_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(row_pins[i], 0); // Initialize to LOW (common anode)
    }

    // Set column pins as outputs
    int col_pins[] = {COL_1, COL_2, COL_3, COL_4, COL_5, COL_6, COL_7, COL_8};
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set mode for column pin %d\n", col_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(col_pins[i], 1); // Initialize to HIGH (cathode)
    }

    return 0;
}

// Function to clear the LED matrix (turn off all LEDs)
void clear_matrix() {
    int row_pins[] = {ROW_1, ROW_2, ROW_3, ROW_4, ROW_5, ROW_6, ROW_7, ROW_8};
    for (int i = 0; i < 8; i++) {
        gpioWrite(row_pins[i], 0); // Set row to LOW (common anode)
    }
    int col_pins[] = {COL_1, COL_2, COL_3, COL_4, COL_5, COL_6, COL_7, COL_8};
    for (int i = 0; i < 8; i++) {
        gpioWrite(col_pins[i], 1); // Set column to HIGH (cathode)
    }
}

// Function to display a single frame of the animation
void display_frame(int frame_number) {
    int row_pins[] = {ROW_1, ROW_2, ROW_3, ROW_4, ROW_5, ROW_6, ROW_7, ROW_8};
    int col_pins[] = {COL_1, COL_2, COL_3, COL_4, COL_5, COL_6, COL_7, COL_8};

    // Calculate the starting index for the left-to-right animation
    int left_to_right_index = frame_number % 256;

    // Calculate the starting index for the right-to-left animation
    int right_to_left_index = 255 - (frame_number % 256);

    // Set up the row and column pins
    for (int i = 0; i < 8; i++) {
        gpioWrite(row_pins[i], 1); // Set row to HIGH (common anode)
        gpioWrite(col_pins[i], 0); // Set column to LOW (cathode)
    }

    // Render the left-to-right animation
    for (int i = 0; i < 8; i++) {
        gpioWrite(row_pins[i], 0); // Set row to LOW (common anode)
        gpioWrite(col_pins[i], 1); // Set column to HIGH (cathode)

        if (left_to_right_index & (1 << i)) {
            gpioWrite(row_pins[i], 1); // Turn on the LED if the bit is set
        }
    }

    // Render the right-to-left animation
    for (int i = 0; i < 8; i++) {
        gpioWrite(row_pins[i], 1); // Set row to HIGH (common anode)
        gpioWrite(col_pins[i], 0); // Set column to LOW (cathode)

        if (right_to_left_index & (1 << i)) {
            gpioWrite(row_pins[i], 0); // Turn off the LED if the bit is set
        }
    }

    gpioDelay(ANIMATION_DELAY); // Delay for the frame duration
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to display the animations
    while (!terminate) {
        // Display the left-to-right animation
        for (int i = 0; i < 256; i++) {
            display_frame(i);
        }

        // Display the right-to-left animation
        for (int i = 0; i < 256; i++) {
            display_frame(i);
        }
    }

    // Clean up and terminate the pigpio library
    clear_matrix(); // Clear the matrix before exiting
    gpioTerminate();

    return 0;
}

