// Define GPIO pins for rows and columns
int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};

// Number of rows and columns
#define NUM_ROWS 8
#define NUM_COLS 8

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Set all row pins to LOW
    for (int i = 0; i < NUM_ROWS; i++)
    {
        gpioWrite(row_pins[i], 0);
    }

    // Set all column pins to HIGH (turn off all LEDs)
    for (int i = 0; i < NUM_COLS; i++)
    {
        gpioWrite(col_pins[i], 1);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set row pins as output
    for (int i = 0; i < NUM_ROWS; i++)
    {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 0); // Initialize to LOW (off)
    }

    // Set column pins as output
    for (int i = 0; i < NUM_COLS; i++)
    {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize to HIGH (off)
    }

    // Main loop for wave animation
    while (1)
    {
        // Clear the matrix (set all column pins HIGH)
        for (int i = 0; i < NUM_COLS; i++)
        {
            gpioWrite(col_pins[i], 1);
        }
        gpioDelay(150000); // 150ms delay

        // Light up the matrix row by row, scanning from left to right
        for (int row = 0; row < NUM_ROWS; row++)
        {
            // Set the row pin HIGH
            gpioWrite(row_pins[row], 1);

            // Scan through the columns
            for (int col = 0; col < NUM_COLS; col++)
            {
                // Set the column pin LOW
                gpioWrite(col_pins[col], 0);
                gpioDelay(10000); // 10ms delay

                // Set the column pin HIGH
                gpioWrite(col_pins[col], 1);
                gpioDelay(10000); // 10ms delay
            }

            // Set the row pin LOW
            gpioWrite(row_pins[row], 0);
        }
    }

    return 0;
}

