#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// VL53L3CX register addresses (Example - refer to datasheet for complete list)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L3CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L3CX_REG_SYSRANGE_START 0x0015
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single byte from the VL53L3CX
int vl53l3cx_read_byte(int handle, uint16_t reg_addr, uint8_t *data) {
    char buf[2];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;      // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address to VL53L3CX\n");
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error reading byte from VL53L3CX\n");
        return -1;
    }

    return 0;
}

// Function to write a single byte to the VL53L3CX
int vl53l3cx_write_byte(int handle, uint16_t reg_addr, uint8_t data) {
    char buf[3];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;      // LSB of register address
    buf[2] = data;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing byte to VL53L3CX\n");
        return -1;
    }

    return 0;
}

// Function to read a word (2 bytes) from the VL53L3CX
int vl53l3cx_read_word(int handle, uint16_t reg_addr, uint16_t *data) {
    char buf[2];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;      // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address to VL53L3CX\n");
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading word from VL53L3CX\n");
        return -1;
    }

    return 0;
}

// Function to initialize the VL53L3CX sensor
int vl53l3cx_init(int handle) {
    uint8_t model_id;

    // Check sensor ID (Example - refer to datasheet for correct register and value)
    if (vl53l3cx_read_byte(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID from VL53L3CX\n");
        return -1;
    }

    if (model_id != 0xE1) { // Expected model ID for VL53L3CX
        fprintf(stderr, "Incorrect model ID (0x%02X) from VL53L3CX\n", model_id);
        return -1;
    }

    // Example initialization sequence (refer to VL53L3CX datasheet for complete sequence)
    if (vl53l3cx_write_byte(handle, 0x02D8, 0x01) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02D9, 0x02) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DA, 0x03) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DB, 0x04) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DC, 0x05) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DD, 0x06) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DE, 0x07) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02DF, 0x08) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02E0, 0x09) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02E1, 0x0A) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02E2, 0x0B) != 0) return -1;
    if (vl53l3cx_write_byte(handle, 0x02E3, 0x0C) != 0) return -1;
