#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address for the MLX75031
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A

// Define the register address for distance data (replace with actual value from datasheet)
#define DISTANCE_REG 0x00

// Define the filename for logging
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    const char *log_filename;
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C interface
int initialize(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance data from the MLX75031
int read_distance() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a single distance value (adjust based on datasheet)
    int distance = (buf[0] << 8) | buf[1];

    return distance;
}

// Function to log data to a CSV file
void log_data(int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }

        // Check if the file is newly created and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Distance (mm)\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75031_ADDR,
        .log_filename = LOG_FILE
    };

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio and I2C
    if (initialize(&config) != 0) {
        return 1;
    }

    printf("MLX75031 Distance Logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();

        if (distance >= 0) {
            log_data(distance);
        } else {
            // Log error to file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,Error reading distance\n", timestamp);
            fflush(log_file);

            // Attempt to re-open I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                terminate = 1; // Exit if re-opening fails
            }
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

