int detect_falling_edge() {
    static int last_state = 1; // Assume initially no object detected (HIGH)
    int current_state = read_sensor();

    if (current_state == 0 && last_state == 1) { // Falling edge detected
        last_state = current_state;
        return 1;
    } else if (current_state != last_state) {
        last_state = current_state;
    }

    return 0;
}

