            printf("Object detected!\n");
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            blink_led();
        }
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    gpioTerminate();
    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

