#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_proximity();
int read_ambient_light();
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Si1145 initialization function
int si1145_init() {
    // Check PART_ID register
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PARTID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Initialize sensor (example configuration - adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) return -1; // PS_LED21_SELECT
    if (i2cWriteByteData(i2c_handle, 0x19, 0x77) < 0) return -1; // PS_LED21_DUTYCYCLE
    if (i2cWriteByteData(i2c_handle, 0x03, 0x00) < 0) return -1; // MEAS_RATE
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) return -1; // ALS_RATE

    return 0;
}

// Function to read proximity data
int read_proximity() {
    int proximity = i2cReadWordData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity);
        return -1;
    }
    return proximity;
}

// Function to read ambient light data
int read_ambient_light() {
    int ambient_light = i2cReadWordData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (ambient_light < 0) {
        fprintf(stderr, "Error reading ambient light data: %d\n", ambient_light);
        return -1;
    }
    return ambient_light;
}

// Function to log data to file
void log_data(int proximity, int ambient_light) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

