#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27

#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define WATER_THRESHOLD 15.0
#define TIMEOUT_US 30000 // 30ms

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        uint32_t start_tick = 0, end_tick = 0;
        int echo_timeout = 0;

        // Wait for echo start
        int timeout_counter = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1us
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_US) {
            fprintf(log_file, "%s Sensor absent or timeout waiting for echo start\n", get_iso8601_timestamp());
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        start_tick = gpioTick();

        // Wait for echo end
        timeout_counter = 0;
        while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1);
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_US) {
            fprintf(log_file, "%s Echo timeout waiting for echo end\n", get_iso8601_timestamp());
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        end_tick = gpioTick();

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

        // Validate distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "%s Distance out of range: %.2f cm\n", get_iso8601_timestamp(), distance);
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        // Log distance
        fprintf(log_file, "%s Distance: %.2f cm\n", get_iso8601_timestamp(), distance);
        fflush(log_file);

        // Watering plant logic
        if (distance < WATER_THRESHOLD) {
            fprintf(log_file, "%s Time to water the plant!\n", get_iso8601_timestamp());
            fflush(log_file);
        }

    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program terminated.\n");
    return 0;
}

char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

