    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor() {
    int result = i2cWriteByteData(i2c_handle, TRIGGER_REG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to trigger register: %d\n", result);
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_MS * 1000); // Delay in microseconds
    return 0;
}

