int read_distance(int *distance) {
    int raw_distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (raw_distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", raw_distance);
        return -1;
    }
    *distance = raw_distance;
    return 0;
}

