#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A // Default I2C address
#define DISTANCE_REG 0x00 // Register to read distance from (example)
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_distance(float *distance);
void control_led(float distance);
void log_data(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C bus initialized successfully.\n");
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    gpioWrite(LED_GPIO, 0); // Initially turn the LED off
    printf("GPIO initialized successfully.\n");
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    }

    // Assuming the distance is a 16-bit value in centimeters
    int16_t raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance / 10.0; // Convert to cm

    return 0;
}

// Control the LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log data to file
void log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Release GPIO
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_led(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

