#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x10
#define REG_PS1_DATA0 0x18

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t proximity;
    uint16_t ambient_light;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int write_register(int reg, int value);
int read_register(int reg, uint8_t *value);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Basic sensor check (read Part ID register)
    uint8_t part_id;
    if (read_register(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    printf("Si1182 Part ID: 0x%02X\n", part_id);

    return 0;
}

// Function to write to a register
int write_register(int reg, int value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to register 0x%02X: %d, retries left: %d\n", reg, result, retries);
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    return -1; // Failure after retries
}

// Function to read from a register
int read_register(int reg, uint8_t *value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "Error reading from register 0x%02X: %d, retries left: %d\n", reg, result, retries);
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    return -1; // Failure after retries
}

