    if (read_register(REG_ALS_VIS_DATA0 + 1, &als_data[1]) != 0) return -1;
    if (read_register(REG_PS1_DATA0, &ps_data[0]) != 0) return -1;
    if (read_register(REG_PS1_DATA0 + 1, &ps_data[1]) != 0) return -1;

    data->ambient_light = (uint16_t)als_data[0] | ((uint16_t)als_data[1] << 8);
    data->proximity = (uint16_t)ps_data[0] | ((uint16_t)ps_data[1] << 8);

    return 0;
}

