#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x50

// Define the command frame (replace with actual command from datasheet)
const uint8_t command_frame[] = {0x01, 0x02, 0x03, 0x04};

// Define the header value (replace with actual header value from datasheet)
const uint8_t header_value = 0xAA;

// Define the number of measurements per cycle
#define NUM_MEASUREMENTS 10

// Define the delay between cycles (in milliseconds)
#define CYCLE_DELAY 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint8_t header;
    uint16_t distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(const uint8_t *command, int length);
int read_response(uint8_t *response, int length);
int verify_header(const uint8_t *response, int length);
uint16_t extract_distance(const uint8_t *response);
float calculate_average_distance(uint16_t distances[], int num_measurements);
void log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(const uint8_t *command, int length) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, length);
    if (result != length) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a response from the sensor
int read_response(uint8_t *response, int length) {
    int result = i2cReadDevice(i2c_handle, (char *)response, length);
    if (result != length) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to verify the header byte
int verify_header(const uint8_t *response, int length) {
    if (response[0] != header_value) {
        fprintf(stderr, "Error: Invalid header value: 0x%02X\n", response[0]);
        return -1;
    }
    return 0;
}

// Function to extract the distance from the response
uint16_t extract_distance(const uint8_t *response) {
    return (uint16_t)((response[11] << 8) | response[12]);
}

// Function to calculate the average distance
float calculate_average_distance(uint16_t distances[], int num_measurements) {
    float sum = 0.0;
    for (int i = 0; i < num_measurements; i++) {
        sum += distances[i];
    }
    return sum / num_measurements;
}

// Function to log intrusion events
void log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, Average Distance: %.2f mm\n", timestamp, average_distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t response[16]; // Buffer to store the 15-byte response + null terminator
        uint16_t distances[NUM_MEASUREMENTS];

        // Send command
        if (send_command(command_frame, sizeof(command_frame)) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for 10ms
        gpioDelay(10);

        // Read response
        if (read_response(response, sizeof(response)) != 0) {
            fprintf(stderr, "Error reading response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify header
        if (verify_header(response, sizeof(response)) != 0) {
            fprintf(stderr, "Error verifying header, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract distances
        for (int i = 0; i < NUM_MEASUREMENTS; i++) {
            distances[i] = extract_distance(response);
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, NUM_MEASUREMENTS);

        // Check for intrusion
        if (average_distance < 1000.0) {
            log_intrusion(average_distance);
        }

        // Delay before next cycle
        gpioDelay(CYCLE_DELAY);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

