#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS      0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C register
int i2c_read_word(int handle, uint8_t reg, uint16_t *data) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (uint16_t)result;
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x(int handle) {
    uint8_t model_id;

    // Read the model ID
    if (i2c_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }

    // Verify the model ID
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02x (expected 0xEA)\n", model_id);
        return -1;
    }

    // Initialize the sensor (simplified initialization sequence)
    if (i2c_write_byte(handle, 0x02d, 0x01) != 0) return -1;
    if (i2c_write_byte(handle, 0x02e, 0x01) != 0) return -1;
    if (i2c_write_byte(handle, 0x001, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x002, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x003, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x004, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x005, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x006, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x007, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x008, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x009, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x00a, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x00b, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x00c, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x00d, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, 0x00e, 0x00) != 0) return -1;
