#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x60

// Si1182 register addresses (Example - adjust based on datasheet)
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_ALS_VIS_DATA0 0x10
#define SI1182_REG_ALS_VIS_DATA1 0x11
#define SI1182_REG_PS1_DATA0 0x12
#define SI1182_REG_PS1_DATA1 0x13

// I2C handle
int i2c_handle;

// Function prototypes
int si1182_init();
int read_proximity_data(uint16_t *proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Si1182 initialization function
int si1182_init() {
    // Check if the sensor is present by writing to a register and checking for NACK
    char buf[1];
    buf[0] = SI1182_REG_PART_ID; // Register to read device ID

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error: Si1182 not detected on I2C bus (error code %d)\n", result);
        return -1;
    }

    // Add more initialization commands here based on the Si1182 datasheet
    // For example, configuring parameters, enabling measurements, etc.

    return 0;
}

// Function to read proximity data from the Si1182
int read_proximity_data(uint16_t *proximity) {
    char buf[1];
    char data[2];

    // Write the register address to read from
    buf[0] = SI1182_REG_PS1_DATA0; // Register to read proximity data from
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (error code %d)\n", result);
        return -1;
    }

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (error code %d)\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *proximity = (data[1] << 8) | data[0];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t proximity_data;
    while (1) {
        if (read_proximity_data(&proximity_data) == 0) {
            printf("Proximity data: %u\n", proximity_data);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

