#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00 // Example register address, adjust as needed

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_read_data(int fd, int reg) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading data");
        return -1;
    }

    return buf[0];
}

int i2c_write_data(int fd, int reg, int data) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing data");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = i2c_setup(I2C_BUS, MLX75030_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    while (keep_running) {
        int distance = i2c_read_data(i2c_fd, DISTANCE_REG);
        if (distance >= 0) {
