#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measure_pulse()
{
    long start_tick, end_tick, pulse_duration;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo pulse timeout (rising edge)\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo pulse timeout (falling edge)\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0)
    {
        pulse_duration += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_duration;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_duration)
{
    if (pulse_duration <= 0 || pulse_duration > 38000) // Validate pulse duration
    {
        fprintf(stderr, "Error: Invalid pulse duration: %ld us\n", pulse_duration);
        return -1.0; // Indicate invalid reading
    }

    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Convert us to cm
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        trigger_sensor();
        long pulse_duration = measure_pulse();

        if (pulse_duration > 0)
        {
            float distance = calculate_distance(pulse_duration);

            if (distance > 0)
            {
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);

                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                printf("%s Distance: %.2f cm\n", timestamp, distance);
            }
            else
            {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    return 0;
}

