#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define DISTANCE_THRESHOLD 1.0 // meters
#define LED_GPIO 17

int uart_fd = -1;
FILE *log_file = NULL;

// Structure to hold UART configuration
typedef struct {
    char device[20];
    int baud_rate;
} uart_config_t;

// Function to initialize UART
int init_uart(const uart_config_t *config) {
    uart_fd = open(config->device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, config->baud_rate);
    cfsetispeed(&tty, config->baud_rate);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

// Function to read magic word from UART
int read_magic_word(int fd, unsigned char *magic_word) {
    ssize_t bytes_read = read(fd, magic_word, MAGIC_WORD_SIZE);
    if (bytes_read != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error reading magic word: %zd bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to read range profile data from UART
int read_range_profile(int fd, short *range_profile) {
    ssize_t bytes_read = read(fd, range_profile, RANGE_PROFILE_SIZE * sizeof(short));
    if (bytes_read != RANGE_PROFILE_SIZE * sizeof(short)) {
        fprintf(stderr, "Error reading range profile: %zd bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to check for intrusion
int check_for_intrusion(const short *range_profile, int profile_size) {
    for (int i = 0; i < profile_size; i++) {
        if (range_profile[i] < 0 && range_profile[i] > -10000) { // Assuming negative values indicate distance
            float distance = (float)range_profile[i] / 100.0; // Convert to meters
            if (distance <= DISTANCE_THRESHOLD) {
                return 1; // Intrusion detected
            }
        }
    }
    return 0; // No intrusion detected
}

// Function to log intrusion event
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to activate LED
void activate_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    uart_config_t uart_config = {UART_DEVICE, BAUD_RATE};
    unsigned char magic_word[MAGIC_WORD_SIZE];
    short range_profile[RANGE_PROFILE_SIZE];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize UART
    if (init_uart(&uart_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read magic word
        if (read_magic_word(uart_fd, magic_word) == 0) {
            // Read range profile
            if (read_range_profile(uart_fd, range_profile) == 0) {
                // Check for intrusion
                if (check_for_intrusion(range_profile, RANGE_PROFILE_SIZE)) {
                    // Log intrusion
                    float distance = (float)range_profile[0] / 100.0; // Assuming first bin indicates distance
                    log_intrusion(distance);

                    // Activate LED
                    activate_led(LED_GPIO, 2000); // 2 seconds
                }
            } else {
                fprintf(stderr, "Error reading range profile, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error reading magic word, retrying...\n");
        }

        gpioDelay(10000); // Delay for 10ms to avoid busy-waiting
    }

    // Cleanup (should not reach here due to signal handler)
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

