#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
int log_distance(FILE *log_file, float distance);
int check_distance_threshold(float distance, float threshold);
int set_gpio_alert(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char cmd[1] = {0x00}; // Replace with the actual command to trigger a reading
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the raw data to distance (example: 16-bit integer)
    int16_t raw_distance = (buffer[0] << 8) | buffer[1];
    float distance = (float)raw_distance / 10.0; // Example scaling

    return (int)distance;
}

// Function to log distance to a file
int log_distance(FILE *log_file, float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to check if distance is below threshold
int check_distance_threshold(float distance, float threshold) {
    return (distance < threshold) ? 1 : 0;
}

// Function to set GPIO alert
int set_gpio_alert(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

