    int distance;
    float logged_distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance monitoring...\n");

    // Main loop
    while (!terminate) {
        distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        logged_distance = (float)distance; // Cast to float for logging
        if (log_distance(log_file, logged_distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        if (check_distance_threshold(logged_distance, DISTANCE_THRESHOLD)) {
            set_gpio_alert(GPIO_PIN, 1); // Set GPIO HIGH
        } else {
            set_gpio_alert(GPIO_PIN, 0); // Set GPIO LOW
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW before exiting
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

