    data[1] = 0x01; // Data to write (example)

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization.\n");
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    data[0] = 0x01; // Register address (example)
    data[1] = 0x00; // Data to write (example)

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization.\n");
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    char cmd[1];
    char data[2];

    // Start a single measurement
    cmd[0] = 0x00; // Register address (example)
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to VL53L1X to start measurement.\n");
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    // Read the distance (example: read 2 bytes from register 0x14)
    cmd[0] = 0x14; // Register address (distance MSB)
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to VL53L1X to set register address for read.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X.\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1]; // Combine MSB and LSB

    return 0;
}

// Log data to file
void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print parking guidance message
void print_guidance(uint16_t distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

