#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define LED_GPIO 18
#define PWM_FREQ_MAX 1000 // Maximum PWM frequency (Hz)
#define PWM_DUTY_CYCLE_MAX 1000000 // Maximum duty cycle (microseconds)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_frequency(uint16_t distance);
void set_led_frequency(float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    // Retry mechanism
    for (int i = 0; i < 3; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Calculate LED blinking frequency based on distance
float calculate_frequency(uint16_t distance) {
    // Map distance (0-1000mm) to frequency (1Hz - 1000Hz)
    float frequency = 1.0f + (float)distance / 1000.0f * 999.0f;
    return frequency;
}

// Set LED blinking frequency using PWM
void set_led_frequency(float frequency) {
    // Calculate PWM parameters
    int pwm_frequency = (int)frequency;
    int pwm_duty_cycle = PWM_DUTY_CYCLE_MAX * (1.0f - (float)pwm_frequency / PWM_FREQ_MAX);

    // Set PWM parameters
    gpioSetPWMfrequency(LED_GPIO, pwm_frequency);
    gpioPWM(LED_GPIO, pwm_duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Read distance
        if (read_distance(&distance) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Calculate LED blinking frequency
            float frequency = calculate_frequency(distance);

            // Set LED blinking frequency
            set_led_frequency(frequency);

            // Log data to stdout
            printf("%s, Distance: %dmm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Check I2C connection.\n");
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

