int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce the sensor readings
int debounce(int gpio, int current_state) {
    unsigned long now = gpioTick();
    if (current_state != gpioRead(gpio)) {
        if ((now - sensor1.last_event_time) > (DEBOUNCE_TIME * 1000)) {
            sensor1.last_state = current_state;
            sensor1.last_event_time = now;
            return 1; // State changed
        }
    }
    return 0; // No state change
}

// Function to log sensor events to a file
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor1_state_changed = debounce(SENSOR_1_GPIO, sensor1_value);
        if (sensor1_state_changed) {
            if (sensor1_value == 0) {
                log_event(1, "DETECTED");
                printf("Sensor 1: Obstacle DETECTED\n");
            } else {
                log_event(1, "CLEARED");
                printf("Sensor 1: Clearance CLEARED\n");
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        int sensor2_state_changed = debounce(SENSOR_2_GPIO, sensor2_value);
        if (sensor2_state_changed) {
            if (sensor2_value == 0) {
                log_event(2, "DETECTED");
                printf("Sensor 2: Obstacle DETECTED\n");
            } else {
                log_event(2, "CLEARED");
                printf("Sensor 2: Clearance CLEARED\n");
            }
        }

        gpioDelay(10); // Poll every 10 milliseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

