int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_mm(uint16_t distance);
int log_data(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with timeout
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int result;
    int retries = 3; // Retry mechanism

    // Read status
    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, MEAS_STATUS_REG, buf, 2);
        if (result == 2) {
