        fprintf(stderr, "Failed to read status after multiple retries.\n");
        return -1;
    }

    // Read distance
    retries = 3;
    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
