    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float distance_mm;

    printf("Starting distance measurements...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Check for valid measurement (example: check if status is zero)
            if (sensor_data.status == 0) {
                // Convert to millimetres
                distance_mm = convert_to_mm(sensor_data.distance);

                // Log data
                if (log_data(distance_mm) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }

                printf("Distance: %.2f mm\n", distance_mm);
            } else {
                fprintf(stderr, "Invalid measurement status: %u\n", sensor_data.status);
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Delay before next sample
        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

