#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// Register addresses (Example - refer to datasheet for actual values)
#define REG_IDENTIFICATION_MODEL_ID 0x0000
#define REG_SYSTEM_START 0x0008
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_SPAD_NB 0x0022
#define REG_RESULT_SIGNAL_RATE 0x0024
#define REG_RESULT_AMBIENT_RATE 0x0026
#define REG_RESULT_DISTANCE 0x0028

// Zone grid configuration registers (Example - refer to datasheet)
#define REG_FIRMWARE_SYSTEM_CONFIG_ZONE_COUNT 0x001E
#define REG_SYSTEM_SEQUENCE_CONFIG 0x0081

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint16_t reg_addr, uint8_t *data) {
    char buf[2];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error reading byte from I2C device.\n");
        return -1;
    }

    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint16_t reg_addr, uint8_t data) {
    char buf[3];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;        // LSB of register address
    buf[2] = data;                   // Data to write

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing byte to I2C device.\n");
        return -1;
    }

    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int handle) {
    uint8_t model_id;

    // Check sensor ID (Example)
    if (i2c_read_byte(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor ID.\n");
        return -1;
    }

    if (model_id != 0xE1) { // Expected model ID for VL53L5CX
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure zone grid (Example - adjust based on datasheet)
    if (i2c_write_byte(handle, REG_FIRMWARE_SYSTEM_CONFIG_ZONE_COUNT, 64) != 0) {
        fprintf(stderr, "Error configuring zone count.\n");
        return -1;
    }

    // Start continuous ranging (Example - adjust based on datasheet)
    if (i2c_write_byte(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous ranging.\n");
        return -1;
    }

    return 0;
}

// Function to read distance data for all zones
int read_zone_data(int handle, uint16_t *distances) {
    uint8_t data[128]; // 64 zones * 2 bytes/zone
    uint8_t range_status;

    // Read range status
    if (i2c_read_byte(handle, REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status.\n");
        return -1;
    }

    // Read distance data for all zones
    if (i2cReadDevice(handle, (char *)data, 128) != 128) {
        fprintf(stderr, "Error reading zone data.\n");
        return -1;
    }

    // Convert raw data to distances (Example - adjust based on datasheet)
    for (int i = 0; i < 64; i++) {
        distances[i] = (data[2 * i] << 8) | data[2 * i + 1];
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L5CX_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L5CX sensor
    if (init_vl53l5cx(i2c_handle) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t distances[64];
    struct timespec sleep_time = {0, 500000000}; // 500ms

    printf("Reading zone data every 500ms. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read zone data
        if (read_zone_data(i2c_handle, distances) == 0) {
            // Print zone distances
            for (int i = 0; i < 64; i++) {
                printf("%d ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Error reading zone data. Retrying...\n");
        }

        // Sleep for 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

