#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance data (example, adjust as needed)
#define DISTANCE_REG 0x00

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char buf[2];
    int result;

    // Write the register address to read from
    result = i2cWriteByteData(i2c_handle, DISTANCE_REG, 0); // Assuming no register address needed for reading
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Read two bytes of distance data
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and log distance measurements
    while (!terminate) {
        uint16_t distance;
        struct timespec ts;

        // Read the distance from the sensor
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get the current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log the distance with the timestamp
                printf("Timestamp: %ld.%09ld, Distance: %u mm\n", ts.tv_sec, ts.tv_nsec, distance);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the I2C bus
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

