#include <wiringPi.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for the buzzer
#define BUZZER_PIN 23

// Message queue key
#define MSG_QUEUE_KEY 1234

// Message structure for the POSIX message queue
struct msgbuf {
    long mtype;         // Message type (must be > 0)
    int distance;       // Distance in millimeters
};

// Global variables
int i2c_fd = -1;
int msg_queue_id = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int fd);
int vl53l1x_read_distance(int fd);
void buzzer_on(int pin);
void buzzer_off(int pin);
void signal_handler(int sig);

// VL53L1X register addresses (example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


// Function to initialize the VL53L1X sensor
int vl53l1x_init(int fd) {
    uint8_t model_id, revision_id;
    uint8_t data[2];

    // Check sensor ID (example)
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read sensor ID");
        return -1;
    }
    model_id = data[0];

    if (read(fd, &data, 1) != 1) {
        perror("Failed to read sensor revision ID");
        return -1;
    }
    revision_id = data[0];

    printf("VL53L1X Model ID: 0x%02x\n", model_id);
    printf("VL53L1X Revision ID: 0x%02x\n", revision_id);

    // Basic initialization sequence (example - adjust as needed)
    uint8_t init_data[] = {0x00, 0x01}; // Example initialization data
    if (write(fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        perror("Failed to write initialization data");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int fd) {
    uint8_t cmd = 0x01; // Command to start a single measurement
    uint8_t data[2];
    int distance;

    // Start a single measurement
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    usleep(10000); // 10ms

    // Read the distance data (2 bytes)
    if (read(fd, data, 2) != 2) {
        perror("Failed to read distance data");
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Function to turn the buzzer on
void buzzer_on(int pin) {
    digitalWrite(pin, HIGH);
}

// Function to turn the buzzer off
void buzzer_off(int pin) {
    digitalWrite(pin, LOW);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

int main() {
    int distance;
    struct msgbuf message;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set buzzer pin as output
    pinMode(BUZZER_PIN, OUTPUT);
    buzzer_off(BUZZER_PIN);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
