#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define BUZZER_THRESHOLD 30.0   // Distance threshold for buzzer (cm)
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that rising edge is received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate timeout
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance > 0 && distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for 100ms
        gpioDelay(100000); // 100ms

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Handle tick wraparound
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        }

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Check for errors
        if (distance < 0) {
            if (distance == -1.0) {
                fprintf(stderr, "Timeout occurred\n");
            } else {
                fprintf(stderr, "Invalid reading: %f cm\n", distance);
            }
        } else {
            printf("Distance: %f cm\n", distance);
        }

        // Control the buzzer
        control_buzzer(distance);
    }

    return 0;
}

