#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 90
#define CLOSE_ANGLE 0
#define DISTANCE_THRESHOLD 20 // cm
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void set_servo_angle(int angle);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


// VL53L1X Initialization
int vl53l1x_init(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
    char data[2];
    int status;

    // Reset the device
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Reset value
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        log_event("Error: VL53L1X reset failed");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure for short-range mode (example)
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Value to write
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        log_event("Error: VL53L1X short-range config failed");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Start continuous ranging
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01;
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        log_event("Error: VL53L1X start ranging failed");
        return -1;
    }

    log_event("VL53L1X initialized successfully");
    return 0;
}

// VL53L1X Distance Reading
int vl53l1x_read_distance(int i2c_handle) {
    char cmd[1];
    char buffer[2];
    int distance = -1; // Default to error value
    int retries = 0;
    int status;

    // Read distance register
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        log_event("Error: VL53L1X write address failed");
        return -1;
    }

    status = i2cReadDevice(i2c_handle, buffer, 2);
    if (status != 0) {
        log_event("Error: VL53L1X read distance failed");
        return -1;
    }

    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Servo Control
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = 500 + (angle * 2000 / 180); // Map angle to pulse width (SG90 range)
    gpioPWM(SERVO_PIN, pulse_width);
    log_event("Servo angle set to");
    char log_buffer[50];
    sprintf(log_buffer, "%d degrees", angle);
    log_event(log_buffer);
}

// Logging
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    log_event("Signal received, terminating...");
    terminate = 1;
}

int main() {
    int distance;
    int servo_angle = CLOSE_ANGLE; // Initialize servo to closed position

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Could not open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        log_event("Error: VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output and configure PWM
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 2000); // Range of 2000 for finer control

    // Set initial servo angle
    set_servo_angle(servo_angle);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate control system started");

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);

        if (distance > 0) {
            char log_buffer[50];
            sprintf(log_buffer, "Distance: %d mm", distance);
            log_event(log_buffer);

            if (distance < DISTANCE_THRESHOLD * 10) { // Convert cm to mm
                if (servo_angle == CLOSE_ANGLE) {
                    set_servo_angle(OPEN_ANGLE);
                    log_event("Opening gate");
                }
            } else {
                if (servo_angle == OPEN_ANGLE) {
                    set_servo_angle(CLOSE_ANGLE);
                    log_event("Closing gate");
                }
            }
        } else {
            log_event("Error: Could not read distance");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    set_servo_angle(CLOSE_ANGLE); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    log_event("Gate control system stopped");

    return 0;
}

