    status = i2cReadDevice(i2c_handle, buffer, 2);
    if (status != 0) {
        log_event("Error: VL53L1X read distance failed");
        return -1;
    }

    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Servo Control
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = 500 + (angle * 2000 / 180); // Map angle to pulse width (SG90 range)
    gpioPWM(SERVO_PIN, pulse_width);
    log_event("Servo angle set to");
    char log_buffer[50];
    sprintf(log_buffer, "%d degrees", angle);
    log_event(log_buffer);
}

// Logging
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    log_event("Signal received, terminating...");
    terminate = 1;
}

int main() {
    int distance;
    int servo_angle = CLOSE_ANGLE; // Initialize servo to closed position

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Could not open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        log_event("Error: VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output and configure PWM
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 2000); // Range of 2000 for finer control

    // Set initial servo angle
    set_servo_angle(servo_angle);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate control system started");

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);

        if (distance > 0) {
            char log_buffer[50];
            sprintf(log_buffer, "Distance: %d mm", distance);
            log_event(log_buffer);

            if (distance < DISTANCE_THRESHOLD * 10) { // Convert cm to mm
                if (servo_angle == CLOSE_ANGLE) {
                    set_servo_angle(OPEN_ANGLE);
                    log_event("Opening gate");
                }
            } else {
                if (servo_angle == OPEN_ANGLE) {
                    set_servo_angle(CLOSE_ANGLE);
                    log_event("Closing gate");
                }
            }
        } else {
            log_event("Error: Could not read distance");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    set_servo_angle(CLOSE_ANGLE); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    log_event("Gate control system stopped");

    return 0;
}

