#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23  // BCM GPIO 16
#define ECHO_PIN 24  // BCM GPIO 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // us
#define TRIGGER_INTERVAL 200 // ms
#define TIMEOUT_US 30000       // 30ms
#define NOISE_THRESHOLD_US 100
#define ECHO_TIMEOUT_US 60000   // 60ms

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_duration);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 0; // Reset flag for falling edge
    } else if (level == 0) {
        falling_tick = tick;
        echo_received = 1; // Set flag to indicate falling edge received
    }
}

// Function to calculate distance from pulse duration
double calculate_distance(uint32_t pulse_duration) {
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file and stdout
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
    printf("%s,%.2f\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set trigger pin low initially
    gpioWrite(TRIG_PIN, 0);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_flag = 0;
        if (!echo_received) {
            gpioDelay(TIMEOUT_US);
            timeout_flag = 1;
        }

        if (echo_received) {
            // Calculate pulse duration
            uint32_t pulse_duration = falling_tick - rising_tick;

            // Handle tick wraparound
            if (pulse_duration > 0xFFFFFFFF) {
                pulse_duration %= 0xFFFFFFFF;
            }

            // Validate pulse duration
            if (pulse_duration < NOISE_THRESHOLD_US || pulse_duration > TIMEOUT_US) {
                fprintf(stderr, "Warning: Invalid pulse duration: %u us\n", pulse_duration);
            } else {
                // Calculate distance
                double distance = calculate_distance(pulse_duration);

                // Log distance
                log_distance(distance);
            }
        } else {
            // Timeout occurred
            fprintf(stderr, "Warning: Timeout waiting for echo.\n");
        }

        gpioDelay(TRIGGER_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

