// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 500 // mm
#define DISTANCE_THRESHOLD_CLOSE 600 // mm
#define SERVO_OPEN_PULSE 1500 // us
#define SERVO_CLOSE_PULSE 1000 // us
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24

// Global variables
int i2c_handle;
FILE *log_file;
volatile int gate_open = 0; // 0 = closed, 1 = open

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void vl53l1x_shutdown();
void set_servo_pulse(int pulse_width);
void open_gate();
void close_gate();
void log_event(int distance, int gate_state);
void signal_handler(int signal);
void alert_callback(int gpio, int level, uint32_t tick);

// VL53L1X register addresses (example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure shutdown pin as output
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1); // Initially disable shutdown

    // Configure interrupt pin as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set servo pin as PWM output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // Range for 20ms period

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        vl53l1x_shutdown();
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback (using a dummy function for now)
    // gpioSetAlertFunc(INTERRUPT_PIN, alert_callback); // Removed because of error

    // Main loop
    while (1) {
        int distance = vl53l1x_read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                open_gate();
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                close_gate();
            }

            log_event(distance, gate_open);
        }

        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

int vl53l1x_init() {
    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully\n");
    return 0;
}

int vl53l1x_read_distance() {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    int distance = (data[0] << 8) | data[1];
    return distance;
}

void vl53l1x_shutdown() {
    i2cClose(i2c_handle);
    printf("VL53L1X sensor shutdown\n");
}

void set_servo_pulse(int pulse_width) {
    gpioPWM(SERVO_PIN, pulse_width);
}

void open_gate() {
    set_servo_pulse(SERVO_OPEN_PULSE);
    gate_open = 1;
    printf("Gate opened\n");
}

void close_gate() {
    set_servo_pulse(SERVO_CLOSE_PULSE);
    gate_open = 0;
    printf("Gate closed\n");
}

void log_event(int distance, int gate_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Distance: %d mm, Gate: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, gate_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C bus
    vl53l1x_shutdown();

    // Stop PWM
    gpioPWM(SERVO_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

void alert_callback(int gpio, int level, uint32_t tick) {
    // This function is called when the interrupt pin changes state.
    // For now, it does nothing, but it could be used to handle interrupts from the VL53L1X.
    printf("Interrupt callback called (GPIO %d, level %d, tick %u)\n", gpio, level, tick);
}

