#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300
#define GPIO_DISTANCE_INTERRUPT 24

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int motor_state = 0; // 0: stopped, 1: forward, -1: backward

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void distance_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
int i2c_write_byte(int handle, uint8_t reg, uint8_t data);
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data);
int i2c_read_word(int handle, uint8_t reg, uint16_t *data);

// I2C write byte with retry and exponential backoff
int i2c_write_byte(int handle, uint8_t reg, uint8_t data) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error: reg=0x%02x, data=0x%02x, result=%d. Retrying in %d ms...\n", reg, data, result, delay_ms);
        gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read byte with retry and exponential backoff
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *data = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read error: reg=0x%02x, result=%d. Retrying in %d ms...\n", reg, result, delay_ms);
        gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read word with retry and exponential backoff
int i2c_read_word(int handle, uint8_t reg, uint16_t *data) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *data = (uint16_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read word error: reg=0x%02x, result=%d. Retrying in %d ms...\n", reg, result, delay_ms);
        gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "I2C read word failed after multiple retries.\n");
    return -1; // Failure
}


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_DISTANCE_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_DISTANCE_INTERRUPT, PI_PUD_UP); // Enable pull-up resistor

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
