#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELE_STATUS_REG 0x00
#define ELE_TOUCH_TH_REG 0x41
#define ELE_RELEASE_TH_REG 0x42
#define ELE_FILTER_REG 0x2B
#define ELE_CONFIG_REG 0x5E

#define LED_GPIO_1 17
#define LED_GPIO_2 18
#define LED_GPIO_3 27
#define LED_GPIO_4 22

#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_electrode_status(int i2c_handle, uint16_t *status);
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4);
void log_proximity_event(int electrode);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure electrode touch and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, ELE_TOUCH_TH_REG + 2 * i, 0x30) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, ELE_RELEASE_TH_REG + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter control register
    if (i2cWriteByteData(i2c_handle, ELE_FILTER_REG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter control\n");
        return -1;
    }

    // Configure electrode configuration register
    if (i2cWriteByteData(i2c_handle, ELE_CONFIG_REG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to set electrode config\n");
        return -1;
    }

    return 0;
}

// Function to read electrode status
int read_electrode_status(int i2c_handle, uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ELE_STATUS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read electrode status\n");
        return -1;
    }

    *status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to set LED pattern
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4) {
    gpioWrite(gpio1, (gpio1 >> 0) & 1);
    gpioWrite(gpio2, (gpio2 >> 1) & 1);
    gpioWrite(gpio3, (gpio3 >> 2) & 1);
    gpioWrite(gpio4, (gpio4 >> 3) & 1);
}

// Function to log proximity event
void log_proximity_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Electrode %d detected proximity\n", timestamp, electrode);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for LEDs
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);
    gpioSetMode(LED_GPIO_4, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t electrode_status = 0;
    uint16_t previous_electrode_status = 0;

    // Main loop
    while (!terminate) {
        if (read_electrode_status(i2c_handle, &electrode_status) == 0) {
            // Check for changes in electrode status
            if (electrode_status != previous_electrode_status) {
                for (int i = 0; i < NUM_ELECTRODES; i++) {
                    if ((electrode_status & (1 << i)) && !(previous_electrode_status & (1 << i))) {
                        log_proximity_event(i);
                        // Determine LED pattern based on electrode number
                        switch (i) {
                            case 0: set_led_pattern(0b0001, 0b0000, 0b0000, 0b0000); break;
                            case 1: set_led_pattern(0b0010, 0b0000, 0b0000, 0b0000); break;
                            case 2: set_led_pattern(0b0100, 0b0000, 0b0000, 0b0000); break;
                            case 3: set_led_pattern(0b1000, 0b0000, 0b0000, 0b0000); break;
                            case 4: set_led_pattern(0b0001, 0b0001, 0b0000, 0b0000); break;
                            case 5: set_led_pattern(0b0010, 0b0010, 0b0000, 0b0000); break;
                            case 6: set_led_pattern(0b0100, 0b0100, 0b0000, 0b0000); break;
                            case 7: set_led_pattern(0b1000, 0b1000, 0b0000, 0b0000); break;
                            case 8: set_led_pattern(0b0001, 0b0000, 0b0010, 0b0000); break;
                            case 9: set_led_pattern(0b0010, 0b0000, 0b0010, 0b0000); break;
                            case 10: set_led_pattern(0b0100, 0b0000, 0b0010, 0b0000); break;
                            case 11: set_led_pattern(0b1000, 0b0000, 0b0010, 0b0000); break;
                        }
                    } else if (!(electrode_status & (1 << i)) && (previous_electrode_status & (1 << i))) {
                        // Electrode released
                        // Optionally, you can clear the corresponding LED bit here
                        // set_led_pattern(0b0000, 0b0000, 0b0000, 0b0000);
                    }
                }
                previous_electrode_status = electrode_status;
            }
        } else {
            fprintf(stderr, "Error: Failed to read electrode status, retrying...\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

