    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIG_PIN, 0);

    // Set up interrupt handler for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(1000); // Wait for 1 second

        if (echo_valid) {
            // Calculate pulse width in microseconds
            uint32_t pulse_width = end_tick - start_tick;

            // Validate pulse width
            if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
                // Calculate distance in meters
                float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0;

                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log the distance to the file
                fprintf(log_file, "%s, Distance: %.2f m\n", timestamp, distance);
                fflush(log_file); // Ensure data is written to disk immediately

                printf("%s, Distance: %.2f m\n", timestamp, distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            }
        } else {
            fprintf(stderr, "No echo received\n");
        }
    }

    return 0;
}

