#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define READ_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Enable XSHUT GPIO
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);
    gpioWrite(XSHUT_GPIO, 1); // Active high

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialized successfully.");
    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a reading
    char data[2];
    int result;

    // Write command to sensor
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device: %d", result);
        return -1;
    }

    // Read distance data (2 bytes)
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device: %d", result);
        return -1;
    }

    // Convert data to distance (mm)
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s Distance: %d mm", timestamp, distance);
    } else {
        syslog(LOG_ERR, "%s Error reading distance", timestamp);
    }
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    int distance;
    int status;

    // Main loop
    while (!terminate) {
        status = read_distance(&distance);
        if (status == 0) {
            log_data(distance, status);
        } else {
            log_data(0, status); // Log error with 0 distance
        }

        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

