#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23  // BCM GPIO 23
#define ECHO_PIN 24     // BCM GPIO 24
#define SERVO_PIN 18    // BCM GPIO 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_CENTER_ANGLE 90
#define NUM_FILTER_SAMPLES 5
#define FILTER_SAMPLE_DELAY 10 // milliseconds

// Global variables
volatile int pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float filter_distance(float distance, float *filter_buffer);
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        set_servo_angle(SERVO_CENTER_ANGLE); // Stop the servo
        gpioTerminate();                     // Terminate pigpio
        exit(0);
    }
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        new_pulse = 1;
    } else if (level == 0) {
        // Handle timeout if echo doesn't return
        if (pulse_width == 0) {
            fprintf(stderr, "Error: No echo received.\n");
            log_data(-1.0, SERVO_CENTER_ANGLE); // Log -1.0 and set servo to center
            return;
        }
    }
}

// Calculate distance function
float calculate_distance(int pulse_width) {
    float time_taken = (float)pulse_width / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Filter distance function
float filter_distance(float distance, float *filter_buffer) {
    static int filter_index = 0;
    float sum = 0.0;

    // Subtract the oldest sample and add the new sample
    sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = distance;
    sum += distance;

    // Increment the index, wrapping around if necessary
    filter_index = (filter_index + 1) % NUM_FILTER_SAMPLES;

    return sum / NUM_FILTER_SAMPLES;
}

// Set servo angle function
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)(angle - SERVO_CENTER_ANGLE) / (180.0 - SERVO_CENTER_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data function
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for logging!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(fp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Initialize servo to center position
    set_servo_angle(SERVO_CENTER_ANGLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Filter buffer
    float filter_buffer[NUM_FILTER_SAMPLES] = {0.0};
    float filtered_distance;
    int angle;

    // Main loop
    while (program_running) {
        // Trigger a pulse
        trigger_pulse();

        // Wait for new pulse or timeout
        int timeout_counter = 0;
        while (!new_pulse && timeout_counter < 3000) { // 300 ms timeout
            gpioDelay(1); // 1 ms delay
            timeout_counter++;
        }

        if (!new_pulse) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            log_data(-1.0, SERVO_CENTER_ANGLE); // Log -1.0 and set servo to center
            continue;
        }

        new_pulse = 0; // Reset new_pulse flag

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Filter the distance
        filtered_distance = filter_distance(distance, filter_buffer);

        // Check for valid distance
        if (filtered_distance < 2.0 || filtered_distance > 400.0) {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", filtered_distance);
            log_data(-1.0, SERVO_CENTER_ANGLE); // Log -1.0 and set servo to center
            continue;
        }

        // Calculate servo angle (map distance to 90-180 degrees)
        if (filtered_distance < 50.0) {
            angle = 90;
        } else if (filtered_distance > 350.0) {
            angle = 180;
        } else {
            angle = 90 + (int)(((filtered_distance - 50.0) / (350.0 - 50.0)) * 90.0);
        }

        // Set servo angle
        set_servo_angle(angle);

        // Log data
        log_data(filtered_distance, angle);

        // Wait before next reading
        gpioDelay(FILTER_SAMPLE_DELAY * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(SERVO_CENTER_ANGLE);
    gpioTerminate();
    return 0;
}

