#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for the warning LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// Circular buffer size
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void update_circular_buffer(int distance);
void control_led(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_VCSEL_PERIOD 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_VCSEL_PERIOD 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance
        int distance = read_distance();

        // Update circular buffer
        update_circular_buffer(distance);

        // Control LED
        control_led(distance);

        // Delay
        gpioDelay(50000); // 50ms
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Check sensor ID (Example - refer to datasheet for correct value)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, 0x00); // Dummy write to initiate read
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor ID register: %d\n", status);
        return -1;
    }
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Example initialization sequence (Refer to VL53L1X datasheet)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_VCSEL_PERIOD, 0x14);
    if (status < 0) {
        fprintf(stderr, "Error writing to pre-range config VCSEL period: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_VCSEL_PERIOD, 0x10);
    if (status < 0) {
        fprintf(stderr, "Error writing to final range config VCSEL period: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to system sequence config: %d\n", status);
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to system sequence config: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    int distance = -1; // Default to error value

    // Read distance from register (Example - refer to datasheet for correct register)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, 0x00); // Dummy write to initiate read
    if (status < 0) {
        fprintf(stderr, "Error writing to distance register: %d\n", status);
        return -1;
    }

    distance = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }

    return distance;
}

// Update circular buffer
void update_circular_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Control LED based on distance
void control_led(int distance) {
    if (distance < 200) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

