#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define INTERRUPT_GPIO 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int threshold = DEFAULT_THRESHOLD;
volatile int proximity_value = 0;
volatile int interrupt_flag = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_proximity_value(int i2c_handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Function to configure the Si1102 sensor
int configure_sensor(int i2c_handle) {
    // Example configuration (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) { // PS_LED21_SELECT
        fprintf(stderr, "Error writing to register 0x18\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x19, 0x77) < 0) { // PS_LED21_DUTY
        fprintf(stderr, "Error writing to register 0x19\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) { // MEAS_RATE
        fprintf(stderr, "Error writing to register 0x03\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // PS_EN
        fprintf(stderr, "Error writing to register 0x02\n");
        return -1;
    }

    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity_value(int i2c_handle) {
    int proximity = i2cReadWordData(i2c_handle, 0x24); // Register address for proximity
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity value\n");
        return -1;
    }
    return proximity;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    interrupt_flag = 1;
}

// Function to log data to a file
void log_data(int proximity_value, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            int proximity = read_proximity_value(i2c_handle);
            if (proximity >= 0) {
                proximity_value = proximity;
                if (proximity > threshold) {
                    log_data(proximity_value, "ALERT");
                } else {
                    log_data(proximity_value, "SAFE");
                }
            }
        }
        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

