#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, diff;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }
    return diff;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%lf cm)\n", distance);
        return -1.0; // Indicate error
    }

    // Logarithmic mapping
    double frequency = MIN_FREQUENCY * pow((double)(MAX_DISTANCE - distance) / MAX_DISTANCE, 0.5);
    return frequency;
}

// Function to set the PWM frequency and duty cycle
void set_pwm_frequency(double frequency) {
    if (frequency < 0) return; // Don't set frequency if mapping failed

    int range = 1000; // PWM range
    int duty_cycle = range / 2; // 50% duty cycle

    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial value)
    gpioSetPWMrange(SPEAKER_PIN, range);
    gpioSetPWMfrequency(SPEAKER_PIN, 440); // Initial frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double frequency = 440.0; // Initial frequency
    set_pwm_frequency(frequency);

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            if (distance > 0) {
                double new_frequency = map_distance_to_frequency(distance);
                if (new_frequency > 0) {
                    frequency = new_frequency;
                    set_pwm_frequency(frequency);
                }
            }
        }

        gpioDelay(50); // Delay between measurements
    }

    // Clean up
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

