#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0       // Minimum distance (cm)
#define MAX_DISTANCE 50.0      // Maximum distance (cm)
#define MIN_FREQUENCY 200.0    // Minimum frequency (Hz)
#define MAX_FREQUENCY 2000.0   // Maximum frequency (Hz)
#define TIMEOUT_MS 100         // Timeout in milliseconds
#define MEASURE_DELAY_MS 10     // Delay between measurements (ms)

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2); // 2 us
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width()
{
    long start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after ~10ms
    {
        count++;
        gpioDelay(1); // 1 us delay
    }

    if (count >= 10000)
    {
        fprintf(stderr, "Error: Echo pulse timeout (waiting for HIGH)\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) // Timeout after ~10ms
    {
        count++;
        gpioDelay(1); // 1 us delay
    }

    if (count >= 10000)
    {
        fprintf(stderr, "Error: Echo pulse timeout (waiting for LOW)\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0)
    {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    if (pulse_width < 0)
    {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE)
    {
        return MIN_FREQUENCY;
    }
    if (distance > MAX_DISTANCE)
    {
        return MAX_FREQUENCY;
    }
    return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to generate a tone on the buzzer
void generate_tone(float frequency)
{
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

// Function to print the distance and frequency
void print_distance_and_frequency(float distance, float frequency)
{
    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (optional, adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Last valid distance and frequency
    float last_valid_distance = 0.0;
    float last_valid_frequency = 0.0;

    // Main loop
    while (!terminate)
    {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Map the distance to the frequency
        float frequency = map_distance_to_frequency(distance);

        // Generate the tone
        generate_tone(frequency);

        // Print the distance and frequency
        print_distance_and_frequency(distance, frequency);

        // Delay before the next measurement
        gpioDelay(MEASURE_DELAY_MS * 1000); // Convert ms to us
    }

    // Stop PWM and terminate pigpio
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

