#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 50000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 50000) return -1.0; // Timeout
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 50000) {
        count++;
        gpioDelay(1);
    }
    if (count >= 50000) return -1.0; // Timeout
    end_tick = gpioTick();

    double diff = (double)(end_tick - start_tick);
    double distance = diff / 2.0 / 29.1;

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Timeout occurred\n");
        } else if (distance < 2 || distance > 400) {
            fprintf(stderr, "Invalid reading: Distance = %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        gpioDelay(500);
    }

    gpioTerminate();
    return 0;
}

