#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // BCM GPIO 8
#define RANGE_MIN 200
#define RANGE_MAX 5000
#define LOG_FILE "distance_log.csv"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
float convert_to_mm(uint16_t raw_distance);
int log_data(time_t timestamp, float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI setup failed: %s\n", strerror(errno));
        return -1;
    }

    pinMode(CS_PIN, OUTPUT);
    digitalWrite(CS_PIN, HIGH); // Deactivate chip select initially

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Read distance data from the sensor
int read_distance(uint16_t *distance) {
    unsigned char data[2];
    int result;

    digitalWrite(CS_PIN, LOW); // Activate chip select
    delayMicroseconds(10); // Small delay after CS activation

    result = wiringPiSPIDataRW(SPI_CHANNEL, data, 2);

    digitalWrite(CS_PIN, HIGH); // Deactivate chip select
    delayMicroseconds(10); // Small delay after CS deactivation

    if (result != 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw distance to millimeters
float convert_to_mm(uint16_t raw_distance) {
    float distance_mm = (float)raw_distance;

    if (distance_mm < RANGE_MIN) {
        distance_mm = RANGE_MIN;
    } else if (distance_mm > RANGE_MAX) {
        distance_mm = RANGE_MAX;
    }

    return distance_mm;
}

// Log data to CSV file
int log_data(time_t timestamp, float distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    time_t current_time;
    uint16_t raw_distance;
    float distance_mm;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPi setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() == -1) {
        fprintf(stderr, "Sensor initialization failed.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read distance
        if (read_distance(&raw_distance) == -1) {
            fprintf(stderr, "Failed to read distance.\n");
        } else {
            // Convert to millimeters
            distance_mm = convert_to_mm(raw_distance);

            // Get current timestamp
            current_time = time(NULL);

            // Log data
            if (log_data(current_time, distance_mm) == -1) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        // Delay
        delay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

