    // Example initialization sequence (adjust based on datasheet)
    // This is a placeholder - refer to the Si1175 datasheet for proper initialization
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) { // Example register and value
        fprintf(stderr, "Error writing to Si1175 during initialization\n");
        return -1;
    }
