        status = i2cReadWordData(i2c_handle, REG_ALS_VIS_DATA0);
        if (status >= 0) {
            *als = (uint16_t)status;
            break;
        }
        gpioDelay(10);
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read ALS data (attempts left: %d, status: %d)\n", retries, status);
