    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, REG_PS1_DATA0);
        if (status >= 0) {
            *prox = (uint16_t)status;
            break;
        }
        gpioDelay(10);
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read Proximity data (attempts left: %d, status: %d)\n", retries, status);
        return -1;
    }

    return 0;
}

