// Function to read ALS and proximity data
int read_si1120_data(uint16_t *als, uint16_t *prox) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, REG_ALS_VIS_DATA0);
        if (status >= 0) {
            *als = (uint16_t)status;
            break;
        }
        gpioDelay(10);
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read ALS data (attempts left: %d, status: %d)\n", retries, status);
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, REG_PS1_DATA0);
        if (status >= 0) {
            *prox = (uint16_t)status;
            break;
        }
        gpioDelay(10);
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read Proximity data (attempts left: %d, status: %d)\n", retries, status);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Prox: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    uint16_t als, prox;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code: %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Error: Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_si1120_data(&als, &prox);
        if (status == 0) {
            // Log data
            log_data(als, prox);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait 500ms
        gpioDelay(500);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

