// Function to read proximity data from the Si1145 sensor
int read_proximity_data(uint16_t *proximity) {
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, PS1_DATA0);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Function to log proximity data to a file
int log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s; %u\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t proximity;

    // Main loop
    while (!terminate) {
        if (read_proximity_data(&proximity) == 0) {
            log_data(proximity);
        } else {
            fprintf(stderr, "Error: Failed to read proximity data\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

