#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4  // BCM GPIO 4
#define ECHO_PIN 17     // BCM GPIO 17
#define SERVO_PIN 18    // BCM GPIO 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 20.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_PULSE_WIDTH 500    // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width in microseconds
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (high)\n");
        return -1.0;
    }
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (low)\n");
        return -1.0;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle
void set_servo_angle(float distance) {
    // Map distance to pulse width (angle)
    float pulse_width = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);

    // Ensure pulse width is within valid range
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Clean up and exit
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    fprintf(stderr, "Parking assist system stopped.\n");
    return 0;
}

