#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_SERVO 18
#define DISTANCE_REG 0x0089 // Register address for distance reading
#define OPEN_PULSE_WIDTH 1000 // Pulse width for open position (us)
#define CLOSE_PULSE_WIDTH 2000 // Pulse width for close position (us)
#define DISTANCE_THRESHOLD_OPEN 250 // Distance threshold for open position (mm)
#define DISTANCE_THRESHOLD_CLOSE 200 // Distance threshold for close position (mm)
#define HYSTERESIS_THRESHOLD 20  // Hysteresis threshold (mm)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check if I2C is initialized
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C not initialized.\n");
        return -1;
    }

    // Verify sensor model ID (0x0010)
    char model_id_reg = 0x0010;
    char model_id;

    if (i2cWriteDevice(i2c_handle, &model_id_reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, &model_id, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
