#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23  // BCM GPIO 23
#define ECHO_PIN 24     // BCM GPIO 24
#define SERVO_PIN 18    // BCM GPIO 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0           // degrees
#define MAX_ANGLE 180         // degrees
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define TIMEOUT_US 50000       // us (50 ms)

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
void triggerSensor();
float getDistance();
void setServoAngle(float angle);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        setServoAngle(MIN_ANGLE); // Set servo to 0 degrees
        gpioTerminate();          // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    long long start_tick, end_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for rising edge.\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for falling edge.\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate the pulse width in microseconds
    long long pulse_width = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map the distance to a servo angle
void setServoAngle(float angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    // Map the angle to a pulse width
    float pulse_width = SERVO_MIN_PULSE_WIDTH + (angle / MAX_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);

    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic distance measurement and servo control\n");
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the distance
        float distance = getDistance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        } else {
            // Map the distance to a servo angle
            float angle = 0.0;
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
            } else if (distance < MIN_DISTANCE) {
                angle = MIN_ANGLE;
            } else {
                angle = MAX_ANGLE;
            }

            // Set the servo angle
            setServoAngle(angle);

            // Print the distance and angle
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }

        // Pause for 100 ms
        gpioDelay(100);
    }

    // Clean up (should not reach here if signal handler works correctly)
    setServoAngle(MIN_ANGLE);
    gpioTerminate();

    return 0;
}

