#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_TEMP_REG 0x00
#define SI7005_HUMID_REG 0x01
#define SI7005_CONFIG_REG 0x02

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(uint8_t register_address, uint16_t *data);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the pigpio library and I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configures the Si7005 sensor
int configure_sensor() {
    // Configure for continuous temperature and humidity measurement
    if (i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Reads temperature and humidity data from the Si7005
int read_sensor_data(uint8_t register_address, uint16_t *data) {
    char buf[2];

    if (i2cWriteByte(i2c_handle, register_address) < 0) {
        fprintf(stderr, "Failed to write register address\n");
        return -1;
    }

    gpioDelay(10000); // 10 ms delay

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read data from register\n");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Logs the temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(SI7005_TEMP_REG, &raw_temperature) < 0) {
            fprintf(stderr, "Failed to read temperature, re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            if (initialize_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            if (configure_sensor() < 0) {
                fprintf(stderr, "Failed to re-configure sensor, exiting...\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Read humidity
        if (read_sensor_data(SI7005_HUMID_REG, &raw_humidity) < 0) {
            fprintf(stderr, "Failed to read humidity, re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            if (initialize_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            if (configure_sensor() < 0) {
                fprintf(stderr, "Failed to re-configure sensor, exiting...\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Convert raw data to temperature and humidity
        temperature = (175.0 * raw_temperature / 65536.0) - 45.0;
        humidity = (100.0 * raw_humidity / 65536.0);

        // Log the data
        log_data(temperature, humidity);

        // Wait for 2 seconds
        gpioDelay(2000000);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

