        int16_t gyro_y = read_word_2c(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_word_2c(i2c_handle, GYRO_XOUT_H + 4);

        // Print the data
        printf("Accel: X=%6d, Y=%6d, Z=%6d  ", accel_x, accel_y, accel_z);
        printf("Gyro: X=%6d, Y=%6d, Z=%6d\n", gyro_x, gyro_y, gyro_z);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

