#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High repeatability measurement command
#define MEASURE_HIGH_REPEATABILITY 0x240B

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0)
    {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6)
    {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Validate temperature CRC
    uint8_t temp_crc = crc8(data, 2);
    if (temp_crc != data[2])
    {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate humidity CRC
    uint8_t humidity_crc = crc8(data + 3, 2);
    if (humidity_crc != data[5])
    {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Main loop
    while (1)
    {
        // Read temperature and humidity
        if (read_sht40(&temperature, &humidity) == 0)
        {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log temperature and humidity to console
            printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-opening I2C bus.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                gpioTerminate();
                return 1;
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

