#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement command
#define DATA_LEN 9

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *data, int len);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature, uint16_t scale_factor_pressure, uint16_t scale_factor_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *data, int len) {
    int result = i2cReadDevice(handle, data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == checksum);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature, uint16_t scale_factor_pressure, uint16_t scale_factor_temperature) {
    sensor_data_t data;
    data.pressure = (float)raw_pressure / scale_factor_pressure;
    data.temperature = (float)raw_temperature / scale_factor_temperature;
    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    char data[DATA_LEN];
    int16_t raw_pressure, raw_temperature;
    uint16_t scale_factor_pressure, scale_factor_temperature;
    sensor_data_t sensor_data;

    while (!terminate) {
        // Read data from sensor
        if (read_data(i2c_handle, data, DATA_LEN) == 0) {
            // Extract raw data and scale factors
            raw_pressure = (int16_t)((data[0] << 8) | data[1]);
            raw_temperature = (int16_t)((data[3] << 8) | data[4]);
            scale_factor_pressure = (uint16_t)((data[6] << 8) | data[7]);
            scale_factor_temperature = (uint16_t)((data[8] << 8) | data[9]);

            // Validate CRC checksums
            if (validate_crc((uint8_t *)data, 2, data[2]) &&
                validate_crc((uint8_t *)(data + 3), 2, data[5]) &&
                validate_crc((uint8_t *)(data + 6), 2, data[8]) &&
                validate_crc((uint8_t *)(data + 9), 2, data[11])) {
                // Convert data to pressure and temperature
                sensor_data = convert_data(raw_pressure, raw_temperature, scale_factor_pressure, scale_factor_temperature);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Error logging data!\n");
                }
            } else {
                fprintf(stderr, "CRC checksum error!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

