// SHT40 I2C address
#define SHT40_ADDR 0x44

// High repeatability measurement command
#define MEASURE_HIGH_REPEATABILITY 0x2400

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int sht40_read_data(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
