#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(int16_t *pressure, int16_t *temperature);
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature);
int log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait at least 1 ms
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *pressure, int16_t *temperature) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature) {
    sensor_data_t data;
    // Conversion formulas from SDP31 datasheet
    data.pressure_pa = (float)raw_pressure / 60.0; // Scale factor for SDP31
    data.temperature_c = (float)raw_temperature / 200.0; // Scale factor for SDP31
    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    fflush(log_file);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("SDP31 data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_pressure, raw_temperature;
        sensor_data_t data;
        int retries = 3;

        // Trigger measurement with retries
        while (retries > 0) {
            if (trigger_measurement() == 0) {
                break;
            } else {
                retries--;
                gpioDelay(1000 * (3 - retries)); // Exponential backoff
            }
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        retries = 3;
        // Read sensor data with retries
        while (retries > 0) {
            if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
                break;
            } else {
                retries--;
                gpioDelay(1000 * (3 - retries)); // Exponential backoff
            }
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        data = convert_data(raw_pressure, raw_temperature);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

