    return 0;
}

int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int close_i2c_bus() {
    int result = i2cClose(i2c_handle);
    if (result < 0) {
        fprintf(stderr, "Failed to close I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int write_command(int handle, unsigned char command) {
    int result = i2cWriteByte(handle, command);
    if (result < 0) {
        fprintf(stderr, "Failed to write command 0x%02X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

float read_temperature(int handle) {
    char buffer[2];
    if (write_command(handle, TEMP_CMD) < 0) return -1000.0;
    gpioDelay(20); // Wait for measurement (datasheet specifies typical 12.1ms)
    if (read_data(handle, buffer, 2) < 0) return -1000.0;
    unsigned int raw_temp = (buffer[0] << 8) | buffer[1];
    return ((175.72 * raw_temp) / 65536.0) - 46.85;
}

float read_humidity(int handle) {
    char buffer[2];
    if (write_command(handle, HUM_CMD) < 0) return -1000.0;
    gpioDelay(20); // Wait for measurement (datasheet specifies typical 12.1ms)
    if (read_data(handle, buffer, 2) < 0) return -1000.0;
    unsigned int raw_humidity = (buffer[0] << 8) | buffer[1];
    return ((125.0 * raw_humidity) / 65536.0) - 6.0;
}

int open_log_file() {
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_pigpio() < 0) {
        return 1;
    }

    if (open_i2c_bus() < 0) {
        gpioTerminate();
        return 1;
    }

    if (open_log_file() < 0) {
        close_i2c_bus();
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        float temperature = read_temperature(i2c_handle);
        float humidity = read_humidity(i2c_handle);

        if (temperature > -999.0 && humidity > -999.0) {
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            fprintf(log_file, "%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            fflush(log_file);
        } else {
            fprintf(stderr, "%s - Failed to read sensor data\n", timestamp);
            fprintf(log_file, "%s - Failed to read sensor data\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    close_i2c_bus();
    close_log_file();
    gpioTerminate();

    return 0;
}

