#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F // Continuous measurement without averaging
#define DATA_LENGTH 6
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL 0xFF
#define LOG_FILE "airflow_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int length);
int validate_crc(uint8_t data[], int length, uint8_t crc);
int convert_data(uint8_t *data, sensor_data_t *sensor_data);
int log_data(FILE *file, sensor_data_t sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t command_bytes[2];
    command_bytes[0] = (command >> 8) & 0xFF;
    command_bytes[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)command_bytes, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC8 checksum
uint8_t calculate_crc(uint8_t data[], int length) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int length, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, length);
    return (calculated_crc == crc);
}

// Convert raw data to pressure and temperature
int convert_data(uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Convert to physical units (refer to SDP800 datasheet)
    sensor_data->pressure = (float)raw_pressure / 30.0; // Pressure in Pa
    sensor_data->temperature = (float)raw_temperature / 200.0; // Temperature in °C

    return 0;
}

// Log data to file
int log_data(FILE *file, sensor_data_t sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure, sensor_data.temperature);
    fflush(file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(1); // Wait for measurement (adjust as needed)

        // Read data
        if (read_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(data, 2, data[2]) || !validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed, skipping data point\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Error converting data\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

