#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial and initialization value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIALIZATION 0xFF

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int verify_crc(uint8_t *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // I2C bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the SCD40
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIALIZATION;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC checksum verification
int verify_crc(uint8_t *data, int len) {
    uint8_t crc_calculated = crc8(data, len - 1);
    if (crc_calculated != data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];

    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    if (read_data(handle, raw_data, 9) != 0) {
        return -1;
    }

    if (verify_crc(raw_data, 9) != 0) {
        return -1;
    }

    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = -45 + 175 * ((raw_data[3] << 8) | raw_data[4]) / 65535.0;
    data->humidity = 100 * ((raw_data[6] << 8) | raw_data[7]) / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioDelay(1000); // Wait at least one second before first read

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        gpioDelay(5000); // Wait 5 seconds

        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            log_data(log_file, sensor_data);
            printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

