#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5
#define TIMEOUT_MS 50
#define MAX_FAILURES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    FILE *log_file;
    int init_result;
    int failures = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Program started\n");
    fflush(log_file);

    while (!terminate) {
        int high_time = 0;
        int total_time = 0;
        double temperature = -999.0; // Initialize to an invalid value
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Measure high and total pulse widths
        int start_seconds, start_micros;
        gpioTime(PI_TIME_RELATIVE, &start_seconds, &start_micros);
        int end_seconds, end_micros;
        int timeout_count = 0;

        while (total_time < 10000) { // Sample for 10ms (10000 us)
            gpioTime(PI_TIME_RELATIVE, &end_seconds, &end_micros);
            int elapsed_time = (end_seconds - start_seconds) * 1000000 + (end_micros - start_micros);

            if (elapsed_time >= timeout_ms * 1000) {
                fprintf(stderr, "Timeout waiting for edge\n");
                break; // Exit loop if timeout
            }

            if (gpioRead(GPIO_PIN) == 1) {
                gpioTime(PI_TIME_RELATIVE, &start_seconds, &start_micros);
                high_time = elapsed_time;
            } else {
                gpioTime(PI_TIME_RELATIVE, &end_seconds, &end_micros);
                total_time += elapsed_time;
            }
        }

        if (total_time >= 10000) {
            fprintf(stderr, "Error: Could not measure pulse widths within timeout.\n");
            fprintf(log_file, "Error: Could not measure pulse widths within timeout.\n");
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        // Calculate temperature
        if (high_time > 0) {
            double TL = (double)total_time - (double)high_time;
            if (TL > 0) {
                temperature = 20.0 + (high_time / TL) * 60.0;
            } else {
                fprintf(stderr, "Error: Division by zero (TL = %d)\n", (int)TL);
                fprintf(log_file, "Error: Division by zero (TL = %d)\n", (int)TL);
                fflush(log_file);
                temperature = -999.0; // Set to invalid value
            }
        } else {
            fprintf(stderr, "Error: High time is zero.\n");
            fprintf(log_file, "Error: High time is zero.\n");
            fflush(log_file);
            temperature = -999.0; // Set to invalid value
        }

        // Validate temperature range
        if (temperature < -40.0 || temperature > 150.0) {
            fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
            fprintf(log_file, "Error: Temperature out of range: %.2f\n", temperature);
            fflush(log_file);
        } else {
            // Get timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log temperature reading
            fprintf(log_file, "%s Temperature: %.2f °C\n", timestamp, temperature);
            fflush(log_file);
            printf("%s Temperature: %.2f °C\n", timestamp, temperature);
            failures = 0; // Reset failure count
        }

        // Check for consecutive failures
        if (temperature == -999.0) {
            failures++;
            if (failures >= MAX_FAILURES) {
                fprintf(stderr, "SENSOR MALFUNCTION\n");
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                terminate = 1; // Terminate the program
            }
        } else {
            failures = 0; // Reset failure count
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Clean up
    fprintf(log_file, "Program terminated\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

