    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float temperature, humidity;
    float temp_offset = 2.0 * sin(2.0 * M_PI * (time(NULL) % 3600) / 3600);
    float hum_offset = 5.0 * sin(2.0 * M_PI * (time(NULL) % 3600) / 3600);

    while (program_running) {
        // Read sensor data
        int result = read_sht35(i2c_handle, &temperature, &humidity);

        if (result == 0) {
            // Apply sinusoidal offsets
            temperature += temp_offset;
            humidity += hum_offset;

            // Log the data
            log_data(temperature, humidity);

            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            log_data(NAN, NAN); // Log NaN values to indicate error
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

