    // Placeholder conversion formulas (replace with actual formulas from datasheet)
    data->pressure = (int16_t)((uint16_t)0 << 8 | (uint16_t)0); // Example values
    data->temperature = (int16_t)((uint16_t)0 << 8 | (uint16_t)0); // Example values
    data->scale_factor = (uint16_t)((uint16_t)0 << 8 | (uint16_t)0); // Example values

    return 0;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, (float)data.pressure / 100.0, (float)data.temperature / 100.0);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("airflow.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open airflow.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }
    rewind(fp);

    // Main loop
    while (1) {
        char buffer[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Try again
        }

        // Wait for conversion time (45 ms)
        gpioDelay(50); // Delay in microseconds

        // Read data from sensor
        if (read_data(i2c_handle, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue; // Try again
        }

        // Validate CRC checksums
        for (int i = 0; i < 8; i++) {
            if (!validate_crc(buffer[i], buffer[i + 8]) || !validate_crc(buffer[9 - 1], buffer[9 - 2])) {
                fprintf(stderr, "CRC validation failed\n");
                continue; // Try again
            }
        }

        // Convert raw data to pressure and temperature
        convert_data(&sensor_data);

        // Log data to CSV file
        if (log_data(sensor_data) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

