#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// SHT35 I2C address
#define SHT35_ADDR 0x44

// Measurement command (single shot, high repeatability, clock stretching disabled)
#define MEASURE_CMD 0x2C06

// File to log data to
#define LOG_FILE "environment.csv"

// Global variables for I2C handle and file pointer
