                sensor_data.temperature = (data[0] << 8) | data[1];
                sensor_data.humidity = (data[3] << 8) | data[4];

                float temperature = convert_temperature(sensor_data.temperature);
                float humidity = convert_humidity(sensor_data.humidity);

