// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RESET_CMD 0xFE
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "environment.log"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

