int init_i2c();
int read_sensor_data(uint8_t command, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "ERROR: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry and timeout
int read_sensor_data(uint8_t command, uint8_t *data, int count) {
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, command) != 0) {
            fprintf(stderr, "ERROR: I2C write failed (command 0x%02X)\n", command);
            goto retry;
        }

        gpioDelay(20); // Wait for sensor to be ready

        int bytes_read = i2cReadDevice(i2c_handle, (char *)data, count);
        if (bytes_read == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "ERROR: I2C read failed (expected %d, got %d)\n", count, bytes_read);
            goto retry;
        }

    retry:
        retries--;
        if (retries > 0) {
            fprintf(stderr, "Retrying in %d ms...\n", delay_ms);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "ERROR: Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
