    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint8_t temp_data[2];
        uint8_t humid_data[2];
        sensor_data_t sensor_data;

        // Read temperature
        if (read_sensor_data(TEMP_MEASURE_CMD, temp_data, 2) != 0) {
            fprintf(stderr, "ERROR: Failed to read temperature data.\n");
            i2cWriteByte(i2c_handle, RESET_CMD);
            gpioDelay(100); // Small delay after reset
            continue;
        }

        // Read humidity
        if (read_sensor_data(HUMID_MEASURE_CMD, humid_data, 2) != 0) {
            fprintf(stderr, "ERROR: Failed to read humidity data.\n");
            i2cWriteByte(i2c_handle, RESET_CMD);
            gpioDelay(100); // Small delay after reset
            continue;
        }

        // CRC validation
        uint8_t temp_crc = calculate_crc(temp_data, 2);
        uint8_t humid_crc = calculate_crc(humid_data, 2);

        if (temp_crc != temp_data[2] || humid_crc != humid_data[2]) {
            fprintf(stderr, "ERROR: CRC checksum validation failed.\n");
            i2cWriteByte(i2c_handle, RESET_CMD);
            gpioDelay(100); // Small delay after reset
            continue;
        }

        // Convert data
        int temp_raw = (temp_data[0] << 8) | temp_data[1];
        int humid_raw = (humid_data[0] << 8) | humid_data[1];

        sensor_data.temperature = (175.72 * temp_raw / 65536.0) - 46.85;
        sensor_data.humidity = (125.0 * humid_raw / 65536.0) - 6.0;

        // Log data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "ERROR: Failed to log data.\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

