#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define DATA_LENGTH 9

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr, int flags);
int write_i2c(int handle, int reg, int data);
int read_i2c(int handle, int reg, char *buf, int count);
int start_measurement(int handle);
int read_sensor_data(int handle, char *buf);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(const char *buf);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr, int flags) {
    int handle = i2cOpen(bus, addr, flags);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c(int handle, int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, int reg, char *buf, int count) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to write register address for read: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadDevice(handle, buf, count);
    if (result != count) {
