#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the continuous measurement command
#define MEASURE_CMD 0x362F

// Define the conversion time in milliseconds
#define CONVERSION_TIME 45

// Define the polynomial for CRC-8
#define CRC_POLYNOMIAL 0x31

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write_command(int handle, uint16_t command);
int i2c_read_data(int handle, char *buffer, int count);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
int read_sdp800(int handle, float *pressure);
void log_pressure(float pressure);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function to write a command to the I2C device
int i2c_write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int i2c_read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return (crc == checksum);
}

// Function to read pressure from the SDP800 sensor
int read_sdp800(int handle, float *pressure) {
    char buffer[9];
    int16_t raw_pressure;
    uint8_t crc_pressure;

    // Send the continuous measurement command
    if (i2c_write_command(handle, MEASURE_CMD) != 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    // Wait for the conversion time
    gpioDelay(CONVERSION_TIME * 1000); // Convert ms to us

    // Read the 9 bytes of data
    if (i2c_read_data(handle, buffer, 9) != 0) {
        fprintf(stderr, "Error reading data from sensor\n");
        return -1;
    }

    // Extract the pressure data and CRC
    raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    crc_pressure = buffer[2];

    // Validate the CRC
    if (!validate_crc((uint8_t *)buffer, 2, crc_pressure)) {
        fprintf(stderr, "CRC validation failed for pressure data\n");
        return -1;
    }

    // Convert the raw pressure to Pascals (Pa)
    *pressure = (float)raw_pressure / 240.0; // Sensitivity from datasheet

    return 0;
}

// Function to log the pressure reading to a file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);

    // Close the I2C handle if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure;

    // Main loop
    while (1) {
        // Read the pressure from the sensor
        if (read_sdp800(i2c_handle, &pressure) == 0) {
            // Log the pressure reading
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Error reading pressure\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

