    // Enable continuous mode and set ODR to 1 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

