    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    int16_t raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *temperature = (float)raw_temperature / 100.0; // Convert to °C
    return 0;
}

