#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

int i2c_handle;

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    return 0;
}

// Function to read temperature from the sensor
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1000.0; // Indicate an error
    }

    // Convert the two bytes to a signed 16-bit integer
    short raw_temp = (buf[0] << 8) | buf[1];

    // The STLM75 provides a 9-bit temperature value, left-aligned.
    // Shift right by 7 bits to get the correct value.
    raw_temp = raw_temp >> 7;

    // Convert to Celsius (0.5 degrees per bit)
    float temperature = raw_temp * 0.5;
    return temperature;
}

// Function to update the circular buffer
void update_buffer(float buffer[], int *index, float new_value) {
    buffer[*index] = new_value;
    *index = (*index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
float calculate_average(float buffer[]) {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (1) {
        float temperature = read_temperature();

        if (temperature < -900.0) { // Error occurred during read
            fprintf(stderr, "Error reading temperature, skipping iteration.\n");
            sleep(1);
            continue;
        }

        update_buffer(temperature_buffer, &buffer_index, temperature);
        float average_temperature = calculate_average(temperature_buffer);
        control_led(average_temperature);

        printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        sleep(1);
    }

    return 0;
}

