#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_ADDR 0x61
#define I2C_BUS 1

// SCD30 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Ventilation control thresholds
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
unsigned char crc8(const unsigned char *data, int len);
void log_data(sensor_data_t data);
void ventilation_control(float co2);
void signal_handler(int signal);
void log_error(const char *message);
int is_sensor_present();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    char buf[2];
    char read_buf[18];
    int result;

    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    result = i2cReadDevice(i2c_handle, read_buf, 18);
    if (result != 18) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC Check
    if (crc8(read_buf, 2) != read_buf[2] ||
        crc8(read_buf + 3, 2) != read_buf[5] ||
        crc8(read_buf + 6, 2) != read_buf[8]) {
        log_error("CRC check failed");
        return -1;
    }

    // Convert data
    unsigned int co2_raw = (read_buf[0] << 8) | read_buf[1];
    unsigned int temperature_raw = (read_buf[3] << 8) | read_buf[4];
    unsigned int humidity_raw = (read_buf[6] << 8) | read_buf[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45 + 175 * ((float)temperature_raw / 65535);
    data->humidity = 100 * ((float)humidity_raw / 65535);

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to stop periodic measurement");
        return -1;
    }
    return 0;
