void process_data(const sensor_data_t *data) {
    // Scaling factor is 1 for SDP32
    float pressure = (float)data->pressure / 10.0; // Example scaling
    float temperature = (float)data->temperature / 10.0; // Example scaling

    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
}

