// SDP810 I2C address
#define SDP810_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// Measurement command (continuous measurement without averaging)
#define MEASURE_CMD 0x362F

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the SDP810 sensor
int read_sdp810(sensor_data_t *data) {
    char buf[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 45ms)
    gpioDelay(50000); // 50ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t crc_pressure = buf[2];
    uint8_t crc_temperature = buf[5];

    uint8_t checksum_pressure = 0xFF;
    for (int i = 0; i < 2; i++) {
        checksum_pressure ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (checksum_pressure & 0x80) {
                checksum_pressure = (checksum_pressure << 1) ^ 0x31;
            } else {
                checksum_pressure <<= 1;
            }
        }
    }

    uint8_t checksum_temperature = 0xFF;
    for (int i = 0; i < 5; i++) {
