#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi 4
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

int hdc1000_init(int fd) {
    unsigned char config_data[2] = {0x00, 0x00}; // Default configuration
    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write to config register");
        return -1;
    }
    return 0;
}

int hdc1000_read_data(int fd, float *temperature, float *humidity) {
    unsigned char data[4];
    if (read(fd, data, 4) != 4) {
        perror("Failed to read data from HDC1000");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int humid_raw = (data[2] << 8) | data[3];

    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    if (hdc1000_init(i2c_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        float temperature, humidity;
        if (hdc1000_read_data(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }
        sleep(5);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

