#include <unistd.h>

// Define the I2C bus and address for the MLX90833 sensor
#define I2C_BUS 1
#define MLX90833_ADDR 0x60

// Define the command to read pressure from the sensor
#define READ_PRESSURE_CMD 0x10

// Global variable to store the I2C handle
int i2c_handle;

// Function prototypes
int initialize_i2c();
int read_pressure(float *pressure);
void log_pressure(float pressure);
void signal_handler(int signal);

// Structure to hold program state
struct ProgramState {
    int running;
};

struct ProgramState state = {1}; // Initialize running to 1

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    state.running = 0; // Set running to 0 to exit the main loop
    i2cClose(i2c_handle); // Close the I2C connection
    gpioTerminate(); // Terminate the pigpio library
    exit(0); // Exit the program
}

// Function to initialize the I2C connection
int initialize_i2c() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    printf("I2C connection established.\n");
    return 0;
}

// Function to read the pressure from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;

    // Send the command to read pressure
    result = i2cWriteByte(i2c_handle, READ_PRESSURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Read two bytes of pressure data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a pressure value (example conversion)
    uint16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure * 0.1; // Example scaling factor

    return 0;
}

// Function to log the pressure value with a timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C connection
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    float pressure;

    // Main loop to read and log pressure data
    while (state.running) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

