#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F // Trigger measurement command
#define DATA_LENGTH 9

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_data(uint8_t *data);
int log_data(uint8_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate data
int validate_data(uint8_t *data) {
    for (int i = 0; i < 3; i++) {
        uint8_t crc = calculate_crc(data + i * 2, 2);
        if (crc != data[i * 2 + 2]) {
            fprintf(stderr, "CRC validation failed for byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to log data to file
int log_data(uint8_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Convert raw data to pressure and temperature
    int16_t differential_pressure = (data[0] << 8) | data[1];
    int16_t temperature = (data[3] << 8) | data[4];

    sensor_data_t sensor_data;
    sensor_data.pressure = (float)differential_pressure / 240.0; // Scale factor from datasheet
    sensor_data.temperature = (float)temperature / 200.0; // Scale factor from datasheet

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure, sensor_data.temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[DATA_LENGTH];

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(45); // Wait for measurement (45ms)

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate data
        if (validate_data(sensor_data) != 0) {
            fprintf(stderr, "Error validating sensor data, skipping logging...\n");
            continue;
        }

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

