#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F // Continuous measurement without averaging
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "airflow_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    uint16_t temperature;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t length);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char write_data[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char read_data[3];

    if (i2cWriteDevice(i2c_handle, write_data, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10); // Wait for measurement (adjust as needed)

    if (i2cReadDevice(i2c_handle, read_data, 3) != 3) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Extract data and CRC
    data->pressure = (int16_t)((read_data[0] << 8) | read_data[1]);
    data->temperature = (uint16_t)read_data[2];
    data->crc = read_data[2];

    return 0;
}

// CRC calculation function
uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data logging function
int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is newly created and write the header
    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, data->pressure, data->temperature);
    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            uint8_t calculated_crc = calculate_crc((uint8_t *)&sensor_data, 2);

            if (calculated_crc == sensor_data.crc) {
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }
            } else {
                fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, sensor_data.crc);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(8000); // Wait 8ms
    }

    cleanup();
    return 0;
}

