            return data;
        }
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read failed after re-init: %d\n", result);
            data.pressure_kPa = -1.0; // Indicate error
            return data;
        }
    }

