            log_data(sensor_data.pressure_kPa);
            check_pressure_range(sensor_data.pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure data.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

