#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_OLD "environmental_data.log.old"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define MEASUREMENT_INTERVAL 5 // seconds
#define TRIGGER_DELAY_MS 40

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hih6130(int i2c_handle, float *temperature, float *humidity);
int log_data(const char *filename, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read temperature and humidity from HIH6130 sensor
int read_hih6130(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00); // Send any byte to trigger
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (datasheet recommends at least 37ms)
    gpioDelay(TRIGGER_DELAY_MS * 1000); // Convert ms to us

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate status bits (first two bits of data[0])
    int status = (data[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Invalid sensor status (%d). Skipping reading.\n", status);
        return -1;
    }

    // Convert data to temperature and humidity
    unsigned int humidity_raw = ((data[0] & 0x3F) << 8) | data[1];
    unsigned int temperature_raw = (data[2] << 6) | (data[3] >> 2);

    *humidity = ((float)humidity_raw / 16383) * 100;
    *temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

// Function to log data to file
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open file in append mode
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing.\n", filename);
        return -1;
    }

