#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define SENT_TIMEOUT_US 10000 // 10ms timeout
#define SENT_SYNC_PULSE_US 56
#define SENT_MIN_PULSE_US 36
#define SENT_MAX_PULSE_US 813
#define SENT_CHECKSUM_ERROR -1
#define SENT_TIMEOUT_ERROR -2
#define SENT_DATA_ERROR -3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENT_Data;

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read a single pulse width from the GPIO pin
int read_pulse_width() {
    long start_time = 0, end_time = 0;
    int pulse_width = 0;

    // Wait for the pin to go low
    while (gpioRead(GPIO_PIN) == 1) {
        start_time = gpioTick();
    }

    // Wait for the pin to go high
    while (gpioRead(GPIO_PIN) == 0) {
        end_time = gpioTick();
    }

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Function to decode the SENT data
SENT_Data decode_sent_data(int pulse_width) {
    SENT_Data data = {0, 0, 0, 0, 0};
    static unsigned int last_tick = 0;
    unsigned int current_tick = gpioTick();

    if (pulse_width < SENT_MIN_PULSE_US || pulse_width > SENT_MAX_PULSE_US) {
        fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width);
        return data; // Return default values on error
    }

    if (pulse_width > SENT_SYNC_PULSE_US) {
        data.status = (pulse_width - SENT_SYNC_PULSE_US) / 2; // Status nibble

        // Read data nibbles
        data.data1 = (pulse_width - SENT_SYNC_PULSE_US - (data.status * 2)) / 4;
        data.data2 = (pulse_width - SENT_SYNC_PULSE_US - (data.status * 2) - (data.data1 * 4)) / 4;
        data.data3 = (pulse_width - SENT_SYNC_PULSE_US - (data.status * 2) - (data.data1 * 4) - (data.data2 * 4)) / 4;

        // Calculate checksum
        unsigned int calculated_checksum = data.status + data.data1 + data.data2 + data.data3;
        calculated_checksum &= 0x0F; // Mask to 4 bits

        // Validate checksum
        if (calculated_checksum != data.checksum) {
            fprintf(stderr, "Error: Checksum mismatch! Calculated: %d, Received: %d\n", calculated_checksum, data.checksum);
            data.checksum = SENT_CHECKSUM_ERROR;
        } else {
            data.checksum = calculated_checksum;
        }
    } else {
        data.status = SENT_DATA_ERROR;
        data.data1 = SENT_DATA_ERROR;
        data.data2 = SENT_DATA_ERROR;
        data.data3 = SENT_DATA_ERROR;
        data.checksum = SENT_DATA_ERROR;
        fprintf(stderr, "Error: Sync pulse not detected.\n");
    }

    return data;
}

// Function to log the pressure data to a file
void log_pressure_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt for writing!\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Starting pressure sensor data logging...\n");

    while (program_running) {
        int pulse_width = 0;
        SENT_Data sent_data;
        float pressure = 0.0;
        int start_time_us = gpioTick();

        // Read pulse width
        pulse_width = read_pulse_width();

        // Decode SENT data
        sent_data = decode_sent_data(pulse_width);

        if (sent_data.status == SENT_DATA_ERROR) {
            fprintf(stderr, "Error: Failed to read SENT data.\n");
        } else if (sent_data.status == SENT_CHECKSUM_ERROR) {
            fprintf(stderr, "Error: Checksum error in SENT data.\n");
        } else if (sent_data.status == SENT_TIMEOUT_ERROR) {
            fprintf(stderr, "Error: Timeout error in SENT data.\n");
        } else {
            // Calculate pressure (example: linear relationship)
            pressure = (float)(sent_data.data1 + sent_data.data2 + sent_data.data3) * 0.1; // Adjust scaling as needed

            // Log pressure data
            log_pressure_data(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        }

        // Check for timeout
        int end_time_us = gpioTick();
        if (end_time_us - start_time_us > SENT_TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout occurred while reading SENT data.\n");
        }

        gpioDelay(100); // Delay to avoid overwhelming the CPU
    }

    // Cleanup GPIO
    gpioTerminate();
    printf("GPIO terminated.\n");

    return 0;
}

