#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID 0x48
#define DATA_FILE "greenhouse_temps.dat"

int i2c_fd = -1;
FILE *fp = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to verify the TMP117 device ID
int verify_device_id(int fd) {
    uint8_t device_id;
    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (read(fd, &device_id, 1) != 1) {
        perror("Error reading device ID");
        return -1;
    }
    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x%02X)\n", device_id, DEVICE_ID);
        return -1;
    }
    printf("Device ID verified.\n");
    return 0;
}

// Function to read the temperature from the TMP117
float read_temperature(int fd) {
    uint8_t data[2];
    int16_t raw_temp;
    float temperature;

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1000.0; // Indicate error with an impossible temperature
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading temperature data");
        return -1000.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];
    temperature = raw_temp * 0.0078125;
    return temperature;
}

// Function to log the temperature to a file
int log_temperature(float temperature) {
    uint32_t temp_float = *(uint32_t*)&temperature;
    uint8_t buffer[4];
    buffer[0] = (temp_float & 0x000000FF) >> 0;
    buffer[1] = (temp_float & 0x0000FF00) >> 8;
    buffer[2] = (temp_float & 0x00FF0000) >> 16;
    buffer[3] = (temp_float & 0xFF000000) >> 24;

    if (fwrite(buffer, 1, 4, fp) != 4) {
        perror("Error writing to file");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify device ID
    if (verify_device_id(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open the data file in append binary mode
    fp = fopen(DATA_FILE, "ab");
    if (fp == NULL) {
        perror("Error opening data file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature(i2c_fd);
        if (temperature > -999.0) { // Check for read error
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log.\n");
        }
        sleep(60);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop is ever modified.
    close(i2c_fd);
    fclose(fp);
    return 0;
}

