        return 1;
    }
    return 0;
}

// Send command to SHT40
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read data from SHT40
int read_data(int handle, char *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }
    return 0;
}

// CRC-8 validation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

