    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

