#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// Measurement command (Normal Mode, Clock Stretching Enabled)
#define MEASURE_CMD 0x7866

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Function prototypes
int shtc3_read_data(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
int validate_data(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHTC3
int shtc3_read_data(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 12.4 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -2;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -3;
    }

    // Convert data to temperature and humidity
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    *temperature = 175.0f * temperature_raw / 65535.0f - 45.0f;
    *humidity = 100.0f * humidity_raw / 65535.0f;

    return 0;
}

// Function to validate temperature and humidity data
int validate_data(float temperature, float humidity) {
    if (temperature < -40.0 || temperature > 125.0 || humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Invalid data: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("shtc3_environment.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Write data to log file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    // Close log file
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        result = shtc3_read_data(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Validate data
            if (validate_data(temperature, humidity) == 0) {
                // Log data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                // Print data to stdout
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Invalid data received\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data: %d\n", result);
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

