#define SI7202_REG_FIELD_B 0x01
#define SI7202_REG_TEMP 0x02
#define SI7202_REG_CONFIG 0x03
#define SAMPLE_INTERVAL_MS 1000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    double speed;
    double temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Configure the sensor (example: set ODR to 100 Hz)
    char config_data[2] = {SI7202_REG_CONFIG, 0x03}; // Example configuration value
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Extract field data
    int16_t field_a = (buffer[0] << 8) | buffer[1];
    int16_t field_b = (buffer[2] << 8) | buffer[3];

    // Extract temperature data
    int16_t temp_raw = (buffer[4] << 8) | buffer[5];
    double temperature = (double)temp_raw / 100.0; // Example conversion

    // Calculate speed (example: simple RMS approximation)
    data->speed = (double)field_a * (double)field_a + (double)field_b * (double)field_b;
    data->speed = sqrt(data->speed); // Simple RMS calculation

