#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
char* format_log_entry(float temperature);
int write_to_log(char* log_entry);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        terminate = 1;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * TEMP_SCALE;
    return temperature;
}

// Format log entry with timestamp
char* format_log_entry(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char *log_entry = (char*)malloc(100 * sizeof(char)); // Allocate memory for the log entry
    if (log_entry == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    snprintf(log_entry, 100, "%s, Temperature: %.2f C\n", timestamp, temperature);
    return log_entry;
}

// Write log entry to file
int write_to_log(char* log_entry) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    if (fprintf(fp, "%s", log_entry) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    int reinit_attempts = 0;
    while (init_i2c() != 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Attempting to re-initialize I2C (attempt %d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
        reinit_attempts++;
        gpioDelay(1000); // Wait before re-initializing
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after multiple attempts. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature < -999.0) { // Check for error condition
            fprintf(stderr, "Error reading temperature. Skipping log entry.\n");
        } else {
            char* log_entry = format_log_entry(temperature);
            if (log_entry != NULL) {
                if (write_to_log(log_entry) != 0) {
                    fprintf(stderr, "Error writing to log. Check permissions and disk space.\n");
                }
                free(log_entry); // Free allocated memory
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

