#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C address of the Honeywell HAFUHH0025PA3 sensor
#define I2C_ADDR 0x28

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the filename for logging
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t flow;
    uint16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void process_sensor_data(const sensor_data_t *data, float *flow_slpm, float *temperature_c);
int log_data(float flow_slpm, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C device initialized successfully.\n");
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the bytes into 14-bit flow and 12-bit temperature values
    data->flow = ((uint16_t)buf[0] << 6) | (buf[1] >> 2);
    data->temperature = ((uint16_t)buf[2] << 4) | (buf[3] >> 4);

    return 0;
}

// Function to process the raw sensor data
void process_sensor_data(const sensor_data_t *data, float *flow_slpm, float *temperature_c) {
    // Convert raw flow value to SLPM (adjust based on sensor datasheet)
    *flow_slpm = (float)data->flow / 120.0; // Example conversion

    // Convert raw temperature value to Celsius (adjust based on sensor datasheet)
    *temperature_c = (float)data->temperature / 4.0; // Example conversion
}

