#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define DHT11_PIN 4 // BCM GPIO 4, physical pin 7
#define TIMEOUT_US 100000 // 100ms timeout

// Structure to hold DHT11 data
typedef struct {
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
    uint8_t checksum;
} DHT11Data;

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to log errors with timestamp and status code
void log_error(int status, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s - ERROR: Status %d - %s\n", timestamp, status, message);
}

// Function to log data with timestamp
void log_data(const DHT11Data *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    printf("%s - Humidity: %d.%d, Temperature: %d.%d\n", timestamp, data->humidity_integer, data->humidity_decimal, data->temperature_integer, data->temperature_decimal);
}

// Function to log sensor absent conditions
void log_sensor_absent(int status, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s - SENSOR ABSENT: Status %d - %s\n", timestamp, status, message);
}

// Function to log checksum failures
void log_checksum_failure(int status, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s - CHECKSUM FAILURE: Status %d - %s\n", timestamp, status, message);
}

// Function to log timeouts
void log_timeout(int status, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s - TIMEOUT: Status %d - %s\n", timestamp, status, message);
}

// Function to read DHT11 data
int read_dht11(DHT11Data *data) {
    int i, j;
    uint32_t start_time, bit_time;
    uint32_t pulse_length;
    uint8_t bit;
    uint8_t data_buffer[5] = {0, 0, 0, 0, 0};
    uint8_t checksum;

    // 1. Send start signal
    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioWrite(DHT11_PIN, 0);
    gpioDelay(18000); // > 18ms
    gpioWrite(DHT11_PIN, 1);
    gpioDelay(20);

    // 2. Receive response
    gpioSetMode(DHT11_PIN, PI_INPUT);
    gpioSetPullUpDown(DHT11_PIN, PI_PUD_UP);
    gpioDelay(80); // Wait for initial 80us low pulse

    if (gpioRead(DHT11_PIN) != 0) {
        log_error(1, "DHT11 not responding (initial low pulse missing)");
        return 1;
    }
    gpioDelay(80); // Wait for initial 80us high pulse

    if (gpioRead(DHT11_PIN) != 1) {
        log_error(2, "DHT11 not responding (initial high pulse missing)");
        return 2;
    }
    gpioDelay(80);

    // 3. Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low pulse (50us)
            start_time = gpioTick();
            while (gpioRead(DHT11_PIN) == 0) {
                if (gpioTick() - start_time > TIMEOUT_US) {
                    log_timeout(3, "Timeout waiting for low pulse");
                    return 3;
                }
            }

            // Measure high pulse duration (26-28us for 0, 70us for 1)
            start_time = gpioTick();
            while (gpioRead(DHT11_PIN) == 1) {
                if (gpioTick() - start_time > TIMEOUT_US) {
                    log_timeout(4, "Timeout waiting for high pulse");
                    return 4;
                }
            }
            pulse_length = gpioTick() - start_time;

            // Determine bit value
            bit = (pulse_length > 50) ? 1 : 0; // > 50us is a '1', otherwise '0'

            // Store bit in data buffer
            data_buffer[i] <<= 1;
            data_buffer[i] |= bit;
        }
    }

    // 4. Verify checksum
    checksum = data_buffer[0] + data_buffer[1] + data_buffer[2] + data_buffer[3];
    if (checksum != data_buffer[4]) {
        log_checksum_failure(5, "Checksum failure");
        return 5;
    }

    // 5. Populate DHT11Data structure
    data->humidity_integer = data_buffer[0];
    data->humidity_decimal = data_buffer[1];
    data->temperature_integer = data_buffer[2];
    data->temperature_decimal = data_buffer[3];
    data->checksum = data_buffer[4];

    return 0; // Success
}

// Function to write data to file
void write_to_file(const DHT11Data *data) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        log_error(6, "Failed to open file for writing");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, data->humidity_integer, data->humidity_decimal, data->temperature_integer, data->temperature_decimal);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT11Data data;

    while (!terminate) {
        int status = read_dht11(&data);

        if (status == 0) {
            log_data(&data);
            write_to_file(&data);
        } else {
            switch (status) {
                case 1:
                    log_sensor_absent(status, "DHT11 not responding (initial low pulse missing)");
                    break;
                case 2:
                    log_sensor_absent(status, "DHT11 not responding (initial high pulse missing)");
                    break;
                case 3:
                    log_timeout(status, "Timeout waiting for low pulse");
                    break;
                case 4:
                    log_timeout(status, "Timeout waiting for high pulse");
                    break;
                case 5:
                    log_checksum_failure(status, "Checksum failure");
                    break;
                default:
                    log_error(status, "Unknown error");
                    break;
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    gpioTerminate();
    return 0;
}

