#define LOG_FILE "pressure_log.txt"

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void log_error(const char *message);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data = {0.0, 0.0};
    char buf[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        log_error("Failed to read sensor data");
        return data; // Return default values on error
    }

    // Convert the data (example conversion, adjust based on datasheet)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[2] << 8) | buf[3];

    // Example conversion formulas (replace with actual formulas from datasheet)
    data.pressure = (float)raw_pressure * 0.1; // kPa
    data.temperature = (float)raw_temperature * 0.01 - 40.0; // Celsius

    return data;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fclose(log_file);
}

