    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file for error logging");
        return;
    }

    fprintf(log_file, "%s,ERROR: %s\n", timestamp, message);
    fclose(log_file);
}

