    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(2000); // Wait 2 seconds
    }

    return 0;
}

