void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

