    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    time_t last_print_time = time(NULL);

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Add temperature to circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate running average
            float average_temp = calculate_average(&temp_buffer);

            // Control cooling fan
            control_fan(average_temp);

            // Print temperature and average every 5 seconds
            time_t current_time = time(NULL);
            if (current_time - last_print_time >= 5) {
                printf("Temperature: %.2f\u00b0C, Average: %.2f\u00b0C\n", temperature, average_temp);
                last_print_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading temperature. Retrying...\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

