#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Trigger measurement command
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_data(const sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate data
            if (validate_data(&sensor_data) == 0) {
                // Log data
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }

                // Check pressure threshold and print warning
                if (sensor_data.pressure > 5000) { // 5.0 Pa
                    fprintf(stderr, "WARNING: Differential pressure exceeds 5.0 Pa: %d Pa\n", sensor_data.pressure);
                }
            } else {
                fprintf(stderr, "CRC validation failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[9];
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command.\n");
        return 1;
    }

    gpioDelay(45); // Wait 45 ms

    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return 1;
    }

    // Extract data from buffer
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->crc_pressure = buf[2];
    data->crc_temperature = buf[5];

    return 0;
}

// Validate data using CRC check
int validate_data(const sensor_data_t *data) {
    if (crc8((uint8_t *)data, 2) != data->crc_pressure) {
        return 1;
    }
    if (crc8((uint8_t *)(data + 1), 2) != data->crc_temperature) {
        return 1;
    }
    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (float)data->pressure / 10.0, (float)data->temperature / 10.0);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

