// Constants
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_PIN 17 // BCM GPIO 17
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from STTS2004
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = wiringPiI2CReadReg16(i2c_fd, TEMP_REG);
    if (raw_temp == -1) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see STTS2004 datasheet)
    temperature = (float)((int16_t)raw_temp >> 4) * 0.0625;
    return temperature;
}

// Function to control the LED based on temperature
