#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F

// Define the CRC-8 polynomial and initialization value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *fp = NULL;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *data, int count);
uint8_t crc8(const char *data, int len);
int validate_crc(uint8_t crc_calculated, uint8_t crc_received);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t crc8(const char *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t crc_calculated, uint8_t crc_received) {
    return (crc_calculated == crc_received);
}

// Read sensor data and perform CRC validation
int read_sensor_data(int handle, sensor_data_t *data) {
    char raw_data[9];
    int16_t differential_pressure_raw, temperature_raw;
    uint8_t pressure_crc, temperature_crc;

    // Send measurement command
    if (send_command(handle, MEASURE_CMD) < 0) {
        return -1;
    }

    // Wait for at least 45ms
    gpioDelay(50000); // 50ms

    // Read 9 bytes of data
    if (read_data(handle, raw_data, 9) < 0) {
        return -1;
    }

    // Extract data
    differential_pressure_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    pressure_crc = raw_data[2];
    temperature_raw = (int16_t)((raw_data[3] << 8) | raw_data[4]);
    temperature_crc = raw_data[5];
    // Skip the next 3 bytes of scale factor data

    // Calculate CRC checksums
    uint8_t calculated_pressure_crc = crc8(raw_data, 2);
    uint8_t calculated_temperature_crc = crc8(raw_data + 3, 2);

    // Validate CRC checksums
    if (!validate_crc(calculated_pressure_crc, pressure_crc)) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }
    if (!validate_crc(calculated_temperature_crc, temperature_crc)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Convert raw data to physical units (Pa and Celsius)
    data->differential_pressure = (float)differential_pressure_raw / 240.0; // Pa
    data->temperature = (float)temperature_raw / 200.0; // Celsius

    return 0;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f, %.2f\n", timestamp, data.differential_pressure, data.temperature);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C communication
    if (init_i2c() < 0) {
        return 1;
    }

    // Open the data log file
    fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log data to file
            log_data(fp, sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();
    return 0;
}

