#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY_NO_HOLD 0xE5
#define MEASURE_TEMPERATURE_NO_HOLD 0xE3
#define READ_TEMP_FROM_PREV_RH_MEASUREMENT 0xE0
#define RETRY_COUNT 3
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    unsigned char buf[2];
    int result;

    // Measure Relative Humidity, No Master Hold
    result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_NO_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    unsigned int humidity_raw = (buf[0] << 8) | buf[1];
    data->humidity = (125.0 * humidity_raw / 65536.0) - 6.0;

    // Measure Temperature, No Master Hold
    result = i2cWriteByte(i2c_handle, MEASURE_TEMPERATURE_NO_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    unsigned int temperature_raw = (buf[0] << 8) | buf[1];
    data->temperature = (175.72 * temperature_raw / 65536.0) - 46.85;

    return 0;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file);

    printf("%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor readings...\n");

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

