    int result;

    // Measure Relative Humidity, No Master Hold
    result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_NO_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    unsigned int humidity_raw = (buf[0] << 8) | buf[1];
    data->humidity = (125.0 * humidity_raw / 65536.0) - 6.0;

    // Measure Temperature, No Master Hold
    result = i2cWriteByte(i2c_handle, MEASURE_TEMPERATURE_NO_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    unsigned int temperature_raw = (buf[0] << 8) | buf[1];
    data->temperature = (175.72 * temperature_raw / 65536.0) - 46.85;

    return 0;
}

