// STS40 I2C address
#define STS40_ADDR 0x44

// Measure High Repeatability command
#define MEASURE_HIGH_REPEATABILITY_CMD 0x2D, 0xE0

// Global variables for signal handling
static int i2c_handle = -1;
static FILE *log_file = NULL;

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
int read_sts40(int i2c_handle, float *temperature) {
    uint8_t cmd[2] = MEASURE_HIGH_REPEATABILITY_CMD;
    uint8_t data[3];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 3 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC check
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature, FILE *log_file) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, STS40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;

    // Main loop
    while (1) {
        if (read_sts40(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature, log_file) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

