#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len, unsigned char checksum);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index);
int write_to_csv(const char *filename, const circular_buffer_t *buffer);
void log_error(const char *message);
void signal_handler(int signal);
void logging_thread(void *arg);

// CRC-8 validation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function with checksum
int validate_crc(const unsigned char *data, int len, unsigned char checksum) {
    unsigned char crc = crc8(data, len);
    return (crc == checksum);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait at least 1 second
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {0xE4, 0xB8};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // CRC validation
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (!validate_crc(buffer + 6, 2, buffer[8])) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert data
    data->co2 = (float)((unsigned int)buffer[0] << 8 | (unsigned int)buffer[1]);
    data->temperature = -45 + (float)((unsigned int)buffer[3] << 8 | (unsigned int)buffer[4]) / 65535 * 175;
    data->humidity = (float)((unsigned int)buffer[6] << 8 | (unsigned int)buffer[7]) / 65535 * 100;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    return 0;
}

// Write data to CSV file
int write_to_csv(const char *filename, const circular_buffer_t *buffer) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);

    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s%s.csv", LOG_DIR, timestamp);

    FILE *fp = fopen(filepath, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

    for (int i = 0; i < buffer->count; i++) {
        sensor_data_t data;
        if (get_from_buffer(buffer, &data, i) == 0) {
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Failed to get data from buffer\n");
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Log error message
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Logging thread function
void logging_thread(void *arg) {
    while (running) {
        gpioDelay(60000); // Sleep for 60 seconds

        if (write_to_csv("scd40_data", &buffer) != 0) {
            log_error("Failed to write data to CSV");
        }
    }
}

int main() {
    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create logging directory if it doesn't exist
    char command[128];
    snprintf(command, sizeof(command), "mkdir -p %s", LOG_DIR);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to create log directory\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create a thread for logging
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            add_to_buffer(&buffer, sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(5000); // Read every 5 seconds
    }

    // Stop periodic measurement
    char stop_cmd[2] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, 2);

    // Join the logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush remaining data to a final CSV file
    if (buffer.count > 0) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);

        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%sfinal_%s.csv", LOG_DIR, timestamp);

        FILE *fp = fopen(filepath, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open final CSV file for writing\n");
        } else {
            fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
            for (int i = 0; i < buffer.count; i++) {
                sensor_data_t data;
                if (get_from_buffer(&buffer, &data, i) == 0) {
                    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
                } else {
                    fprintf(stderr, "Failed to get data from buffer for final file\n");
                }
            }
            fclose(fp);
        }
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

