#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C address of the SDP810-500Pa sensor
#define SDP810_I2C_ADDRESS 0x25

// Define the measurement command (continuous measurement without averaging)
#define MEASUREMENT_COMMAND 0x362F

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SDP810_I2C_ADDRESS, 0); // Bus 1, address 0x25, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the SDP810-500Pa sensor
int read_sensor_data(sensor_data_t *data) {
    char write_data[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char read_data[9];

    // Send the measurement command
    if (i2cWriteDevice(i2c_handle, write_data, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for at least 45ms for the measurement to complete
    gpioDelay(50000); // 50ms

    // Read the sensor data
    if (i2cReadDevice(i2c_handle, read_data, 9) != 9) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Extract the data from the read buffer
    data->pressure = (int16_t)((read_data[0] << 8) | read_data[1]);
    data->temperature = (int16_t)((read_data[3] << 8) | read_data[4]);
    data->scale_factor = (int16_t)((read_data[6] << 8) | read_data[7]);

    // Calculate the CRC for each byte
    uint8_t pressure_crc = calculate_crc(read_data, 2);
    uint8_t temperature_crc = calculate_crc(read_data + 3, 2);
    uint8_t scale_factor_crc = calculate_crc(read_data + 6, 2);

    // Validate the CRC values
    if (pressure_crc != read_data[2] || temperature_crc != read_data[5] || scale_factor_crc != read_data[8]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log the sensor data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (float)data.pressure / 10.0, (float)data.temperature / 10.0);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

