// Define register addresses (replace with actual values from datasheet)
#define ICP10110_REG_PRODUCT_ID 0x71
#define ICP10110_REG_PRESSURE_MSB 0x00
#define ICP10110_REG_TEMP_MSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int read_register(int handle, uint8_t reg, uint8_t *data, int count);
int write_register(int handle, uint8_t reg, uint8_t *data, int count);
sensor_data_t read_sensor_data(int handle);
char* format_data(sensor_data_t data);
int write_to_file(const char *data);
void print_data(const char *data);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, ICP10110_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data(i2c_handle);

        // Format data
        char *formatted_data = format_data(sensor_data);

        // Write data to file
        if (write_to_file(formatted_data) != 0) {
            fprintf(stderr, "Failed to write data to file.\n");
        }

        // Print data to stdout
        print_data(formatted_data);

        // Free allocated memory
        free(formatted_data);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from a register
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Write data to a register
int write_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cWriteI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Failed to write register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data = {0.0, 0.0};
    uint8_t raw_data[6]; // Assuming 3 bytes for pressure and 3 for temperature

    // Read pressure data (replace with actual register addresses)
    if (read_register(handle, ICP10110_REG_PRESSURE_MSB, raw_data, 3) != 0) {
        fprintf(stderr, "Failed to read pressure data.\n");
        return data; // Return default values
    }

    // Read temperature data (replace with actual register addresses)
    if (read_register(handle, ICP10110_REG_TEMP_MSB, raw_data + 3, 3) != 0) {
        fprintf(stderr, "Failed to read temperature data.\n");
        return data; // Return default values
    }

    // Convert raw data to pressure and temperature (replace with actual conversion formulas)
    // This is a placeholder, you need to implement the correct conversion
    // based on the ICP-10110 datasheet.
    data.pressure = (float)((raw_data[0] << 16) | (raw_data[1] << 8) | raw_data[2]) / 100.0; // Example conversion
    data.temperature = (float)((raw_data[3] << 16) | (raw_data[4] << 8) | raw_data[5]) / 100.0; // Example conversion

    return data;
}

// Format data with timestamp
char* format_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    char *formatted_data = (char *)malloc(100 * sizeof(char)); // Allocate memory
    if (formatted_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for formatted data.\n");
        return NULL;
    }

    snprintf(formatted_data, 100, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    return formatted_data;
}

// Write data to file
int write_to_file(const char *data) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return -1;
    }

    if (fputs(data, fp) == EOF) {
        fprintf(stderr, "Failed to write to file.\n");
        fclose(fp);
        return -1;
    }

    fflush(fp);
    fclose(fp);
    return 0;
}

// Print data to stdout
void print_data(const char *data) {
    printf("%s", data);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed. Exiting...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

