    if (formatted_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for formatted data.\n");
        return NULL;
    }

    snprintf(formatted_data, 100, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    return formatted_data;
}

// Write data to file
int write_to_file(const char *data) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return -1;
    }

    if (fputs(data, fp) == EOF) {
        fprintf(stderr, "Failed to write to file.\n");
        fclose(fp);
        return -1;
    }

    fflush(fp);
    fclose(fp);
    return 0;
}

