#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_THRESHOLD 30.0
#define OBJECT_THRESHOLD 28.0
#define HYSTERESIS 2.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int read_temperature(int handle, int reg, float *temperature);
int write_temperature(int handle, int reg, int value);
void control_fan(float ambient_temp, float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from sensor
int read_temperature(int handle, int reg, float *temperature) {
    int count, retries = 0;
    char buf[2];
    int16_t raw_temp;

    while (retries < MAX_RETRIES) {
        count = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (count == 2) {
            raw_temp = (buf[1] << 8) | buf[0];
            *temperature = (float)raw_temp * 0.02 - 273.15;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, retry %d): %d\n", reg, retries + 1, count);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Write temperature to sensor (not used in this example, but included for completeness)
int write_temperature(int handle, int reg, int value) {
    int count, retries = 0;
    char buf[3];

    while (retries < MAX_RETRIES) {
        buf[0] = reg;
        buf[1] = (value >> 8) & 0xFF;
        buf[2] = value & 0xFF;

        count = i2cWriteI2CBlockData(handle, reg, buf + 1, 2);

        if (count == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%02X, value 0x%04X, retry %d): %d\n", reg, value, retries + 1, count);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to write temperature after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Control the cooling fan
void control_fan(float ambient_temp, float object_temp) {
    static int fan_on = 0; // Track fan state

    if (ambient_temp > AMBIENT_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (object_temp < OBJECT_THRESHOLD && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Log temperature readings to file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

int main() {
    float ambient_temp, object_temp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90614_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperatures
        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient_temp) == 0 &&
            read_temperature(i2c_handle, OBJECT_TEMP_REG, &object_temp) == 0) {
            // Control fan
            control_fan(ambient_temp, object_temp);

            // Log temperature
            log_temperature(ambient_temp, object_temp);

            printf("Ambient: %.2f °C, Object: %.2f °C\n", ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

