#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10);
            retries--;
            continue;
        }
        gpioDelay(10);
        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result == 6) {
            unsigned int temp_ticks = (buf[0] << 8) | buf[1];
            unsigned int humidity_ticks = (buf[3] << 8) | buf[4];

            *temperature = -45.0 + 175.0 * (float)temp_ticks / 65535.0;
            *humidity = 100.0 * (float)humidity_ticks / 65535.0;

            // Clamp humidity to 0-100%
            if (*humidity < 0.0) *humidity = 0.0;
