#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define SSR_GPIO 17 // BCM numbering
#define PWM_FREQUENCY 1000 // 1 kHz
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

// PID Constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static float target_profile[100]; // Assuming a maximum of 100 profile points
static int profile_size = 0;
static float current_time = 0.0;
static float current_target_temp = 20.0; // Default initial temperature

// Function Prototypes
float read_temperature();
void update_ssr(float duty_cycle);
void load_profile(const char *filename);
float pid_control(float setpoint, float actual_value);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX6675
float read_temperature() {
    char buf[2];
    int result;

    result = spiRead(spi_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bit (bit 0 of byte 1)
    if (buf[1] & 0x01) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -273.15; // Indicate error with absolute zero
    }

    // Extract temperature data (bits 3-14 of byte 0 and byte 1)
    int16_t raw_temp = ((buf[0] << 8) | buf[1]) >> 3;
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to update SSR duty cycle using PWM
void update_ssr(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pwm_value = (int)(duty_cycle * 255.0); // Scale to 0-255
    gpioPWM(SSR_GPIO, pwm_value);
}

// Function to load temperature profile from file
void load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        return;
    }

    char line[256];
    profile_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL && profile_size < 100) {
        float time, temp;
        if (sscanf(line, "%f,%f", &time, &temp) == 2) {
            target_profile[profile_size++] = temp;
            current_time = time;
        } else {
            fprintf(stderr, "Error parsing line: %s\n", line);
        }
    }

    fclose(fp);

    if (profile_size == 0) {
        fprintf(stderr, "Warning: Profile file is empty or invalid.\n");
    }
}

// Function to implement PID control
float pid_control(float setpoint, float actual_value) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    float error = setpoint - actual_value;

    integral += error;
    float derivative = error - previous_error;

    float output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    return output;
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set SSR GPIO as output
    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SSR_GPIO, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    load_profile(PROFILE_FILE);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    time_t last_profile_time = time(NULL);
    time_t current_time_local;

    // Main loop
    while (running) {
        float temperature = read_temperature();
        if (temperature < -200) {
            fprintf(stderr, "Invalid temperature reading, skipping PID control.\n");
            sleep(1);
            continue;
        }

        // Update time for profile loading
        current_time = time(NULL);
        current_time_local = localtime(&current_time);
        if (current_time_local - last_profile_time >= 60) {
            load_profile(PROFILE_FILE);
            last_profile_time = current_time;
        }

        // Calculate duty cycle using PID control
        float duty_cycle = pid_control(current_target_temp, temperature);

        // Update SSR
        update_ssr(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioSetMode(SSR_GPIO, PI_INPUT); // Set back to input
    fclose(log_file);
    gpioTerminate();

    return 0;
}

