#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>

// Constants
#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_RELAY 17
#define GPIO_PWM 18
#define PWM_RANGE 1024
#define PWM_FREQUENCY 1000 // Hz
#define DEFAULT_SETPOINT 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define LOG_FILE "greenhouse.log"
#define SERVER_PORT 12345

// Global variables
double setpoint = DEFAULT_SETPOINT;
double Kp = DEFAULT_KP;
double Ki = DEFAULT_KI;
double Kd = DEFAULT_KD;
char sensor_id[20] = {0};
int server_socket = -1;
FILE *log_file = NULL;

// Function prototypes
int read_temperature(const char *sensor_id, double *temperature);
int validate_crc(const char *data);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double Kp, double Ki, double Kd);
void set_pwm_duty_cycle(int duty_cycle);
void set_relay_state(int state);
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from DS18B20 sensor
int read_temperature(const char *sensor_id, double *temperature) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_PATH, sensor_id, W1_SLAVE_FILE);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading from %s\n", filepath);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature from line2
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (double)temp_raw / 1000.0;

    return 0;
}

// Function to validate CRC checksum
int validate_crc(const char *data) {
    unsigned char crc = 0;
    unsigned char i, bit;

    for (i = 0; i < 85; i++) {
        bit = (unsigned char)data[i];
        if (bit == '0')
            crc ^= (1 << (7 - (i % 8)));
        if (i > 0 && (i % 8) == 0)
            crc = (crc >> 1) ^ 0x83;
    }

    if (crc != (unsigned char)data[85])
        return 0;

    return 1;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double Kp, double Ki, double Kd) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    pwmWrite(GPIO_PWM, duty_cycle);
}

// Function to set relay state
void set_relay_state(int state) {
    digitalWrite(GPIO_RELAY, state);
}

// Function to log data to file
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    set_relay_state(0); // Turn off heater
    set_pwm_duty_cycle(0); // Set PWM to 0
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    wiringPiSetupGpio();
    pinMode(GPIO_RELAY, OUTPUT);
    digitalWrite(GPIO_RELAY, LOW);
    pinMode(GPIO_PWM, PWM_OUTPUT);
    pwmWrite(GPIO_PWM, 0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <sensor_id> <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }

    strncpy(sensor_id, argv[1], sizeof(sensor_id) - 1);
    setpoint = atof(argv[2]);
    Kp = atof(argv[3]);
    Ki = atof(argv[4]);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_PWM, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        fprintf(stderr, "Error binding socket: %s\n", strerror(errno));
