#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_read_data(uint8_t *data);
float aht20_convert_humidity(uint8_t *data);
void gpio_set_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// AHT20 Initialization function
int aht20_init() {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
        if (result == 0) {
            gpioDelay(20); // Wait for initialization to complete
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing initialization command (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    fprintf(stderr, "Failed to initialize AHT20 after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// AHT20 Data Reading function
int aht20_read_data(uint8_t *data) {
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading data (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    fprintf(stderr, "Failed to read data after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// AHT20 Humidity Conversion function
float aht20_convert_humidity(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    float humidity = ((float)humidity_raw / 0x100000) * 100;
    return humidity;
}

// GPIO Relay Control function
void gpio_set_relay_state(int state) {
    gpioWrite(GPIO_RELAY, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        float humidity;
        int result;

        // Trigger measurement
        uint8_t trigger_cmd[3] = {0xAC, 0x33, 0x00};
        result = i2cWriteDevice(i2c_handle, (char *)trigger_cmd, 3);
        if (result != 0) {
            fprintf(stderr, "Error triggering measurement: %d\n", result);
            continue; // Skip to the next iteration
        }

        gpioDelay(MEASUREMENT_DELAY_MS);

        // Read data
        if (aht20_read_data(data) != 0) {
            fprintf(stderr, "Failed to read data, retrying initialization...\n");
            aht20_init(); // Attempt to re-initialize
            continue;
        }

        // Convert humidity
        humidity = aht20_convert_humidity(data);

        // Get current time
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Log humidity reading
        printf("%s Humidity: %.2f%%\n", timestamp, humidity);

        // Control dehumidifier relay
        if (humidity > HUMIDITY_THRESHOLD_HIGH) {
            gpio_set_relay_state(1); // Turn on relay
        } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
            gpio_set_relay_state(0); // Turn off relay
        }

        gpioDelay(POLL_INTERVAL_S * 1000); // Wait 5 seconds
    }

    // Cleanup
    gpio_set_relay_state(0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

