#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting gracefully.");
    terminate = 1;
}

int read_htu21d_data(int handle, unsigned char *data) {
    if (i2cWriteByte(handle, TRIGGER_HUMID_MEASURE) != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement.");
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet says 50ms)

    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read humidity data.");
        return -1;
    }

    return 0;
}

float calculate_humidity(unsigned short raw_humidity) {
    float humidity = (float)raw_humidity * 125.0 / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

int post_humidity_data(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[50];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed.");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Assuming API endpoint listens on port 80
    if (inet_pton(AF_INET, API_ENDPOINT, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported.");
        close(sockfd);
        return -1;
    }

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    if (sendto(sockfd, json_data, strlen(json_data), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Failed to send data.");
        close(sockfd);
