#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control duration
#define MOTOR_DURATION 5 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void control_motor(int forward);
void stop_motor();
void log_message(const char *message);
void signal_handler(int signal);

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed. Exiting.");
        return 1;
    }

    log_message("Program started.");

    // Main loop
    while (program_running) {
        // Read rain sensor
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) {
            // Rain detected
            log_message("Rain detected!");

            // Control the motor
            control_motor(1); // Forward

            // Stop the motor
            stop_motor();

            // Log the motor control
            log_message("Motor stopped.");
        } else if (rain_detected < 0) {
            log_message("Error reading rain sensor.");
        }

        // Wait for 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Cleanup and exit
    log_message("Program terminated.");
    stop_motor(); // Ensure motor is stopped on exit
    gpioTerminate(); // Terminate pigpio
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set initial motor state to stopped
    stop_motor();

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message("Error reading rain sensor.");
        return -1;
    }
    return sensor_value;
}

// Function to control the motor
void control_motor(int forward) {
    if (forward) {
        // Move forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 100); // Set PWM duty cycle (0-255)
        log_message("Motor started (forward).");
    } else {
        // Move backward (not implemented in this example)
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        gpioPWM(MOTOR_ENA_PIN, 100); // Set PWM duty cycle
        log_message("Motor started (backward).");
    }
}

// Function to stop the motor
void stop_motor() {
    // Stop the motor
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_ENA_PIN, 0); // Set PWM duty cycle to 0
    log_message("Motor stopped.");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fflush(stdout); // Ensure the message is immediately written to stdout
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, stopping motor and exiting...");
}

