#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU usage from /proc/stat
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading /proc/stat");
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu", user, nice, system, idle) != 4) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
double calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle,
                           unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle)
{
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle;
    unsigned long long total = user + nice + system + idle;

    unsigned long long prev_idle_all = prev_total;
    unsigned long long idle_all = total;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle_all - prev_idle_all;

    if (delta_total == 0) {
        return 0.0; // Avoid division by zero
    }

    return 100.0 * (delta_idle / delta_total);
}

// Function to map CPU load to RGB color values
void map_load_to_color(double load, int *red, int *green, int *blue)
{
    if (load < 50.0) {
        // Green to Yellow
        *red = (int)(255.0 * (load / 50.0));
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = 255.0 * (100.0 - (load - 50.0) / 50.0);
        *blue = 0;
    }
}

// Function to set PWM values for RGB LED
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    unsigned long long prev_user, prev_nice, prev_system, prev_idle;
    unsigned long long user, nice, system, idle;
    double cpu_load;
    int red, green, blue;

    // Initial CPU stats
    if (read_cpu_stats(&prev_user, &prev_nice, &prev_system, &prev_idle) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU stats
        if (read_cpu_stats(&user, &nice, &system, &idle) != 0) {
            fprintf(stderr, "Error reading CPU stats, exiting\n");
            break;
        }

        // Calculate CPU load
        cpu_load = calculate_cpu_load(prev_user, prev_nice, prev_system, prev_idle, user, nice, system, idle);

        // Map CPU load to color
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU stats
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;

        // Wait 500ms
        usleep(500000); // 500ms = 500000 microseconds
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

