#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define FAN_GPIO 18
#define BUFFER_SIZE 20

// Structure to store temperature and duty cycle
typedef struct {
    float temperature;
    int duty_cycle;
} DataPoint;

// Circular buffer
DataPoint buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(float *temperature);
int set_fan_speed(int duty_cycle);
void update_buffer(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Global variable for pigpio initialization status
int pigpio_initialized = 0;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(FAN_GPIO, 1000);

    // Set PWM range to 0-255
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open SPI channel
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle;

    // Main loop
    while (1) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature\n");
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle based on temperature
        if (temperature < 25.0) {
            duty_cycle = 0;
        } else if (temperature < 40.0) {
            duty_cycle = (int)((temperature - 25.0) * 50.0);
        } else if (temperature < 60.0) {
            duty_cycle = 50 + (int)((temperature - 40.0) * 150.0);
        } else {
            duty_cycle = 255;
        }

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed\n");
        }

        // Update circular buffer
        update_buffer(temperature, duty_cycle);

        // Print buffer contents every 10 seconds
        if (buffer_index % 10 == 0) {
            print_buffer();
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    return 0;
}

// Function to read temperature from MAX31855
