#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI mode 0
#define RTD_NOMINAL 100.0 // PT100
#define A 3.9083e-3
#define B 5.775e-7
#define C -4.183e-3
#define REF_RESISTOR 430.0
#define LOG_FILE "rtd_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
float read_temperature();
float calculate_temperature(float rtd_resistance);
void log_data(float temperature);
void signal_handler(int signal);

// Function to read a register from the MAX31865
int spi_read_register(int reg) {
  char tx[2], rx[2];
  tx[0] = 0x80 | (reg << 1); // Set MSB for read
  tx[1] = 0x00;

  if (spiXfer(spi_handle, tx, rx, 2) != 0) {
    fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
    return -1;
  }

  return rx[1];
}

// Function to write a register to the MAX31865
int spi_write_register(int reg, int value) {
  char tx[2], rx[2];
  tx[0] = (reg << 1); // Clear MSB for write
  tx[1] = value;

  if (spiXfer(spi_handle, tx, rx, 2) != 0) {
    fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
    return -1;
  }

  return 0;
}

// Function to read the temperature from the MAX31865
float read_temperature() {
  int rtd_msb, rtd_lsb, rtd_fault;
  int rtd_raw;

  rtd_msb = spi_read_register(0x01);
  rtd_lsb = spi_read_register(0x02);
  rtd_fault = spi_read_register(0x03);

  if (rtd_msb < 0 || rtd_lsb < 0 || rtd_fault < 0) {
    fprintf(stderr, "Error reading RTD registers\n");
    return -1000.0; // Indicate error
  }

  rtd_raw = ((rtd_msb << 8) | rtd_lsb) >> 1; // Remove fault bit

  if (rtd_raw == 0) {
    fprintf(stderr, "Sensor absent\n");
    return -1000.0; // Indicate error
  }

  // Check for fault
  if (rtd_fault & 0x01) {
    fprintf(stderr, "RTD fault detected!\n");
    return -1000.0; // Indicate error
  }

  // Read configuration register to confirm 3-wire mode
  int config = spi_read_register(0x00);
  if (config < 0) {
    fprintf(stderr, "Error reading config register\n");
    return -1000.0;
  }
  if ((config & 0x01) != 0) {
      fprintf(stderr, "MAX31865 not configured for 3-wire mode\n");
      return -1000.0;
  }

  // Read bias voltage register to confirm bias voltage enabled
  config = spi_read_register(0x04);
  if (config < 0) {
    fprintf(stderr, "Error reading bias voltage register\n");
    return -1000.0;
  }
  if ((config & 0x01) != 0) {
      fprintf(stderr, "MAX31865 not configured for bias voltage\n");
      return -1000.0;
  }

  // Read RTD value
  return (float)rtd_raw;
}

// Function to calculate the temperature using the Callendar-Van Dusen equation
float calculate_temperature(float rtd_resistance) {
  float rtd_ratio = rtd_resistance / REF_RESISTOR;
  float temperature = A + (B + C * rtd_ratio) * rtd_ratio;
  return temperature;
}

// Function to log the data to a file
void log_data(float temperature) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[80];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
  fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  fprintf(stderr, "Received signal %d, terminating...\n", signal);
  terminate = 1;
}

int main() {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Open SPI device
  spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
  if (spi_handle < 0) {
    fprintf(stderr, "SPI open failed\n");
    gpioTerminate();
    return 1;
  }

  // Open log file
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    spiClose(spi_handle);
    gpioTerminate();
    return 1;
  }

  // Write header to log file if it's a new file
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,Temperature(C)\n");
  }
  rewind(log_file);

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (!terminate) {
    float rtd_resistance = read_temperature();
    if (rtd_resistance > 0) {
      float temperature = calculate_temperature(rtd_resistance);
      log_data(temperature);
      printf("Temperature: %.2f C\n", temperature);
    } else {
      fprintf(stderr, "Failed to read temperature\n");
    }

    sleep(5);
  }

  // Cleanup
  spiClose(spi_handle);
  fclose(log_file);
  gpioTerminate();

  return 0;
}

