#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int handle, struct bme280_calib_data *cal) {
    cal->dig_T1 = i2c_read_reg(handle, BME280_REG_CALIB_00);
    cal->dig_T1 |= (i2c_read_reg(handle, BME280_REG_CALIB_00 + 1) << 8);

    cal->dig_T2 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 2) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 3) << 8));

    cal->dig_T3 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 4) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 5) << 8));

    cal->dig_P1 = i2c_read_reg(handle, BME280_REG_CALIB_00 + 6);
    cal->dig_P1 |= (i2c_read_reg(handle, BME280_REG_CALIB_00 + 7) << 8);

    cal->dig_P2 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 8) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 9) << 8));

    cal->dig_P3 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 10) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 11) << 8));

    cal->dig_P4 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 12) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 13) << 8));

    cal->dig_P5 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 14) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 15) << 8));

    cal->dig_P6 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 16) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 17) << 8));

    cal->dig_P7 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 18) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 19) << 8));

    cal->dig_P8 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 20) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 21) << 8));

    cal->dig_P9 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_00 + 22) | (i2c_read_reg(handle, BME280_REG_CALIB_00 + 23) << 8));

    cal->dig_H1 = i2c_read_reg(handle, BME280_REG_CALIB_26);

    cal->dig_H2 = (int16_t)(i2c_read_reg(handle, BME280_REG_CALIB_26 + 1) | (i2c_read_reg(handle, BME280_REG_CALIB_26 + 2) << 8));

    cal->dig_H3 = i2c_read_reg(handle, BME280_REG_CALIB_26 + 3);

    cal->dig_H4 = (int16_t)((i2c_read_reg(handle, BME280_REG_CALIB_26 + 4) << 4) | (i2c_read_reg(handle, BME280_REG_CALIB_26 + 5) & 0x0F));

    cal->dig_H5 = (int16_t)((i2c_read_reg(handle, BME280_REG_CALIB_26 + 6) << 4) | (i2c_read_reg(handle, BME280_REG_CALIB_26 + 5) >> 4));

    cal->dig_H6 = (int8_t)i2c_read_reg(handle, BME280_REG_CALIB_26 + 7);

    return 0;
}

// Function to initialize the BME280 sensor
int init_bme280(int handle) {
    // Check the chip ID
    int chip_id = i2c_read_reg(handle, BME280_REG_CHIPID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(handle, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_reg(handle, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error setting humidity oversampling\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to forced
    if (i2c_write_reg(handle, BME280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Error setting temperature/pressure oversampling and mode\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
int read_raw_data(int handle, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int32_t raw_temp_msb = i2c_read_reg(handle, BME280_REG_TEMP_MSB);
    int32_t raw_temp_lsb = i2c_read_reg(handle, BME280_REG_TEMP_LSB);
    int32_t raw_temp_xlsb = i2c_read_reg(handle, BME280_REG_TEMP_XLSB);

    int32_t raw_press_msb = i2c_read_reg(handle, BME280_REG_PRESS_MSB);
    int32_t raw_press_lsb = i2c_read_reg(handle, BME280_REG_PRESS_LSB);
    int32_t raw_press_xlsb = i2c_read_reg(handle, BME280_REG_PRESS_XLSB);

    int32_t raw_hum_msb = i2c_read_reg(handle, BME280_REG_HUM_MSB);
    int32_t raw_hum_lsb = i2c_read_reg(handle, BME280_REG_HUM_LSB);

    if (raw_temp_msb < 0 || raw_temp_lsb < 0 || raw_temp_xlsb < 0 ||
        raw_press_msb < 0 || raw_press_lsb < 0 || raw_press_xlsb < 0 ||
        raw_hum_msb < 0 || raw_hum_lsb < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *temperature = (raw_temp_msb << 12) | (raw_temp_lsb << 4) | (raw_temp_xlsb >> 4);
    *pressure = (raw_press_msb << 12) | (raw_press_lsb << 4) | (raw_press_xlsb >> 4);
    *humidity = (raw_hum_msb << 8) | raw_hum_lsb;

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temp, struct bme280_calib_data cal) {
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)cal.dig_T1) / 1024.0) * ((double)cal.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)cal.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)cal.dig_T1) / 8192.0)) * ((double)cal.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
