#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 50ms = 3000 samples)
#define BUFFER_SIZE 3000

// Structure to hold pressure reading and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

// Circular buffer
PressureReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// I2C handle
int i2c_handle;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t raw_temp);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void add_reading(float pressure);
float calculate_rolling_average();
void set_alert(bool active);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temp, raw_pressure;
    float temperature, pressure, rolling_average;

    // Main loop
    while (program_running) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Add reading to circular buffer
        add_reading(pressure);

        // Calculate rolling average
        rolling_average = calculate_rolling_average();

        // Check for deviation and set alert
        if (fabs(pressure - rolling_average) > 5.0) {
            set_alert(true);
            fprintf(stderr, "Alert: Pressure deviation detected!\n");
        } else {
            set_alert(false);
        }

        // Print current values for debugging
        printf("Temperature: %.2f C, Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", temperature, pressure, rolling_average);

        // Wait 50ms
        gpioDelay(50000); // pigpioDelay is in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Turn off alert
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data from I2C\n");
