// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t buffer[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22);

    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    return 0;
}

