int read_raw_temperature(int *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    uint8_t data[2];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature data: %d\n", result);
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(2 + (3 << OSS)) ; // Wait for conversion

    uint8_t data[3];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3);

    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
