#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int read_temperature() {
    FILE *fp;
    int temperature = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temperature;
}

int map_temperature_to_duty_cycle(int temperature) {
    if (temperature < 40000) {
        return 0;
    }

    if (temperature > 70000) {
        return 255;
    }

    return (temperature - 40000) * 255 / (70000 - 40000);
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting fan speed\n");
        return -1;
    }
    return 0;
}

int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %d, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    while (!terminate) {
        temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, exiting...\n");
            break;
        }

        duty_cycle = map_temperature_to_duty_cycle(temperature);

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, exiting...\n");
            break;
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        sleep(5);
    }

    set_fan_speed(0);
    gpioTerminate();

    return 0;
}

