int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check the sensor ID
    char id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_ID, &id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set forced mode and other configurations
    char config = (0x04 << 5) | (0x02 << 2) | 0x00; // t_sb = 0.5ms, filter = x4, spi3w_en = disabled
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CONFIG, &config, 1) != 1) {
        fprintf(stderr, "Failed to write config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set forced mode and oversampling
    char ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x03; // osrs_t = x16, osrs_p = x16, mode = forced
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Failed to write ctrl_meas register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read calibration data from BMP280
int read_calibration_data() {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) != 26) {
        fprintf(stderr, "Failed to read calibration data block\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | (int8_t)data[2];
    dig_T3 = (data[5] << 8) | (int8_t)data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | (int8_t)data[8];
    dig_P3 = (data[11] << 8) | (int8_t)data[10];
    dig_P4 = (data[13] << 8) | (int8_t)data[12];
    dig_P5 = (data[15] << 8) | (int8_t)data[14];
    dig_P6 = (data[17] << 8) | (int8_t)data[16];
    dig_P7 = (data[19] << 8) | (int8_t)data[18];
    dig_P8 = (data[21] << 8) | (int8_t)data[20];
    dig_P9 = (data[23] << 8) | (int8_t)data[22];

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Compensate temperature using BMP280 formulas
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using BMP280 formulas
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
