#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define REINIT_DELAY 5 // seconds

// Global variables
int i2c_handle;
int running_average = 0;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int alert_active = 0;

// Mutex
pthread_mutex_t mutex;

// Function prototypes
float read_temperature();
void update_running_average(float new_temp);
void control_alert_led(float temperature);
void *alert_thread_func(void *arg);
void signal_handler(int signal);

// Function to read temperature from LM75 sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125;

    return temperature;
}

// Function to update the running average of temperatures
void update_running_average(float new_temp) {
    pthread_mutex_lock(&mutex);
    running_average -= (int)(temperature_buffer[buffer_index] * (1.0 / buffer_size));
    running_average += new_temp;
    temperature_buffer[buffer_index] = new_temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to control the alert LED based on temperature
void control_alert_led(float temperature) {
    if (temperature > TEMP_THRESHOLD && !alert_active) {
        gpioWrite(ALERT_GPIO, 1); // Turn LED on
        alert_active = 1;
    } else if (temperature <= TEMP_THRESHOLD && alert_active) {
        gpioWrite(ALERT_GPIO, 0); // Turn LED off
        alert_active = 0;
    }
}

// Alert thread function
void *alert_thread_func(void *arg) {
    while (1) {
        sleep(1);
        pthread_mutex_lock(&mutex);
        float current_avg = (float)running_average / buffer_count;
        pthread_mutex_unlock(&mutex);
        control_alert_led(current_avg);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(ALERT_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alert LED
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure LED is off initially

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize temperature buffer with 0s
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create alert thread
    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_thread_func, NULL) != 0) {
        fprintf(stderr, "Error creating alert thread\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_running_average(temperature);
            printf("Temperature: %.2f °C, Running Average: %.2f °C\n", temperature, (float)running_average / buffer_count);
        } else {
            fprintf(stderr, "Invalid temperature reading, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            sleep(REINIT_DELAY);
            i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                // If re-initialization fails, exit the program
                signal_handler(SIGINT); // Simulate a SIGINT to clean up and exit
            }
        }
        sleep(1);
    }

    return 0;
}

