#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration structure
typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} Config;

// Global variables
static int spi_handle;
static volatile bool running = true;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double Kp, double Ki, double Kd, double *integral, double *previous_error);
void set_pwm(int duty_cycle);
void signal_handler(int signal);
void cleanup();

// MAX31865 fault detection
bool fault_detected() {
    uint8_t fault_status;
    if (spiRead(spi_handle, (char *)&fault_status, 1) != 1) {
        fprintf(stderr, "Error reading fault status\n");
        return false; // Assume no fault if read fails
    }
    return (fault_status & 0x01); // Check for fault bit
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration
    if (read_config("heater_config.json", &config) != 0) {
        fprintf(stderr, "Failed to read configuration. Using default values.\n");
        config.target_temperature = 25.0;
        config.Kp = 1.0;
        config.Ki = 0.1;
        config.Kd = 0.01;
    }

    // Initialize SPI
    spi_handle = spiOpen(0, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(18, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(18, 1000); // 1kHz
    gpioSetPWMrange(18, 1000);    // Range 0-1000 for 0-100%

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral = 0.0;
    double previous_error = 0.0;

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        // Check for errors
        if (temperature < -50.0 || temperature > 150.0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            continue; // Skip to the next iteration
        }

        if (fault_detected()) {
            fprintf(stderr, "MAX31865 Fault Detected!\n");
            set_pwm(0); // Turn off heater
            running = false;
            break;
        }

        // Calculate PID output
        double pid_output = calculate_pid(config.target_temperature, temperature, config.Kp, config.Ki, config.Kd, &integral, &previous_error);

        // Set PWM duty cycle
        int duty_cycle = (int)pid_output;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 1000) duty_cycle = 1000;
        set_pwm(duty_cycle);

        // Print debug information
        printf("Temperature: %.2f °C, PID Output: %.2f, Duty Cycle: %d\n", temperature, pid_output, duty_cycle);

        // Failsafe
        if (temperature > 80.0) {
            fprintf(stderr, "Failsafe triggered! Temperature exceeds 80 °C\n");
            set_pwm(0); // Turn off heater
            running = false;
            break;
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Read configuration from JSON file
int read_config(const char *filename, Config *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config file: %s\n", error.text);
        return 1;
    }

    json_t *target_temperature = json_object_get(root, "target_temperature");
    json_t *Kp = json_object_get(root, "Kp");
    json_t *Ki = json_object_get(root, "Ki");
    json_t *Kd = json_object_get(root, "Kd");

    if (!json_is_real(target_temperature) || !json_is_real(Kp) || !json_is_real(Ki) || !json_is_real(Kd)) {
        fprintf(stderr, "Error: Invalid configuration values\n");
        json_decref(root);
        return 1;
    }

    config->target_temperature = json_real_value(target_temperature);
    config->Kp = json_real_value(Kp);
    config->Ki = json_real_value(Ki);
    config->Kd = json_real_value(Kd);

    json_decref(root);
    return 0;
}

