void control_fan(float temperature) {
    if (temperature > 30.0) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;
    sensor_data_t data;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature in timer callback\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
