}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
