    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for fan as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

