        return 1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp)
{
    int32_t X1 = (((int32_t)raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, double temperature)
{
    int32_t B6 = ((int32_t)temperature * 10) - 4000;
    int32_t X1 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X2 = ((int32_t)ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    uint32_t X1_u = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)b1 * (B6 * B6) >> 12) >> 16;
    uint32_t X3_u = ((X1_u + X2_u) + 2) >> 2;
    uint32_t B4 = ((uint32_t)ac4 * (X3_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Log data to file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %.2f Pa\n", timestamp, pressure);
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > 200000) // 200ms debounce (in microseconds)
    {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
    last_tick = current_tick;
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

