#define TARGET_TEMPERATURE 25.0 // Target temperature in Celsius
#define MAX_DUTY_CYCLE 80.0   // Maximum allowed duty cycle (percentage)
#define LOG_FILE "heater_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_temperature();
void set_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;

    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        log_data(-999.0, -1.0); // Log error
        set_duty_cycle(0.0);    // Set duty cycle to 0
        return -999.0;          // Indicate error
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-998.0, -1.0); // Log error
        set_duty_cycle(0.0);    // Set duty cycle to 0
        return -998.0;          // Indicate error
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to ground\n");
        log_data(-997.0, -1.0); // Log error
        set_duty_cycle(0.0);    // Set duty cycle to 0
        return -997.0;          // Indicate error
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-996.0, -1.0); // Log error
        set_duty_cycle(0.0);    // Set duty cycle to 0
        return -996.0;          // Indicate error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to set the PWM duty cycle
void set_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 10.23); // Calculate PWM value (0-1023 for 10-bit PWM)
    pwmWrite(HEATER_PIN, pwm_value);
}

// Function to log data to a file
void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    set_duty_cycle(0.0); // Turn off heater
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure heater pin as PWM output
    pinMode(HEATER_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Set PWM mode to mark:space
    pwmSetRange(1024);       // Set PWM range to 1024
    pwmSetClock(192);        // Set PWM clock to achieve ~25kHz (adjust as needed)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, duty_cycle;
    float prev_error = 0.0; // For anti-windup

    // Main loop
    while (program_running) {
        temperature = read_temperature();

        if (temperature != -999.0) {
            // PI controller (very basic)
            float error = TARGET_TEMPERATURE - temperature;
            float proportional_gain = 1.0; // Adjust as needed
            duty_cycle = proportional_gain * error;

            // Anti-windup
            if (duty_cycle < 0.0) {
                duty_cycle = 0.0;
            } else if (duty_cycle > MAX_DUTY_CYCLE) {
                duty_cycle = MAX_DUTY_CYCLE;
                duty_cycle -= error / (MAX_DUTY_CYCLE / proportional_gain); // Adjust as needed
                if (duty_cycle < 0.0) duty_cycle = 0.0;
            }

            set_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            // Error condition, set duty cycle to 0
            set_duty_cycle(0.0);
            log_data(-999.0, -1.0); // Log error
        }

        delay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_duty_cycle(0.0);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

