#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds (in millidegrees Celsius)
#define TEMP_BLUE  40000
#define TEMP_GREEN 59999
#define TEMP_RED   60000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty(int gpio, int duty)
{
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d: %d\n", gpio, gpioPWM(gpio, duty));
        return -1;
    }
    return 0;
}

int main()
{
    FILE *fp;
    int temperature_milli_c;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open temperature file
    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature from file
        if (fscanf(fp, "%d", &temperature_milli_c) != 1) {
            if (ferror(fp)) {
                fprintf(stderr, "Error reading temperature from file\n");
            }
            // Skip to the next iteration if there's an error
            usleep(500000); // 0.5 seconds
            continue;
        }

        // Determine LED color based on temperature
        if (temperature_milli_c < TEMP_BLUE) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temperature_milli_c < TEMP_GREEN) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set PWM duty cycles for RGB LED
        if (set_pwm_duty(RED_PIN, red) != 0) {
            fprintf(stderr, "Error setting RED PWM\n");
        }
        if (set_pwm_duty(GREEN_PIN, green) != 0) {
            fprintf(stderr, "Error setting GREEN PWM\n");
        }
        if (set_pwm_duty(BLUE_PIN, blue) != 0) {
            fprintf(stderr, "Error setting BLUE PWM\n");
        }

        // Print temperature and PWM values to stdout
        printf("Temperature: %d m°C, R: %d, G: %d, B: %d\n", temperature_milli_c, red, green, blue);

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Cleanup and exit
    printf("Terminating program...\n");

    // Turn off all channels
    set_pwm_duty(RED_PIN, 255);
    set_pwm_duty(GREEN_PIN, 255);
    set_pwm_duty(BLUE_PIN, 255);

    // Call pigpio cleanup function
    gpioTerminate();

    // Close the temperature file
    fclose(fp);

    return 0;
}

