#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    int data_bits[40] = {0};
    unsigned int pulse_lengths[80] = {0};

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Error: DHT22 start signal timeout\n");
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Error: DHT22 start signal timeout\n");
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Error: DHT22 start signal timeout\n");
            return data; // Return invalid data
        }
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "Error: DHT22 data timeout (low)\n");
                return data; // Return invalid data
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "Error: DHT22 data timeout (high)\n");
                return data; // Return invalid data
            }
        }
        long end = gpioTick();

        pulse_lengths[i] = end - start;

        // Determine if it's a 0 or a 1 based on pulse length
        data_bits[i] = (pulse_lengths[i] > 40) ? 1 : 0; // Adjusted threshold
    }

    // Convert bits to bytes
    unsigned char byte_data[5] = {0};
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            byte_data[i] <<= 1;
            byte_data[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (byte_data[4] != ((byte_data[0] + byte_data[1] + byte_data[2] + byte_data[3]) & 0xFF)) {
        fprintf(stderr, "Error: DHT22 checksum mismatch\n");
        return data; // Return invalid data
    }

    // Calculate temperature and humidity
    data.humidity = ((byte_data[0] * 256) + byte_data[1]) / 10.0;
    data.temperature = (((byte_data[2] & 0x7F) * 256) + byte_data[3]) / 10.0;
    if (byte_data[2] & 0x80) {
        data.temperature *= -1;
    }
    data.valid = 1;

    return data;
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to the server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : 1; // Return 0 on success, 1 on failure
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            char *json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                int retries = 0;
                int post_result = 1; // Assume failure initially
                while (retries < MAX_RETRIES && post_result != 0) {
                    post_result = post_data(json_data);
                    if (post_result != 0) {
                        fprintf(stderr, "Error: Failed to post data (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
                        retries++;
                        sleep(1 << retries); // Exponential backoff (1s, 2s, 4s)
                    }
                }
                free(json_data);
                if (post_result == 0) {
                    printf("Data posted successfully\n");
                } else {
                    fprintf(stderr, "Error: Failed to post data after %d retries\n", MAX_RETRIES);
                }
            } else {
                fprintf(stderr, "Error: Failed to format JSON data\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid DHT22 data\n");
        }

        sleep(5); // Read sensor data every 5 seconds
    }

    gpioTerminate();
    return 0;
}

