// Initialize I2C
int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Open I2C bus 1, BMP180 address
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data()
{
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22)
    {
        fprintf(stderr, "Failed to read calibration data block\n");
        return 1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature value from BMP180
int read_raw_temperature(int32_t *raw_temp)
{
    char buf[2];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1)
    {
        fprintf(stderr, "Failed to write temperature measurement command\n");
        return 1;
    }

    gpioDelay(5000); // Wait 5ms

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Failed to set register for temperature read\n");
        return 1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2)
    {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return 1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw pressure value from BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[3];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1)
    {
        fprintf(stderr, "Failed to write pressure measurement command\n");
        return 1;
    }

    gpioDelay(26000); // Wait 26ms for OSS = 3

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Failed to set register for pressure read\n");
        return 1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3)
    {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut)
{
    int32_t x1, x2;

    x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    return ((b5 + 8) >> 4) / 10.0;
}

// Calculate pressure in hPa
double calculate_pressure(int32_t up, int32_t ut)
{
    int32_t x1, x2, x3, b3, b6, p;
    uint32_t b4, b7;

    int32_t b5 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x1_local = ((int32_t)mc << 11) / (b5 + md);
    b6 = b5 + x1_local - 4000;

    x1 = ((int32_t)b2 * (b6 * b6) >> 12) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;

    b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p / 100.0; // Convert to hPa
}

// Log pressure to file
void log_pressure(double pressure)
{
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("pressure_log.txt", "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Failed to open pressure_log.txt\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick)
{
    static uint32_t last_tick = 0;

    if (gpio == INTERRUPT_PIN && level == FALLING_EDGE)
    {
        uint32_t diff = tick - last_tick;
        if (diff > DEBOUNCE_TIME)
        {
            logging_enabled = !logging_enabled;
            if (logging_enabled)
            {
                printf("Pressure logging enabled.\n");
            }
            else
            {
                printf("Pressure logging disabled.\n");
            }
            last_tick = tick;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Exiting.\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

