#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

#define MAX_TEMP 65000 // 65 degrees Celsius
#define MAX_SPEED 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", sig);
}

int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    char buffer[10];

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        return -1;
    }

    return temp / 1000; // Convert to degrees Celsius
}

int read_fan_speed() {
    FILE *fp;
    int speed = -1;
    char buffer[10];

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open fan file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read fan speed");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &speed) != 1) {
        fprintf(stderr, "Failed to parse fan speed\n");
        return -1;
    }

    return speed;
}

int set_fan_speed(int speed) {
    FILE *fp;
    int max_speed;

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open fan file for reading max_state");
        return -1;
    }

    char buffer[10];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read max_state");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &max_speed) != 1) {
        fprintf(stderr, "Failed to parse max_state\n");
        return -1;
    }

    if (speed < 0 || speed > max_speed) {
        fprintf(stderr, "Invalid fan speed: %d.  max_state is %d\n", speed, max_speed);
        return -1;
    }

    fp = fopen(FAN_FILE, "w");
    if (fp == NULL) {
        perror("Failed to open fan file for writing");
        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        perror("Failed to write fan speed");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int calculate_fan_speed(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    int current_speed = -1;
    int new_speed = -1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        int temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        int fan_speed = read_fan_speed();
        if (fan_speed == -1) {
            fprintf(stderr, "Failed to read fan speed. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        current_speed = fan_speed;

        new_speed = calculate_fan_speed(temperature);

        if (new_speed != current_speed) {
            if (set_fan_speed(new_speed) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d (Temperature: %d)", new_speed, temperature);
                log_event(log_message);
            } else {
                fprintf(stderr, "Failed to set fan speed. Retrying in 5 seconds.\n");
            }
        }

        sleep(5);
    }

    if (set_fan_speed(0) == 0) {
        log_event("Fan turned off on shutdown.");
    } else {
        fprintf(stderr, "Failed to turn off fan on shutdown.\n");
    }

    return 0;
}

