            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        int fan_speed = read_fan_speed();
        if (fan_speed == -1) {
            fprintf(stderr, "Failed to read fan speed. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        current_speed = fan_speed;

        new_speed = calculate_fan_speed(temperature);

        if (new_speed != current_speed) {
            if (set_fan_speed(new_speed) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d (Temperature: %d)", new_speed, temperature);
                log_event(log_message);
            } else {
                fprintf(stderr, "Failed to set fan speed. Retrying in 5 seconds.\n");
            }
        }

        sleep(5);
    }

    if (set_fan_speed(0) == 0) {
        log_event("Fan turned off on shutdown.");
    } else {
        fprintf(stderr, "Failed to turn off fan on shutdown.\n");
    }

    return 0;
}

