#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define PID gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define failsafe temperature limits
#define FAILSAFE_MIN_TEMP 0.0
#define FAILSAFE_MAX_TEMP 100.0

// Define MAX31855 fault bits
#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_TO_GND 0x02
#define MAX31855_FAULT_SHORT_TO_VCC 0x04

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
void set_pwm(int duty_cycle);
double calculate_pid(double current_temperature);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(0, 500000, 0); // SPI0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    // Check for fault bits
    if (buffer[3] & MAX31855_FAULT_OPEN_CIRCUIT) {
        fprintf(stderr, "MAX31855: Open circuit fault\n");
        return -1000.0;
    }
    if (buffer[3] & MAX31855_FAULT_SHORT_TO_GND) {
        fprintf(stderr, "MAX31855: Short to GND fault\n");
        return -1000.0;
    }
    if (buffer[3] & MAX31855_FAULT_SHORT_TO_VCC) {
        fprintf(stderr, "MAX31855: Short to VCC fault\n");
        return -1000.0;
    }

    // Extract temperature data (ignoring the fault bit)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle) {
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;

    integral += error;
    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Limit the output to the PWM range
    if (output < 0) {
        output = 0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
    }

    return output;
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.4f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Function to cleanup resources
void cleanup() {
    // Disable heater
    set_pwm(0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > FAILSAFE_MIN_TEMP && temperature < FAILSAFE_MAX_TEMP) {
            double pid_output = calculate_pid(temperature);
            int duty_cycle = (int)pid_output;
            set_pwm(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        } else {
            fprintf(stderr, "Failsafe triggered: Temperature out of range\n");
            set_pwm(0); // Disable heater
            log_data(temperature, 0, 0.0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    cleanup();

    return 0;
}

