#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_40C 40.0
#define TEMP_70C 70.0
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
}

int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature <= TEMP_40C) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_70C) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - TEMP_40C) / (TEMP_70C - TEMP_40C)) * 100.0);
    }

    return duty_cycle;
}

int set_pwm_duty_cycle(int gpio, int frequency, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 100); // Set range to 0-100 for percentage

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temperature);
            if (set_pwm_duty_cycle(FAN_GPIO, PWM_FREQUENCY, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle. Retrying in 5 seconds.\n");
            }

            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
            }

            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        }

        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    gpioTerminate();

    printf("Fan control stopped.\n");
    return 0;
}

