#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flow_sensor(int i2c_handle, int sensor_address);
int validate_checksum(unsigned char data[], int len);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read flow sensor data
int read_flow_sensor(int i2c_handle, int sensor_address) {
    unsigned char data[3];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            // Checksum validation
            if (validate_checksum(data, 2)) {
                // Convert raw data to flow rate (example conversion, adjust as needed)
                int raw_flow = (data[0] << 8) | data[1];
                float flow_rate = (float)raw_flow / 100.0; // Example scaling factor
                return (int)(flow_rate * 100); // Return flow rate * 100 for precision
            } else {
                fprintf(stderr, "Error: Checksum validation failed for sensor 0x%02X\n", sensor_address);
                retries--;
                gpioDelay(100); // Wait before retrying
            }
        } else {
            fprintf(stderr, "Error: I2C read failed for sensor 0x%02X (result = %d), retrying...\n", sensor_address, result);
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: I2C read failed for sensor 0x%02X after multiple retries\n", sensor_address);
    return -1; // Indicate error
}

// Function to validate checksum
int validate_checksum(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    unsigned char i, bit;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }

    if (crc != data[len])
        return 0; // Checksum failed
    else
        return 1; // Checksum passed
}

// Function to log flow data to file
void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1 (address 0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2 (address 0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int raw_flow1 = read_flow_sensor(i2c_handle1, SENSOR1_ADDR);
        int raw_flow2 = read_flow_sensor(i2c_handle2, SENSOR2_ADDR);

        if (raw_flow1 != -1 && raw_flow2 != -1) {
            float flow1 = (float)raw_flow1 / 100.0;
            float flow2 = (float)raw_flow2 / 100.0;
            log_flow_data(flow1, flow2);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

