#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Global variables
volatile int encoder_position = 0;
volatile int last_encoder_position = 0;
FILE *log_file = NULL;

// Function prototypes
void encoder_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int log_file_open;
} program_state_t;

program_state_t state = {0, 0};

// Encoder interrupt service routine
void encoder_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    static int last_level_a = 0;
    static int last_level_b = 0;
    int current_level_a = gpioRead(ENCODER_A);
    int current_level_b = gpioRead(ENCODER_B);

    if (current_level_a != last_level_a) {
        if (current_level_a == 0 && last_level_a == 1) {
            if (current_level_b == 0) {
                encoder_position = (encoder_position + 1) % 360;
            } else {
                encoder_position = (encoder_position + 2) % 360;
            }
        } else if (current_level_a == 1 && last_level_a == 0) {
            if (current_level_b == 1) {
                encoder_position = (encoder_position + 2) % 360;
            } else {
                encoder_position = (encoder_position + 3) % 360;
            }
        }
    }

    if (current_level_b != last_level_b) {
        if (current_level_b == 0 && last_level_b == 1) {
            if (current_level_a == 0) {
                encoder_position = (encoder_position + 2) % 360;
            } else {
                encoder_position = (encoder_position + 3) % 360;
            }
        } else if (current_level_b == 1 && last_level_b == 0) {
            if (current_level_a == 1) {
                encoder_position = (encoder_position + 1) % 360;
            } else {
                encoder_position = (encoder_position + 2) % 360;
            }
        }
    }

    last_level_a = current_level_a;
    last_level_b = current_level_b;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    if (state.log_file_open) {
        fclose(log_file);
    }

    if (state.gpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    state.gpio_initialized = 1;

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    // Open log file
    log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }
    state.log_file_open = 1;

    // Register interrupt handlers for both channels
    if (gpioSetISRFuncEx(ENCODER_A, EITHER_EDGE, 0, encoder_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for ENCODER_A!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ENCODER_B, EITHER_EDGE, 0, encoder_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for ENCODER_B!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Check if the encoder position has changed
        if (encoder_position != last_encoder_position) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the timestamp and encoder position to the file
            fprintf(log_file, "%s, %d\n", timestamp, encoder_position);
            fflush(log_file); // Ensure data is written to disk immediately

            last_encoder_position = encoder_position;
        }

        gpioDelay(10000); // Delay for 10 milliseconds
    }

    return 0;
}

