#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define PULSES_PER_REVOLUTION 1
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;

// Function to log RPM with timestamp
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Interrupt service routine (ISR)
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Thread function to calculate RPM
void *rpm_calculator(void *arg) {
    (void)arg; // unused
    int local_pulse_count;
    double rpm;
    time_t start_time, current_time;
    double elapsed_time;

    time(&start_time);

    while (1) {
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        if (elapsed_time >= 1.0) {
            pthread_mutex_lock(&pulse_mutex);
            local_pulse_count = pulse_count;
            pthread_mutex_unlock(&pulse_mutex);

            rpm = (double)local_pulse_count / PULSES_PER_REVOLUTION / (elapsed_time / 1.0);
            log_rpm(rpm);

            time(&start_time);
        }
        gpioDelay(10000); // Check every 10ms
    }

    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    exit(0);
}

int main() {
    int result;
    pthread_t rpm_thread;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register interrupt service routine
    result = gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL);
    if (result != 0) {
        fprintf(stderr, "Error setting ISR function: %d\n", result);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Create RPM calculator thread
    if (pthread_create(&rpm_thread, NULL, rpm_calculator, NULL) != 0) {
        fprintf(stderr, "Error creating RPM calculator thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Keep the main thread alive
    while (1) {
        gpioDelay(1000000); // Sleep for 1 second
    }

    return 0;
}

