#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE "audio_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int last_state = 0;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);
    gpioWrite(GAIN_SELECT_PIN, 0); // Select 60dB gain

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_state = gpioRead(AUDIO_INPUT_PIN);

        if (current_state != last_state) {
            if (current_state == 1) {
                // Rising edge detected
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

                fprintf(log_file, "%s 1\n", timestamp);
                fflush(log_file); // Ensure immediate write to file
                printf("Peak detected at %s\n", timestamp);
            }
            last_state = current_state;
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

