#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_flow_rate(uint16_t *raw_flow_rate);
uint8_t calculate_crc(const uint8_t *data, size_t length);
float convert_to_ul_min(uint16_t raw_flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t raw_flow_rate;
    float flow_rate_ul_min;
    uint8_t crc_status;
} sensor_data_t;


int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&sensor_data.raw_flow_rate) == 0) {
            // Calculate CRC
            uint8_t crc = calculate_crc((uint8_t *)&sensor_data.raw_flow_rate, 2);

            // Validate CRC
            if (crc == ((uint8_t *)&sensor_data.raw_flow_rate)[2]) {
                // Convert to ul/min
                sensor_data.flow_rate_ul_min = convert_to_ul_min(sensor_data.raw_flow_rate);
                sensor_data.crc_status = 0; // Success
            } else {
                sensor_data.flow_rate_ul_min = -1.0; // Indicate CRC failure
                sensor_data.crc_status = 1; // CRC failure
            }
        } else {
            sensor_data.flow_rate_ul_min = -1.0; // Indicate read failure
            sensor_data.crc_status = 2; // I2C read failure
        }

        // Log flow rate
        if (sensor_data.crc_status == 0) {
            if (log_flow_rate(sensor_data.flow_rate_ul_min) != 0) {
                fprintf(stderr, "Failed to log flow rate.\n");
            }
        } else {
            fprintf(stderr, "CRC failure or I2C read error. Skipping logging.\n");
        }

        // Delay
        gpioDelay(1000); // 1000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
