#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define TVOC_REG 0x01 // Example register address for TVOC
#define ECO2_REG 0x02  // Example register address for eCO2
#define LOG_FILE "air_quality_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int tvoc;
    int eco2;
} SensorData;

// Function prototypes
int initialize_i2c();
SensorData read_sensor_data();
float calculate_iaq(int tvoc, int eco2);
int log_data(float iaq, int tvoc, int eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C device initialized successfully.\n");
    return 0;
}

// Read sensor data from I2C
SensorData read_sensor_data() {
    SensorData data;
    char buf[2];

    // Read TVOC
    if (i2cReadI2CBlockData(i2c_handle, TVOC_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading TVOC data\n");
        data.tvoc = -1; // Indicate error
    } else {
        data.tvoc = (buf[0] << 8) | buf[1];
    }

    // Read eCO2
    if (i2cReadI2CBlockData(i2c_handle, ECO2_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading eCO2 data\n");
        data.eco2 = -1; // Indicate error
    } else {
        data.eco2 = (buf[0] << 8) | buf[1];
    }

    return data;
}

// Calculate IAQ index (example formula)
float calculate_iaq(int tvoc, int eco2) {
    // This is a placeholder.  A real IAQ index calculation would use
    // formulas specific to the sensor and environmental conditions.
    // This example just averages the two readings.
    return (float)(tvoc + eco2) / 2.0;
}

// Log data to CSV file
int log_data(float iaq, int tvoc, int eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        printf("I2C device closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_sensor_data();

        if (sensor_data.tvoc != -1 && sensor_data.eco2 != -1) {
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);
            printf("TVOC: %d ppb, eCO2: %d ppm, IAQ: %.2f\n", sensor_data.tvoc, sensor_data.eco2, iaq);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

