#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define INTRUSION_THRESHOLD 5
#define DEBOUNCE_DELAY 100 // milliseconds

volatile sig_atomic_t program_running = 1;
static volatile int touch_start_time = 0;
static volatile int touch_detected = 0;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpioRead(GPIO_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            return 1;
        }

        if (sensor_value == 1) {
            if (!touch_detected) {
                touch_detected = 1;
                touch_start_time = time(NULL);
                printf("Touch detected at %ld\n", touch_start_time);
            }
        } else {
            if (touch_detected) {
                touch_detected = 0;
                time_t current_time = time(NULL);
                if (difftime(current_time, touch_start_time) > INTRUSION_THRESHOLD) {
                    printf("INTRUSION DETECTED!\n");
                }
                touch_start_time = 0;
            }
        }

        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

