#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Log system start
    log_event("System Start");

    // Main loop
    int flame_detected = 0;
    int sensor_present = 1;
    time_t last_read_time = time(NULL);
    const int timeout_duration = 10; // Timeout after 10 seconds

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == -1) {
            // Sensor absent or error
            if (sensor_present) {
                log_event("Sensor Absent");
                sensor_present = 0;
            }
        } else {
            // Sensor present
            sensor_present = 1;

            if (sensor_value == 0 && !flame_detected) {
                // Flame detected
                log_event("Flame Detected");
                flame_detected = 1;
                control_fan(1);
            } else if (sensor_value == 1 && flame_detected) {
                // Flame gone
                log_event("Flame Gone");
                flame_detected = 0;
                control_fan(0);
            }
        }

        // Timeout check
        if (!sensor_present) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_read_time) > timeout_duration) {
                log_event("Timeout");
                sensor_present = 0; // Prevent repeated timeout messages
            }
        } else {
            last_read_time = time(NULL);
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay (microseconds)
    }

    // Log system shutdown
    log_event("System Shutdown");

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 1000); // Set PWM range to 0-1000

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Control the fan
void control_fan(int flame_detected) {
    if (flame_detected) {
        gpioPWM(FAN_PIN, 500); // 50% duty cycle
    } else {
        gpioPWM(FAN_PIN, 0);   // 0% duty cycle (fan off)
    }
}

// Log an event to the log file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Stop the fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set pin to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set pin to input
    gpioTerminate();       // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

