        gpioTerminate();
        return 1;
    }

    // Configure SPI
    if (configureSPI() != 0) {
        fprintf(stderr, "SPI configuration failed\n");
        fclose(logFile);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    if (configureGPIO() != 0) {
        fprintf(stderr, "GPIO configuration failed\n");
        fclose(logFile);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    return 0;
}

int configureSPI() {
    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spiHandle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spiHandle);
        return 1;
    }
    return 0;
}

int configureGPIO() {
    gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler
    if (gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, dataReadyISR, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        return 1;
    }
    return 0;
}

int captureFrame(uint8_t *frameData) {
    // Trigger frame capture
    gpioWrite(FRAME_TRIGGER_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(FRAME_TRIGGER_PIN, 0);

    // Wait for data ready signal (with timeout)
    int timeout = 1000; // 1 second timeout
    while (gpioRead(DATA_READY_PIN) == 0 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready signal\n");
        return 1;
    }

    // Read data from SPI
    char rxBuffer[FRAME_SIZE];
    int bytesRead = spiRead(spiHandle, rxBuffer, FRAME_SIZE);
    if (bytesRead != FRAME_SIZE) {
        fprintf(stderr, "SPI read failed: %d\n", bytesRead);
        return 1;
    }

    // Copy data to frameData
    memcpy(frameData, rxBuffer, FRAME_SIZE);

    return 0;
}

int logFrame(uint8_t *frameData) {
    FrameHeader header;
    header.magicNumber = MAGIC_NUMBER;
    clock_gettime(CLOCK_REALTIME, &header.timestamp);
    memcpy(header.configData, "AWR1642_Config", 15); // Example config data

    // Write header to file
    size_t headerWritten = fwrite(&header, sizeof(FrameHeader), 1, logFile);
    if (headerWritten != 1) {
        fprintf(stderr, "Failed to write header to file\n");
        return 1;
    }

    // Get timestamp and frame number
    struct timespec timestamp;
    clock_gettime(CLOCK_REALTIME, &timestamp);
    uint32_t frameNumber = 1; // Assuming sequential frame numbering

    // Write frame data to file
    size_t frameDataWritten = fwrite(frameData, 1, FRAME_SIZE, logFile);
    if (frameDataWritten != FRAME_SIZE) {
        fprintf(stderr, "Failed to write frame data to file\n");
        return 1;
    }

    // Write frame data structure to file
    FrameData frameDataStruct;
    frameDataStruct.timestamp = timestamp;
    frameDataStruct.frameNumber = frameNumber;
    size_t frameDataStructWritten = fwrite(&frameDataStruct, sizeof(FrameData), 1, logFile);
    if (frameDataStructWritten != 1) {
        fprintf(stderr, "Failed to write frame data structure to file\n");
        return 1;
    }

    return 0;
}

void dataReadyISR(int gpio, int level, uint32_t tick) {
    // This function is called when the data ready pin goes high
    // You can add code here to process the data or trigger further actions
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
}

void signalHandler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spiHandle >= 0) {
        spiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

