    while (keepRunning) {
        currentState = readFlameSensor(GPIO_PIN);

        if (currentState < 0) {
            fprintf(stderr, "Error reading flame sensor\n");
            break;
        }

        if (currentState != previousState) {
            if (getTimestamp(timestamp, sizeof(timestamp)) == 0) {
                if (logFlameEvent(timestamp, currentState, LOG_FILE) != 0) {
                    fprintf(stderr, "Error logging flame event\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
            previousState = currentState;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

