#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the OPT3001 sensor
int init_opt3001(int i2c_handle) {
    // Configure for continuous conversion mode with automatic full-scale range
    // Configuration value: 0xCC (Continuous mode, Auto range)
    char config_data[2] = {CONFIG_REG, 0xCC};
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the lux value from the OPT3001 sensor
float read_lux(int i2c_handle) {
    char result_data[2];
    int result = i2cReadDevice(i2c_handle, result_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading result register: %d\n", result);
        return -1.0;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_result = (result_data[0] << 8) | result_data[1];

    // Extract the exponent and result from the raw result
    int exponent = (raw_result >> 12) & 0x0F;
    int result_val = raw_result & 0x0FFF;

    // Calculate the lux value
    float lux = result_val * (0.01 * (1 << exponent));

    return lux;
}

// Function to get the current timestamp in ISO 8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to log the lux value to a file
int log_lux_value(const char *timestamp, float lux, FILE *log_file) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the OPT3001 sensor
    if (init_opt3001(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing OPT3001 sensor.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the lux value
        float lux = read_lux(i2c_handle);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value.\n");
        } else {
            // Get the current timestamp
            char timestamp[21];
            get_timestamp(timestamp);

            // Log the lux value to the file
            if (log_lux_value(timestamp, lux, log_file) != 0) {
                fprintf(stderr, "Error logging lux value.\n");
            }

            printf("%s, Lux: %.2f\n", timestamp, lux);
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper cleanup in case the loop is ever modified.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

