        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
