#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int left_state, center_state, right_state;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Main loop to read sensor data
    while (program_running) {
        // Read the states of the GPIO pins
        left_state = gpioRead(LEFT_SENSOR_PIN);
        center_state = gpioRead(CENTER_SENSOR_PIN);
        right_state = gpioRead(RIGHT_SENSOR_PIN);

        // Check for errors during GPIO read operations
        if (left_state < 0 || center_state < 0 || right_state < 0) {
            fprintf(stderr, "Error reading GPIO pin\n");
            gpioTerminate();
            return 1;
        }

        // Print the sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Delay for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

