#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor channels
#define SENSOR_PINS {2, 3, 4, 17, 27, 22, 10, 9}

// Define the number of sensor channels
#define NUM_CHANNELS 8

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read the sensor channels
int read_sensor_channels(int *channels)
{
    int i;
    for (i = 0; i < NUM_CHANNELS; i++) {
        channels[i] = gpioRead(i + 2); // Read the GPIO pin
        if (channels[i] < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", i + 2, channels[i]);
            return -1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

// Function to format the data into a CSV string
void format_data(int *channels, char *buffer, size_t buffer_size)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ",%d", channels[0]);
    for (int i = 1; i < NUM_CHANNELS; i++) {
        snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ",%d", channels[i]);
    }
}

// Function to print the data to the console
void print_data(const char *data)
{
    printf("%s\n", data);
}

int main()
{
    int sensor_pins[] = SENSOR_PINS;
    int channels[NUM_CHANNELS];
    char data_buffer[100];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Configure the GPIO pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(i + 2, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", i + 2);
            gpioTerminate();
            return 1;
        }
        gpioSetPullUpDown(i + 2, PI_PUD_OFF); // Disable bias
    }

    // Main loop
    while (!terminate) {
        // Read the sensor channels
        if (read_sensor_channels(channels) != 0) {
            fprintf(stderr, "Error reading sensor channels\n");
        } else {
            // Format the data into a CSV string
            format_data(channels, data_buffer, sizeof(data_buffer));

            // Print the data to the console
            print_data(data_buffer);
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

