            fprintf(stderr, "Failed to set GPIO %d as input\n", i + 2);
            gpioTerminate();
            return 1;
        }
        gpioSetPullUpDown(i + 2, PI_PUD_OFF); // Disable bias
    }

    // Main loop
    while (!terminate) {
        // Read the sensor channels
        if (read_sensor_channels(channels) != 0) {
            fprintf(stderr, "Error reading sensor channels\n");
        } else {
            // Format the data into a CSV string
            format_data(channels, data_buffer, sizeof(data_buffer));

            // Print the data to the console
            print_data(data_buffer);
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

