// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define UV_INDEX_REG 0x2C
#define ALS_VISIBLE_REG 0x22
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *uv_index, uint16_t *als_visible);
void process_sensor_data(uint16_t uv_index_raw, uint16_t als_visible_raw, float *uv_index, float *als_visible);
int log_data(float uv_index, float als_visible);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si1145
int read_sensor_data(uint16_t *uv_index, uint16_t *als_visible) {
    char buf[1];
    int result;

    // Read UV index
    buf[0] = UV_INDEX_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to UV index register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char*)uv_index, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading UV index: %d\n", result);
        return -1;
    }

    // Read Ambient Light Sensor (ALS) Visible
    buf[0] = ALS_VISIBLE_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS visible register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char*)als_visible, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading ALS visible: %d\n", result);
        return -1;
    }

    return 0;
}

// Process raw sensor data
void process_sensor_data(uint16_t uv_index_raw, uint16_t als_visible_raw, float *uv_index, float *als_visible) {
    // UV Index conversion (example, adjust based on datasheet)
    *uv_index = (float)uv_index_raw / 100.0; // Example scaling

    // ALS Visible conversion (example, adjust based on datasheet)
    *als_visible = (float)als_visible_raw; // Example scaling
}

// Log data to CSV file
int log_data(float uv_index, float als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data logging...\n");

    // Main loop
    while (!terminate) {
        uint16_t uv_index_raw, als_visible_raw;
        float uv_index, als_visible;

        if (read_sensor_data(&uv_index_raw, &als_visible_raw) == 0) {
            process_sensor_data(uv_index_raw, als_visible_raw, &uv_index, &als_visible);
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, ALS Visible: %.2f\n", uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

