#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define MEASUREMENT_INTERVAL 1 // seconds
#define START_COMMAND_SIZE 2
#define START_COMMAND_VALUE {0x36, 0x08}
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int start_sensor(int i2c_handle);
int read_flow_rate(int i2c_handle);
int validate_checksum(uint8_t data[], int len);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(int alarm_state);
void log_data(float flow1, float flow2, float average_flow, int alarm_state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int valid;
} sensor_data_t;


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connections
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Start the sensors
    if (start_sensor(i2c_handle1) != 0 || start_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Failed to start sensors\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1 = 0.0, flow2 = 0.0;
        int alarm_state = 0;

        // Read flow rates from sensors
        sensor_data_t sensor1_data, sensor2_data;
        sensor1_data.flow_rate = read_flow_rate(i2c_handle1);
        sensor1_data.valid = (sensor1_data.flow_rate >= 0.0); // Basic validation

        sensor2_data.flow_rate = read_flow_rate(i2c_handle2);
        sensor2_data.valid = (sensor2_data.flow_rate >= 0.0); // Basic validation

        if (sensor1_data.valid) {
            flow1 = sensor1_data.flow_rate;
        } else {
            fprintf(stderr, "Invalid reading from sensor 1\n");
        }

        if (sensor2_data.valid) {
            flow2 = sensor2_data.flow_rate;
        } else {
            fprintf(stderr, "Invalid reading from sensor 2\n");
        }

        // Calculate average flow rate
        float average_flow = calculate_average_flow(flow1, flow2);

        // Set alarm state
        if (average_flow < FLOW_THRESHOLD) {
            alarm_state = 1;
        }

        // Set alarm
        set_alarm(alarm_state);

        // Log data
        log_data(flow1, flow2, average_flow, alarm_state);

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Function to start the sensor
int start_sensor(int i2c_handle) {
    char start_command[START_COMMAND_SIZE] = START_COMMAND_VALUE;
    int result = i2cWriteDevice(i2c_handle, start_command, START_COMMAND_SIZE);
    if (result != START_COMMAND_SIZE) {
        fprintf(stderr, "Failed to start sensor: %d\n", result);
        return 1;
    }
    gpioDelay(100); // Wait 100ms after start command
    return 0;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow rate: %d\n", result);
        return -1; // Indicate error
    }

    uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    if (!validate_checksum((uint8_t *)buffer, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1; // Indicate error
    }

    return (int16_t)raw_flow; // Return raw flow rate
}

// Function to validate CRC checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Function to set the alarm state
void set_alarm(int alarm_state) {
    gpioWrite(ALARM_GPIO, alarm_state);
}

// Function to log data to file
void log_data(float flow1, float flow2, float average_flow, int alarm_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min, Alarm: %d\n",
            timestamp, flow1, flow2, average_flow, alarm_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

