        if (sensor2_data.valid) {
            flow2 = sensor2_data.flow_rate;
        } else {
            fprintf(stderr, "Invalid reading from sensor 2\n");
        }

        // Calculate average flow rate
        float average_flow = calculate_average_flow(flow1, flow2);

        // Set alarm state
        if (average_flow < FLOW_THRESHOLD) {
            alarm_state = 1;
        }

        // Set alarm
        set_alarm(alarm_state);

        // Log data
        log_data(flow1, flow2, average_flow, alarm_state);

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Function to start the sensor
int start_sensor(int i2c_handle) {
    char start_command[START_COMMAND_SIZE] = START_COMMAND_VALUE;
    int result = i2cWriteDevice(i2c_handle, start_command, START_COMMAND_SIZE);
    if (result != START_COMMAND_SIZE) {
        fprintf(stderr, "Failed to start sensor: %d\n", result);
        return 1;
    }
    gpioDelay(100); // Wait 100ms after start command
    return 0;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow rate: %d\n", result);
        return -1; // Indicate error
    }

    uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    if (!validate_checksum((uint8_t *)buffer, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1; // Indicate error
    }

    return (int16_t)raw_flow; // Return raw flow rate
}

// Function to validate CRC checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Function to set the alarm state
void set_alarm(int alarm_state) {
    gpioWrite(ALARM_GPIO, alarm_state);
}

// Function to log data to file
void log_data(float flow1, float flow2, float average_flow, int alarm_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min, Alarm: %d\n",
            timestamp, flow1, flow2, average_flow, alarm_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

