#include <pigpio.h>

#define GPIO_PIN 7 // BCM GPIO 7 (GPIO4)
#define BUFFER_SIZE 100

// Structure to hold timestamp and detection status
typedef struct {
    time_t timestamp;
    int detected;
} DetectionEntry;

// Circular buffer
DetectionEntry detection_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to configure the GPIO pin as an input with pull-up resistor
int setup_gpio() {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add a detection event to the circular buffer
void add_detection(int detected) {
    detection_buffer[buffer_index].timestamp = time(NULL);
    detection_buffer[buffer_index].detected = detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\nDetection Log:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = detection_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("Timestamp: %s, Obstacle Detected: %s\n", timestamp_str, detection_buffer[i].detected ? "Yes" : "No");
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio()) {
        return 1;
    }

    // Setup GPIO pin
    if (setup_gpio()) {
        gpioTerminate();
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        add_detection(sensor_value == 0); // Obstacle detected if sensor output is LOW

        if (sensor_value == 0) {
            printf("Obstacle Detected!\n");
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Cleanup and exit
    dump_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

