#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define D7S_ADDR 0x18
#define SAMPLE_RATE_MS 500
#define SAMPLE_PERIOD_US (SAMPLE_RATE_MS * 1000)
#define MAX_RETRIES 3

// D7S Register Addresses (Example - Adjust based on datasheet)
#define D7S_REG_X_LSB 0x02
#define D7S_REG_X_MSB 0x03
#define D7S_REG_Y_LSB 0x04
#define D7S_REG_Y_MSB 0x05
#define D7S_REG_Z_LSB 0x06
#define D7S_REG_Z_MSB 0x07
#define D7S_REG_MODE 0x00 // Example mode register

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int read_sensor_data(sensor_data_t *data);
int write_data_to_csv(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Set sensor mode
int set_sensor_mode(int mode) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, D7S_REG_MODE, mode);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting sensor mode (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to set sensor mode after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buf, 6);
        if (result == 6) {
            // Combine LSB and MSB for each axis
            data->x = (int16_t)((buf[1] << 8) | buf[0]);
            data->y = (int16_t)((buf[3] << 8) | buf[2]);
            data->z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Write data to CSV file
int write_data_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set sensor mode (e.g., active mode)
    if (set_sensor_mode(0x01) != 0) {
        cleanup();
        return 1;
    }

    // Wait for sensor to become active
    gpioDelay(1000000); // 1 second

    // Open CSV file for writing
    fp = fopen("fan_health.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    rewind(fp);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            write_data_to_csv(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

