#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    int rc;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR1_PIN);
        int sensor2_value = gpioRead(SENSOR2_PIN);

        // Control LED based on sensor values
        if (sensor1_value == 0 || sensor2_value == 0)
        {
            gpioWrite(LED_PIN, 1); // Turn LED on
        }
        else
        {
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio
    return 0;
}

