#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170 register addresses
#define TMAG5170_REG_X_MSB 0x00
#define TMAG5170_REG_X_LSB 0x01
#define TMAG5170_REG_Y_MSB 0x02
#define TMAG5170_REG_Y_LSB 0x03
#define TMAG5170_REG_Z_MSB 0x04
#define TMAG5170_REG_Z_LSB 0x05
#define TMAG5170_REG_CONFIG 0x0B

// Configuration values
#define TMAG5170_CONFIG_CONTINUOUS 0x00 // Continuous conversion mode
#define TMAG5170_CONFIG_RANGE 0x00      // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x08, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Sensor configuration function
int configure_sensor() {
    char buf[2];
    buf[0] = TMAG5170_REG_CONFIG;
    buf[1] = TMAG5170_CONFIG_CONTINUOUS | TMAG5170_CONFIG_RANGE;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Sensor data reading function
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB for each axis
    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw values to Gauss (adjust scale as needed)
    data->x = (float)x_raw * 0.00013; // Example scale factor for 50 mT range
    data->y = (float)y_raw * 0.00013;
    data->z = (float)z_raw * 0.00013;

    return 0;
}

// Data logging function
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen("magnetic_log.csv", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }

        // Check if the file is newly created and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,X,Y,Z\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data->x, data->y, data->z);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

