#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
FILE *log_file = NULL;

// Function to handle rising edge interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    pulse_count++;
}

// Function to calculate RPM
double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0;
}

// Function to log RPM data
void log_rpm_data(double rpm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to file immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }

    printf("%s %.2f\n", timestamp, rpm);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    (void)signal; // unused
    printf("Caught signal, exiting gracefully...\n");

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioTerminate();                         // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
