// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex and condition variable
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t log_cond = PTHREAD_COND_INITIALIZER;

// Global variables
volatile int running = 1;
FILE *log_file = NULL;

// Structure to hold the last known state of the sensors
typedef struct {
    int sensor_a_state;
    int sensor_b_state;
} sensor_state_t;

sensor_state_t last_state = {0, 0};

// Function prototypes
void signal_handler(int signal);
void log_rotation_event(const char *direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;

        // Flush the log file
        if (log_file != NULL) {
            pthread_mutex_lock(&log_mutex);
            fflush(log_file);
            pthread_mutex_unlock(&log_mutex);
        }

        // Close the log file
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }

        // Terminate the pigpio library
        gpioTerminate();

        // Destroy the mutex and condition variable
        pthread_mutex_destroy(&log_mutex);
        pthread_cond_destroy(&log_cond);

        exit(0);
    }
}

// Function to log a rotation event to the file
void log_rotation_event(const char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s.%03ld %s\n", timestamp, (long int)(timeinfo->tm_sec / 1000), direction);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_b_state = gpioRead(SENSOR_B_GPIO);

    if (level == PI_LOW) {
        if (sensor_b_state == last_state.sensor_b_state) {
            if (sensor_b_state == 0 && last_state.sensor_b_state == 1) {
                log_rotation_event("Clockwise");
            } else if (sensor_b_state == 1 && last_state.sensor_b_state == 0) {
                log_rotation_event("Counter-Clockwise");
            }
            last_state.sensor_a_state = level;
            last_state.sensor_b_state = sensor_b_state;
        }
    }
}

