    int sensor_a_state = gpioRead(SENSOR_A_GPIO);

    if (level == PI_LOW) {
        if (sensor_a_state == last_state.sensor_a_state) {
            if (sensor_a_state == 0 && last_state.sensor_a_state == 1) {
                log_rotation_event("Counter-Clockwise");
            } else if (sensor_a_state == 1 && last_state.sensor_a_state == 0) {
                log_rotation_event("Clockwise");
            }
            last_state.sensor_a_state = level;
            last_state.sensor_b_state = sensor_b_state;
        }
    }
}

