    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, FALLING_EDGE, 0, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler for Sensor A!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, FALLING_EDGE, 0, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler for Sensor B!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        pthread_cond_wait(&log_cond, &log_mutex);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
    pthread_cond_destroy(&log_cond);

    return 0;
}

