#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int rc;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting touch sensor and LED control program");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", LED_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (gpioRead(TOUCH_SENSOR_GPIO) == 1) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                syslog(LOG_ERR, "Failed to write to GPIO%d", LED_GPIO);
            }
            syslog(LOG_INFO, "Touch detected, LED on");
        } else {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                syslog(LOG_ERR, "Failed to write to GPIO%d", LED_GPIO);
            }
            syslog(LOG_INFO, "No touch, LED off");
        }
        gpioDelay(50000); // 50ms
    }

    syslog(LOG_INFO, "Turning off LED");
    gpioWrite(LED_GPIO, 0);

    syslog(LOG_INFO, "Terminating pigpio");
    gpioTerminate();

    syslog(LOG_INFO, "Exiting program");
    closelog();

    return 0;
}

