#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    int rc;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    /* Set initial LED state to LOW */
    gpioWrite(LED_PIN, 0);

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        /* Wait for rising edge on TOUCH_PIN */
        rc = gpioWaitForRisingEdge(TOUCH_PIN);
        if (rc != 0) {
            fprintf(stderr, "Error waiting for rising edge on GPIO%d: %d\n", TOUCH_PIN, rc);
            break;
        }

        /* Debounce delay */
        gpioDelay(50000); // 50ms

        /* Toggle LED state */
        int current_led_state = gpioRead(LED_PIN);
        if (current_led_state < 0) {
            fprintf(stderr, "Error reading GPIO%d: %d\n", LED_PIN, current_led_state);
            break;
        }
        gpioWrite(LED_PIN, !current_led_state);

        printf("Touch detected, LED toggled.\n");
    }

    /* Cleanup and exit */
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    printf("Application terminated.\n");
    return 0;
}

