#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4  // GPIO4 (BCM)
#define SENSOR_2_PIN 17 // GPIO17 (BCM)
#define LED_1_PIN 27    // GPIO27 (BCM)
#define LED_2_PIN 22    // GPIO22 (BCM)

// Define buffer size
#define BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
int overflow_count = 0;
log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void add_to_buffer(int sensor_pin, int state);
void print_buffer();
void signal_handler(int signal);

// Function to read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(50000); // 50ms delay
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to add log entry to circular buffer
void add_to_buffer(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

