#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int keepRunning = 1;
FILE *logFile = NULL;

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    keepRunning = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
    if (logFile != NULL) {
        fclose(logFile);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
    exit(0);
}

// Function to read the rain sensor state
int readRainSensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

// Function to log rain events with timestamp
void logRainEvent(int rainDetected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (logFile != NULL) {
        fprintf(logFile, "%s Rain %s\n", timestamp, rainDetected ? "Detected" : "No Rain");
        fflush(logFile); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Cannot log rain event.\n");
    }
}

int main() {
    int rainState = -1; // Initialize to an invalid state
    int currentRainState;

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        currentRainState = readRainSensor();

        if (currentRainState != rainState) {
            logRainEvent(currentRainState == 0); // Active low
            rainState = currentRainState;
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(logFile);
    gpioTerminate();

    return 0;
}

