#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_MS 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    return gpioRead(gpio);
}

void log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(fp, "%s.%09ld,%d,%d\n", timestamp, ts.tv_nsec, sensor1_state, sensor2_state);
    fflush(fp);
}

double calculate_rpm(struct timespec prev_time, struct timespec current_time) {
    double time_diff_sec = (current_time.tv_sec - prev_time.tv_sec) + (current_time.tv_nsec - prev_time.tv_nsec) / 1000000000.0;
    if (time_diff_sec > 0) {
        return 60.0 / time_diff_sec; // Assuming one pulse per revolution
    } else {
        return 0.0;
    }
}

int main() {
    FILE *fp;
    int sensor1_state = -1, sensor2_state = -1;
    struct timespec last_transition_time = {0, 0};
    struct timespec current_time;
    double rpm = 0.0;

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    fp = fopen("shaft_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open shaft_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR1_GPIO);
        int new_sensor2_state = read_sensor(SENSOR2_GPIO);

        clock_gettime(CLOCK_REALTIME, &current_time);

        if (new_sensor1_state != sensor1_state || new_sensor2_state != sensor2_state) {
            if (new_sensor1_state != sensor1_state) {
                clock_gettime(CLOCK_REALTIME, &current_time);
                log_data(fp, new_sensor1_state, sensor2_state);
                sensor1_state = new_sensor1_state;
            }
            if (new_sensor2_state != sensor2_state) {
                clock_gettime(CLOCK_REALTIME, &current_time);
                log_data(fp, sensor1_state, new_sensor2_state);
                sensor2_state = new_sensor2_state;
            }

            if (sensor1_state != -1 && sensor2_state != -1) {
                rpm = calculate_rpm(last_transition_time, current_time);
                printf("RPM: %.2f\n", rpm);
                last_transition_time = current_time;
            }
        }

        gpioDelay(DEBOUNCE_MS * 1000); // Debounce
    }

    fclose(fp);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

