#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define HEART_RATE_REG 0x24 // Example register, adjust as needed
#define SPO2_REG 0x26        // Example register, adjust as needed
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *heart_rate, int *spo2);
int write_data_to_log(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int heart_rate;
    int spo2;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int heart_rate, spo2;
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            if (write_data_to_log(heart_rate, spo2) != 0) {
                fprintf(stderr, "Failed to write data to log\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *heart_rate, int *spo2) {
    char buf[4]; // Assuming 2 bytes for heart rate and 2 for spo2
    int result;

    // Read heart rate
    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read heart rate: %d\n", result);
        return 1;
    }
    *heart_rate = (buf[0] << 8) | buf[1];

    // Read SpO2
    result = i2cReadI2CBlockData(i2c_handle, SPO2_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read SpO2: %d\n", result);
        return 1;
    }
    *spo2 = (buf[0] << 8) | buf[1];

    return 0;
}

// Write data to log file
int write_data_to_log(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

