    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int heart_rate, spo2;
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            if (write_data_to_log(heart_rate, spo2) != 0) {
                fprintf(stderr, "Failed to write data to log\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *heart_rate, int *spo2) {
    char buf[4]; // Assuming 2 bytes for heart rate and 2 for spo2
    int result;

    // Read heart rate
    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read heart rate: %d\n", result);
        return 1;
    }
    *heart_rate = (buf[0] << 8) | buf[1];

    // Read SpO2
    result = i2cReadI2CBlockData(i2c_handle, SPO2_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read SpO2: %d\n", result);
        return 1;
    }
    *spo2 = (buf[0] << 8) | buf[1];

    return 0;
}

// Write data to log file
int write_data_to_log(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

