// Define sensor and LED pins
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_PIN 17

// Define I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D

// Define Euclidean threshold
#define EUCLIDEAN_THRESHOLD 500

// Define register addresses (replace with actual values from datasheet)
#define REG_X_LSB 0x02
#define REG_Y_LSB 0x04
#define REG_Z_LSB 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_euclidean_magnitude(sensor_data_t data);
void log_event(sensor_data_t data);
void control_led(int on);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Example: Write to a register to clear power-down bit (replace with actual register and value)
    char buf[2];
    buf[0] = 0x80; // Register address (example)
    buf[1] = 0x00; // Value to write (example)

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(100000); // 100ms delay
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[1];
    int result;

    // Read X, Y, and Z axis data from registers
    buf[0] = REG_X_LSB;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }
    gpioDelay(1000); // Small delay before reading
    result = i2cReadDevice(i2c_handle, (char*)&data.x, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading X data: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }

    buf[0] = REG_Y_LSB;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }
    gpioDelay(1000); // Small delay before reading
    result = i2cReadDevice(i2c_handle, (char*)&data.y, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading Y data: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }

    buf[0] = REG_Z_LSB;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }
    gpioDelay(1000); // Small delay before reading
    result = i2cReadDevice(i2c_handle, (char*)&data.z, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading Z data: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }

    return data;
}

// Function to calculate Euclidean magnitude
double calculate_euclidean_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log event to file
void log_event(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Peak Vibration: %d\n", timestamp, (int)calculate_euclidean_magnitude(data));
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
    gpioDelay(1000000); // 1 second delay
    gpioWrite(LED_PIN, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_euclidean_magnitude(data);

        if (magnitude > EUCLIDEAN_THRESHOLD) {
            log_event(data);
            control_led(1);
            printf("Earthquake-like event detected! Magnitude: %.2f\n", magnitude);
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

