#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define sensor pins
#define SENSOR_1_PIN 3
#define SENSOR_2_PIN 5
#define SENSOR_3_PIN 7
#define SENSOR_4_PIN 11
#define SENSOR_5_PIN 13

// Define GPIO chip and line numbers
#define GPIO_CHIP 0
#define NUM_LINES 5

// Define log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor data
typedef struct {
    int pin;
    char *line;
    int line_num;
} sensor_t;

// Global variables
volatile sig_atomic_t terminate = 0;
int gpio_handle;

// Sensor array
sensor_t sensors[NUM_LINES] = {
    {SENSOR_1_PIN, NULL, -1},
    {SENSOR_2_PIN, NULL, -1},
    {SENSOR_3_PIN, NULL, -1},
    {SENSOR_4_PIN, NULL, -1},
    {SENSOR_5_PIN, NULL, -1}
};

// Function prototypes
int initialize_gpio();
int acquire_lines();
int read_sensors();
void log_event(int sensor_id, int pin);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO interface
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpio_handle = gpioOpen(GPIO_CHIP, PI_OPEN_READ);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %d", gpio_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to acquire lines from the GPIO chip
int acquire_lines() {
    for (int i = 0; i < NUM_LINES; i++) {
        sensors[i].line = gpioGetLine(sensors[i].pin);
        if (sensors[i].line < 0) {
            syslog(LOG_ERR, "Failed to get line for sensor %d (GPIO %d): %d", i, sensors[i].pin, sensors[i].line);
            return -1;
        }
        sensors[i].line_num = i; // Store the line number
    }
    return 0;
}

// Function to read the sensors and log events
int read_sensors() {
    for (int i = 0; i < NUM_LINES; i++) {
        int current_state = gpioRead(sensors[i].pin);
        int previous_state = -1; // Initialize to an invalid state

        if (sensors[i].line != NULL) {
            previous_state = gpioReadLine(sensors[i].line);
        }

        if (current_state == 0 && previous_state == 1) { // Flame detected (LOW signal)
            gpioDelay(50); // Debounce
            if (gpioRead(sensors[i].pin) == 0) { // Re-read to confirm
                log_event(i, sensors[i].pin);
            }
        }
    }
    return 0;
}

// Function to log an event to the log file
void log_event(int sensor_id, int pin) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", LOG_FILE);
        fclose(fp);
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", buf, sensor_id, pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", LOG_FILE);
    }

    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    // Release lines
    for (int i = 0; i < NUM_LINES; i++) {
        if (sensors[i].line != NULL) {
            gpioReleaseLine(sensors[i].line);
            sensors[i].line = NULL;
        }
    }

    // Close GPIO chip
    if (gpio_handle >= 0) {
        gpioClose(gpio_handle);
    }

    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Acquire lines
    if (acquire_lines() != 0) {
        syslog(LOG_ERR, "Line acquisition failed, exiting");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Flame monitor started");

    // Main loop
    while (!terminate) {
        read_sensors();
        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

