#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read the state of a single sensor pin
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a sensor event
void log_event(int sensor_index, int pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    const char *state_str = (state == 1) ? "Touched" : "Released";
    printf("%s - Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, pin, state_str);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure the sensor pins as inputs
    for (int i = 0; i < num_sensors; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    printf("TTP226 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the sensor pins
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int pin = sensor_pins[i];
            int current_state = read_sensor(pin);

            if (current_state >= 0) {
                // Check if the state has changed since the last read
                static int last_states[num_sensors] = {0}; // Initialize to 0
                int last_state = last_states[i];

                if (current_state != last_state) {
                    log_event(i, pin, current_state);
                    last_states[i] = current_state; // Update last state
                }
            }
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    return 0;
}

