#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define PWM_PIN 18 // BCM GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_veml7700(int fd, uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int map_lux_to_pwm(float lux);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_data(FILE *fp, float lux, int brightness, int error_code);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", sig);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C bus %d at address 0x%02x: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return fd;
}

// Read ambient light data from VEML7700
int read_veml7700(int fd, uint16_t *als_data) {
    int raw_data = wiringPiI2CReadReg16(fd, ALS_DATA_REG);
    if (raw_data == -1) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als_data = (uint16_t)raw_data;
    return 0;
}

// Calculate lux value from raw ALS data (example formula, adjust as needed)
float calculate_lux(uint16_t als_data) {
    // This is a placeholder.  The actual calculation depends on the sensor's
    // gain and integration time settings.  Refer to the VEML7700 datasheet.
    // For example, if gain = 1/8 and integration time = 100ms:
    // lux = als_data * 0.000122 // Example calculation
    return (float)als_data * 0.000122; // Example calculation
}

// Map lux value to PWM duty cycle
int map_lux_to_pwm(float lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set PWM duty cycle on GPIO18
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    pwmWrite(pin, duty_cycle);
    return 0;
}

// Log data to file
int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(fp, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, VEML7700_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Configure VEML7700 (example configuration: gain = 1/8, integration time = 100ms)
    // wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x00); // Example register write

    // Configure PWM on GPIO18
    pinMode(PWM_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // For 1000 Hz frequency

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t als_data;
        float lux;
        int brightness;
        int error_code = 0;

        // Read ambient light data
        if (read_veml7700(i2c_fd, &als_data) == -1) {
            error_code = 1; // I2C read error
        } else {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Map lux to PWM duty cycle
            brightness = map_lux_to_pwm(lux);

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(PWM_PIN, brightness) == -1) {
                error_code = 2; // PWM set error
            }
        }

        // Log data
        if (log_data(log_file, lux, brightness, error_code) == -1) {
            error_code = 3; // Log write error
        }

        // Wait for 1 second
        delay(1000);
