// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define PWM_PIN 18 // BCM GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
