#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define SENSOR_START_PIN 2
#define SENSOR_END_PIN 9

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time[8] = {0};

// Function prototypes
int initialize_gpio();
int read_sensor_channel(int channel);
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int channels[8];
    int touched;
} SensorData;

SensorData sensor_data = {{0}, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        for (int channel = 0; channel < 8; channel++) {
            int sensor_value = read_sensor_channel(channel);

            if (sensor_value == 1) {
                unsigned long current_time = gpioTick();
                if ((current_time - last_touch_time[channel]) > DEBOUNCE_TIME * 1000) {
                    log_touch_event(channel);
                    sensor_data.channels[channel] = 1;
                    sensor_data.touched = 1;
                    control_led(1);
                }
                last_touch_time[channel] = current_time;
            } else {
                sensor_data.channels[channel] = 0;
            }
        }

        if (sensor_data.touched == 0) {
            control_led(0);
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    printf("Touch sensor monitoring stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially off

    // Set sensor pins as input with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(SENSOR_START_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_START_PIN + i, PI_PUD_DOWN);
    }

    return 0;
}

// Read sensor channel
int read_sensor_channel(int channel) {
    return gpioRead(SENSOR_START_PIN + channel);
}

// Log touch event to file
void log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel);

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to touch_log.txt\n");
    }

    fclose(fp);
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

