#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
float read_lux();
char* format_data(float lux);
int write_to_file(const char *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    // Continuous mode, auto range, 100ms conversion time
    unsigned short config_value = 0x1080; //0b0001000010000000

    // Byte swap for little-endian to big-endian
    config_value = (config_value >> 8) | (config_value << 8);

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // High byte
    buf[2] = config_value & 0xFF;        // Low byte

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait at least 100ms
    return 0;
}

// Read the lux value from the OPT3001 sensor
float read_lux() {
    char buf[1];
    buf[0] = RESULT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to result register: %d\n", result);
        return -1.0;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1.0;
    }

    // Byte swap for little-endian to big-endian
    unsigned short raw_data = (data[1] << 8) | data[0];

    // Extract exponent and result
    int exponent = (raw_data >> 12) & 0x0F;
    int result_val = raw_data & 0x0FFF;

    // Calculate lux value
    float lux = result_val * (0.01 * (1 << exponent));

    return lux;
}

// Format the data with timestamp
char* format_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char data_string[50]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(data_string, sizeof(data_string), "%s, %.2f", timestamp, lux);

    return data_string;
}

// Write the data to the log file
int write_to_file(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Cleanup function to close I2C and file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            char *data = format_data(lux);
            if (write_to_file(data) != 0) {
                fprintf(stderr, "Failed to write data to file.\n");
            }
            printf("%s\n", data);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

