#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4 // BCM GPIO 4, physical pin 7
#define DEBOUNCE_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in the specified format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to write a log entry to the file
int log_event(const char *event) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to handle touch events
void handle_touch(int gpio, int level, uint32_t tick) {
    static int last_level = 0; // Store the last known level
    static uint32_t last_tick = 0; // Store the last known tick

    if (level != last_level) {
        uint32_t diff = tick - last_tick;
        if (diff > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
            if (level == 1) {
                if (log_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error writing to log file.\n");
                }
            } else {
                if (log_event("Touch Released") != 0) {
                    fprintf(stderr, "Error writing to log file.\n");
                }
            }
            last_level = level;
            last_tick = tick;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for touch events
    gpioSetAlertFuncEx(GPIO_PIN, handle_touch, NULL);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

