#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define FLOW_RATE_SCALE_FACTOR 0.05 // ml/min per unit
#define FLOW_RATE_OFFSET 0.0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_flow_rate(int16_t raw_flow);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int validate_flow_rate(float flow_rate);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    data->raw_flow = (buf[0] << 8) | buf[1];
    data->crc = buf[2];

    return 0;
}

// Converts raw flow data to ml/min
float convert_flow_rate(int16_t raw_flow) {
    return (float)raw_flow * FLOW_RATE_SCALE_FACTOR + FLOW_RATE_OFFSET;
}

// Validates the CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated != crc);
}

// Validates the flow rate
int validate_flow_rate(float flow_rate) {
    return (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX);
}

// Logs the sensor data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char status_str[20];
    if (data.status == 0) {
        snprintf(status_str, sizeof(status_str), "VALID");
    } else {
        snprintf(status_str, sizeof(status_str), "INVALID");
    }

    fprintf(log_file, "%s,%.2f,%d,%s\n", timestamp, data.flow_rate, data.status, status_str);
    fflush(log_file);
    return 0;
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert flow rate
            sensor_data.flow_rate = convert_flow_rate(sensor_data.raw_flow);

            // Validate CRC
            if (validate_crc((uint8_t[]){sensor_data.raw_flow >> 8, sensor_data.raw_flow & 0xFF}, 2, sensor_data.crc) == 0) {
                // Validate flow rate
                if (validate_flow_rate(sensor_data.flow_rate) == 0) {
                    sensor_data.status = 0; // VALID
                } else {
                    sensor_data.status = 1; // INVALID
                }
            } else {
                sensor_data.status = 1; // INVALID
            }

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting recovery...\n");
            // Log error
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,ERROR,ERROR,ERROR\n", timestamp);
            fflush(log_file);

            // Re-initialize I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

