#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#include <wiringPi.h>

#define TOUCH_PIN 23 // BCM GPIO 23
#define LED_PIN 24   // BCM GPIO 24
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int touch_state = 0;
    int led_state = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi using GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as input/output
    pinMode(TOUCH_PIN, INPUT);
    pinMode(LED_PIN, OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the touch sensor state
        int current_touch_state = digitalRead(TOUCH_PIN);

        // Check for rising edge (touch detected)
        if (current_touch_state == HIGH && touch_state == LOW) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Toggle the LED state
            led_state = !led_state;
            digitalWrite(LED_PIN, led_state);

            // Log the event
            fprintf(log_file, "%s - Touch detected, LED state: %d\n", timestamp, led_state);
            fflush(log_file); // Ensure the log is written immediately

            printf("%s - Touch detected, LED state: %d\n", timestamp, led_state);
        }

        touch_state = current_touch_state;
        delay(100); // Small delay to avoid busy-waiting
    }

    // Cleanup before exiting
    digitalWrite(LED_PIN, LOW); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

