#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17 // BCM GPIO 17, physical pin 11
#define BUZZER_PIN 18       // BCM GPIO 18, physical pin 12

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int init_gpio();
int read_flame_sensor();
void activate_buzzer();
void log_event(const char *message);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int buzzer_pin;
} gpio_config_t;

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate the buzzer for 2 seconds
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(2000000);       // Wait for 2 seconds (2000000 microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();           // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received (%d). Shutting down...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Log system start
    log_event("System started");

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) { // Flame detected (LOW signal)
            log_event("FLAME DETECTED");
            activate_buzzer();
        }

        gpioDelay(500000); // Poll every 500ms (500000 microseconds)
    }

    cleanup();
    return 0;
}

