#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4  // BCM GPIO 4, physical pin 7
#define LED_PIN 17   // BCM GPIO 17, physical pin 11
#define DEBOUNCE_MS 200

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 1; // Assume initially not touched (HIGH)
    time_t last_touch_time = 0;

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 0 && last_touch_state == 1) { // LOW-to-HIGH transition
            time_t now = time(NULL);
            if (difftime(now, last_touch_time) * 1000 >= DEBOUNCE_MS) {
                // Debounced touch detected
                gpioWrite(LED_PIN, !gpioRead(LED_PIN)); // Toggle LED

                // Get UTC timestamp
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

                // Append to log file
                if (log_file != NULL) {
                    fprintf(log_file, "%s\n", timestamp);
                    fflush(log_file); // Ensure immediate write
                } else {
                    fprintf(stderr, "Warning: Log file is not open.\n");
                }

                last_touch_time = now;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Touch sensor logging stopped.\n");
    return 0;
}

