#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Global variables
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        running = 0;
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log the event to a file
void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, state == 0 ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables to store the initial sensor states
    int sensor1_initial_state = read_sensor(SENSOR1_PIN);
    int sensor2_initial_state = read_sensor(SENSOR2_PIN);
    int sensor3_initial_state = read_sensor(SENSOR3_PIN);

    if (sensor1_initial_state < 0 || sensor2_initial_state < 0 || sensor3_initial_state < 0) {
        fprintf(stderr, "Error reading initial sensor states. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);
        int sensor3_state = read_sensor(SENSOR3_PIN);

        if (sensor1_state < 0 || sensor2_state < 0 || sensor3_state < 0) {
            fprintf(stderr, "Error reading sensor states. Continuing...\n");
            gpioDelay(100); // Delay to avoid spamming errors
            continue;
        }

        // Log events only if the state has changed
        if (sensor1_state != sensor1_initial_state) {
            log_event(1, sensor1_state);
            sensor1_initial_state = sensor1_state;
        }
        if (sensor2_state != sensor2_initial_state) {
            log_event(2, sensor2_state);
            sensor2_initial_state = sensor2_state;
        }
        if (sensor3_state != sensor3_initial_state) {
            log_event(3, sensor3_state);
            sensor3_initial_state = sensor3_state;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

