#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle, sensor_config_t *config);
int read_heart_rate(int i2c_handle);
int validate_bpm(int bpm);
int write_to_csv(const char *timestamp, int bpm);
void signal_handler(int signal);

// Moving average filter function
int moving_average_filter(int new_value, int *window, int window_size) {
    static int sum = 0;
    static int index = 0;

    sum -= window[index];
    sum += new_value;

    window[index] = new_value;
    index = (index + 1) % window_size;

    return sum / window_size;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Sensor configuration
    sensor_config_t config = {0};

    // Initialize sensor
    if (initialize_sensor(i2c_handle, &config) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read heart rate
        int raw_heart_rate = read_heart_rate(i2c_handle);
        if (raw_heart_rate < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            continue; // Retry
        }

        // Apply moving average filter
        int filtered_heart_rate = moving_average_filter(raw_heart_rate, (int[]){0, 0, 0, 0, 0}, MOVING_AVG_SIZE);

        // Validate BPM
        if (validate_bpm(filtered_heart_rate) != 0) {
            fprintf(stderr, "Invalid BPM value\n");
            continue; // Retry
        }

        // Get timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

        // Write to CSV
        if (write_to_csv(timestamp, filtered_heart_rate) != 0) {
            fprintf(stderr, "Failed to write to CSV\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize sensor function
int initialize_sensor(int i2c_handle, sensor_config_t *config) {
    int retries = 3;
    int result;

    // Read PART_ID register
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (result >= 0) {
            config->part_id = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Failed to read PART_ID, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read PART_ID after multiple retries\n");
        return -1;
    }

    // Read HW_REV register
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, HW_REV_REG);
        if (result >= 0) {
            config->hw_rev = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Failed to read HW_REV, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read HW_REV after multiple retries\n");
        return -1;
    }

    // Check PART_ID and HW_REV
    if (config->part_id != 0x82 || config->hw_rev != 0x01) {
        fprintf(stderr, "Incorrect PART_ID or HW_REV\n");
        return -1;
    }

    return 0;
}

// Read heart rate function
int read_heart_rate(int i2c_handle) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, HEART_RATE_REG);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    fprintf(stderr, "Failed to read heart rate after multiple retries\n");
    return -1;
}

// Validate BPM function
int validate_bpm(int bpm) {
    if (bpm < 30 || bpm > 220) {
        return -1;
    }
    return 0;
}

// Write to CSV function
int write_to_csv(const char *timestamp, int bpm) {
    if (fprintf(log_file, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Failed to write to CSV\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

