    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, HEART_RATE_REG);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    fprintf(stderr, "Failed to read heart rate after multiple retries\n");
    return -1;
}

