void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to log flame detection event with timestamp
int log_flame_event(const char *filename) {
    FILE *fp = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s FLAME DETECTED\n", timestamp);
    fflush(fp); // Ensure immediate write to file
    fclose(fp);
    return 0;
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 1; // Assume initially no flame

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) { // Flame detected (LOW signal)
            printf("FLAME DETECTED\n");
            if (log_flame_event(LOG_FILE) != 0) {
                fprintf(stderr, "Error logging flame event.\n");
            }
            last_state = 0; // Update last state
            gpioDelay(500); // Debounce delay (500ms)
        } else if (current_state == 1 && last_state == 0) {
            last_state = 1; // Reset last state when flame is no longer detected
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup before exiting
    gpioTerminate();
    printf("GPIO terminated.\n");

    return 0;
}

