#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_START_PIN 5
#define SENSOR_END_PIN 12
#define OUTPUT_START_PIN 17
#define OUTPUT_END_PIN 24

// Define constants
#define STABILIZATION_DELAY_MS 200
#define POLL_DELAY_MS 10
#define NUM_CHANNELS 8

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void handle_signal(int signal);
int read_sensor_channel(int pin);
int write_output_channel(int pin, int value);
int update_output_pins(int counter);
int log_event(int channel, int counter);
int output_write_check(int pin, int value);

// Signal handler
void handle_signal(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set sensor pins as input
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(SENSOR_START_PIN + i, PI_INPUT);
    }

    // Set output pins as output
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(OUTPUT_START_PIN + i, PI_OUTPUT);
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Reset all output pins to 0
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(OUTPUT_START_PIN + i, 0);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Read sensor channel
int read_sensor_channel(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Write output channel
int write_output_channel(int pin, int value) {
    int result = gpioWrite(pin, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to output pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Update output pins with the counter value
int update_output_pins(int counter) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (output_write_check(OUTPUT_START_PIN + i, (counter >> i) & 1)) return -1;
    }
    return 0;
}

// Log event to file
int log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Check for output write errors
int output_write_check(int pin, int value) {
    int result = gpioWrite(pin, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Continue without logging to file, but keep stdout output functional
    }

    // Stabilization delay
    gpioDelay(STABILIZATION_DELAY_MS * 1000); // Convert ms to microseconds

    int counter = 0;
    int last_counter = 0;

    printf("Touch sensor counter started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor_channel(SENSOR_START_PIN + i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                counter = (counter + 1) % 256;
                if (update_output_pins(counter) != 0) {
                    fprintf(stderr, "Error updating output pins.\n");
                }
                if (log_event(i, counter) != 0) {
                    fprintf(stderr, "Error logging event for channel %d.\n", i);
                }
                printf("Touch on channel %d | Counter: %d\n", i, counter);
            }
        }
        gpioDelay(POLL_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

