#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL; // Indicate memory allocation failure
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to write a row to the CSV file
int write_to_csv(FILE *fp, const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1; // Indicate an error
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the CSV file for appending
    FILE *fp = fopen("tracking_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header row
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            program_running = 0; // Exit loop if timestamp allocation failed
            continue; // Skip the rest of the loop iteration
        }

        // Write the data to the CSV file
        if (write_to_csv(fp, timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
            program_running = 0; // Exit loop if write to CSV failed
        }

        // Free the timestamp memory
        free(timestamp);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Close the CSV file and flush the buffer
    fclose(fp);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

