#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 4  // BCM GPIO 4, physical pin 7
#define LED_OUTPUT_PIN 17 // BCM GPIO 17, physical pin 11

// Define sampling parameters
#define SAMPLE_PERIOD_US 125 // Sampling period in microseconds (8 kHz)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void sample_audio();
void process_peak_event();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(LED_OUTPUT_PIN, PI_OUTPUT);
    gpioWrite(LED_OUTPUT_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Sample audio data
void sample_audio() {
    int level = gpioRead(AUDIO_INPUT_PIN);

    if (level == 1) {
        process_peak_event();
    }

    gpioDelay(SAMPLE_PERIOD_US); // Delay for the sampling period
}

// Process peak event
void process_peak_event() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("Peak detected at: %ld ms\n", timestamp_ms);

    gpioWrite(LED_OUTPUT_PIN, 1); // Turn LED on
    gpioDelay(100);               // Wait for 100 ms
    gpioWrite(LED_OUTPUT_PIN, 0); // Turn LED off
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_OUTPUT_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sample_audio();
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

