#include <pigpio.h>

// Define GPIO pins for the IR sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int left_state, center_state, right_state;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Main loop to read and log sensor data
    while (program_running) {
        // Read the digital state of each sensor
        left_state = gpioRead(LEFT_SENSOR_PIN);
        center_state = gpioRead(CENTER_SENSOR_PIN);
        right_state = gpioRead(RIGHT_SENSOR_PIN);

        // Log the sensor states to the console
        printf("L: %d, C: %d, R: %d\n", left_state, center_state, right_state);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

