#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 Register Addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify Si1175 presence by reading Part ID register
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register: %d\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Si1175 not found. Part ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1175 sensor found. Part ID: 0x%02X\n", part_id);

    // Main loop
    while (1) {
        // Read ALS Visible data (LSB and MSB)
        int als_vis_lsb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        int als_vis_msb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);

        if (als_vis_lsb < 0 || als_vis_msb < 0) {
            fprintf(stderr, "Error reading ALS data: LSB=%d, MSB=%d\n", als_vis_lsb, als_vis_msb);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Combine LSB and MSB into a 16-bit raw value
        uint16_t raw_value = (uint16_t)als_vis_lsb | ((uint16_t)als_vis_msb << 8);

        // Log the raw sensor reading to the console
        printf("Raw ALS Value: %u\n", raw_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached in normal execution
    // because the main loop is infinite.  However, they are included
    // for completeness in case the loop is ever modified.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

