        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1175 sensor found. Part ID: 0x%02X\n", part_id);

    // Main loop
    while (1) {
        // Read ALS Visible data (LSB and MSB)
        int als_vis_lsb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        int als_vis_msb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);

        if (als_vis_lsb < 0 || als_vis_msb < 0) {
            fprintf(stderr, "Error reading ALS data: LSB=%d, MSB=%d\n", als_vis_lsb, als_vis_msb);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Combine LSB and MSB into a 16-bit raw value
        uint16_t raw_value = (uint16_t)als_vis_lsb | ((uint16_t)als_vis_msb << 8);

        // Log the raw sensor reading to the console
        printf("Raw ALS Value: %u\n", raw_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached in normal execution
    // because the main loop is infinite.  However, they are included
    // for completeness in case the loop is ever modified.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

