// Define GPIO pins for the sensors
#define LEFT_SENSOR 2
#define MIDDLE_SENSOR 3
#define RIGHT_SENSOR 4

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main()
{
    int left_value, middle_value, right_value;

    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Main loop to read sensor values
    while (!terminate)
    {
        // Read sensor values
        left_value = gpioRead(LEFT_SENSOR);
        middle_value = gpioRead(MIDDLE_SENSOR);
        right_value = gpioRead(RIGHT_SENSOR);

        // Log sensor values to stdout
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

