#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>

// gcc -o touch_poll touch_poll.c -lrt

#define	NUM_CHANNELS	8

static volatile int keepRunning = 1 ;

void intHandler (int dummy) {
  keepRunning = 0 ;
}

/*
 * readTouch:
 *	Read the state of the touch sensor inputs
 *********************************************************************************
 */

int readTouch (int channel)
{
  int pin ;

  switch (channel)
  {
    case 0 : pin = 5 ; break ;
    case 1 : pin = 6 ; break ;
    case 2 : pin = 13 ; break ;
    case 3 : pin = 19 ; break ;
    case 4 : pin = 26 ; break ;
    case 5 : pin = 12 ; break ;
    case 6 : pin = 16 ; break ;
    case 7 : pin = 20 ; break ;
    default: return -1 ;
  }

  return digitalRead (pin) ;
}


/*
 * outputLine:
 *	Output a line to stdout
 *********************************************************************************
 */

void outputLine (int touchValues [])
{
  time_t now ;
  char buffer [80] ;
  int i ;

  now = time (NULL) ;
  strftime (buffer, sizeof (buffer), "%S.%3lds", localtime (&now)) ;

  printf ("[%s] CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d CH%02d=%d\n",
	  buffer,
	  0, touchValues [0], 1, touchValues [1], 2, touchValues [2], 3, touchValues [3],
	  4, touchValues [4], 5, touchValues [5], 6, touchValues [6], 7, touchValues [7],
	  8, touchValues [8]) ;
}


/*
 * setup:
 *	Setup the GPIO
 *********************************************************************************
 */

void setup (void)
{
  int i ;

  wiringPiSetupSys () ;

  for (i = 0 ; i < NUM_CHANNELS ; ++i)
    pinMode (i, INPUT) ;
}


/*
 * main
 *********************************************************************************
 */

int main (void)
{
  int touchValues [NUM_CHANNELS] ;
  int i ;

  signal (SIGINT, intHandler) ;
  signal (SIGTERM, intHandler) ;

  setup () ;

  printf ("Raspberry Pi TTP226 Touch Sensor Poll\n") ;
  printf ("=====================================\n") ;
  printf ("\n") ;
  printf ("Press CTRL-C to end\n") ;

  for (;;)
  {
    for (i = 0 ; i < NUM_CHANNELS ; ++i)
      touchValues [i] = readTouch (i) ;

    outputLine (touchValues) ;

    delay (200) ;
  }

  return 0 ;
}

