#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17   // BCM GPIO 17
#define GREEN_PIN 18   // BCM GPIO 18
#define BLUE_PIN  27   // BCM GPIO 27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Transition duration (seconds)
#define TRANSITION_DURATION 5

// Number of steps in the transition
#define NUM_STEPS 50

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio()
{
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to set GPIO pin mode
int set_gpio_mode(int pin, int mode)
{
    if (gpioSetMode(pin, mode) != 0)
    {
        syslog(LOG_ERR, "Failed to set GPIO %d mode", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency)
{
    if (gpioSetPWMfrequency(pin, frequency) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int pin, int range)
{
    if (gpioSetPWMrange(pin, range) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM range for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int pin, int duty_cycle)
{
    if (gpioPWM(pin, duty_cycle) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM duty cycle for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to generate a random hue (0-359)
int generate_hue()
{
    return rand() % 360;
}

// Function to convert hue to RGB components
void hue_to_rgb(int hue, int *red, int *green, int *blue)
{
    float h = (float)hue / 60.0f;
    float x = 1.0f - fabsf(fmodf(h, 2.0f) - 1.0f);
    float r = 0.0f, g = 0.0f, b = 0.0f;

    if (h < 120.0f)
    {
        r = 1.0f;
        g = x;
    }
    else if (h < 240.0f)
    {
        r = x;
        g = 1.0f;
    }

    *red = (int)(r * PWM_RANGE);
    *green = (int)(g * PWM_RANGE);
    *blue = (int)(b * PWM_RANGE);
}

// Function to perform a linear interpolation between two RGB colors
void linear_interpolation(int *current_red, int *current_green, int *current_blue, int *target_red, int *target_green, int *target_blue, int step, int *new_red, int *new_green, int *new_blue)
{
    float red_diff = (float)(*target_red - *current_red) / NUM_STEPS;
    float green_diff = (float)(*target_green - *current_green) / NUM_STEPS;
    float blue_diff = (float)(*target_blue - *current_blue) / NUM_STEPS;

    *new_red = *current_red + (int)(red_diff * step);
    *new_green = *current_green + (int)(green_diff * step);
    *new_blue = *current_blue + (int)(blue_diff * step);

    // Clamp values to 0-255 range
    if (*new_red < 0) *new_red = 0;
    if (*new_red > PWM_RANGE) *new_red = PWM_RANGE;
    if (*new_green < 0) *new_green = 0;
    if (*new_green > PWM_RANGE) *new_green = PWM_RANGE;
    if (*new_blue < 0) *new_blue = 0;
    if (*new_blue > PWM_RANGE) *new_blue = PWM_RANGE;
}

int main()
{
    // Seed the random number generator
    srand(time(NULL));

    // Open syslog
    openlog("rgb_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0)
    {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Set GPIO pin modes to output
    if (set_gpio_mode(RED_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(GREEN_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(BLUE_PIN, PI_OUTPUT) != 0)
    {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(RED_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(GREEN_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(BLUE_PIN, PWM_FREQUENCY) != 0)
    {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM range
    if (set_pwm_range(RED_PIN, PWM_RANGE) != 0 ||
        set_pwm_range(GREEN_PIN, PWM_RANGE) != 0 ||
        set_pwm_range(BLUE_PIN, PWM_RANGE) != 0)
    {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Generate initial and target hues
    int hue = generate_hue();
    int target_hue = generate_hue();

    // Convert hue to RGB components
    int red = 0, green = 0, blue = 0;
    int new_red = 0, new_green = 0, new_blue = 0;

    // Main loop
    while (!terminate)
    {
        // Perform linear interpolation
        linear_interpolation(&red, &green, &blue, &target_red, &target_green, &target_blue, 1, &new_red, &new_green, &new_blue);

        // Set PWM duty cycles
        set_pwm_duty_cycle(RED_PIN, new_red);
        set_pwm_duty_cycle(GREEN_PIN, new_green);
        set_pwm_duty_cycle(BLUE_PIN, new_blue);

        // Update current hue and RGB components
        hue = target_hue;
        target_hue = generate_hue();
        hue_to_rgb(hue, &red, &green, &blue);

        // Check if the transition is complete
        if (hue == target_hue)
        {
            // Reset target hue to a new random value
            target_hue = generate_hue();
        }

        // Delay for a short period
        usleep(20000); // 20ms
    }

    // Turn off the LED
    set_pwm_duty_cycle(RED_PIN, 0);
    set_pwm_duty_cycle(GREEN_PIN, 0);
    set_pwm_duty_cycle(BLUE_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

