    }

    // Turn off the LED
    set_pwm_duty_cycle(RED_PIN, 0);
    set_pwm_duty_cycle(GREEN_PIN, 0);
    set_pwm_duty_cycle(BLUE_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

