// Signal Handler Function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable the sensor
    if (i2c_fd != -1) {
        uint8_t enable_reg = TCS34725_ENABLE;
        enable_reg &= ~TCS34725_PON;
        enable_reg &= ~TCS34725_AEN;
        if (write(i2c_fd, &enable_reg, 1) != 1) {
