#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi 4
#define BH1750_ADDR 0x23      // BH1750 I2C address
#define WS2812B_GPIO 18       // GPIO pin for WS2812B data line (BCM numbering)
#define NUM_LEDS 10           // Number of LEDs on the strip
#define MAX_LUX 1000.0        // Maximum lux value for mapping
#define MIN_LUX 0.0           // Minimum lux value for mapping

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

// Function prototypes
int init_i2c(const char *bus);
int read_bh1750(int fd);
float map_lux_to_brightness(float lux);
void generate_ws2812b_data(float brightness, uint32_t *data);
void send_ws2812b_data(uint32_t *data, int num_leds, int gpio_pin);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        program_running = 0;
    }
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Read illumination data from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t buf[2];
    uint8_t cmd = 0x10; // High resolution mode

    // Write command to start measurement
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine bytes to get lux value
    uint16_t lux_raw = (buf[0] << 8) | buf[1];
    float lux = (float)lux_raw / 1.2; // Convert to lux

    return lux;
}

// Map lux value to brightness level (logarithmic scale)
float map_lux_to_brightness(float lux) {
    if (lux <= MIN_LUX) {
        return 0.0;
    }
    if (lux >= MAX_LUX) {
        return 1.0;
    }
    return log10(lux / MIN_LUX); // Logarithmic mapping
}

// Generate WS2812B data (RGB values for each LED)
void generate_ws2812b_data(float brightness, uint32_t *data) {
    // Convert brightness to RGB (white light)
    float red = brightness;
    float green = brightness;
    float blue = brightness;

    // Scale RGB values to 0-255 range
    uint8_t red_int = (uint8_t)(red * 255.0);
    uint8_t green_int = (uint8_t)(green * 255.0);
    uint8_t blue_int = (uint8_t)(blue * 255.0);

    // Combine RGB values into a 32-bit word
    *data = ((uint32_t)red_int << 16) | ((uint32_t)green_int << 8) | blue_int;
}

// Send WS2812B data to GPIO pin using hardware PWM/wave
void send_ws2812b_data(uint32_t *data, int num_leds, int gpio_pin) {
    int i;
    uint32_t bit;
    uint32_t gpio_value = 0;

    // Set GPIO pin to output mode
    *gpio_value = 0; // Low
    write(1, gpio_value, sizeof(gpio_value));
    usleep(500); // Small delay

    for (i = 0; i < num_leds * 24; i++) {
        bit = (data[i / 8] >> (7 - (i % 8))) & 1;

        if (bit == 0) {
            // Logic 0: Low for 0.4us, High for 0.8us
            gpio_value = 0;
            write(1, gpio_value, sizeof(gpio_value));
            usleep(4); // 0.4us
            gpio_value = 1;
            write(1, gpio_value, sizeof(gpio_value));
            usleep(8); // 0.8us
        } else {
            // Logic 1: High for 0.4us, Low for 0.8us
            gpio_value = 1;
            write(1, gpio_value, sizeof(gpio_value));
            usleep(4); // 0.4us
            gpio_value = 0;
            write(1, gpio_value, sizeof(gpio_value));
            usleep(8); // 0.8us
        }
    }

    // Set GPIO pin to input mode (optional, but good practice)
    *gpio_value = 0; // Low
    write(1, gpio_value, sizeof(gpio_value));
    usleep(500); // Small delay
}

int main() {
    int retries = 3;
    int lux;
    float brightness;
    uint32_t ws2812b_data[NUM_LEDS];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    printf("BH1750 to WS2812B controller started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read illumination data with retries
        lux = -1;
        for (int i = 0; i < retries; i++) {
            lux = read_bh1750(i2c_fd);
            if (lux >= 0) {
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, retries);
                usleep(100000); // Wait before retrying
            }
        }

        if (lux < 0) {
            fprintf(stderr, "Failed to read BH1750 after multiple retries. Skipping.\n");
            usleep(500000); // Wait before next attempt
            continue;
        }

        // Map lux to brightness
        brightness = map_lux_to_brightness(lux);

        // Generate WS2812B data
        generate_ws2812b_data(brightness, ws2812b_data);

        // Send WS2812B data
        send_ws2812b_data(ws2812b_data, NUM_LEDS, WS2812B_GPIO);

        // Wait before next iteration
        usleep(500000); // 500ms
    }

    // Clean up resources
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Program terminated.\n");
    return 0;
}

