int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode and speed
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read light level from BH1750
uint16_t read_bh1750(int fd) {
    uint8_t buf[2];
    uint16_t lux = 0;

    // Send start measurement command (High Resolution Mode)
    uint8_t cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return 0; // Return 0 on error
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return 0; // Return 0 on error
    }

    // Combine bytes to form lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

