    // Scale brightness (0-4095)
    uint16_t scaled_brightness = (lux * 4095) / max_lux;

    // Ensure brightness is within the valid range
    if (scaled_brightness > 4095) {
        scaled_brightness = 4095;
    } else if (scaled_brightness < 0) {
        scaled_brightness = 0;
    }

    return (uint32_t)scaled_brightness;
}

// Send APA102 data
int send_apa102_data(int fd, uint32_t *data, int num_leds) {
    uint8_t start_frame[4] = {(APA102_START_FRAME >> 0) & 0xFF, (APA102_START_FRAME >> 8) & 0xFF, (APA102_START_FRAME >> 16) & 0xFF, (APA102_START_FRAME >> 24) & 0xFF};
