    for (int i = 0; i < num_leds; i++) {
        uint32_t led_data = data[i];
        uint8_t led_frame[4] = {(led_data >> 0) & 0xFF, (led_data >> 8) & 0xFF, (led_data >> 16) & 0xFF, (led_data >> 24) & 0xFF};
        if (write(fd, led_frame, 4) != 4) {
            perror("Error writing LED data");
            return -1;
        }
    }

