    if (write(fd, end_frame, 4) != 4) {
        perror("Error writing end frame");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Initialization complete. Running...\n");

    // Main loop
    while (!terminate) {
        // Read light level
        uint16_t lux = read_bh1750(i2c_fd);
        if (lux == 0 && errno != 0) {
            fprintf(stderr, "Error reading light level. Continuing...\n");
            lux = 100; // Assign a default value to avoid crashing
        }

        // Scale brightness
        uint32_t brightness = scale_brightness(lux);

        // Prepare APA102 data
        uint32_t led_data[NUM_LEDS];
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i] = brightness; // All LEDs have the same brightness
        }

        // Send APA102 data
        if (send_apa102_data(spi_fd, led_data, NUM_LEDS) != 0) {
            fprintf(stderr, "Error sending APA102 data. Continuing...\n");
        }

        // Wait before next iteration
        usleep(120000); // 120ms
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Turn off LEDs (send end frame)
    uint8_t end_frame[4] = {(APA102_END_FRAME >> 0) & 0xFF, (APA102_END_FRAME >> 8) & 0xFF, (APA102_END_FRAME >> 16) & 0xFF, (APA102_END_FRAME >> 24) & 0xFF};
    if (write(spi_fd, end_frame, 4) != 4) {
        perror("Error writing end frame during cleanup");
    }

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    printf("Exiting.\n");
    return 0;
}

