#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C

// APA102 SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOSI_PIN 10
#define SCLK_PIN 11

// Number of LEDs in the strip
#define NUM_LEDS 10

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
int read_bh1750(int i2c_handle);
float average_light_level(int sensor1_reading, int sensor2_reading, int sensor3_reading);
void set_apa102_brightness(int brightness);
void fade_apa102_brightness(int target_brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) != 0) { // Continuous high-resolution mode
        fprintf(stderr, "Error: Could not configure BH1750 sensor.\n");
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Error: Could not read data from BH1750 sensor.\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Calculate average light level
float average_light_level(int sensor1_reading, int sensor2_reading, int sensor3_reading) {
    int count = 0;
    int sum = 0;

    if (sensor1_reading != -1) {
        sum += sensor1_reading;
        count++;
    }
    if (sensor2_reading != -1) {
        sum += sensor2_reading;
        count++;
    }
    if (sensor3_reading != -1) {
        sum += sensor3_reading;
        count++;
    }

    if (count == 0) {
        return 0.0; // Avoid division by zero
    } else {
        return (float)sum / count;
    }
}

// Set APA102 brightness
void set_apa102_brightness(int brightness) {
    unsigned char data[4];
    int i;

    // Start frame (32 bits of 0x00)
    for (i = 0; i < 4; i++) {
        data[i] = 0x00;
    }

    // LED data (brightness, red, green, blue)
    for (i = 0; i < NUM_LEDS; i++) {
        data[1] = 0xE0 | (brightness & 0x1F); // Global brightness
        data[2] = 0x00; // Red
        data[3] = 0x00; // Green
        data[4] = 0x00; // Blue

        spiWrite(spi_handle, (char *)data, 4);
    }

    // End frame (at least (NUM_LEDS + 1) / 2 0xFF bytes)
    int end_frame_size = ((NUM_LEDS + 1) / 2) + 1;
    for (i = 0; i < end_frame_size; i++) {
        data[1] = 0xFF;
        spiWrite(spi_handle, (char *)data, 1);
    }
}

// Fade APA102 brightness
void fade_apa102_brightness(int target_brightness) {
    int current_brightness = 0;
    int increment = (target_brightness > current_brightness) ? 1 : -1;
    int num_steps = 20; // Adjust for smoother/faster fade

    for (int i = 0; i < num_steps; i++) {
        current_brightness += increment;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;
        set_apa102_brightness(current_brightness);
        gpioDelay(50); // 50 ms delay
    }
    set_apa102_brightness(target_brightness); // Ensure final brightness is set
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(1, BH1750_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C bus for BH1750_ADDR1.\n");
    }

    i2c_handle2 = i2cOpen(1, BH1750_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C bus for BH1750_ADDR2.\n");
    }

    // Initialize BH1750 sensors
    if (i2c_handle1 >= 0 && init_bh1750(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0 && init_bh1750(i2c_handle2) != 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel.\n");
        if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
        if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor1_reading = -1, sensor2_reading = -1, sensor3_reading = -1;

        // Read sensor 1
        if (i2c_handle1 >= 0) {
            sensor1_reading = read_bh1750(i2c_handle1);
            if (sensor1_reading == -1) {
                fprintf(stderr, "Error reading sensor 1, skipping.\n");
                i2cClose(i2c_handle1);
                i2c_handle1 = -1;
            }
        }

        // Read sensor 2
        if (i2c_handle2 >= 0) {
            sensor2_reading = read_bh1750(i2c_handle2);
            if (sensor2_reading == -1) {
                fprintf(stderr, "Error reading sensor 2, skipping.\n");
                i2cClose(i2c_handle2);
                i2c_handle2 = -1;
            }
        }

        // Read sensor 3 (dummy value if no sensor 3)
        if (i2c_handle1 >= 0 || i2c_handle2 >= 0) {
            sensor3_reading = 500; // Dummy value
        } else {
            sensor3_reading = -1;
        }

        // Calculate average light level
        float avg_light_level = average_light_level(sensor1_reading, sensor2_reading, sensor3_reading);

        // Map light level to brightness (0-31)
        int target_brightness = (int)(avg_light_level / 100.0); // Example mapping
        if (target_brightness < 0) target_brightness = 0;
        if (target_brightness > 31) target_brightness = 31;

        // Fade to the new brightness
        fade_apa102_brightness(target_brightness);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

