#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// WS2812B LED strip parameters
#define LED_COUNT 1
#define GPIO_PIN 18
#define PWM_FREQUENCY 800000 // 800 kHz

// Gamma correction parameters
#define GAMMA 2.2

// I2C retry parameters
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold VEML7700 configuration
typedef struct {
    uint16_t gain;
    uint16_t integration_time;
} veml7700_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the VEML7700 sensor
int init_veml7700(int i2c_handle) {
    // Configuration: Gain 2x, Integration Time 100ms
    uint16_t config_value = 0x0000; // Default configuration
    uint8_t data[3];

    data[0] = VEML7700_ALS_CONF | 0x80; // Write command
    data[1] = config_value & 0xFF;       // LSB
    data[2] = (config_value >> 8) & 0xFF; // MSB

    if (i2cWriteDevice(i2c_handle, (char *)data, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read ambient light data from the VEML7700 sensor
int read_veml7700(int i2c_handle, uint16_t *lux) {
    uint8_t data[2];

    // Read ALS data (2 bytes)
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading ambient light data from VEML7700\n");
        return -1;
    }

    *lux = (data[1] << 8) | data[0];
    return 0;
}

// Function to apply gamma correction to the lux value
uint8_t gamma_correct(uint16_t lux) {
    double gamma_corrected_lux = pow(lux / 65535.0, GAMMA) * 65535.0;
    return (uint8_t)(gamma_corrected_lux > 65535 ? 65535 : gamma_corrected_lux);
}

// Function to set the brightness of the WS2812B LED strip
void set_led_brightness(int gpio_pin, uint8_t brightness) {
    // Bit-banging the data line
    for (int i = 0; i < LED_COUNT; i++) {
        // Green
        gpioPWM(gpio_pin, brightness);
        gpioDelay(1); // 0.8us
        gpioPWM(gpio_pin, 0);
        gpioDelay(0.5); // 0.45us

        // Red
        gpioPWM(gpio_pin, brightness);
        gpioDelay(1); // 0.8us
        gpioPWM(gpio_pin, 0);
        gpioDelay(0.5); // 0.45us

        // Blue
        gpioPWM(gpio_pin, brightness);
        gpioDelay(1); // 0.8us
        gpioPWM(gpio_pin, 0);
        gpioDelay(0.5); // 0.45us
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency (approximately 800 kHz)
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t lux;
        uint8_t brightness;

        // Read ambient light data with retries
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_veml7700(i2c_handle, &lux) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read error, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "I2C read failed after %d retries, using threshold-based control\n", MAX_RETRIES);
            brightness = (lux > 1000) ? 255 : 0; // Simple threshold-based control
        } else {
            // Apply gamma correction
            brightness = gamma_correct(lux);
        }

        // Set LED brightness
        set_led_brightness(GPIO_PIN, brightness);

        // Print lux reading and brightness value
        printf("Lux: %d, Brightness: %d\n", lux, brightness);

        // Pause for 200 ms
        gpioDelay(200);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

