#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define POLL_INTERVAL_MS 50
#define ERROR_BLINK_MS 100
#define ERROR_BUZZER_PATTERN_MS {200, 200, 600, 200}
#define ERROR_BUZZER_REPEATS 3

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
void error_handler();
void signal_handler(int signal);
void log_event(const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Error handling function
void error_handler() {
    // Blink LED rapidly
    for (int i = 0; i < 10; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(ERROR_BLINK_MS);
        gpioWrite(LED_PIN, 0);
        gpioDelay(ERROR_BLINK_MS);
    }

    // Activate buzzer with pattern
    for (int i = 0; i < ERROR_BUZZER_REPEATS; i++) {
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(ERROR_BUZZER_PATTERN_MS[0]);
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(ERROR_BUZZER_PATTERN_MS[1]);
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(ERROR_BUZZER_PATTERN_MS[2]);
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(ERROR_BUZZER_PATTERN_MS[3]);
    }

    log_event("ERROR: Flame detected on all samples during self-test.");
    gpioTerminate();
    exit(1);
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Self-test
    printf("Starting self-test...\n");
    log_event("Starting self-test...");

    // Blink LED
    for (int i = 0; i < 10; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500);
        gpioWrite(LED_PIN, 0);
        gpioDelay(500);
    }

    // Read flame sensor 5 times with 100ms delay
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        gpioDelay(100);
        if (sensor_value == 0) {
            log_event("Self-test: Flame detected.");
        }
    }

    // Check if all readings were LOW
    if (read_flame_sensor() == 0) {
        error_handler();
    }

    printf("Self-test complete.\n");
    log_event("Self-test complete.");

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            // Flame detected
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            log_event("Flame detected!");

            // Wait for flame to clear
            while (read_flame_sensor() == 0) {
                gpioDelay(POLL_INTERVAL_MS);
            }

            // Flame cleared
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            log_event("Flame cleared.");

        } else {
            // No flame detected
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

