        gpioDelay(ERROR_BUZZER_PATTERN_MS[3]);
    }

    log_event("ERROR: Flame detected on all samples during self-test.");
    gpioTerminate();
    exit(1);
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

