    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Self-test
    printf("Starting self-test...\n");
    log_event("Starting self-test...");

    // Blink LED
    for (int i = 0; i < 10; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500);
        gpioWrite(LED_PIN, 0);
        gpioDelay(500);
    }

    // Read flame sensor 5 times with 100ms delay
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        gpioDelay(100);
        if (sensor_value == 0) {
            log_event("Self-test: Flame detected.");
        }
    }

    // Check if all readings were LOW
    if (read_flame_sensor() == 0) {
        error_handler();
    }

    printf("Self-test complete.\n");
    log_event("Self-test complete.");

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            // Flame detected
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            log_event("Flame detected!");

            // Wait for flame to clear
            while (read_flame_sensor() == 0) {
                gpioDelay(POLL_INTERVAL_MS);
            }

            // Flame cleared
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            log_event("Flame cleared.");

        } else {
            // No flame detected
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

