#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0
#define MIN_LUX 0.0
#define MAX_LUX 1000.0

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void init_gpio();
void cleanup();
void signal_handler(int signal);
float circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_get_average(CircularBuffer *cb);
float map_lux_to_frequency(float lux);

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buf[2];
    unsigned char mode = 0x10; // High resolution mode

    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Initialize GPIO
void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        cleanup();
        exit(1);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    close(i2c_fd);          // Close I2C file descriptor
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Add value to circular buffer
float circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
    return value;
}

// Get average of circular buffer
float circular_buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Map lux to frequency
float map_lux_to_frequency(float lux) {
    float frequency = MIN_FREQ + (lux - MIN_LUX) * (MAX_FREQ - MIN_FREQ) / (MAX_LUX - MIN_LUX);
    if (frequency < MIN_FREQ) frequency = MIN_FREQ;
    if (frequency > MAX_FREQ) frequency = MAX_FREQ;
    return frequency;
}

int main() {
    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    init_gpio();

    // Signal handling
    signal(SIGINT, signal_handler);

    // Circular buffer initialization
    CircularBuffer lux_buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            circular_buffer_add(&lux_buffer, lux);
            float avg_lux = circular_buffer_get_average(&lux_buffer);
            float frequency = map_lux_to_frequency(avg_lux);

            // Blink LED with square wave
            gpioWaveClear(); // Clear existing waves

            int period_ms = (int)(1000.0 / frequency); // Period in milliseconds
            int on_time_ms = period_ms / 2;             // 50% duty cycle

            gpioPulse_t pulse[2];
            pulse[0].gpioOn = 1 << GPIO_LED;  // Turn on GPIO
            pulse[0].gpioOff = 0;           // Turn off other GPIOs
            pulse[0].usDelay = on_time_ms * 1000; // Delay in microseconds

            pulse[1].gpioOn = 0;              // Turn off GPIOs
            pulse[1].gpioOff = 1 << GPIO_LED; // Turn off GPIO
            pulse[1].usDelay = period_ms * 1000 - on_time_ms * 1000; // Delay in microseconds

            gpioWaveAddGeneric(2, pulse);

            int wave_id = gpioWaveCreate();
            if (wave_id >= 0) {
                gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Send wave in loop mode
                while (!terminate) {
                    usleep(100000); // Wait for wave to complete one cycle
                }
                gpioWaveTxStop();
                gpioWaveDelete(wave_id);
            } else {
                fprintf(stderr, "Error creating wave: %d\n", wave_id);
            }

            printf("Lux: %.2f, Frequency: %.2f Hz\n", avg_lux, frequency);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

