#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <unistd.h>

// Define GPIO pins
#define DATA_PIN 17  // BCM GPIO 17
#define CLOCK_PIN 18 // BCM GPIO 18
#define LATCH_PIN 27 // BCM GPIO 27

// Seven-segment display mapping
const int segment_map[] = {1, 1, 1, 1, 1, 1, 0, 0}; // a, b, c, d, e, f, g, dp

// Function to shift out data to the 74HC595
void shiftOut(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin
        digitalWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        digitalWrite(CLOCK_PIN, HIGH);
        delayMicroseconds(1); // Clock pulse width
        digitalWrite(CLOCK_PIN, LOW);
        delayMicroseconds(1);

        // Latch the data to the output
        digitalWrite(LATCH_PIN, HIGH);
        delayMicroseconds(1); // Latch pulse width
        digitalWrite(LATCH_PIN, LOW);
        delayMicroseconds(1);
    }
}

// Function to display a digit on the seven-segment display
void displayDigit(int digit) {
    // Convert digit to a byte array
    unsigned char data[8];
    for (int i = 0; i < 8; i++) {
        data[i] = (digit & (1 << i)) ? segment_map[i] : 0; // Set bit if segment is on, otherwise 0
    }

    // Shift out the data
    shiftOut(data[0]);
    shiftOut(data[1]);
    shiftOut(data[2]);
    shiftOut(data[3]);
    shiftOut(data[4]);
    shiftOut(data[5]);
    shiftOut(data[6]);
    shiftOut(data[7]);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed, exiting...\n");
        return 1;
    }

    // Set GPIO pins as outputs
    pinMode(DATA_PIN, OUTPUT);
    pinMode(CLOCK_PIN, OUTPUT);
    pinMode(LATCH_PIN, OUTPUT);

    // Display the digit '5'
    displayDigit(5);

    // Blink the digit '5'
    while (1) {
        // Turn the display on
        displayDigit(5);
        delay(500);

        // Turn the display off
        //displayDigit(0); // Displaying 0 turns off all segments
        //delay(500);

        // Alternatively, you can clear the display by shifting out all 0s
        for (int i = 0; i < 8; i++) {
            shiftOut(0x00);
        }
        delay(500);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    digitalWrite(DATA_PIN, LOW);
    digitalWrite(CLOCK_PIN, LOW);
    digitalWrite(LATCH_PIN, LOW);

    return 0;
}

