#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin as output\n");
        return -1;
    }

    // Set button pin as input with pull-up resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting button pin as input\n");
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistor on button pin\n");
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led()
{
    // Turn LED on
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error writing to LED pin\n");
    }

    // Wait for 1 second
    gpioDelay(1000000); // 1 second = 1000000 microseconds

    // Turn LED off
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to LED pin\n");
    }

    // Wait for 1 second
    gpioDelay(1000000); // 1 second = 1000000 microseconds
}

// Function to handle button press event
void button_pressed()
{
    // Turn LED off
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to LED pin\n");
    }

    // Print button press message
    printf("Button pressed! Exiting.\n");

    // Terminate the program
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Blink the LED
        blink_led();

        // Check for button press event
        if (gpioEvent(BUTTON_PIN, FALLING_EDGE, 0) == 0) {
            button_pressed();
        }
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    return 0;
}

