    terminate = 1;
}

int main() {
    int rc;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    rc = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", LED_GPIO, rc);
        gpioTerminate();
        return 1;
    }

    rc = gpioSetMode(BUTTON_GPIO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", BUTTON_GPIO, rc);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_DOWN);

    printf("Press the button to blink the LED. Press Ctrl-C to exit.\n");

    while (!terminate) {
        if (gpioRead(BUTTON_GPIO) == 1) {
            // Button is pressed
            while (gpioRead(BUTTON_GPIO) == 1 && !terminate) {
                rc = gpioWrite(LED_GPIO, 1);
                if (rc != 0) {
                    fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_GPIO, rc);
                    terminate = 1; // Exit loop on error
                    break;
                }
                gpioDelay(500000); // 500ms

                rc = gpioWrite(LED_GPIO, 0);
                if (rc != 0) {
                    fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_GPIO, rc);
                    terminate = 1; // Exit loop on error
                    break;
                }
                gpioDelay(500000); // 500ms
            }
        } else {
            // Button is not pressed
            rc = gpioWrite(LED_GPIO, 0);
            if (rc != 0) {
                fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_GPIO, rc);
                terminate = 1; // Exit loop on error
                break;
            }
        }
        gpioDelay(10000); // Small delay to avoid busy-waiting
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

