#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common cathode)
#define RED_PIN   18   // BCM GPIO 18
#define GREEN_PIN 16   // BCM GPIO 16
#define BLUE_PIN  12   // BCM GPIO 12

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB color using software PWM
void set_rgb(int red, int green, int blue)
{
    // Common cathode, so invert the values
    int r = 255 - (red > 127 ? 255 : 0);
    int g = 255 - (green > 127 ? 255 : 0);
    int b = 255 - (blue > 127 ? 255 : 0);

    gpioPWM(RED_PIN, r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN, b);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Generate random RGB values
        int red   = rand() % 101;
        int green = rand() % 101;
        int blue  = rand() % 101;

        // Set the RGB color
        set_rgb(red, green, blue);

        // Wait for 100ms before changing color
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Clean up GPIO pins before exiting
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    gpioTerminate();
    return 0;
}

