#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A   0x28
#define OUT_X_H_A   0x29
#define OUT_Y_L_A   0x2A
#define OUT_Y_H_A   0x2B
#define OUT_Z_L_A   0x2C
#define OUT_Z_H_A   0x2D

// GPIO pin for impact interrupt
#define IMPACT_PIN 17

// Default impact threshold (in G)
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_impact_interrupt();
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        impact_threshold = strtod(argv[1], &endptr);
        if (*endptr != '\0' || impact_threshold <= 0) {
            fprintf(stderr, "Error: Invalid impact threshold. Using default value (%f G).\n", DEFAULT_THRESHOLD);
            impact_threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t data;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&data.x, &data.y, &data.z) == 0) {
            // Calculate G-force magnitude
            magnitude = calculate_magnitude(data.x, data.y, data.z);

            // Check for impact
            if (magnitude > impact_threshold) {
                trigger_impact_interrupt();
            }

            // Log data
            log_data(data.x, data.y, data.z, magnitude);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // I2C bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure accelerometer (100Hz, enable all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate G-force magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    // Assuming +/- 2G sensitivity (16384 counts/G)
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Trigger impact interrupt
void trigger_impact_interrupt() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50000);        // Wait 50ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f G\n", s, x, y, z, magnitude);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(IMPACT_PIN, 0); // Ensure GPIO is LOW
    gpioSetMode(IMPACT_PIN, PI_INPUT); // Set back to input
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

