// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ registers
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Data rate (Hz)
#define DATA_RATE 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xC7, got 0x%X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby)\n");
        return -1;
    }

    // Configure for ±2g range and 200 Hz data rate
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG2, 0x02) < 0) { // Active mode, 200 Hz
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the FXOS8700CQ
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return 0;
}

// Calculate the acceleration magnitude
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0f; // +/- 2g range
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

