    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() < 0) {
        fprintf(stderr, "FXOS8700CQ initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            magnitude = calculate_acceleration_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

