#define GYRO_ADDR 0x69

// Define the WHO_AM_I register address
#define WHO_AM_I 0x0F

// Define the CTRL_REG1 register address
#define CTRL_REG1 0x20

// Define the OUT_X_L register address
#define OUT_X_L 0x28

// Define the number of calibration samples
#define NUM_CALIBRATION_SAMPLES 100

// Define the zero-rate threshold (dps)
#define ZERO_RATE_THRESHOLD 50.0

// Define the log file name
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
gyro_data_t calibrate_gyro();
gyro_data_t read_gyro_data(gyro_data_t offsets);
void log_data(gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the gyroscope
int initialize_gyro() {
    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x49, got 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure the gyroscope (e.g., enable all axes, 100Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
