int read_accel(int handle, float *x, float *y, float *z);
int read_mag(int handle, float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
int log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle_accel = init_i2c(1, LSM303_ACCEL_ADDR);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Accelerometer I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = init_i2c(1, LSM303_MAG_ADDR);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Magnetometer I2C initialization failed\n");
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

