        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accel(i2c_handle_accel, &sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        }
        if (read_mag(i2c_handle_mag, &sensor_data.mag_x, &sensor_data.mag_y, &sensor_data.mag_z) != 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        // Calculate heading
        sensor_data.heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

        // Log data
        if (log_data(log_file, sensor_data.heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %d\n", addr, bus, handle);
        return -1;
    }

    // Configure accelerometer (enable all axes, 50Hz data rate)
    if (i2cWriteByteData(handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) != 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        i2cClose(handle);
        return -1;
    }

    // Configure magnetometer (continuous conversion mode)
    if (i2cWriteByteData(handle, LSM303_MAG_MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M\n");
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Read accelerometer data
int read_accel(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) * ACCEL_SENSITIVITY;
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) * ACCEL_SENSITIVITY;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) * ACCEL_SENSITIVITY;

    return 0;
}

// Read magnetometer data
int read_mag(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    *x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) * MAG_SENSITIVITY;
    *y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) * MAG_SENSITIVITY;
    *z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) * MAG_SENSITIVITY;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float cosRoll = cos(roll);
    float sinRoll = sin(roll);
    float cosPitch = cos(pitch);
    float sinPitch = sin(pitch);

    float x_h = mag_x * cosPitch + mag_z * sinPitch;
    float y_h = mag_x * sinRoll * sinPitch + mag_y * cosRoll - mag_z * sinRoll * cosPitch;

    float heading = atan2(y_h, x_h) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
int log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

