#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor addresses and I2C bus
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define data structure for sensor readings
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
} SensorData;

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
SensorData read_sensor_data(int i2c_handle);
long long get_timestamp_ns();
double calculate_tdoa(int16_t sensor1, int16_t sensor2);
int log_data(long long timestamp, int16_t sensor1, int16_t sensor2, double tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data from I2C
SensorData read_sensor_data(int i2c_handle) {
    SensorData data;
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        data.sensor1 = 0; // Set to 0 to indicate error
        data.sensor2 = 0;
        return data;
    }

    data.sensor1 = (int16_t)((buf[1] << 8) | buf[0]);
    data.sensor2 = (int16_t)((buf[3] << 8) | buf[2]);

    return data;
}

// Function to get timestamp in nanoseconds
long long get_timestamp_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000000000LL + ts.tv_nsec);
}

// Function to calculate TDOA (simple cross-correlation)
double calculate_tdoa(int16_t sensor1, int16_t sensor2) {
    // This is a placeholder.  A real implementation would use cross-correlation.
    // This simplified version just returns the difference.
    return (double)(sensor1 - sensor2);
}

// Function to log data to CSV file
int log_data(long long timestamp, int16_t sensor1, int16_t sensor2, double tdoa) {
    char sec_str[20];
    char nsec_str[20];

    snprintf(sec_str, sizeof(sec_str), "%lld", timestamp / 1000000000LL);
    snprintf(nsec_str, sizeof(nsec_str), "%09lld", timestamp % 1000000000LL);

    fprintf(log_file, "%s,%s,%d,%d,%lf\n", sec_str, nsec_str, sensor1, sensor2, tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        SensorData sensor_data1, sensor_data2;
        long long timestamp;
        double tdoa;

        // Read sensor data
        sensor_data1 = read_sensor_data(i2c_handle1);
        sensor_data2 = read_sensor_data(i2c_handle2);

        // Get timestamp
        timestamp = get_timestamp_ns();

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor_data1.sensor1, sensor_data2.sensor2);

        // Log data
        log_data(timestamp, sensor_data1.sensor1, sensor_data2.sensor2, tdoa);

        // Delay
        gpioDelay(10000); // 10ms
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

