#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define REG_GYRO_XOUT 0x04
#define REG_GYRO_YOUT 0x06
#define REG_GYRO_ZOUT 0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Sensitivity Values
#define GYRO_SENSITIVITY 0.005 // deg/s/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function Prototypes
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint16_t command, uint8_t reg);
int read_data(int handle, uint8_t reg, int16_t *data);
void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g);
int log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// Function to read a register
int read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = 0x80 | reg; // Set MSB for read operation
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    return rx[1];
}

// Function to write a register
int write_register(int handle, uint16_t command, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = command & 0xFF; //LSB
    tx[1] = (command >> 8) & 0xFF; //MSB

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to read data from a register
int read_data(int handle, uint8_t reg, int16_t *data) {
    char tx[2], rx[2];
    tx[0] = 0x00; // Dummy byte
    tx[1] = reg; // Register address

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI data read error\n");
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

// Function to convert raw data to physical units
void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g) {
    *gyro_x_dps = gyro_x * GYRO_SENSITIVITY;
    *gyro_y_dps = gyro_y * GYRO_SENSITIVITY;
    *gyro_z_dps = gyro_z * GYRO_SENSITIVITY;
    *accel_x_g = accel_x * ACCEL_SENSITIVITY;
    *accel_y_g = accel_y * ACCEL_SENSITIVITY;
    *accel_z_g = accel_z * ACCEL_SENSITIVITY;
}

