#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Scaling factors
#define GYRO_SCALE 0.05 // degrees/sec per LSB
#define ACCEL_SCALE 0.00025 // g per LSB

