// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read IMU data
int read_imu_data(int spi_handle, int reg_addr, float *data)
{
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Prepare the transmit buffer with the register address
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for clocking out data

    // Transfer the data
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1; // Indicate failure
    }

    // Extract the 16-bit data from the receive buffer
    int16_t raw_data = (rx_buf[0] << 8) | rx_buf[1];

    // Scale the data
    data[0] = (float)raw_data * GYRO_SCALE;
    data[1] = (float)raw_data * GYRO_SCALE;
    data[2] = (float)raw_data * GYRO_SCALE;
    data[3] = (float)raw_data * ACCEL_SCALE;
    data[4] = (float)raw_data * ACCEL_SCALE;
    data[5] = (float)raw_data * ACCEL_SCALE;

    return 0; // Indicate success
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
