#define ADIS16448_REG_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Scaling factors
#define GYRO_SCALE 0.05 // degrees/sec per LSB
#define ACCEL_SCALE 0.00025 // g per LSB

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read IMU data
int read_imu_data(int spi_handle, int reg_addr, float *data)
{
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Prepare the transmit buffer with the register address
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for clocking out data

    // Transfer the data
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1; // Indicate failure
    }

    // Extract the 16-bit data from the receive buffer
    int16_t raw_data = (rx_buf[0] << 8) | rx_buf[1];

    // Scale the data
    data[0] = (float)raw_data * GYRO_SCALE;
    data[1] = (float)raw_data * GYRO_SCALE;
    data[2] = (float)raw_data * GYRO_SCALE;
    data[3] = (float)raw_data * ACCEL_SCALE;
    data[4] = (float)raw_data * ACCEL_SCALE;
    data[5] = (float)raw_data * ACCEL_SCALE;

    return 0; // Indicate success
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float imu_data[6];

    // Main loop
    while (1) {
        // Read IMU data
        if (read_imu_data(spi_handle, ADIS16448_REG_GYRO_XOUT, imu_data) != 0) {
            fprintf(stderr, "Failed to read IMU data\n");
        } else {
            // Print the IMU data
            printf("Gyro X: %.2f, Gyro Y: %.2f, Gyro Z: %.2f, Accel X: %.2f, Accel Y: %.2f, Accel Z: %.2f\n",
                   imu_data[0], imu_data[1], imu_data[2], imu_data[3], imu_data[4], imu_data[5]);
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

