// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_value(int reg)
{
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            return (int16_t)((buf[0] << 8) | buf[1]);
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return 0; // Return 0 on failure
}

