#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
sensor_data_t read_imu_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ICM-20602
int init_imu() {
    // Wake up the sensor (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602\n");
        return -1;
    }
    return 0;
}

// Read accelerometer and gyroscope data from the ICM-20602
sensor_data_t read_imu_data() {
    sensor_data_t data;
    char buf[12];

    // Read accelerometer and gyroscope data in one burst
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12) < 0) {
        fprintf(stderr, "Error: Could not read IMU data\n");
        data.accel_x = data.accel_y = data.accel_z = 0;
        data.gyro_x = data.gyro_y = data.gyro_z = 0;
        return data;
    }

    // Combine high and low bytes for accelerometer data
    data.accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data.accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data.accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope data
    data.gyro_x = (int16_t)((buf[6] << 8) | buf[7]);
    data.gyro_y = (int16_t)((buf[8] << 8) | buf[9]);
    data.gyro_z = (int16_t)((buf[10] << 8) | buf[11]);

    return data;
}

// Log the sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

