#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D // Or 0x1C, check your sensor
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define GPIO_LED 17
#define THRESHOLD 2.0 // g
#define SENSITIVITY 0.000244 // g/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
void signal_handler(int signal);
int read_accelerometer_data(accelerometer_data_t *data);
float calculate_magnitude(accelerometer_data_t data);
void log_data(accelerometer_data_t data, float magnitude);
void control_led(int on);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID (example value, check datasheet)
    int sensor_id = i2cReadByteData(i2c_handle, 0x00); // Or 0x0D, check datasheet
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }
    if (sensor_id != 0x1A) { // Example ID, check datasheet
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Set to active mode, 800 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    float x_g = data.x * SENSITIVITY;
    float y_g = data.y * SENSITIVITY;
    float z_g = data.z * SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.4f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(GPIO_LED, on);
    gpioDelay(500); // 500 ms
    gpioWrite(GPIO_LED, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    accelerometer_data_t data;
    float magnitude;

    printf("Monitoring acceleration... Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_accelerometer_data(&data) == 0) {
            magnitude = calculate_magnitude(data);

            if (magnitude > THRESHOLD) {
                printf("Impact detected! Magnitude: %.4f g\n", magnitude);
                log_data(data, magnitude);
                control_led(1);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

