#define ADXL345_REG_INT_SOURCE 0x30

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.3

// Free-fall duration (in ms)
#define FREEFALL_DURATION 100

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// UDP server address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 5000

// Global variables
int i2c_handle;
int udp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
int detect_freefall();
int send_data(float x, float y, float z);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init() {
    // Set standby mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set standby mode.\n");
        return -1;
    }

    // Enable interrupts (optional)
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_INT_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Could not disable interrupts.\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to detect free-fall
int detect_freefall() {
    int freefall_count = 0;
    int freefall_active = 0;
    struct timespec start_time, current_time;
    long elapsed_time_ms;

    // Check for free-fall event
    if (i2cReadByteData(i2c_handle, ADXL345_REG_INT_SOURCE) & 0x10) {
        freefall_active = 1;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
    }

    while (freefall_active) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        if (elapsed_time_ms >= FREEFALL_DURATION) {
            freefall_count++;
        }

        if (elapsed_time_ms > FREEFALL_DURATION * 2) {
            freefall_active = 0;
        }

