    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid server address.\n");
        return -1;
    }

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Could not send data to server.\n");
        return -1;
    }

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    float x, y, z;

    if (level == 0) { // Interrupt triggered (assuming falling edge)
