        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Check for data availability on the event file descriptor
        event_fd = select(0, &fdset, NULL, NULL, NULL);

        if (event_fd > 0) {
            // Data is available on the event file descriptor
            // In a real application, you would read the event data here
