#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Scaling factors
#define ACCEL_SCALE 0.061  // mg/LSB for ±2g range
#define GYRO_SCALE 8.75   // mdps/LSB for ±250dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define FREEFALL_DURATION 1.0 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
    struct timespec timestamp;
    int state;
} sensor_data_t;

// Function prototypes
int init_i2c();
int check_who_am_i();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t *data);
void log_data(sensor_data_t *data);
void fall_detection_state_machine(sensor_data_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // Bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check WHO_AM_I register
int check_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F); // WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x69, got 0x%X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed!\n");
    return 0;
}

// Configure the LSM6DSR sensor
int configure_sensor() {
    // Accelerometer: ±2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Gyroscope: ±250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
