#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I   0x02
#define ADIS16266_SMPL_PRD   0x36
#define ADIS16266_GYRO_OUT   0x04

// SPI Configuration
#define SPI_CHANNEL         0
#define SPI_CE              8  // GPIO8 (BCM)
#define SPI_MODE            3
#define SPI_SPEED           1000000 // 1 MHz

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int verify_who_am_i(int handle);
float read_angular_rate(int handle);
void log_data(FILE *fp, float angular_rate);
void signal_handler(int signal);

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int ce;
    int mode;
    int speed;
} spi_config_t;


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_CE, SPI_MODE, SPI_SPEED};
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, spi_config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(spi_handle) != 0) {
        fprintf(stderr, "WHO_AM_I verification failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set sample period (optional, adjust as needed)
    if (spi_write_register(spi_handle, ADIS16266_SMPL_PRD, 0x0A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Angular Rate (deg/s)\n");

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float angular_rate = read_angular_rate(spi_handle);
        if (angular_rate != -1000.0) { // Assuming -1000.0 indicates an error
            log_data(log_file, angular_rate);
        } else {
            fprintf(stderr, "Failed to read angular rate\n");
        }
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t reg) {
    char tx_buf[2], rx_buf[2];
    int result;

    tx_buf[0] = reg | 0x80; // Set MSB to 1 for read operation
    tx_buf[1] = 0x00;       // Dummy byte

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    return ((int)rx_buf[0] << 8) | (int)rx_buf[1];
}

// Function to write a register in the ADIS16266
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    int result;

    tx_buf[0] = reg & 0x7F; // Set MSB to 0 for write operation
    tx_buf[1] = value;

    result = spiWrite(handle, tx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i(int handle) {
    int who_am_i = spi_read_register(handle, ADIS16266_WHO_AM_I);
    if (who_am_i != 0x5678) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I verification passed\n");
    return 0;
}

// Function to read the angular rate from the gyroscope
float read_angular_rate(int handle) {
    int raw_data = spi_read_register(handle, ADIS16266_GYRO_OUT);
    if (raw_data < 0) {
        return -1000.0; // Indicate error
    }
    return (float)raw_data * 0.0305; // Convert to degrees per second
}

// Function to log data to the CSV file
void log_data(FILE *fp, float angular_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f\n", timestamp, angular_rate);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

