#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the gyroscope
int initialize_gyro() {
    // Set the CTRL_REG1 register to enable the gyroscope and set the data rate
    // 0x0F = 0b00001111 (ODR = 100Hz, Cut-off = 12.5Hz, Enable X, Y, Z axes)
    char buf[2];
    buf[0] = CTRL_REG1;
    buf[1] = 0x0F;

    int retries = 3;
    while (retries > 0) {
        int result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d. Retrying...\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize gyro after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read the X, Y, and Z axis data
    int retries = 3;
    while (retries > 0) {
        int result = i2cReadDevice(i2c_handle, buffer, 6);
        if (result == 6) {
            // Combine high and low bytes for each axis
            raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert raw values to angular velocity (mdps)
            data.x = (float)raw_x / SENSITIVITY;
            data.y = (float)raw_y / SENSITIVITY;
            data.z = (float)raw_z / SENSITIVITY;
