#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int level = gpioRead(GPIO_PIN);
        if (level == PI_BAD_GPIO) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
            fprintf(log_file, "%s – Sensor read error\n", buf);
            fflush(log_file);
        } else {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

            if (level == 0) {
                fprintf(log_file, "%s – Flame detected: YES\n", buf);
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s – Flame detected: NO\n", buf);
            }
            fflush(log_file);
        }
        gpioDelay(500000); // 500ms
    }

    printf("Exiting gracefully...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    return 0;
}

