        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the sensor
acceleration_data_t read_acceleration_data() {
    acceleration_data_t data;
    char buffer[AXIS_BYTES];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X, buffer, AXIS_BYTES);
    if (result < 0) {
        fprintf(stderr, "Error reading X axis data: %d\n", result);
        data.x = 0; // Set to 0 to indicate error
    } else {
        data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    }

    // Read Y axis data
    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_Y, buffer, AXIS_BYTES);
    if (result < 0) {
        fprintf(stderr, "Error reading Y axis data: %d\n", result);
        data.y = 0; // Set to 0 to indicate error
    } else {
        data.y = (int16_t)((buffer[1] << 8) | buffer[0]);
    }

    // Read Z axis data
    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_Z, buffer, AXIS_BYTES);
    if (result < 0) {
        fprintf(stderr, "Error reading Z axis data: %d\n", result);
        data.z = 0; // Set to 0 to indicate error
    } else {
        data.z = (int16_t)((buffer[1] << 8) | buffer[0]);
    }

    return data;
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the data to a CSV file
int log_data(char *timestamp, acceleration_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        acceleration_data_t data = read_acceleration_data();

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log the data
        if (log_data(timestamp, data) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

