#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file;
    int sensor1_value, sensor2_value;
    struct timespec ts;
    char timestamp[30];
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        sensor1_value = gpioRead(SENSOR_1_GPIO);
        sensor2_value = gpioRead(SENSOR_2_GPIO);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break; // Exit loop on error
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + 19, 11, ".%03ld", ts.tv_nsec / 1000000); // Milliseconds

        // Log sensor data
        fprintf(log_file, "%s Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value);
        fflush(log_file); // Ensure data is written to file immediately

        // Check for halt condition
        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("HALT\n");
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

