#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MMA8452Q I2C address
#define MMA8452Q_ADDR 0x1D

// MMA8452Q registers
#define MMA8452Q_REG_STATUS 0x00
#define MMA8452Q_REG_OUT_X_MSB 0x01
#define MMA8452Q_REG_OUT_X_LSB 0x02
#define MMA8452Q_REG_OUT_Y_MSB 0x03
#define MMA8452Q_REG_OUT_Y_LSB 0x04
#define MMA8452Q_REG_OUT_Z_MSB 0x05
#define MMA8452Q_REG_OUT_Z_LSB 0x06
#define MMA8452Q_REG_SYSMOD 0x0B
#define MMA8452Q_REG_CTRL_REG1 0x2A
#define MMA8452Q_REG_CTRL_REG2 0x2B
#define MMA8452Q_REG_WHO_AM_I 0x0D

// Data rate setting
#define MMA8452Q_DATA_RATE 0x0A // 100 Hz

// Tilt threshold
#define TILT_THRESHOLD 45.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int init_mma8452q();
accelerometer_data_t read_accelerometer_data();
float calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_fall_data(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MMA8452Q sensor
int init_mma8452q() {
    int who_am_i;

    // Read WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, MMA8452Q_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    // Verify sensor identity
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, MMA8452Q_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    // Configure data rate
    if (i2cWriteByteData(i2c_handle, MMA8452Q_REG_CTRL_REG2, MMA8452Q_DATA_RATE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2 (data rate): %s\n", strerror(errno));
        return -1;
    }

    // Enable active mode
    if (i2cWriteByteData(i2c_handle, MMA8452Q_REG_CTRL_REG1, MMA8452Q_DATA_RATE | 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active mode): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, MMA8452Q_REG_OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 4;
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 4;
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 4;

    return data;
}

// Calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 1096.0; // Convert to g (assuming +/- 2g range)
    float y_g = (float)y / 1096.0;
    float z_g = (float)z / 1096.0;

    return atan2(sqrt(x_g * x_g + y_g * y_g), z_g) * 180.0 / M_PI;
}

// Log fall data to file
void log_fall_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MMA8452Q_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8452Q sensor
    if (init_mma8452q() < 0) {
        fprintf(stderr, "MMA8452Q initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float tilt_angle = calculate_tilt(data.x, data.y, data.z);

        if (tilt_angle > TILT_THRESHOLD) {
            log_fall_data(data);
            printf("Fall detected! Tilt angle: %.2f degrees\n", tilt_angle);
        }

        gpioDelay(10); // 10 ms delay for approximately 100 Hz
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

