int initialize_i2c();
int initialize_sensor();
sensor_data_t read_sensor_data();
void calibrate_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void check_metal_detector(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the LIS3MDL sensor
int initialize_sensor() {
    // Set data rate to 10 Hz and full scale to ±4 gauss
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) { // 0x70 = 01110000 (ODR = 10 Hz, FS = +/- 4 gauss)
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Enable continuous conversion mode
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) { // 0x00 = Continuous conversion mode
        fprintf(stderr, "Failed to write to CTRL_REG3\n");
        return -1;
    }

    // Set output polarity to positive
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00) < 0) { // 0x00 = +/- gauss
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read raw sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, and convert to signed 16-bit integer
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (float)x;
    data.y = (float)y;
    data.z = (float)z;

    return data;
}

// Calibrate raw data
void calibrate_data(sensor_data_t *data) {
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
    data->z -= Z_OFFSET;
    data->x *= X_SCALE;
    data->y *= Y_SCALE;
    data->z *= Z_SCALE;
}

// Log calibrated data to file
void log_data(sensor_data_t data) {
    fprintf(log_file, "%.2f,%.2f,%.2f\n", data.x, data.y, data.z);
    fflush(log_file);
}

// Check for metal detector threshold
void check_metal_detector(sensor_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detector alert! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Initialize sensor with retry mechanism
    int init_attempts = 0;
    while (initialize_sensor() < 0 && init_attempts < 3) {
        fprintf(stderr, "Retrying sensor initialization... (%d/3)\n", init_attempts + 1);
        init_attempts++;
        gpioDelay(1000); // Wait 1 second before retrying
    }

    if (init_attempts >= 3) {
        fprintf(stderr, "Failed to initialize sensor after multiple attempts. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Calibrate data
        calibrate_data(&data);

        // Log data
        log_data(data);

        // Check for metal detector
        check_metal_detector(data);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
