#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_PARTID         0x00
#define ADXL354B_RESET          0x01
#define ADXL354B_POWER_CTL      0x2D
#define ADXL354B_STATUS         0x2B
#define ADXL354B_XDATA_L        0x08
#define ADXL354B_XDATA_H        0x09
#define ADXL354B_YDATA_L        0x0A
#define ADXL354B_YDATA_H        0x0B
#define ADXL354B_ZDATA_L        0x0C
#define ADXL354B_ZDATA_H        0x0D

// SPI Configuration
#define SPI_CHANNEL            0
#define SPI_CE_PIN             8  // BCM GPIO 8
#define SPI_MODE               0
#define SPI_SPEED              1000000 // 1 MHz

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(uint8_t reg_addr, uint8_t data);
int adxl354b_reset();
int adxl354b_verify_partid();
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    memset(tx_buf + 1, 0, len);

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) == len + 1) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        }
        fprintf(stderr, "SPI read error, retrying...\n");
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Register Function
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 2) {
            return 0; // Success
        }
        fprintf(stderr, "SPI write error, retrying...\n");
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Reset Function
int adxl354b_reset() {
    if (spi_write_register(ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Verify PARTID Function
int adxl354b_verify_partid() {
    uint8_t partid;
    if (spi_read_register(ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (partid != 0x54) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    printf("ADXL354B PARTID verified: 0x%02X\n", partid);
    return 0;
}

// ADXL354B Read Acceleration Data Function
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (spi_read_register(ADXL354B_XDATA_L, &x_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_XDATA_H, &x_h, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_L, &y_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_H, &y_h, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_L, &z_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_H, &z_h, 1) != 0) return -1;

    *x = ((int16_t)x_h << 8) | x_l;
    *y = ((int16_t)y_h << 8) | y_l;
    *z = ((int16_t)z_h << 8) | z_l;

    return 0;
}

// Log Data Function
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ADXL354B Initialization
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_verify_partid() != 0) {
        fprintf(stderr, "ADXL354B PARTID verification failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

