#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define ADIS16362_REG_GYRO_XOUT 0x04
#define ADIS16362_REG_ACCEL_XOUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factors
#define GYRO_SCALE 0.05 // degrees/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function prototypes
int initialize_pigpio();
int open_spi_device();
int read_register(uint8_t address, int16_t *data);
imu_data_t process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z);
int log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the SPI device
int open_spi_device() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADIS16362
int read_register(uint8_t address, int16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Construct the transmit buffer: address (MSB first) + dummy byte
    tx_buffer[0] = (address << 1) | 0x80; // MSB is set for read
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buffer[0] << 8) | rx_buffer[1];

    return 0;
}

// Function to process raw data and convert to physical units
imu_data_t process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    imu_data_t data;

    data.gyro_x = gyro_x * GYRO_SCALE;
    data.gyro_y = gyro_y * GYRO_SCALE;
    data.gyro_z = gyro_z * GYRO_SCALE;
    data.accel_x = accel_x * ACCEL_SCALE;
    data.accel_y = accel_y * ACCEL_SCALE;
    data.accel_z = accel_z * ACCEL_SCALE;

    return data;
}

// Function to log data to a CSV file
int log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Format timestamp in seconds.nanoseconds
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    double timestamp_s = (double)ts.tv_sec;

    fprintf(log_file, "%lld,%lld,%lld,%lld,%lld,%lld,%lld\n",
            (long long)timestamp_s,
            (long long)data.gyro_x,
            (long long)data.gyro_y,
            (long long)data.gyro_z,
            (long long)data.accel_x,
            (long long)data.accel_y,
            (long long)data.accel_z);

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and file handles
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI device
    if (open_spi_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (read_register(ADIS16362_REG_GYRO_XOUT, &gyro_x) != 0) {
            fprintf(stderr, "Failed to read gyro X\n");
            continue; // Skip to the next iteration
        }
        if (read_register(ADIS16362_REG_GYRO_XOUT + 2, &gyro_y) != 0) {
            fprintf(stderr, "Failed to read gyro Y\n");
            continue;
        }
        if (read_register(ADIS16362_REG_GYRO_XOUT + 4, &gyro_z) != 0) {
            fprintf(stderr, "Failed to read gyro Z\n");
            continue;
        }

        // Read accelerometer data
        if (read_register(ADIS16362_REG_ACCEL_XOUT, &accel_x) != 0) {
            fprintf(stderr, "Failed to read accel X\n");
            continue;
        }
        if (read_register(ADIS16362_REG_ACCEL_XOUT + 2, &accel_y) != 0) {
            fprintf(stderr, "Failed to read accel Y\n");
            continue;
        }
        if (read_register(ADIS16362_REG_ACCEL_XOUT + 4, &accel_z) != 0) {
            fprintf(stderr, "Failed to read accel Z\n");
            continue;
        }

        // Process data
        imu_data_t imu_data = process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log data
        if (log_data(imu_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay for approximately 100 Hz
        gpioDelay(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

