#include <time.h>
#include <unistd.h>

#define GPIO_PIN 17
#define GPIO_CHIP 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
}

int main() {
    int status;
    int gpio_line;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_line = gpioOpen(GPIO_CHIP, GPIO_PIN, 0); // Open GPIO line for input
    if (gpio_line < 0) {
        fprintf(stderr, "Failed to open GPIO line %d on chip %d: %d\n", GPIO_PIN, GPIO_CHIP, gpio_line);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Self-parking sequence started\n");

    while (!terminate) {
        // Read sensor value
        int sensor_value = gpioRead(gpio_line);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %d\n", GPIO_PIN, sensor_value);
            break; // Exit loop on error
        }

        // Check for obstacle (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s: Obstacle detected! Self-parking sequence completed\n", timestamp);
            break; // Exit loop after obstacle detected
        }

        sleep(1); // Wait for 1 second
    }

    // Clean up and exit
    gpioClose(gpio_line);
    gpioTerminate();
    printf("pigpio terminated\n");
    return 0;
}

