#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    int sensor1_value, sensor2_value;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Read sensor values using bulk read
        sensor1_value = gpioRead(SENSOR1_PIN);
        sensor2_value = gpioRead(SENSOR2_PIN);

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Log sensor data with timestamp
        printf("%s - Sensor 1: %d, Sensor 2: %d\n", time_string, sensor1_value, sensor2_value);

        // Check for errors during GPIO read
        if (sensor1_value == PI_BAD_GPIO || sensor2_value == PI_BAD_GPIO)
        {
            fprintf(stderr, "Error reading GPIO pin\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

