// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz

// Global Variables
int spi_fd;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t address, uint8_t *data, int len);
float convert_to_deg_per_sec(int16_t raw_data);
void log_data(float x, float y, float z);
void signal_handler(int sig);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data;
        uint8_t x_data[2], y_data[2], z_data[2];

        // Read X gyroscope data
        if (spi_transfer(ADIS16266_XGYRO_OUT, x_data, 2) < 0) {
            fprintf(stderr, "Error reading X gyro data.\n");
            continue; // Continue to the next iteration
        }

        // Read Y gyroscope data
        if (spi_transfer(ADIS16266_YGYRO_OUT, y_data, 2) < 0) {
            fprintf(stderr, "Error reading Y gyro data.\n");
