// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Accelerometer and gyroscope scales
#define ACCEL_SCALE 0.061  // mg/LSB, for +/- 2g range
#define GYRO_SCALE 4.375   // mdps/LSB, for +/- 250 dps range

// I2C handle
int i2c_handle;

// Function prototypes
int init_i2c();
int configure_imu();
int read_imu_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
void print_imu_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the IMU
int configure_imu() {
    // Set accelerometer to +/- 2g and 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Failed to write to CTRL1_XL\n");
        return -1;
    }

    // Set gyroscope to +/- 250 dps and 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Failed to write to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read IMU data
int read_imu_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) != 12) {
        fprintf(stderr, "Failed to read IMU data\n");
        return -1;
    }

    // Combine high and low bytes for gyroscope data
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for accelerometer data
    raw_accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0f;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0f;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0f;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0f;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0f;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0f;

    return 0;
}

// Print IMU data
void print_imu_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure IMU
    if (configure_imu() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (1) {
        // Read IMU data
        if (read_imu_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print IMU data
            print_imu_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read IMU data in main loop\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    return 0;
}

