#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register from the FXOS8700
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadI2CBlockData(handle, reg, value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the FXOS8700
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteI2CBlockData(handle, reg, &value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the FXOS8700
int init_fxos8700(int handle) {
    // Set to active mode, 100 Hz ODR
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01 | (1 << 1)) != 0) {
        fprintf(stderr, "Error setting active mode\n");
        return -1;
    }

    // Set accelerometer range to +/-2g
    if (write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize FXOS8700
    if (init_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[12];
        int result;

        // Read 12 bytes of data
        result = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, (char *)data, 12);
        if (result != 12) {
            fprintf(stderr, "Error reading data: %d\n", result);
            // Retry after a short delay
            gpioDelay(10000); // 10ms
            continue;
        }

        // Extract accelerometer data
        int16_t acc_x = (data[0] << 6) | (data[1] >> 2);
        int16_t acc_y = (data[2] << 6) | (data[3] >> 2);
        int16_t acc_z = (data[4] << 6) | (data[5] >> 2);

        // Extract magnetometer data
        int16_t mag_x = (data[6] << 8) | data[7];
        int16_t mag_y = (data[8] << 8) | data[9];
        int16_t mag_z = (data[10] << 8) | data[11];

        // Print the data
        printf("AccX: %6d, AccY: %6d, AccZ: %6d, MagX: %6d, MagY: %6d, MagZ: %6d\n",
               acc_x, acc_y, acc_z, mag_x, mag_y, mag_z);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

