#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Scaling factor for +/- 2g range (10 bits)
#define SCALE_FACTOR 0.00390625

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_tilt_event(double angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize ADXL345
int init_adxl345() {
    // Set power control register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not write to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate tilt angle from acceleration data
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double angle_x = atan2(x * SCALE_FACTOR, sqrt(y * y + z * z)) * 180 / M_PI;
    double angle_y = atan2(y * SCALE_FACTOR, sqrt(x * x + z * z)) * 180 / M_PI;
    double angle_z = atan2(z * SCALE_FACTOR, sqrt(x * x + y * y)) * 180 / M_PI;

    // Consider only the angle around the X-axis for simplicity
    return angle_x;
}

// Log tilt event to file
void log_tilt_event(double angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double tilt_angle;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check if tilt exceeds threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

