#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define WINDOW_SIZE_US 5000000  // 5 seconds
#define MIN_THRESHOLD 0

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count = 0;
    int i;
    int gpio_status;

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring GPIO %d for %d seconds...\n", GPIO_PIN, threshold);

    while (!terminate) {
        high_count = 0;
        for (i = 0; i < (WINDOW_SIZE_US / SAMPLE_INTERVAL_US); i++) {
            gpio_status = gpioRead(GPIO_PIN);
            if (gpio_status < 0) {
                fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_status);
                break; // Exit loop on error
            }
            if (gpio_status == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d during window, exiting.\n", GPIO_PIN);
            break;
        }

        if (high_count > threshold) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s ALERT: High readings exceeded threshold (%d > %d)\n", timestamp, high_count, threshold);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Window %d: %d high readings (Threshold: %d)\n", timestamp, i + 1, high_count, threshold);
        }

        gpioDelay(1000000); // 1 second pause
    }

    // Terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

