#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the door locks
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the duration for which the door remains unlocked (in seconds)
#define UNLOCK_DURATION 5

// Define the range for the randomly generated security code
#define MIN_CODE 100000
#define MAX_CODE 999999

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to generate a random six-digit security code
int generate_security_code(int *code)
{
    // Use the random number generator to generate a random number between MIN_CODE and MAX_CODE
    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0; // Indicate success
}

// Function to unlock a door for a specified duration
int unlock_door(int gpio_pin, int duration_seconds)
{
    // Set the GPIO pin to HIGH to de-energize the relay and unlock the door
    gpioWrite(gpio_pin, 1);
    gpioDelay(duration_seconds * 1000000); // Delay for the specified duration (in microseconds)

    // Set the GPIO pin to LOW to re-energize the relay and lock the door
    gpioWrite(gpio_pin, 0);
    return 0;
}

// Function to log access attempts to a file
int log_access_attempt(const char *timestamp, int security_code, const char *status)
{
    FILE *fp = fopen("access_log.txt", "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening access_log.txt for writing!\n");
        return -1; // Indicate failure
    }

    fprintf(fp, "%s,%d,%s\n", timestamp, security_code, status);
    fclose(fp);
    return 0; // Indicate success
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Ensure both doors are locked (relays are energized) at startup
    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int security_code;
    char input_buffer[256]; // Buffer to store user input
    char *input_ptr;
    char *endptr;
    int user_input;

    // Main loop
    while (!terminate)
    {
        // Generate a new security code
        if (generate_security_code(&security_code) != 0)
        {
            fprintf(stderr, "Error generating security code!\n");
            continue; // Continue to the next iteration
        }

        // Print the generated security code to stdout
        printf("Security Code: %d\n", security_code);

        // Read user input from stdin
        input_ptr = fgets(input_buffer, sizeof(input_buffer), stdin);
        if (input_ptr == NULL)
        {
            fprintf(stderr, "Error reading from stdin!\n");
            continue; // Continue to the next iteration
        }

        // Clear the input buffer (consume any remaining characters)
        while (fgets(input_buffer, sizeof(input_buffer), stdin) != NULL)
        {
            // Do nothing, just consume the characters
        }

        // Convert the input string to an integer
        errno = 0; // Reset errno before calling strtol
        user_input = strtol(input_buffer, &endptr, 10);

        // Check for errors during conversion
        if (errno != 0 || endptr == input_buffer)
        {
            fprintf(stderr, "Invalid input! Please enter a six-digit number.\n");
            continue; // Continue to the next iteration
        }

        // Check if the input is within the valid range
        if (user_input < MIN_CODE || user_input > MAX_CODE)
        {
            fprintf(stderr, "Invalid input! Please enter a six-digit number between %d and %d.\n", MIN_CODE, MAX_CODE);
            continue; // Continue to the next iteration
        }

        // Check if the entered code matches the generated code
        if (user_input == security_code)
        {
            // Unlock Door A
            if (unlock_door(DOOR_A_GPIO, UNLOCK_DURATION) == 0)
            {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log the access attempt
                if (log_access_attempt(timestamp, security_code, "Granted") != 0)
                {
                    fprintf(stderr, "Error logging access attempt!\n");
                }
                else
                {
                    printf("Access Granted\n");
                }
            }
            else
            {
                fprintf(stderr, "Error unlocking Door A!\n");
            }

            // Unlock Door B
            if (unlock_door(DOOR_B_GPIO, UNLOCK_DURATION) == 0)
            {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

                time(&rawtime);
                timeinfo = localtime(&rawtime);
