#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and sensor address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define the measurement mode (High Resolution Mode)
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int init_i2c();
int read_illuminance(float *lux_value);
int log_data(float lux_value);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int running;
} program_state_t;

program_state_t state = {1}; // Initialize running to 1

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        state.running = 0; // Set running to 0 to exit the main loop
    }
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from the sensor
int read_illuminance(float *lux_value) {
    char config_mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];

    // Send the configuration command
    int write_result = i2cWriteByteData(i2c_handle, 0x00, config_mode);
    if (write_result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", write_result);
        return -1;
    }

    // Wait for the maximum conversion time (180ms)
    gpioDelay(180000); // Delay in microseconds

    // Read two bytes of data
    int read_result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (read_result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", read_result);
        return -1;
    }

    // Convert the data to lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux_value = (float)raw_value / 1.2;

    return 0;
}

// Log data to a file
int log_data(float lux_value) {
    FILE *fp = fopen("light_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Light sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (state.running) {
        float lux_value;

        if (read_illuminance(&lux_value) == 0) {
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading illuminance.\n");
        }

        gpioDelay(5000000); // Delay for 5 seconds (5000000 microseconds)
    }

    // Clean up
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

