#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define BUFFER_SIZE 1024
#define FREQUENCY_LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
int generate_frequency(unsigned short touch_data, int *frequency);
void play_tone(int frequency);
void stop_tone();
void log_frequency(int frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0C) < 0) return -1; // Touch Threshold
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x06) < 0) return -1; // Release Threshold
    }

    // Configure filter settings (example values)
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x10) < 0) return -1; // MHD_R
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) return -1; // NHD_R
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) return -1; // NCL_R
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x00) < 0) return -1; // FDL_R

    if (i2cWriteByteData(i2c_handle, 0x60, 0x10) < 0) return -1; // MHD_T
    if (i2cWriteByteData(i2c_handle, 0x61, 0x01) < 0) return -1; // NHD_T
    if (i2cWriteByteData(i2c_handle, 0x62, 0x01) < 0) return -1; // NCL_T
    if (i2cWriteByteData(i2c_handle, 0x63, 0x00) < 0) return -1; // FDL_T

    if (i2cWriteByteData(i2c_handle, 0x64, 0x01) < 0) return -1; // MHD_D
    if (i2cWriteByteData(i2c_handle, 0x65, 0x00) < 0) return -1; // NHD_D
    if (i2cWriteByteData(i2c_handle, 0x66, 0x00) < 0) return -1; // NCL_D
    if (i2cWriteByteData(i2c_handle, 0x67, 0x00) < 0) return -1; // FDL_D

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x3F) < 0) return -1; // ELE_EN

    // Enter Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) return -1; // ELE_EN

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Generate frequency based on touch data
int generate_frequency(unsigned short touch_data, int *frequency) {
    // Simple mapping: frequency = 1000 + (touch_data * 50)
    *frequency = 1000 + (touch_data * 50);
    if (*frequency > 2000) *frequency = 2000; // Limit frequency
    return 0;
}

// Play tone on GPIO18
void play_tone(int frequency) {
    gpioSetPWMfrequency(GPIO_PWM, frequency);
    gpioPWM(GPIO_PWM, 128); // 50% duty cycle
}

// Stop tone on GPIO18
void stop_tone() {
    gpioPWM(GPIO_PWM, 0);
}

// Log frequency to file
void log_frequency(int frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }

    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        // Extract shared secret
        char *secret_start = strstr(buffer, "MySecretKey");
        if (secret_start != NULL) {
            secret_start += strlen("MOTION_DETECTED:MySecretKey");
            char shared_secret[256];
            strncpy(shared_secret, secret_start, 255);
            shared_secret[255] = '\0'; // Ensure null termination

            // Check if the shared secret matches
            if (strcmp(shared_secret, "MySecretKey") == 0) {
                printf("Shared secret matched!\n");

                // Initialize pigpio
                if (gpioInitialise() < 0) {
                    fprintf(stderr, "Error: pigpio initialisation failed\n");
                    close(client_socket);
                    return;
                }

                // Open I2C interface
                i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Failed to open I2C interface\n");
                    gpioTerminate();
                    close(client_socket);
                    return;
                }

                // Initialize MPR121
                if (init_mpr121() < 0) {
                    fprintf(stderr, "Error: MPR121 initialisation failed\n");
                    i2cClose(i2c_handle);
                    gpioTerminate();
                    close(client_socket);
                    return;
                }

                // Configure GPIO18 as PWM output
                gpioSetMode(GPIO_PWM, PI_OUTPUT);

                // Open log file
                log_file = fopen(FREQUENCY_LOG_FILE, "a");
                if (log_file == NULL) {
                    fprintf(stderr, "Error: Failed to open log file\n");
                    i2cClose(i2c_handle);
                    gpioTerminate();
                    close(client_socket);
                    return;
                }

                // Play tone for 5 seconds
                int frequency;
                unsigned short touch_data;
                while (!terminate) {
                    if (read_touch_data(&touch_data) == 0) {
                        generate_frequency(touch_data, &frequency);
                        play_tone(frequency);
                        log_frequency(frequency);
                    } else {
                        fprintf(stderr, "Error reading touch data, exiting loop.\n");
                        break;
                    }
                    gpioDelay(20000); // 20ms delay
                }

                // Stop tone
                stop_tone();

                // Clean up
                fclose(log_file);
                i2cClose(i2c_handle);
                gpioTerminate();
            } else {
                fprintf(stderr, "Error: Shared secret mismatch\n");
            }
        } else {
            fprintf(stderr, "Error: Could not find shared secret\n");
        }
    } else {
        fprintf(stderr, "Error: Invalid command\n");
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections
    while (!terminate) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening even if accept fails
        }

        printf("Connection accepted\n");
        handle_client(new_socket);
    }

    // Clean up
    close(server_fd);
    return 0;
}

