#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define LSM303_ADDR_1 0x1E
#define LSM303_ADDR_2 0x1D
#define LSM303_REG_OUT_X_L_M 0x08
#define LSM303_REG_CTRL_REG1_M 0x20
#define LSM303_REG_CTRL_REG3_M 0x22
#define LSM303_REG_MR_REG_M 0x24
#define LSM303_REG_OUT_Z_H_M 0x0A
#define LED_PIN 17 // BCM GPIO 17
#define PWM_RANGE 1024
#define SAMPLE_INTERVAL_MS 100

// Global variables
int fd1 = -1; // I2C file descriptor for sensor 1
int fd2 = -1; // I2C file descriptor for sensor 2
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int init_magnetometer(int fd);
int16_t read_magnetometer_data(int fd, int reg);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(float magnitude);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Stop PWM
    pwmWrite(LED_PIN, 0);

    // Close I2C file descriptors
    if (fd1 != -1) {
        close(fd1);
    }
    if (fd2 != -1) {
        close(fd2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize the LSM303 magnetometer
int init_magnetometer(int fd) {
    // Set CTRL_REG1 to 0x70 (Continuous conversion, 50 Hz, normal measurement)
    if (wiringPiI2CWriteReg8(fd, LSM303_REG_CTRL_REG1_M, 0x70) < 0) {
        log_error("Failed to write to CTRL_REG1_M");
        return -1;
    }

    // Set CTRL_REG3 to 0x00 (Continuous conversion mode)
    if (wiringPiI2CWriteReg8(fd, LSM303_REG_CTRL_REG3_M, 0x00) < 0) {
        log_error("Failed to write to CTRL_REG3_M");
        return -1;
    }

    // Set MR_REG to 0x00 (Continuous conversion mode)
    if (wiringPiI2CWriteReg8(fd, LSM303_REG_MR_REG_M, 0x00) < 0) {
        log_error("Failed to write to MR_REG_M");
        return -1;
    }

    return 0;
}

// Read magnetometer data from a specific register
int16_t read_magnetometer_data(int fd, int reg) {
    int16_t low = wiringPiI2CReadReg8(fd, reg);
    int16_t high = wiringPiI2CReadReg8(fd, reg + 1);

    if (low < 0 || high < 0) {
        log_error("Failed to read magnetometer data");
        return 0; // Return 0 on error
    }

    return (high << 8) | low;
}

// Calculate the magnitude of the magnetic field vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return (float)sqrt(x * x + y * y + z * z);
}

// Set the LED brightness using PWM
void set_led_brightness(float magnitude) {
    int duty_cycle = (int)((magnitude / 100.0) * PWM_RANGE); // Assuming max magnitude is 100 uT
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    pwmWrite(LED_PIN, duty_cycle);
}

// Log errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] Error: %s (errno: %d)\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message, errno);
    fflush(log_file);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C for both sensors
    fd1 = wiringPiI2CSetup(LSM303_ADDR_1);
    if (fd1 == -1) {
        log_error("Failed to initialize I2C for sensor 1");
        fprintf(stderr, "Failed to initialize I2C for sensor 1!\n");
        fclose(log_file);
        return 1;
    }

    fd2 = wiringPiI2CSetup(LSM303_ADDR_2);
    if (fd2 == -1) {
        log_error("Failed to initialize I2C for sensor 2");
        fprintf(stderr, "Failed to initialize I2C for sensor 2!\n");
        close(fd1);
        fclose(log_file);
        return 1;
    }

    // Initialize magnetometers
    if (init_magnetometer(fd1) == -1 || init_magnetometer(fd2) == -1) {
        fprintf(stderr, "Magnetometer initialization failed!\n");
        close(fd1);
        close(fd2);
        fclose(log_file);
        return 1;
    }

    // Configure LED pin as PWM output
    pinMode(LED_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read data from sensor 1
        int16_t x1 = read_magnetometer_data(fd1, LSM303_REG_OUT_X_L_M);
        int16_t y1 = read_magnetometer_data(fd1, LSM303_REG_OUT_X_L_M + 2);
        int16_t z1 = read_magnetometer_data(fd1, LSM303_REG_OUT_Z_H_M);

        // Read data from sensor 2
        int16_t x2 = read_magnetometer_data(fd2, LSM303_REG_OUT_X_L_M);
        int16_t y2 = read_magnetometer_data(fd2, LSM303_REG_OUT_X_L_M + 2);
        int16_t z2 = read_magnetometer_data(fd2, LSM303_REG_OUT_Z_H_M);

        // Calculate magnitudes
        float magnitude1 = calculate_magnitude(x1, y1, z1);
        float magnitude2 = calculate_magnitude(x2, y2, z2);

        // Calculate average magnitude
        float average_magnitude = (magnitude1 + magnitude2) / 2.0;

        // Set LED brightness
        set_led_brightness(average_magnitude);

        // Delay for sample interval
        delay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    pwmWrite(LED_PIN, 0);
    close(fd1);
    close(fd2);
    fclose(log_file);

    return 0;
}

