#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x19

// LSM303D register addresses
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D

// Sensitivity (mg/LSB)
#define SENSITIVITY 0.061

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_handle;
bool running = true;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer acc_buffer;

// Function prototypes
int init_i2c();
int init_lsm303d();
int read_acceleration(float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *cb, float value);
float get_from_buffer(CircularBuffer *cb, int index);
void dump_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get a value from the circular buffer
float get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return 0.0;
    }
    int actual_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[actual_index];
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize LSM303D
int init_lsm303d() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, 0x0F); // Address 0x0F contains the WHO_AM_I register
    if (device_id < 0) {
        fprintf(stderr, "Error: Could not read device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != 0x49) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure accelerometer: 100Hz, enable all axes
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, LSM303D_OUT_X_L_A | 0x80, raw_data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer, and scale
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;

    return 0;
}

// Dump the last ten samples from the circular buffer
void dump_buffer() {
    printf("Timestamp: %ld\n", time(NULL));
    for (int i = 0; i < 10; i++) {
        float sample = get_from_buffer(&acc_buffer, i);
        printf("  Sample %d: X=%.2f, Y=%.2f, Z=%.2f\n", i, sample, sample, sample);
    }
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        dump_buffer();
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("Exiting...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&acc_buffer);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(23, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            add_to_buffer(&acc_buffer, x);
            add_to_buffer(&acc_buffer, y);
            add_to_buffer(&acc_buffer, z);
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data\n");
        }

        gpioDelay(10); // 10ms delay
    }

    // Disable accelerometer
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x00) < 0) {
        fprintf(stderr, "Error: Could not disable accelerometer: %s\n", strerror(errno));
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

