#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Function prototypes
int initialize_gpio();
void actuate_solenoid(int gpio);
void deactuate_solenoid(int gpio);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track the current solenoid
int current_solenoid = 0;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to alternately actuate solenoids
    while (1) {
        if (current_solenoid == 0) {
            actuate_solenoid(SOLENOID_1_GPIO);
            deactuate_solenoid(SOLENOID_2_GPIO);
            current_solenoid = 1;
        } else {
            actuate_solenoid(SOLENOID_2_GPIO);
            deactuate_solenoid(SOLENOID_1_GPIO);
            current_solenoid = 0;
        }

        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0; // This line will never be reached due to the infinite loop
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Deactuate both solenoids before the main loop
    deactuate_solenoid(SOLENOID_1_GPIO);
    deactuate_solenoid(SOLENOID_2_GPIO);

    return 0;
}

// Function to actuate a solenoid
void actuate_solenoid(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
    }
    printf("Solenoid on GPIO %d actuated\n", gpio);
}

// Function to deactuate a solenoid
void deactuate_solenoid(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
    }
    printf("Solenoid on GPIO %d deactuated\n", gpio);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
