#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define UART_DEVICE "/dev/serial0"
#define SECONDARY_UART_DEVICE "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_MS 5000
#define RELAY_ON_TIME_MS 2000
#define MAX_CODE_LENGTH 6

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
int secondary_uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);

    return 0;
}

int initialize_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        perror("Error setting baud rate");
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_serial_port(int fd, char *buffer, int buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval) {
        int bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            return bytes_read;
        } else if (bytes_read == -1) {
            perror("read() error");
            return -1;
        } else {
            return 0; // No data read
        }
    } else {
        return 0; // Timeout
    }
}

int validate_code(const char *code) {
    if (strlen(code) != MAX_CODE_LENGTH) {
        return 0;
    }

    for (int i = 0; i < MAX_CODE_LENGTH; i++) {
        if (code[i] < '0' || code[i] > '9') {
            return 0;
        }
    }

    return 1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    uart_fd = initialize_uart(UART_DEVICE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    secondary_uart_fd = initialize_uart(SECONDARY_UART_DEVICE);
    if (secondary_uart_fd == -1) {
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    char primary_code[MAX_CODE_LENGTH + 1];
    char secondary_code[MAX_CODE_LENGTH + 1];
    int primary_code_index = 0;
    int secondary_code_index = 0;

    printf("Authenticating...\n");

    while (program_running) {
        int primary_read_result = read_serial_port(uart_fd, primary_code + primary_code_index, MAX_CODE_LENGTH - primary_code_index + 1);
        if (primary_read_result > 0) {
            primary_code[primary_code_index + primary_read_result] = '\0';
            primary_code_index += primary_read_result;

            if (validate_code(primary_code)) {
                printf("Primary code received: %s\n", primary_code);
                secondary_code_index = 0; // Reset secondary code index
                continue;
            } else {
                primary_code_index = 0; // Reset primary code index
                fprintf(stderr, "Invalid primary code received.\n");
            }
        } else if (primary_read_result < 0) {
            fprintf(stderr, "Error reading from primary UART.\n");
            break;
        }

        int secondary_read_result = read_serial_port(secondary_uart_fd, secondary_code + secondary_code_index, MAX_CODE_LENGTH - secondary_code_index + 1);
        if (secondary_read_result > 0) {
            secondary_code[secondary_code_index + secondary_read_result] = '\0';
            secondary_code_index += secondary_read_result;

            if (validate_code(secondary_code)) {
                printf("Secondary code received: %s\n", secondary_code);
                if (strcmp(primary_code, secondary_code) == 0 && strcmp(primary_code, "123456") == 0) {
                    printf("Authentication successful!\n");
                    gpioWrite(RELAY1_GPIO, 1);
                    gpioWrite(RELAY2_GPIO, 1);
                    gpioDelay(RELAY_ON_TIME_MS * 1000); // Delay in microseconds
                    gpioWrite(RELAY1_GPIO, 0);
                    gpioWrite(RELAY2_GPIO, 0);
                    printf("Door unlocked and relocks.\n");
                } else {
                    fprintf(stderr, "Codes do not match or do not match expected code.\n");
                }
                secondary_code_index = 0; // Reset secondary code index
            } else {
                secondary_code_index = 0; // Reset secondary code index
                fprintf(stderr, "Invalid secondary code received.\n");
            }
        } else if (secondary_read_result < 0) {
            fprintf(stderr, "Error reading from secondary UART.\n");
            break;
        }
    }

    printf("Cleaning up...\n");

    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);

    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (secondary_uart_fd != -1) {
        close(secondary_uart_fd);
    }

    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

