#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1  // seconds
#define FAILSAFE_TIMEOUT 10 // seconds
#define POLL_INTERVAL 50 // milliseconds

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_relay();
int deactivate_relay();
int log_event(int priority, const char *message);
void signal_handler(int signal);

int main() {
    // Open syslog for logging
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read PIR sensor
        if (read_pir_sensor() == 1) {
            // Motion detected
            log_event(LOG_INFO, "Motion detected!");

            // Activate relay
            if (activate_relay() != 0) {
                syslog(LOG_ERR, "Relay activation failed.");
            }

            // Wait for relay to deactivate
            gpioDelay(RELAY_ON_TIME * 1000000); // Convert seconds to microseconds

            // Deactivate relay
            if (deactivate_relay() != 0) {
                syslog(LOG_ERR, "Relay deactivation failed.");
            }

            // Check for failsafe timeout
            gpioDelay(FAILSAFE_TIMEOUT * POLL_INTERVAL * 1000); // Check every poll interval

            if (read_pir_sensor() == 1) {
                log_event(LOG_WARNING, "PIR sensor continuously HIGH for "
                         "more than "
                         "10 seconds. Potential malfunction.");
                log_event(LOG_CRIT, "Shutting down due to PIR sensor malfunction.");
                program_running = 0; // Stop the main loop
            }
        }

        // Poll interval
        gpioDelay(POLL_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    // Clean up GPIO and close syslog before exiting
    gpioTerminate();
    closelog();

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set PIR sensor pin as input
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);

    // Set Relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate relay
int activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to relay pin");
        return 1;
    }
    log_event(LOG_INFO, "Relay activated");
    return 0;
}

// Function to deactivate relay
int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write to relay pin");
        return 1;
    }
    log_event(LOG_INFO, "Relay deactivated");
    return 0;
}

// Function to log events to syslog
int log_event(int priority, const char *message) {
    syslog(priority, message);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");

    // Ensure relay is off
    deactivate_relay();

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

