#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Circular buffer size
#define BUFFER_SIZE 10

// Global variables
int i2c_fd;
int buffer_index = 0;
int16_t accel_x[BUFFER_SIZE];
int16_t accel_y[BUFFER_SIZE];
int16_t accel_z[BUFFER_SIZE];

// Function prototypes
int init_i2c(int address);
int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void update_circular_buffer(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int write_to_sysfs(const char *path, const char *value);
void signal_handler(int sig);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c(MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    struct timespec req = {0};
    req.tv_sec = 0;
    req.tv_nsec = 10000000; // 100 Hz (10 ms)

    while (1) {
        // Read accelerometer data
        if (read_accel_data(&accel_x[buffer_index], &accel_y[buffer_index], &accel_z[buffer_index]) < 0) {
            fprintf(stderr, "Failed to read accelerometer data. Continuing.\n");
            continue;
        }

        // Update circular buffer
        update_circular_buffer(accel_x[buffer_index], accel_y[buffer_index], accel_z[buffer_index]);

        // Write to sysfs
        char path[64];
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_x");
        if (write_to_sysfs(path, "0") < 0) {
            fprintf(stderr, "Failed to write to sysfs. Continuing.\n");
        }
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_y");
        if (write_to_sysfs(path, "0") < 0) {
            fprintf(stderr, "Failed to write to sysfs. Continuing.\n");
        }
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_z");
        if (write_to_sysfs(path, "0") < 0) {
            fprintf(stderr, "Failed to write to sysfs. Continuing.\n");
        }

        // Sleep for the remaining time
        nanosleep(&req, NULL);
    }

    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Wake up the MPU6050
    uint8_t data = 0; // Value to write to PWR_MGMT_1 register
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t buffer[6];

    // Read 6 bytes of data (X, Y, Z axis)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update circular buffer
void update_circular_buffer(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    accel_x[buffer_index] = accel_x;
    accel_y[buffer_index] = accel_y;
    accel_z[buffer_index] = accel_z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Write to sysfs
int write_to_sysfs(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening sysfs file");
        return -1;
    }

    if (fprintf(fp, "%s", value) < 0) {
        perror("Error writing to sysfs file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);

    // Close I2C device
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Remove sysfs files
    char path[64];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_x");
    remove(path);
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_y");
    remove(path);
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest_z");
    remove(path);

    exit(0);
}

