#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the prime number intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to toggle a relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, current_state);
        return;
    }
    int new_state = (current_state == 0) ? 1 : 0;
    if (gpioWrite(gpio_pin, new_state) != 0) {
        fprintf(stderr, "Error writing to GPIO pin %d\n", gpio_pin);
    }
    printf("Relay on GPIO %d toggled to state %d\n", gpio_pin, new_state);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Toggle relay 1
        toggle_relay(RELAY1_PIN);
        // Wait for 2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = INTERVAL1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Toggle relay 2
        toggle_relay(RELAY2_PIN);
        // Wait for 3 seconds
        sleep_time.tv_sec = INTERVAL2;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Toggle relay 3
        toggle_relay(RELAY3_PIN);
        // Wait for 5 seconds
        sleep_time.tv_sec = INTERVAL3;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Toggle relay 4
        toggle_relay(RELAY4_PIN);
        // Wait for 7 seconds
        sleep_time.tv_sec = INTERVAL4;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Turn off all relays before exiting
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

