#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pthread.h>
#include <syslog.h>
#include <stdarg.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define TIMEOUT_MS 100
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5
#define MAX_BUFFER_SIZE 256

// MH-Z19B Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x44, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
#define CMD_READ_MEASUREMENT 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00

// Global Variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *co2_log_fp = NULL;
FILE *error_log_fp = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
int uart_init(const char *device, speed_t baud_rate);
int uart_write(int fd, const unsigned char *data, size_t length);
int uart_read(int fd, unsigned char *buffer, size_t length);
int read_co2_data(int fd, unsigned char *buffer, size_t length);
int validate_checksum(const unsigned char *data);
int parse_co2_data(const unsigned char *data, int *co2_ppm);
int log_co2_data(FILE *fp, int co2_ppm, int error_flag);
void log_error(const char *format, ...);
void signal_handler(int signum);
void *data_processing_thread(void *arg);

// Helper function to get current timestamp in microseconds
long long get_timestamp_us() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL);
}

int main() {
    openlog("co2_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        log_error("Failed to initialize UART. Exiting.");
        closelog();
        return 1;
    }

    // Open Log Files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        log_error("Failed to open CO2 log file. Exiting.");
        close(uart_fd);
        closelog();
        return 1;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        log_error("Failed to open error log file. Exiting.");
        fclose(co2_log_fp);
        close(uart_fd);
        closelog();
        return 1;
    }

    // Start Periodic Measurement
    if (uart_write(uart_fd, CMD_START_PERIODIC_MEASUREMENT, sizeof(CMD_START_PERIODIC_MEASUREMENT)) != sizeof(CMD_START_PERIODIC_MEASUREMENT)) {
        log_error("Failed to send start periodic measurement command.");
        fclose(co2_log_fp);
        fclose(error_log_fp);
        close(uart_fd);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Started periodic measurement.");

    // Data Processing Thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_processing_thread, NULL) != 0) {
        log_error("Failed to create data processing thread.");
        fclose(co2_log_fp);
        fclose(error_log_fp);
        close(uart_fd);
        closelog();
        return 1;
    }

    // Main Loop (Sleep to allow thread to process data)
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup
    pthread_join(thread_id, NULL);
    fclose(co2_log_fp);
    fclose(error_log_fp);
    close(uart_fd);
    closelog();

    return 0;
}

void *data_processing_thread(void *arg) {
    unsigned char buffer[9];
    int co2_ppm;
    int error_flag = 0;
    long long timestamp;

    while (program_running) {
        // Read CO2 data
        if (read_co2_data(uart_fd, buffer, sizeof(buffer)) == sizeof(buffer)) {
            // Validate checksum
            if (validate_checksum(buffer)) {
                // Parse CO2 data
                if (parse_co2_data(buffer, &co2_ppm) == 0) {
                    // Log CO2 data
                    timestamp = get_timestamp_us();
                    if (log_co2_data(co2_log_fp, co2_ppm, 0) != 0) {
                        log_error("Failed to log CO2 data.");
                        error_flag = 1;
                    }
                    printf("{\"timestamp\":%lld,\"co2_ppm\":%d,\"error_flag\":0}\n", timestamp, co2_ppm);
                    fflush(co2_log_fp);
                } else {
