#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00

// Global Variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *co2_log_fp = NULL;
FILE *error_log_fp = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

