#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Hard iron offsets
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to store magnetometer data and timestamp
typedef struct {
    time_t timestamp;
    float heading;
} magnetometer_data_t;

// Circular buffer
magnetometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron_compensation(float heading, int16_t x, int16_t y);
void store_heading(float heading);
float calculate_deviation(float current_heading);
void set_gpio_output(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Calculate heading from magnetometer data
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard iron compensation
float apply_hard_iron_compensation(float heading, int16_t x, int16_t y) {
    float compensated_x = x - HARD_IRON_X_OFFSET;
    float compensated_y = y - HARD_IRON_Y_OFFSET;
    float compensated_heading = atan2(compensated_y, compensated_x) * 180 / M_PI;
    if (compensated_heading < 0) {
        compensated_heading += 360;
    }
    return compensated_heading;
}

// Store heading in circular buffer
void store_heading(float heading) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate deviation from target heading
float calculate_deviation(float current_heading) {
    float deviation = fabs(current_heading - TARGET_HEADING);
    if (deviation > 180.0) {
        deviation = 360.0 - deviation;
    }
    return deviation;
}

// Set GPIO output
void set_gpio_output(int state) {
    gpioWrite(GPIO_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, compensated_heading, deviation;
    int retry_count;

    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < 3) {
            if (read_magnetometer(&x, &y, &z) == 0) {
                break;
            } else {
                fprintf(stderr, "I2C read error, retrying...\n");
                gpioDelay(10); // Wait 10ms before retrying
                retry_count++;
            }
        }

        if (retry_count >= 3) {
            fprintf(stderr, "Failed to read magnetometer after multiple retries\n");
            continue; // Skip to the next iteration
        }

        heading = calculate_heading(x, y);
        compensated_heading = apply_hard_iron_compensation(heading, x, y);
        store_heading(compensated_heading);
        deviation = calculate_deviation(compensated_heading);

        set_gpio_output(deviation > 10.0 ? 1 : 0);

        printf("Heading: %.2f, Deviation: %.2f\n", compensated_heading, deviation);

        gpioDelay(100); // Sample at 100ms interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

