#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define sensor addresses
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x24
#define BH1750_ADDR_3 0x25

// Define GPIO pins for RGB lamp channels
#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

// Define lux thresholds
#define LUX_THRESHOLD_RED   50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE  300

// Define I2C bus
#define I2C_BUS 1

// Global variables
int fd1 = -1, fd2 = -1, fd3 = -1; // I2C file descriptors
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int init_sensor(int address);
int read_lux(int fd);
void control_lamp(int lux);
void log_data(int lux1, int lux2, int lux3, int red_state, int green_state, int blue_state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = false;

    // Turn off all relays
    digitalWrite(RED_PIN, LOW);
    digitalWrite(GREEN_PIN, LOW);
    digitalWrite(BLUE_PIN, LOW);

    // Close I2C file descriptors
    if (fd1 != -1) close(fd1);
    if (fd2 != -1) close(fd2);
    if (fd3 != -1) close(fd3);

    // Close log file
    if (log_file != NULL) fclose(log_file);

    wiringPiSetupGpio(); // Reset GPIO pins to input mode

    exit(0);
}

// Initialize a BH1750 sensor
int init_sensor(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing sensor at address 0x%02x: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// Read lux value from a BH1750 sensor
int read_lux(int fd) {
    if (wiringPiI2CWrite(fd, 0x10) == -1) { // Start measurement in high resolution mode
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    delay(120); // Wait for measurement
    int msb = wiringPiI2CReadReg8(fd, 0x00);
    int lsb = wiringPiI2CReadReg8(fd, 0x01);
    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    int lux = (msb << 8 | lsb) / 1.2;
    return lux;
}

// Control the RGB lamp based on lux value
void control_lamp(int lux) {
    int red_state = LOW, green_state = LOW, blue_state = LOW;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = HIGH;
    } else if (lux >= LUX_THRESHOLD_RED && lux < LUX_THRESHOLD_GREEN) {
        red_state = LOW;
        green_state = HIGH;
    } else if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
        red_state = LOW;
        green_state = LOW;
        blue_state = HIGH;
    } else {
        red_state = HIGH;
        green_state = HIGH;
        blue_state = HIGH;
    }

    digitalWrite(RED_PIN, red_state);
    digitalWrite(GREEN_PIN, green_state);
    digitalWrite(BLUE_PIN, blue_state);
}

// Log data to file
void log_data(int lux1, int lux2, int lux3, int red_state, int green_state, int blue_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Lux1: %d, Lux2: %d, Lux3: %d, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux1, lux2, lux3, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as output
    pinMode(RED_PIN, OUTPUT);
    pinMode(GREEN_PIN, OUTPUT);
    pinMode(BLUE_PIN, OUTPUT);

    // Initialize I2C sensors
    fd1 = init_sensor(BH1750_ADDR_1);
    fd2 = init_sensor(BH1750_ADDR_2);
    fd3 = init_sensor(BH1750_ADDR_3);

    if (fd1 == -1 || fd2 == -1 || fd3 == -1) {
        fprintf(stderr, "Failed to initialize one or more sensors. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (running) {
        // Read lux values from sensors
        int lux1 = read_lux(fd1);
        int lux2 = read_lux(fd2);
        int lux3 = read_lux(fd3);

        // Check for errors during sensor reading
        if (lux1 == -1 || lux2 == -1 || lux3 == -1) {
            fprintf(stderr, "Error reading from one or more sensors. Skipping this iteration.\n");
            delay(1000);
            continue;
        }

        // Control the RGB lamp
        control_lamp(lux1);

        // Log the data
        int red_state = digitalRead(RED_PIN);
        int green_state = digitalRead(GREEN_PIN);
        int blue_state = digitalRead(BLUE_PIN);
        log_data(lux1, lux2, lux3, red_state, green_state, blue_state);

        // Wait for 1 second
        delay(1000);
    }

    cleanup(0);
    return 0;
}

