#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Define GPIO pins for Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define distance range for simulation (10-100 cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Define distance threshold for forward/backward direction (50 cm)
#define DISTANCE_THRESHOLD 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, stopping motors and exiting...\n");
        program_running = 0;
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_motor_speed(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
    }
}

// Function to stop a motor by setting the PWM duty cycle to 0
void stop_motor(int gpio_pin) {
    if (gpioPWM(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error stopping motor on GPIO %d\n", gpio_pin);
    }
}

int main(int argc, char *argv[]) {
    int distance;
    int duty_cycle;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR_A_IN1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR_B_IN3);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR_B_IN4);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for IN2 and IN4
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_A_IN4, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR_A_IN4);
        gpioTerminate();
        return 1;
    }

    // Set PWM range for IN2 and IN4
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(MOTOR_A_IN4, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", MOTOR_A_IN4);
        gpioTerminate();
        return 1;
    }

    // Main control loop
    while (program_running) {
        // Simulate distance reading for Motor A
        distance = (rand() % (MAX_DISTANCE - MIN_DISTANCE + 1)) + MIN_DISTANCE;

        // Calculate duty cycle based on distance (proportional control)
        duty_cycle = (distance < DISTANCE_THRESHOLD) ? (distance * 2) : (255 - (distance * 2));

        // Set motor speed based on duty cycle
        if (distance < DISTANCE_THRESHOLD) {
            // Forward direction
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
            set_motor_speed(MOTOR_A_IN2, duty_cycle);
        } else {
            // Backward direction
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 1);
            set_motor_speed(MOTOR_A_IN2, duty_cycle);
        }

        // Simulate distance reading for Motor B
        distance = (rand() % (MAX_DISTANCE - MIN_DISTANCE + 1)) + MIN_DISTANCE;

        // Calculate duty cycle based on distance (proportional control)
        duty_cycle = (distance < DISTANCE_THRESHOLD) ? (distance * 2) : (255 - (distance * 2));

        // Set motor speed based on duty cycle
        if (distance < DISTANCE_THRESHOLD) {
            // Forward direction
            gpioWrite(MOTOR_B_IN3, 1);
            gpioWrite(MOTOR_B_IN4, 0);
            set_motor_speed(MOTOR_B_IN4, duty_cycle);
        } else {
            // Backward direction
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 1);
            set_motor_speed(MOTOR_B_IN4, duty_cycle);
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors
    stop_motor(MOTOR_A_IN2);
    stop_motor(MOTOR_A_IN4);
    stop_motor(MOTOR_B_IN4);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

