#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Servo GPIO pin
#define SERVO_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 50

// PWM range (microseconds)
#define PWM_RANGE 2000

// Servo pulse widths for 0 and 180 degrees
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_mpu6050_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
void calculate_pitch_roll(float accel_x, float accel_y, float accel_z, float *pitch, float *roll);
int set_servo_angle(float angle);
int log_data(float pitch, float roll, float position);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read accelerometer and gyroscope data from MPU-6050
int read_mpu6050_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buf[14];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (result != 14) {
        fprintf(stderr, "Error: Could not read MPU-6050 data (%d)\n", result);
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (buf[0] << 8) | buf[1];
    int16_t raw_accel_y = (buf[2] << 8) | buf[3];
    int16_t raw_accel_z = (buf[4] << 8) | buf[5];

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (buf[8] << 8) | buf[9];
    int16_t raw_gyro_y = (buf[10] << 8) | buf[11];
    int16_t raw_gyro_z = (buf[12] << 8) | buf[13];

    // Convert to g's and degrees/second (sensitivity scale factor: 16384 LSB/g, 131 LSB/deg/s)
    *accel_x = (float)raw_accel_x / 16384.0f;
    *accel_y = (float)raw_accel_y / 16384.0f;
    *accel_z = (float)raw_accel_z / 16384.0f;
    *gyro_x = (float)raw_gyro_x / 131.0f;
    *gyro_y = (float)raw_gyro_y / 131.0f;
    *gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

// Calculate pitch and roll from accelerometer data
void calculate_pitch_roll(float accel_x, float accel_y, float accel_z, float *pitch, float *roll) {
    *pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    *roll = atan2(-accel_y, accel_z) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(float angle) {
    int pulse_width;

    // Map angle (0-180) to pulse width (500-2500)
    pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0f) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(SERVO_PIN, pulse_width);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, float position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    float position;
    int retries = 0;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data with retries
        retries = 0;
        do {
            result = read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);
            if (result == 0) break; // Success
            fprintf(stderr, "Error: Failed to read sensor data, retrying (%d/%d)\n", retries + 1, 5);
            gpioDelay(100 * (1 << retries)); // Exponential backoff
            retries++;
        } while (retries < 5);

        if (result != 0) {
            fprintf(stderr, "Error: Failed to read sensor data after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Calculate pitch and roll
        calculate_pitch_roll(accel_x, accel_y, accel_z, &pitch, &roll);

        // Simulate position calculation (replace with actual API call)
        position = 100.0f + (pitch * 2.0f) + (roll * 3.0f);

        // Set servo angle
        set_servo_angle(position);

        // Log data
        log_data(pitch, roll, position);

        // Delay
        gpioDelay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

