#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_schedule(const char *filename, ScheduleEntry **schedule, int *num_entries);
int parse_schedule_entry(const char *line, ScheduleEntry *entry);
int set_relay_state(int relay_number, int state);
int perform_fade(int relay_number, int start_state, int end_state, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read the schedule from the file
int read_schedule(const char *filename, ScheduleEntry **schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of entries
    *num_entries = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        (*num_entries)++;
    }
    rewind(fp);

    // Allocate memory for the schedule
    *schedule = (ScheduleEntry *)malloc(*num_entries * sizeof(ScheduleEntry));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    // Read the schedule entries
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_entry(line, &(*schedule)[i]) != 0) {
            fprintf(stderr, "Error parsing schedule entry\n");
            fclose(fp);
            free(*schedule);
            return -1;
        }
        i++;
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule entry
int parse_schedule_entry(const char *line, ScheduleEntry *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->state) != 5) {
        fprintf(stderr, "Invalid schedule entry format: %s\n", line);
        return -1;
    }
    return 0;
}

