int set_relay_state(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to perform a fade transition
int perform_fade(int relay_number, int start_state, int end_state, int duration) {
    int num_steps = 100; // Number of PWM steps
    float duty_cycle_increment = (float)(end_state - start_state) / num_steps;
    float current_duty_cycle = start_state;
    int i;

    for (i = 0; i < num_steps; i++) {
        current_duty_cycle += duty_cycle_increment;
        if (current_duty_cycle < 0) current_duty_cycle = 0;
        if (current_duty_cycle > 100) current_duty_cycle = 100;

        int gpio_pin;
        switch (relay_number) {
            case 1:
                gpio_pin = RELAY1_PIN;
                break;
            case 2:
                gpio_pin = RELAY2_PIN;
                break;
            case 3:
                gpio_pin = RELAY3_PIN;
                break;
            case 4:
                gpio_pin = RELAY4_PIN;
                break;
            default:
                fprintf(stderr, "Invalid relay number: %d\n", relay_number);
                return -1;
        }

        gpioPWM(gpio_pin, (int)current_duty_cycle);
        gpioDelay(duration / num_steps); // Delay for each step
    }

    return 0;
}

