                    set_relay_state(schedule[i].relay_number, 0);

                    // Perform fade transition if necessary
                    if (schedule[i].state == 0 && gpioRead(RELAY1_PIN) && gpioRead(RELAY2_PIN) && gpioRead(RELAY3_PIN) && gpioRead(RELAY4_PIN)) {
