#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout waiting for HIGH\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout waiting for LOW\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency
int mapDistanceToFrequency(float distance) {
    if (distance < 0) {
        return -1; // Indicate error
    }

    // Clamp distance to a reasonable range (e.g., 2cm - 200cm)
    if (distance < 2.0) distance = 2.0;
    if (distance > 200.0) distance = 200.0;

    // Linear mapping
    float frequency = (float)(MAX_FREQUENCY - MIN_FREQUENCY) * (1.0 - (distance - 2.0) / (200.0 - 2.0)) + MIN_FREQUENCY;
    return (int)frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(int frequency) {
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
        return;
    }

    // Ensure frequency is within valid range
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a frequency
        int frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Delay to control the update rate
        gpioDelay(20000); // 20ms delay
    }

    // Clean up and terminate
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();
    fprintf(stderr, "Theremin terminated.\n");
    return 0;
}

