// Function to set the RGB color values using hardware PWM
void set_color(float proximity) {
    // Scale proximity value to the range 0-255 for PWM duty cycle
    int red_duty_cycle = (int)(255.0 * proximity);
    int green_duty_cycle = (int)(255.0 * (1.0 - proximity));
    int blue_duty_cycle = (int)(255.0 * (1.0 - proximity));

    // Ensure duty cycles are within the valid range
    if (red_duty_cycle < 0) red_duty_cycle = 0;
    if (red_duty_cycle > 255) red_duty_cycle = 255;
    if (green_duty_cycle < 0) green_duty_cycle = 0;
    if (green_duty_cycle > 255) green_duty_cycle = 255;
    if (blue_duty_cycle < 0) blue_duty_cycle = 0;
