#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data = 0; // Value to write to PWR_MGMT_1 register
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read raw gyroscope data from the MPU-6050
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data (X, Y, Z axis)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
gyro_data_t convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    gyro_data_t data;
    data.x = (float)gyro_x / GYRO_SCALE;
    data.y = (float)gyro_y / GYRO_SCALE;
    data.z = (float)gyro_z / GYRO_SCALE;
    return data;
}

// Function to log gyroscope data to a file
int log_gyro_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write timestamp and gyroscope data to file
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t gyro_x, gyro_y, gyro_z;
    gyro_data_t gyro_data;

    // Main loop
    while (!stop_flag) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert gyroscope data to degrees per second
            gyro_data = convert_gyro_data(gyro_x, gyro_y, gyro_z);

            // Log gyroscope data to file
            log_gyro_data(log_file, gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

