#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define melody
const unsigned int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce time (milliseconds)
#define DEBOUNCE_TIME 50

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 4000

// Global variables
volatile int playing = 0; // Flag to indicate if melody is playing
volatile unsigned int last_press_time = 0; // Last press time

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody(int gpio);
void stop_melody(int gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody(BUZZER_GPIO);
    gpioTerminate();
    exit(0);
}

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    unsigned int current_time = gpioTick();

    // Debounce the button
    if (current_time - last_press_time > DEBOUNCE_TIME * 1000) {
        last_press_time = current_time;

        if (level == 0) { // Button is pressed (active low)
            if (!playing) {
                play_melody(BUZZER_GPIO);
            } else {
                stop_melody(BUZZER_GPIO);
            }
        }
    }
}

// Function to play the melody
void play_melody(int gpio) {
    playing = 1;
    for (int i = 0; i < melody_length; i++) {
        gpioPWM(gpio, 128); // 50% duty cycle
        gpioSetPWMfrequency(gpio, PWM_FREQUENCY);
        gpioDelay(500000); // Delay for half a second (500000 microseconds)
        gpioPWM(gpio, 0); // Stop the tone
        gpioDelay(500000); // Delay for half a second
    }
    playing = 0;
}

// Function to stop the melody
void stop_melody(int gpio) {
    gpioPWM(gpio, 0); // Stop the PWM signal
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_GPIO, PWM_FREQUENCY);

    // Set interrupt service routine for button press
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100000); // Check every 100ms
    }

    return 0;
}

