#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_REGISTER_X_AXIS_L 0x08
#define LSM303_REGISTER_X_AXIS_H 0x09
#define LSM303_REGISTER_Y_AXIS_L 0x0A
#define LSM303_REGISTER_Y_AXIS_H 0x0B
#define LSM303_REGISTER_Z_AXIS_L 0x0C
#define LSM303_REGISTER_Z_AXIS_H 0x0D
#define LSM303_REGISTER_CTRL_REG1 0x20

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t x, int16_t y);
const char *get_compass_direction(float heading);
int log_data(int16_t x, int16_t y, int16_t z, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure magnetometer (enable continuous measurement)
    if (i2cWriteByteData(i2c_handle, LSM303_REGISTER_CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, LSM303_REGISTER_X_AXIS_L, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Calculate heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Get compass direction
const char *get_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("mag_log.csv", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, x, y, z, heading);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    int16_t calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *compass_direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calibrate data
            calibrate_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Get compass direction
            compass_direction = get_compass_direction(heading);

            // Log data
            if (log_data(calibrated_x, calibrated_y, calibrated_z, heading) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Print to console
            printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %.2f, Compass Direction: %s\n",
                   calibrated_x, calibrated_y, calibrated_z, heading, compass_direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

