#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4  // BCM GPIO 4
#define RELAY_PIN 17        // BCM GPIO 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, uint32_t tick);
int log_relay_state(int state);
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Keep the program running and responsive to interrupts
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Set interrupt callback for touch sensor
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for touch sensor\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, uint32_t tick) {
    int current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        // Toggle relay state
        relay_state = !relay_state;
        gpioWrite(RELAY_PIN, relay_state);

        // Log relay state
        if (log_relay_state(relay_state) != 0) {
            fprintf(stderr, "Failed to log relay state\n");
        }

        // Update last touch time
        last_touch_time = current_time;
    }
}

// Log relay state to JSON file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp as ISO 8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    // Create JSON object
    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state ? "ON" : "OFF");

    // Flush buffer to ensure data is written to file
    fflush(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Shutting down...\n");

    // Set relay to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log final relay state
    if (log_relay_state(relay_state) != 0) {
        fprintf(stderr, "Failed to log final relay state\n");
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

