#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PIN 17
#define NOZZLE_PIN 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define servo pulse widths (microseconds)
#define SERVO_CLOSED 500
#define SERVO_OPEN 1500

// Define nozzle angles and pulse widths (degrees)
#define NOZZLE_ANGLE_0 0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90 90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180

#define NOZZLE_PULSE_WIDTH_0 500
#define NOZZLE_PULSE_WIDTH_45 1000
#define NOZZLE_PULSE_WIDTH_90 1500
#define NOZZLE_PULSE_WIDTH_135 2000
#define NOZZLE_PULSE_WIDTH_180 2500

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the valve servo position
int set_valve_position(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting valve servo position: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to set the nozzle servo position
int set_nozzle_position(int gpio, int angle, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting nozzle servo position (angle %d): %d\n", angle, result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Simulate soil moisture sensor
    int moisture_level = 20;
    int moisture_sequence[] = {20, 40, 60, 80, 100};
    int moisture_sequence_size = sizeof(moisture_sequence) / sizeof(moisture_sequence[0]);
    int moisture_sequence_index = 0;

    // Main loop
    while (program_running) {
        // Read simulated moisture level
        int current_moisture = moisture_level;

        // Check if watering is needed
        if (current_moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d - Watering needed!\n", current_moisture);

            // Open the valve
            if (set_valve_position(VALVE_PIN, SERVO_OPEN) != 0) {
                fprintf(stderr, "Error opening valve!\n");
                program_running = 0; // Stop the program if valve fails to open
                break;
            }

            // Sweep the nozzle through different angles
            if (set_nozzle_position(NOZZLE_PIN, NOZZLE_ANGLE_0, NOZZLE_PULSE_WIDTH_0) != 0) {
                fprintf(stderr, "Error setting nozzle to 0 degrees\n");
            }
            gpioDelay(2000000); // 2 seconds

            if (set_nozzle_position(NOZZLE_PIN, NOZZLE_ANGLE_45, NOZZLE_PULSE_WIDTH_45) != 0) {
                fprintf(stderr, "Error setting nozzle to 45 degrees\n");
            }
            gpioDelay(2000000); // 2 seconds

            if (set_nozzle_position(NOZZLE_PIN, NOZZLE_ANGLE_90, NOZZLE_PULSE_WIDTH_90) != 0) {
                fprintf(stderr, "Error setting nozzle to 90 degrees\n");
            }
            gpioDelay(2000000); // 2 seconds

            if (set_nozzle_position(NOZZLE_PIN, NOZZLE_ANGLE_135, NOZZLE_PULSE_WIDTH_135) != 0) {
                fprintf(stderr, "Error setting nozzle to 135 degrees\n");
            }
            gpioDelay(2000000); // 2 seconds

            if (set_nozzle_position(NOZZLE_PIN, NOZZLE_ANGLE_180, NOZZLE_PULSE_WIDTH_180) != 0) {
                fprintf(stderr, "Error setting nozzle to 180 degrees\n");
            }
            gpioDelay(5000000); // 5 seconds

            // Close the valve
            if (set_valve_position(VALVE_PIN, SERVO_CLOSED) != 0) {
                fprintf(stderr, "Error closing valve!\n");
                fprintf(stderr, "CRITICAL: Valve failed to close!\n");
            }

            gpioDelay(5000000); // 5 seconds

        } else {
            printf("Moisture level: %d - No watering needed.\n", current_moisture);
        }

        // Update moisture level
        moisture_level = moisture_sequence[moisture_sequence_index];
        moisture_sequence_index = (moisture_sequence_index + 1) % moisture_sequence_size;

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    gpioServo(VALVE_PIN, 0); // Stop valve servo
    gpioServo(NOZZLE_PIN, 0); // Stop nozzle servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

