#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for L293D driver
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define motor control constants
#define STEPS_PER_REVOLUTION 2048  // For 28BYJ-48 with 1.8° step angle
#define STEPS_PER_ROTATION 512     // Number of steps for lock/unlock
#define INTER_STEP_DELAY 3000      // Inter-step delay in microseconds (3ms)

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // De-energize all coils
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);

        // Terminate pigpio library
        gpioTerminate();

        program_running = 0;
        exit(0);
    }
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < STEPS_PER_ROTATION; i++) {
        // Full-step sequence (single-coil excitation)
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 1);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 1);
        gpioDelay(INTER_STEP_DELAY);
    }

    // De-energize all coils after rotation
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < STEPS_PER_ROTATION; i++) {
        // Full-step sequence (single-coil excitation) - Counter-clockwise
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 1);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 1);
        gpioDelay(INTER_STEP_DELAY);
    }

    // De-energize all coils after rotation
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    printf("Door unlocked.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Set GPIO pins for buttons as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control program started. Press LOCK button to lock, UNLOCK button to unlock, or Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for LOCK button press
        if (gpioRead(LOCK_BUTTON) == 0) {
            // Debounce the button
            gpioDelay(200000); // 200ms debounce
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
            }
        }

        // Check for UNLOCK button press
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            // Debounce the button
            gpioDelay(200000); // 200ms debounce
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
            }
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();

    return 0;
}

