#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms
#define SAMPLE_INTERVAL_S 1
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int result;
    double distance;
    struct timespec start, end;
    long long start_ns, end_ns;
    double elapsed_time_s;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting distance measurement. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

        int timeout = 0;
        while (gpioRead(ECHO_PIN) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((end_ns - start_ns) > TIMEOUT_US * 1000) {
                timeout = 1;
                break;
            }
        }

        if (timeout) {
            fprintf(stderr, "Timeout waiting for rising edge!\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        timeout = 0;
        while (gpioRead(ECHO_PIN) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((end_ns - start_ns) > TIMEOUT_US * 1000) {
                timeout = 1;
                break;
            }
        }

        if (timeout) {
            fprintf(stderr, "Timeout waiting for falling edge!\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        // Calculate pulse width in seconds
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        elapsed_time_s = (double)(end_ns - start_ns) / 1000000000.0;

        // Calculate distance in centimeters
        distance = (elapsed_time_s * 34300.0) / 2.0;

        // Validate distance
        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        // Log distance
        fprintf(log_file, "%.2f\n", distance);
        fflush(log_file);
        printf("Distance: %.2f cm\n", distance);

        // Wait before next measurement
        gpioDelay(60); // 60ms
        gpioDelay(SAMPLE_INTERVAL_S * 1000 - 60); // Remaining time to next second
    }

    // Cleanup
    fprintf(stderr, "Releasing resources and closing log file.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

