#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_distance(uint16_t *distance);
int control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        terminate = 1;
    }
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    char cmd[1] = {VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0}; // Command to read distance
    char buffer[2]; // Buffer to store the distance data (2 bytes for 16-bit distance)
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1]; // Combine the two bytes to form the distance

    // Basic data validation (example: check if the distance is within a reasonable range)
    if (*distance > 8000) { // Assuming max range is around 8000mm (8m)
        fprintf(stderr, "Distance out of range: %d\n", *distance);
        return -1;
    }

    return 0;
}

// Control the relay (ON/OFF)
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state); // Set the GPIO pin to HIGH (state) or LOW (not state)
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    control_relay(0); // Turn off the relay
    i2cClose(i2c_handle); // Close the I2C interface
    gpioTerminate(); // Terminate pigpio
}

int main() {
    uint16_t distance;
    int status;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    printf("VL53L1X Distance Sensor and Relay Control\n");

    while (!terminate) {
        // Read distance from sensor
        status = read_distance(&distance);
        if (status == 0) {
            // Control relay based on distance
            if (distance <= DISTANCE_THRESHOLD) {
                control_relay(1); // Turn relay ON
            } else {
                control_relay(0); // Turn relay OFF
            }

            // Print distance to console
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

