#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0)
    {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Read gyroscope data
        int16_t gyro_x = i2cReadWordData(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = i2cReadWordData(i2c_handle, GYRO_YOUT_H);
        int16_t gyro_z = i2cReadWordData(i2c_handle, GYRO_ZOUT_H);

        // Check for I2C errors
        if (gyro_x < 0 || gyro_y < 0 || gyro_z < 0)
        {
            fprintf(stderr, "I2C read error\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Convert to degrees per second
        float gyro_x_dps = (float)gyro_x / GYRO_SCALE;
        float gyro_y_dps = (float)gyro_y / GYRO_SCALE;
        float gyro_z_dps = (float)gyro_z / GYRO_SCALE;

        // Print the data
        printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

