#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the activation duration for each relay (seconds)
#define RELAY_DURATION 5

// Define the watering cycle duration (seconds)
#define WATERING_CYCLE_DURATION (60 * 4) // 4 relays * 15 seconds each

// Define the time between watering cycles (seconds)
#define WATERING_INTERVAL 86400 // 24 hours

// Global variable to track the start time of the current watering cycle
time_t current_cycle_start_time = 0;

// Function prototypes
int initialize_gpio();
void activate_relay(int relay_pin);
void deactivate_all_relays();
void log_start_of_cycle(time_t timestamp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    deactivate_all_relays();
    gpioTerminate();
    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set all relay pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial state to HIGH (inactive)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to activate a specific relay
void activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Set LOW to activate
    gpioDelay(RELAY_DURATION * 1000000); // Delay for the activation duration (microseconds)
    gpioWrite(relay_pin, 1); // Set HIGH to deactivate
}

// Function to deactivate all relays
void deactivate_all_relays() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
}

// Function to log the start time of a watering cycle
void log_start_of_cycle(time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening watering_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s\n", timestamp_str);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        time_t current_time = time(NULL);

        // Check if it's time to start a new watering cycle
        if (current_time - current_cycle_start_time >= WATERING_INTERVAL) {
            printf("Starting watering cycle.\n");

            // Log the start time of the cycle
            log_start_of_cycle(current_time);
            current_cycle_start_time = current_time;

            // Activate relays sequentially
            for (int i = 0; i < 4; i++) {
                int relay_pin;
                switch (i) {
                    case 0: relay_pin = RELAY1_PIN; break;
                    case 1: relay_pin = RELAY2_PIN; break;
                    case 2: relay_pin = RELAY3_PIN; break;
                    case 3: relay_pin = RELAY4_PIN; break;
                }
                activate_relay(relay_pin);
            }
        }

        gpioDelay(1000000); // Delay for 1 second (microseconds)
    }

    return 0; // This line will never be reached due to the infinite loop
}

