    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        time_t current_time = time(NULL);

        // Check if it's time to start a new watering cycle
        if (current_time - current_cycle_start_time >= WATERING_INTERVAL) {
            printf("Starting watering cycle.\n");

            // Log the start time of the cycle
            log_start_of_cycle(current_time);
            current_cycle_start_time = current_time;

            // Activate relays sequentially
            for (int i = 0; i < 4; i++) {
                int relay_pin;
                switch (i) {
                    case 0: relay_pin = RELAY1_PIN; break;
                    case 1: relay_pin = RELAY2_PIN; break;
                    case 2: relay_pin = RELAY3_PIN; break;
