#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to initialize a GPIO pin for PWM output
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d as output", pin);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle for a given pin
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        char message[100];
        sprintf(message, "Invalid duty cycle value: %d", duty_cycle);
        log_event(message);
        return;
    }
    gpioPWM(pin, duty_cycle);
}

// Function to perform the sunrise effect
void sunrise_effect() {
    int duty_cycle;
    for (int i = 0; i <= 255 && program_running; i++) {
        duty_cycle = i;

        set_pwm_duty_cycle(RELAY1_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY2_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY3_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY4_PIN, duty_cycle);

        char message[100];
        sprintf(message, "Duty cycle: %d", duty_cycle);
        log_event(message);

        gpioDelay(1000); // Wait for 1 second
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(RELAY1_PIN) != 0 ||
        initialize_gpio(RELAY2_PIN) != 0 ||
        initialize_gpio(RELAY3_PIN) != 0 ||
        initialize_gpio(RELAY4_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Start the sunrise effect
    log_event("Starting sunrise effect...");
    sunrise_effect();

    // Turn off all relays
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    log_event("Sunrise effect complete.");

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

