#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling rate (Hz)
#define SAMPLE_RATE 20

// Full-scale range (degrees/sec)
#define FS_RANGE 250.0f

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(gyro_data_t data);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // Bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    char data[2];
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00;
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char reg = MPU6050_GYRO_XOUT_H;
    char buf[6];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (reg select): %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if any axis exceeds the threshold
int check_threshold(gyro_data_t data) {
    if (abs(data.x) > FS_RANGE || abs(data.y) > FS_RANGE || abs(data.z) > FS_RANGE) {
        return 1;
    } else {
        return 0;
    }
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold and control LED
            int threshold_exceeded = check_threshold(gyro_data);
            control_led(threshold_exceeded);
        } else {
            fprintf(stderr, "Error reading gyro data, re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Delay for 50ms (20Hz sampling rate)
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

