        fprintf(stderr, "Error initializing SPI. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
