#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0

// GPIO Configuration
#define LED_PIN 17

// Circular Buffer Configuration
#define BUFFER_SIZE 64

// Threshold Configuration
#define THRESHOLD 200.0 // degrees/second

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    long long timestamp;
    int16_t x, y, z;
} sample_t;

sample_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int init_spi();
int init_gpio();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(int16_t x, int16_t y, int16_t z);
void check_threshold(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
void print_buffer_to_csv();

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buffer[1];
    char rx_buffer[6];

    // Read X axis
    tx_buffer[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from X
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (rx_buffer[2] << 8) | rx_buffer[1];
    if (*x == 0) return -1; //Check for zero value

    // Read Y axis
    tx_buffer[0] = GYRO_YOUT_H | 0x80; // Read multiple bytes starting from Y
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *y = (rx_buffer[4] << 8) | rx_buffer[3];
    if (*y == 0) return -1; //Check for zero value

    // Read Z axis
    tx_buffer[0] = GYRO_ZOUT_H | 0x80; // Read multiple bytes starting from Z
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *z = (rx_buffer[6] << 8) | rx_buffer[5];
    if (*z == 0) return -1; //Check for zero value

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    circular_buffer[buffer_index].timestamp = gpioTick();
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check for threshold exceedance
void check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500000);      // Wait 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
        gpioDelay(500000);      // Wait 500ms
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to print the circular buffer to a CSV file
void print_buffer_to_csv() {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return;
    }
    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(fp, "%lld,%d,%d,%d\n", circular_buffer[i].timestamp, circular_buffer[i].x, circular_buffer[i].y, circular_buffer[i].z);
    }
    fclose(fp);
    printf("Data written to gyro_data.csv\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    char tx_buffer[2];
    tx_buffer[0] = PWR_MGMT_1;
    tx_buffer[1] = 0x00; // Clear sleep mode bit
    if (spiWrite(spi_handle, tx_buffer, 2) != 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    print_buffer_to_csv();

    return 0;
}

