    // Wake up the MPU-6050
    char tx_buffer[2];
    tx_buffer[0] = PWR_MGMT_1;
    tx_buffer[1] = 0x00; // Clear sleep mode bit
    if (spiWrite(spi_handle, tx_buffer, 2) != 0) {
