// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define ALS_VIS_DATA0 0x22
#define PS1_DATA0 0x24
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity);
int log_data(FILE *fp, unsigned int ambient_light, unsigned int proximity);
void control_led(int gpio, int state);
void signal_handler(int sig);

// Structure for sensor data
typedef struct {
    unsigned int ambient_light;
    unsigned int proximity;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data.ambient_light, &sensor_data.proximity) == 0) {
            // Log data
            if (log_data(log_file, sensor_data.ambient_light, sensor_data.proximity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Control LED based on proximity
            if (sensor_data.proximity > PROXIMITY_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

