int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity) {
    unsigned char data[4];
    int retries = 3;

    // Read ambient light
    while (retries > 0) {
        if (read(fd, data, 4) == 4) {
            *ambient_light = (data[1] << 8) | data[0];
            break;
        } else {
            usleep(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ambient light after multiple retries\n");
        return -1;
    }

    // Read proximity
    retries = 3;
    while (retries > 0) {
        if (read(fd, data, 4) == 4) {
            *proximity = (data[1] << 8) | data[0];
            break;
        } else {
            usleep(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity after multiple retries\n");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(FILE *fp, unsigned int ambient_light, unsigned int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Control LED state
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

