// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO8 (BCM)
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr);
int16_t read_gyro_axis(int handle, uint8_t reg_addr);
void log_data(FILE *fp, int64_t timestamp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Function to read a register from the ADXRS290
int spi_read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the transmit buffer: register address OR'd with read bit (0x80)
    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read operation
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI Xfer Error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the received data (second byte of the transfer)
    return rx_buf[1];
}

// Function to read the X or Y axis rate from the ADXRS290
