#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define event duration threshold (in milliseconds)
#define EVENT_DURATION_THRESHOLD 500

// Define alert duration (in seconds)
#define ALERT_DURATION 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void log_event(void);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int sensor1_high = 0;
    static int sensor2_high = 0;

    if (level == 1) {
        // Rising edge detected
        if (!sensor1_high) {
            start_tick = tick;
            sensor1_high = 1;
        }
    } else if (level == 0) {
        // Falling edge detected
        if (sensor1_high) {
            uint32_t duration = tick - start_tick;
            if (duration >= EVENT_DURATION_THRESHOLD) {
                if (sensor2_high) {
                    log_event();
                    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
                    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
                    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
                }
            }
            sensor1_high = 0;
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int sensor2_high = 0;
    static int sensor1_high = 0;

    if (level == 1) {
        // Rising edge detected
        if (!sensor2_high) {
            start_tick = tick;
            sensor2_high = 1;
        }
    } else if (level == 0) {
        // Falling edge detected
        if (sensor2_high) {
            uint32_t duration = tick - start_tick;
            if (duration >= EVENT_DURATION_THRESHOLD) {
                if (sensor1_high) {
                    log_event();
                    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
                    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
                    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
                }
            }
            sensor2_high = 0;
        }
    }
}

// Function to log seismic event to file
void log_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (optional, but good practice)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    // Register callback functions
    gpioSetAlertFuncEx(SENSOR1_PIN, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_PIN, sensor2_callback, NULL);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio

    return 0;
}

