#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define SPI device and GPIO pins
#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_PIN 8 // GPIO8 (BCM)
#define SCLK_PIN 11 // GPIO11 (BCM)
#define MOSI_PIN 10 // GPIO10 (BCM)
#define MISO_PIN 9 // GPIO9 (BCM)
#define LED_PIN 17 // GPIO17 (BCM)

// Define ADXRS290 register addresses
#define ADXRS290_REG_XGYRO_OUT 0x02

// Define threshold for angular rate
#define ANGULAR_RATE_THRESHOLD 20.0f

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data and timestamp
typedef struct {
    float angular_rate;
    struct timespec timestamp;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int spi_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t address, uint8_t *data, int len);
float read_gyro_x_rate(void);
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, float angular_rate);
int buffer_get(circular_buffer_t *buffer, int index, gyro_data_t *data);
void led_on(void);
void led_off(void);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t address, uint8_t *data, int len) {
    uint8_t tx_buf[len + 1];
    uint8_t rx_buf[len + 1];

    // Set MSB of address to 1 for read
    tx_buf[0] = address | 0x80;
    for (int i = 0; i < len; i++) {
        tx_buf[i + 1] = data[i];
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len + 1,
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Copy received data to the provided buffer
    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Function to read gyroscope X-axis angular rate
float read_gyro_x_rate(void) {
    uint8_t data[2];
    int16_t raw_data;

    // Set register address
    uint8_t address = ADXRS290_REG_XGYRO_OUT | 0x80; // Read mode

    if (spi_transfer(address, data, 2) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return 0.0f; // Return 0.0 on error
    }

    // Combine the two bytes to form the 16-bit raw data
    raw_data = (int16_t)((data[0] << 8) | data[1]);

    // Convert raw data to degrees per second (adjust scale factor as needed)
    float angular_rate = (float)raw_data / 14.375f; // Example scale factor

    return angular_rate;
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

// Circular buffer add function
int buffer_add(circular_buffer_t *buffer, float angular_rate) {
    if (buffer == NULL) return -1;

    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    buffer->buffer[buffer->head].angular_rate = angular_rate;
    buffer->buffer[buffer->head].timestamp = ts;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }

    return 0;
}

// Circular buffer get function
int buffer_get(circular_buffer_t *buffer, int index, gyro_data_t *data) {
    if (index < 0 || index >= buffer->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1;
    }

    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    return 0;
}

// LED on function
void led_on(void) {
    int fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("Error opening LED value file");
        return;
    }
    if (write(fd, "1", 1) != 1) {
        perror("Error writing to LED value file");
    }
    close(fd);
}

// LED off function
void led_off(void) {
    int fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("Error opening LED value file");
        return;
    }
    if (write(fd, "0", 1) != 1) {
        perror("Error writing to LED value file");
    }
    close(fd);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    program_running = 0;
}

int main(void) {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Configure LED pin as output
    int fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("Error opening LED direction file");
        close(spi_fd);
        return 1;
    }
    if (write(fd, "out", 3) != 3) {
        perror("Error writing to LED direction file");
        close(spi_fd);
        return 1;
    }
    close(fd);

    // Main loop
    while (program_running) {
        float angular_rate = read_gyro_x_rate();

        if (buffer_add(&gyro_buffer, angular_rate) != 0) {
            fprintf(stderr, "Error adding to circular buffer\n");
        }

        // Check if angular rate exceeds threshold
        if (angular_rate > ANGULAR_RATE_THRESHOLD) {
            led_on();
        } else {
            led_off();
        }

        // Print the angular rate (for debugging)
        printf("Angular Rate: %.2f deg/s\n", angular_rate);

        // Delay for 100ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup
    close(spi_fd);
    led_off();

    return 0;
}

