#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define the PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define the PWM range (0-255)
#define PWM_RANGE 255

// Global variable to store the total fade duration in seconds
int total_fade_duration = 0;

// Function prototypes
int validate_duration(int duration);
int initialize_gpio();
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration, int delay_ms);
void signal_handler(int signal);
void cleanup();

int main(int argc, char *argv[]) {
    // Check for the correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the total fade duration
    if (!validate_duration(atoi(argv[1]))) {
        return 1;
    }

    total_fade_duration = atoi(argv[1]);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, total_fade_duration, 10); // 10ms delay
    fade_lamp(LAMP2_GPIO, total_fade_duration, 10);
    fade_lamp(LAMP3_GPIO, total_fade_duration, 10);

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to validate the total fade duration
int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Total fade duration must be between 1 and 3600 seconds.\n");
        return 0;
    }
    return 1;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    printf("GPIO initialisation complete.\n");
    return 0;
}

// Function to set the brightness of a lamp using hardware PWM
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration, int delay_ms) {
    int brightness = PWM_RANGE;
    int steps = duration * 100; // Number of steps for the fade duration
    int delay_us = delay_ms * 1000; // Delay in microseconds

    printf("Fading lamp on GPIO %d...\n", gpio);

    for (int i = 0; i < steps; ++i) {
        set_lamp_brightness(gpio, brightness);
        gpioDelay(delay_us);
        brightness--;
        if (brightness < 0) {
            brightness = 0;
        }
    }

    set_lamp_brightness(gpio, 0);
    printf("Lamp on GPIO %d faded out.\n", gpio);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to turn off lamps and terminate pigpio
void cleanup() {
    printf("Turning off lamps...\n");
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    printf("Terminating pigpio...\n");
    gpioTerminate();
    printf("Cleanup complete.\n");
}

