#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the traffic light
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define ALL_CLEAR_PIN 24

// Define timing constants in seconds
#define RED_TIME    10
#define RED_YELLOW_TIME 2
#define GREEN_TIME  10
#define YELLOW_TIME 3

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state)
{
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to execute the traffic light sequence
void traffic_light_sequence()
{
    // Red
    printf("Red\n");
    if (set_gpio_state(RED_PIN, 0) != 0) return;
    if (set_gpio_state(YELLOW_PIN, 0) != 0) return;
    if (set_gpio_state(GREEN_PIN, 0) != 0) return;
    if (set_gpio_state(ALL_CLEAR_PIN, 0) != 0) return;
    gpioDelay(RED_TIME * 1000000); // Convert seconds to microseconds

    // Red + Yellow
    printf("Red + Yellow\n");
    if (set_gpio_state(RED_PIN, 0) != 0) return;
    if (set_gpio_state(YELLOW_PIN, 0) != 0) return;
    if (set_gpio_state(GREEN_PIN, 0) != 0) return;
    if (set_gpio_state(ALL_CLEAR_PIN, 0) != 0) return;
    gpioDelay(RED_YELLOW_TIME * 1000000);

    // Green
    printf("Green\n");
    if (set_gpio_state(RED_PIN, 1) != 0) return;
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return;
    if (set_gpio_state(GREEN_PIN, 0) != 0) return;
    if (set_gpio_state(ALL_CLEAR_PIN, 1) != 0) return;
    gpioDelay(GREEN_TIME * 1000000);

    // Yellow
    printf("Yellow\n");
    if (set_gpio_state(RED_PIN, 1) != 0) return;
    if (set_gpio_state(YELLOW_PIN, 0) != 0) return;
    if (set_gpio_state(GREEN_PIN, 1) != 0) return;
    if (set_gpio_state(ALL_CLEAR_PIN, 1) != 0) return;
    gpioDelay(YELLOW_TIME * 1000000);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) { fprintf(stderr, "Failed to set RED_PIN as output\n"); gpioTerminate(); return 1; }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) { fprintf(stderr, "Failed to set YELLOW_PIN as output\n"); gpioTerminate(); return 1; }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) { fprintf(stderr, "Failed to set GREEN_PIN as output\n"); gpioTerminate(); return 1; }
    if (gpioSetMode(ALL_CLEAR_PIN, PI_OUTPUT) != 0) { fprintf(stderr, "Failed to set ALL_CLEAR_PIN as output\n"); gpioTerminate(); return 1; }

    // Set initial state to all clear (active low)
    if (set_gpio_state(RED_PIN, 1) != 0) return 1;
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return 1;
    if (set_gpio_state(GREEN_PIN, 1) != 0) return 1;
    if (set_gpio_state(ALL_CLEAR_PIN, 1) != 0) return 1;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop to continuously run the traffic light sequence
    while (!terminate) {
        traffic_light_sequence();
    }

    // Clean up GPIO pins before exiting
    printf("Cleaning up GPIO pins...\n");
    set_gpio_state(RED_PIN, 1);
    set_gpio_state(YELLOW_PIN, 1);
    set_gpio_state(GREEN_PIN, 1);
    set_gpio_state(ALL_CLEAR_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

