#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C address of the MPR121
#define MPR121_ADDRESS 0x5A

// Define the GPIO pin for the relay
#define RELAY_PIN 17

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Define the touch delay in milliseconds
#define TOUCH_DELAY 10

// Global variables
int i2c_fd;
FILE *log_file;
bool relay_state = false;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void toggle_relay(int pin);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, cleaning up...");
        digitalWrite(RELAY_PIN, LOW); // Set relay to LOW
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize the MPR121
int mpr121_init(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x00) < 0) {
        log_message("Error writing to MPR121 register 0x2B");
        return -1;
    }

    // Electrode configuration
    if (wiringPiI2CWriteReg8(fd, 0x5E, 0x8F) < 0) {
        log_message("Error writing to MPR121 register 0x5E");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x41 + 2 * i, 0x30) < 0) {
            log_message("Error writing to MPR121 touch threshold register");
            return -1;
        }
        if (wiringPiI2CWriteReg8(fd, 0x42 + 2 * i, 0x10) < 0) {
            log_message("Error writing to MPR121 release threshold register");
            return -1;
        }
    }

    // Configure and start
    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x01) < 0) {
        log_message("Error writing to MPR121 register 0x2B");
        return -1;
    }

    log_message("MPR121 initialized successfully");
    return 0;
}

// Read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg16(fd, 0x00);
    if (touch_status < 0) {
        log_message("Error reading touch status from MPR121");
        return -1;
    }
    return touch_status;
}

// Toggle the relay state
void toggle_relay(int pin) {
    relay_state = !relay_state;
    digitalWrite(pin, relay_state ? HIGH : LOW);
    char message[100];
    sprintf(message, "Relay toggled to %s", relay_state ? "ON" : "OFF");
    log_message(message);
}

// Log a message to the log file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting touch relay program...");

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        log_message("Error initializing wiringPi");
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDRESS);
    if (i2c_fd == -1) {
        log_message("Error initializing I2C");
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        log_message("Error initializing MPR121");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Set the relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to LOW

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status > 0) {
            if (touch_status & 0x01) { // Check if electrode 0 is touched
                toggle_relay(RELAY_PIN);
                delay(TOUCH_DELAY); // Debounce delay
            }
        }
        delay(5); // Small delay to prevent busy-waiting
    }

    return 0;
}

