#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define FLAME_THRESHOLD 3
#define FLAME_DETECT_TIME 50 // milliseconds
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
void log_flame_event(const char *timestamp);
void activate_alert(int buzzer_pin, int led_pin);
void deactivate_alert(int buzzer_pin, int led_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log a flame event
void log_flame_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alert (buzzer and LED)
void activate_alert(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 1); // Turn on buzzer
    gpioWrite(led_pin, 1);    // Turn on LED
    gpioDelay(ALERT_DURATION * 1000000); // Delay for alert duration (in microseconds)
    gpioWrite(buzzer_pin, 0); // Turn off buzzer
    gpioWrite(led_pin, 0);    // Turn off LED
}

// Function to deactivate the alert (buzzer and LED)
void deactivate_alert(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 0); // Ensure buzzer is off
    gpioWrite(led_pin, 0);    // Ensure LED is off
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_count = 0;
    int last_reading = 1; // Initialize to a non-flame state

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (active-low)
            flame_count++;
            if (flame_count >= FLAME_THRESHOLD) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log the event
                log_flame_event(timestamp);

                // Activate the alert
                activate_alert(BUZZER_PIN, LED_PIN);

                // Reset the flame count
                flame_count = 0;
                last_reading = 0; // Update last reading
            }
        } else {
            flame_count = 0; // Reset flame count if no flame detected
            last_reading = 1; // Update last reading
        }

        gpioDelay(FLAME_DETECT_TIME * 1000); // Delay for flame detection time (in microseconds)
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_alert(BUZZER_PIN, LED_PIN);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

