#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispensing parameters
#define DISPENSE_DURATION 1000 // milliseconds
#define SOLENOID_1_DURATION 500 // milliseconds
#define SOLENOID_2_DURATION 500 // milliseconds

// Global variable for log file pointer
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin, int duration_ms);
int deactivate_solenoid(int pin);
int log_dispense_event(int pin1, int pin2, int duration_ms);
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Main dispensing loop
    while (1) {
        // Dispense 1
        if (activate_solenoid(SOLENOID_1_PIN, SOLENOID_1_DURATION) != 0) {
            fprintf(stderr, "Error activating solenoid 1.\n");
            break;
        }
        if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
            fprintf(stderr, "Error deactivating solenoid 1.\n");
            break;
        }

        // Dispense 2
        if (activate_solenoid(SOLENOID_2_PIN, SOLENOID_2_DURATION) != 0) {
            fprintf(stderr, "Error activating solenoid 2.\n");
            break;
        }
        if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
            fprintf(stderr, "Error deactivating solenoid 2.\n");
            break;
        }

        // Log the event
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event.\n");
            break;
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    signal_handler(SIGINT); // Call signal handler to cleanup

    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure solenoids are initially off
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0;
}

// Function to activate a solenoid for a specified duration
int activate_solenoid(int pin, int duration_ms) {
    if (pin != SOLENOID_1_PIN && pin != SOLENOID_2_PIN) {
        fprintf(stderr, "Invalid solenoid pin: %d\n", pin);
        return 1;
    }

    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error writing to pin %d\n", pin);
        return 1;
    }

    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds

    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (pin != SOLENOID_1_PIN && pin != SOLENOID_2_PIN) {
        fprintf(stderr, "Invalid solenoid pin: %d\n", pin);
        return 1;
    }

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error writing to pin %d\n", pin);
        return 1;
    }

    return 0;
}

// Function to log dispense events to a file
int log_dispense_event(int pin1, int pin2, int duration_ms) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, pin1, pin2, duration_ms);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up and exiting.\n");

    // Deactivate solenoids
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

