#include <signal.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable A
#define ENABLE_A 24

// Enable B
#define ENABLE_B 25

// PWM Frequency
#define PWM_FREQUENCY 1000

// PID Constants
#define KP 0.5
#define KI 0.01
#define KD 0.1

// Obstacle Distance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Log File Name
#define LOG_FILE "balance_log.txt"

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
void signal_handler(int signal);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void set_motor_speed(int motor, int speed);
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error);
void obstacle_avoidance(float distance);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, stopping motors and exiting.\n");
        program_running = 0;
        set_motor_speed(0, 0);
        set_motor_speed(1, 0);
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Log Data Function
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Set Motor Speed Function
void set_motor_speed(int motor, int speed) {
    if (speed < -255) speed = -255;
    if (speed > 255) speed = 255;

    if (motor == 0) { // Motor A
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, 255);
            gpioPWM(ENABLE_A, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENABLE_A, 255);
            gpioPWM(ENABLE_A, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, 0);
        }
    } else { // Motor B
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, 255);
            gpioPWM(ENABLE_B, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENABLE_B, 255);
            gpioPWM(ENABLE_B, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, 0);
        }
    }
}

// Calculate PID Function
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error) {
    float error = setpoint - actual_value;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Obstacle Avoidance Function
void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        printf("Obstacle detected! Reversing motors.\n");
        set_motor_speed(0, -50); // Motor A backward at 50% speed
        set_motor_speed(1, -50); // Motor B backward at 50% speed
    } else {
        // Move forward
        set_motor_speed(0, 100);
        set_motor_speed(1, 100);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(ENABLE_A, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENABLE_B, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // PID variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Main loop
    while (program_running) {
        // Simulate tilt error
        float tilt_error = (float)(rand() % 2000 - 1000) / 1000.0; // Random float between -10.0 and 10.0

        // Simulate ultrasonic distance sensor
        float distance = (float)(rand() % 4000 + 2000) / 100.0; // Random float between 2.0 and 400.0

        // Calculate motor speeds using PID
        float pid_output = calculate_pid(0.0, tilt_error, &integral, &previous_error);

        // Limit PID output to ±255
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        if (motor_a_speed > 255) motor_a_speed = 255;
        if (motor_a_speed < -255) motor_a_speed = -255;
        if (motor_b_speed > 255) motor_b_speed = 255;
        if (motor_b_speed < -255) motor_b_speed = -255;

        // Apply motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Obstacle avoidance
        obstacle_avoidance(distance);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

