#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4  // GPIO4 (physical pin 7, BCM)
#define RELAY_PIN 17        // GPIO17 (physical pin 11, BCM)

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void debounce_delay();
void cleanup_gpio();
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Toggle relay
            toggle_relay();

            // Debounce delay
            debounce_delay();
        }

        // Small delay to prevent busy-waiting
        usleep(1000); // 1 ms
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-down resistor for touch sensor pin
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read touch sensor
int read_touch_sensor() {
    // Read GPIO level
    int level = gpioRead(TOUCH_SENSOR_PIN);

    // Return 1 if touch detected (HIGH), 0 otherwise
    return (level == 1) ? 1 : 0;
}

// Function to toggle relay
void toggle_relay() {
    // Toggle relay state
    relay_state = !relay_state;

    // Set GPIO output
    gpioWrite(RELAY_PIN, relay_state);

    // Print relay state
    printf("Relay toggled to state: %d\n", relay_state);
}

// Function for debounce delay
void debounce_delay() {
    // Delay for 50 milliseconds
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

// Function to cleanup GPIO
void cleanup_gpio() {
    printf("Cleaning up GPIO and exiting.\n");

    // Set relay to LOW (de-energize)
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

