#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE register\n");
        return -1;
    }

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME register\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data registers\n");
        return -1;
    }

    *clear = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
    *red   = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
    *green = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];
    *blue  = (uint16_t)buffer[7] << 8 | (uint16_t)buffer[6];

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", now, red, green, blue, clear);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(fp, "Timestamp,Red,Green,Blue,Clear\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    while (!terminate) {
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading color data, logging zeros\n");
            log_data(0, 0, 0, 0);
        }

        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

