#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define constants for timing
#define SUNRISE_DURATION 3600 // 1 hour
#define DAYTIME_DURATION 7200 // 6 hours
#define SUNSET_DURATION 3600  // 1 hour
#define NIGHTTIME_DURATION 14400 // 14.4 hours

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void sunrise(int duration);
void daytime(int duration);
void sunset(int duration);
void nighttime(int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0; // Set the flag to exit the main loop

        // Turn off all relays
        gpioWrite(RELAY1_PIN, 1); // Deactivate relay 1
        gpioWrite(RELAY2_PIN, 1); // Deactivate relay 2
        gpioWrite(RELAY3_PIN, 1); // Deactivate relay 3
        gpioWrite(RELAY4_PIN, 1); // Deactivate relay 4

        // Terminate the pigpio library
        gpioTerminate();

        exit(0); // Exit the program
    }
}

// Function to simulate sunrise
