#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define CAPTURE_DURATION 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_fp = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to capture video using raspivid
int capture_video() {
    char filename[100];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), VIDEO_DIR "%Y%m%d_%H%M%S.h264", timeinfo);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d000", filename, CAPTURE_DURATION);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command.\n");
        return -1;
    }
    return status;
}

// Function to log motion event to file
int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    fprintf(log_fp, "%s Motion detected\n", timestamp);
    fflush(log_fp); // Ensure the log is written immediately
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    printf("Motion detected at %s\n", timestamp);

    if (capture_video() == 0) {
        printf("Video captured successfully.\n");
    } else {
        fprintf(stderr, "Video capture failed.\n");
    }

    if (log_motion(timestamp) != 0) {
        fprintf(stderr, "Error logging motion event.\n");
    }

    free(timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Assume no motion initially (HIGH)
    unsigned long last_trigger_time = 0;

    while (running) {
        int current_state = gpioRead(SENSOR_PIN);

        if (current_state == 0 && last_state == 1) { // Motion detected (LOW)
            unsigned long now = gpioTick();
            if (now - last_trigger_time > DEBOUNCE_MS * 1000) { // Debounce
                handle_motion();
                last_trigger_time = now;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_fp);
    gpioTerminate();

    return 0;
}

