#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.2

// GPIO pin for alarm
#define ALARM_GPIO 27

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// ADXL345 initialization function
int adxl345_init() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g units (assuming +/- 2g range, 10 bits of resolution)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to detect free-fall event
int detect_freefall(float x, float y, float z) {
    // Check if all three axes are below the threshold
    if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
        return 1; // Free-fall detected
    } else {
        return 0; // No free-fall
    }
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(5000);          // Wait for 5 seconds
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Function to log free-fall event to file
void log_freefall(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

int main() {
    float x, y, z;
    int freefall_count = 0;
    int confirmed_freefall = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Detect free-fall
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= 10) { // Check for 0.5 seconds (10 * 0.05 seconds)
                    if (!confirmed_freefall) {
                        // Read acceleration again after a delay
                        gpioDelay(500); // 0.5 seconds
                        if (read_acceleration(&x, &y, &z) == 0 && detect_freefall(x, y, z)) {
                            // Free-fall confirmed
                            printf("Free-fall confirmed!\n");
                            trigger_alarm();
                            log_freefall(x, y, z);
                            confirmed_freefall = 1; // Set flag to prevent repeated confirmation
                        } else {
                            fprintf(stderr, "Second free-fall reading failed\n");
                        }
                    }
                    freefall_count = 0; // Reset counter after confirmation
                }
            } else {
                freefall_count = 0; // Reset counter if not in free-fall
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

