#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for the buzzer
#define BUZZER_PIN 17

// Default free-fall and impact thresholds (in g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(double *x, double *y, double *z);
double calculate_magnitude(double x, double y, double z);
int detect_freefall(double magnitude);
int detect_impact(double magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // I2C bus 1, LIS3DH address
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the LIS3DH accelerometer
int init_lis3dh() {
    // Enable accelerometer, 100Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(double *x, double *y, double *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);

    if (result < 0) {
        fprintf(stderr, "Failed to read acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g (assuming +/- 2g full-scale)
    *x = (double)x_raw / 16384.0;
    *y = (double)y_raw / 16384.0;
    *z = (double)z_raw / 16384.0;

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to detect free-fall
int detect_freefall(double magnitude) {
    return (magnitude < freefall_threshold);
}

// Function to detect impact
int detect_impact(double magnitude) {
    return (magnitude > impact_threshold);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    printf("Free-fall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        cleanup();
        return 1;
    }

    // Configure buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is initially off

    accelerometer_data_t accel_data;
    double magnitude;
    int freefall_detected = 0;

    printf("Monitoring acceleration...\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) < 0) {
            fprintf(stderr, "Failed to read acceleration, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Detect events
        int impact = detect_impact(magnitude);

        if (impact) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer();
        }

        // Free-fall detection logic
        if (impact) {
            freefall_detected = 0; // Reset free-fall detection
        } else {
            freefall_detected = detect_freefall(magnitude);
            if (freefall_detected) {
                printf("Free-fall detected! Magnitude: %.2f g\n", magnitude);
                // Optionally, add code here to trigger a specific action during free-fall
            }
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

