#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Step delay (microseconds)
#define STEP_DELAY 1000

// 28BYJ-48 gear ratio (1/64) and steps per revolution (2048)
#define GEAR_RATIO 64.0
#define STEPS_PER_REVOLUTION 2048.0

// Square side length (mm)
#define SQUARE_SIDE 50.0

// Function prototypes
void motor1_step(int step);
void motor2_step(int step);
void move_x(int steps);
void move_y(int steps);
void move_square();
void cleanup(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop motors (set all pins low)
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
