#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address (default 0x18)
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Configuration values
#define CTRL_REG1_VALUE 0x77 // 0x77 = 01110111.  ODR = 100Hz, Enable X, Y, Z axes
#define CTRL_REG4_VALUE 0x00 // 0x00 = 00000000.  +/- 2g, High Resolution, Left justified

// Global variables
int i2c_handle;
double threshold = 2.0;
int i2c_address = LIS3DH_ADDR;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int config_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
void log_acceleration(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = strtol(argv[i + 1], NULL, 16);
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtod(argv[i + 1], NULL);
            if (threshold <= 0) {
                fprintf(stderr, "Error: Threshold must be greater than 0.\n");
                return 1;
            }
            i++;
        }
    }

    // Validate I2C address
    if (i2c_address < 0x03 || i2c_address > 0x77) {
        fprintf(stderr, "Error: Invalid I2C address.  Must be between 0x03 and 0x77.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    accelerometer_data_t data;
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &data.x, &data.y, &data.z) == 0) {
            // Convert to g (assuming +/- 2g range)
            double x_g = (double)data.x / 16384.0; // 2^12 = 4096, but we only use 12 bits
            double y_g = (double)data.y / 16384.0;
            double z_g = (double)data.z / 16384.0;

            // Check for threshold exceedance
            if (fabs(x_g) > threshold || fabs(y_g) > threshold || fabs(z_g) > threshold) {
                log_acceleration(data.x, data.y, data.z);
                system("sudo shutdown -h now");
                break; // Exit loop after shutdown is initiated
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data.\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure LIS3DH
int config_lis3dh(int i2c_handle) {
    // Write CTRL_REG1
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, CTRL_REG1_VALUE) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1.\n");
        return -1;
    }

    // Write CTRL_REG4
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, CTRL_REG4_VALUE) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read all six registers at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) != 6) { //0x80 for auto-increment
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Log acceleration data
void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

