#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define MAG_DATA_REG 0x00 // Example register, adjust as needed
#define MAG_DATA_SIZE 2 // Example size, adjust as needed
#define THRESHOLD 5.0f // mT
#define RELAY_GPIO 17 // BCM
#define RETRY_COUNT 3
#define TIMEOUT_ATTEMPTS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetic_field(float *magnetic_field);
int control_relay(int state);
int log_event(const char *event_type, float magnetic_field, int relay_state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetic field data
int read_magnetic_field(float *magnetic_field) {
    char buf[MAG_DATA_SIZE];
    int bytes_read;
    int attempts = 0;

    while (attempts < TIMEOUT_ATTEMPTS) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, MAG_DATA_REG, buf, MAG_DATA_SIZE);
        if (bytes_read == MAG_DATA_SIZE) {
            // Assuming the data is in milliTesla (mT) format
            *magnetic_field = (float)((int16_t)((buf[0] << 8) | buf[1])) / 1000.0f;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempts + 1, bytes_read);
            log_event("I2C_READ_ERROR", 0.0f, -1); // Log the error
            gpioDelay(100); // Wait before retrying
            attempts++;
        }
    }

    fprintf(stderr, "Timeout reading magnetic field data.\n");
    log_event("I2C_TIMEOUT", 0.0f, -1); // Log the timeout
    return -1; // Timeout
}

// Control the relay
int control_relay(int state) {
    int result = gpioWrite(RELAY_GPIO, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", RELAY_GPIO, result);
        log_event("GPIO_WRITE_ERROR", 0.0f, state); // Log the error
        return -1;
    }
    return 0;
}

// Log events
int log_event(const char *event_type, float magnetic_field, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s - Magnetic Field: %.3f mT - Relay: %s\n",
            timestamp, event_type, magnetic_field, relay_state == 1 ? "ON" : (relay_state == 0 ? "OFF" : "ERROR"));
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float magnetic_field;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        if (read_magnetic_field(&magnetic_field) == 0) {
            if (magnetic_field > THRESHOLD) {
                if (relay_state == 0) {
                    if (control_relay(1) == 0) {
                        log_event("MAGNETIC_FIELD_EXCEEDED", magnetic_field, 1);
                        relay_state = 1;
                    }
                }
            } else {
                if (relay_state == 1) {
                    if (control_relay(0) == 0) {
                        log_event("MAGNETIC_FIELD_OK", magnetic_field, 0);
                        relay_state = 0;
                    }
                }
            }
        } else {
            // Error already logged in read_magnetic_field
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

