#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define MAX_CLIENTS 5
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to log events with timestamps
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char command[10] = {0};
        strncpy(command, buffer, 9); // Ensure null termination

        if (strcasecmp(command, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Turn relay ON
            log_event("Relay turned ON");
            send(client_socket, "OK\n", strlen("OK\n"), 0);
        } else if (strcasecmp(command, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Turn relay OFF
            log_event("Relay turned OFF");
            send(client_socket, "OK\n", strlen("OK\n"), 0);
        } else {
            log_event("Invalid command received");
            send(client_socket, "Invalid Command\n", strlen("Invalid Command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Error receiving data");
    }

    close(client_socket);
    log_event("Client disconnected");
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    char message[50];
    sprintf(message, "Signal received, shutting down...");
    log_event(message);

    gpioWrite(GPIO_PIN, 0); // Turn off relay
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen failed");
        log_event("Socket listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Server listening on port 5000");

    // Accept connections and handle them
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            log_event("Socket accept failed");
            continue; // Continue listening for new connections
        }

        handle_client(new_socket);
    }

    return 0;
}

