// Sensor I2C addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// GPIO pin for relay control
#define RELAY_PIN 18

// I2C bus
#define I2C_BUS 1

// Flow rate threshold (ml/min)
#define FLOW_THRESHOLD 5.0

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// File to log flow rates
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int crc_valid;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sensor(int i2c_handle, sensor_data_t *data);
int validate_crc(uint8_t data[], int len);
int control_relay(float flow1, float flow2);
int log_data(float flow1, float flow2);
void cleanup();
void signal_handler(int signal);

int main() {
    sensor_data_t sensor1_data, sensor2_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle1, &sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1. Skipping.\n");
            sensor1_data.flow_rate = -1.0; // Indicate error
        }
        if (read_sensor(i2c_handle2, &sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2. Skipping.\n");
            sensor2_data.flow_rate = -1.0; // Indicate error
        }

        // Control relay
        if (sensor1_data.flow_rate >= 0 && sensor2_data.flow_rate >= 0) {
            control_relay(sensor1_data.flow_rate, sensor2_data.flow_rate);
        }

        // Log data
        if (log_data(sensor1_data.flow_rate, sensor2_data.flow_rate) != 0) {
            fprintf(stderr, "Error logging data. Skipping.\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio, I2C, GPIO, and log file
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin for relay control
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read flow rate from sensor
int read_sensor(int i2c_handle, sensor_data_t *data) {
    char buf[3];
    int bytes_read;

    bytes_read = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return 1;
    }

    // Validate CRC
    uint8_t data_bytes[3] = {buf[0], buf[1], buf[2]};
    if (!validate_crc(data_bytes, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        data->crc_valid = 0;
        return 1;
    }
    data->crc_valid = 1;

    // Convert to flow rate (ml/min) - Example conversion, adjust as needed
    int16_t flow_raw = (buf[0] << 8) | buf[1];
    data->flow_rate = (float)flow_raw / 100.0; // Example scaling factor

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Control the relay based on flow rates
int control_relay(float flow1, float flow2) {
    static int relay_state = 0; // 0 = off, 1 = on
    static time_t last_change_time = 0;
    time_t now = time(NULL);

    if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD && !relay_state) {
        gpioWrite(RELAY_PIN, 1); // Turn on relay
        relay_state = 1;
        last_change_time = now;
        printf("Relay ON\n");
    } else if (flow1 >= FLOW_THRESHOLD && flow2 >= FLOW_THRESHOLD && relay_state) {
        gpioWrite(RELAY_PIN, 0); // Turn off relay
        relay_state = 0;
        printf("Relay OFF\n");
    }

    // Debounce: Wait 5 seconds before changing state again
    if (relay_state && (now - last_change_time) > 5) {
        relay_state = 0; // Reset state to avoid continuous toggling
        gpioWrite(RELAY_PIN, 0); // Ensure relay is off
        printf("Relay AUTO OFF\n");
    }

    return 0;
}

// Log flow rates to file
int log_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

