#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17 // BCM GPIO 17
#define MOTOR_ENA_PIN 22   // BCM GPIO 22
#define MOTOR_IN1_PIN 23   // BCM GPIO 23
#define MOTOR_IN2_PIN 24   // BCM GPIO 24

// Define motor control duration
#define MOTOR_DURATION_MS 5000

// Define debounce delay
#define DEBOUNCE_DELAY_MS 600

// Global variable to track rain state
static volatile int rainDetected = 0;

// Function prototypes
int initGPIO();
int readRainSensor();
void controlMotor(int enable, int direction);
void closeWindow();
void stopMotor();
void signalHandler(int signal);

// Function to initialize GPIO pins
int initGPIO() {
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi");
        return -1;
    }

    // Set rain sensor pin as input with pull-up resistor
    pinMode(RAIN_SENSOR_PIN, INPUT);
    pullUpDnControl(RAIN_SENSOR_PIN, PUD_UP);

    // Set motor control pins as output
    pinMode(MOTOR_ENA_PIN, OUTPUT);
    pinMode(MOTOR_IN1_PIN, OUTPUT);
    pinMode(MOTOR_IN2_PIN, OUTPUT);

    // Initially stop the motor
    stopMotor();

    syslog(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the rain sensor
int readRainSensor() {
    return digitalRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void controlMotor(int enable, int direction) {
    digitalWrite(MOTOR_ENA_PIN, enable ? HIGH : LOW);
    digitalWrite(MOTOR_IN1_PIN, direction ? HIGH : LOW);
    digitalWrite(MOTOR_IN2_PIN, !direction ? HIGH : LOW);
}

// Function to close the window
void closeWindow() {
    syslog(LOG_INFO, "Closing window");
    controlMotor(1, 1); // Enable motor, direction 1
    delay(MOTOR_DURATION_MS);
    stopMotor();
    syslog(LOG_INFO, "Window closed");
}

// Function to stop the motor
void stopMotor() {
    digitalWrite(MOTOR_ENA_PIN, LOW);
    digitalWrite(MOTOR_IN1_PIN, LOW);
    digitalWrite(MOTOR_IN2_PIN, LOW);
    syslog(LOG_INFO, "Motor stopped");
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down");
    stopMotor();
    syslog(LOG_INFO, "GPIO cleanup complete");
    closelog();
    exit(0);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initGPIO() == -1) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    int dryCount = 0;

    // Main loop
    while (1) {
        int rain = readRainSensor();

        if (rain == 0 && !rainDetected) {
            // Rain detected (dry-to-wet transition)
            syslog(LOG_INFO, "Rain detected");
            closeWindow();
            dryCount = 0; // Reset debounce counter
            rainDetected = 1;
        } else if (rain == 1 && rainDetected) {
            // Rain stopped (wet-to-dry transition)
            syslog(LOG_INFO, "Rain stopped");
            dryCount++;
            if (dryCount >= 3) {
                rainDetected = 0;
                syslog(LOG_INFO, "Debounced, rain detection stopped");
            }
        }

        delay(200); // Poll every 200ms
    }

    return 0;
}

