#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    gpioServo(SERVO_PIN, 0); // Stop the servo initially

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (gpioServo(SERVO_PIN, 2000) != 0) {
                fprintf(stderr, "Error setting servo pulse width to 2000\n");
                terminate = 1; // Exit on error
                break;
            }
            printf("Locking door\n");
            gpioDelay(500000); // Debounce delay
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (gpioServo(SERVO_PIN, 1000) != 0) {
                fprintf(stderr, "Error setting servo pulse width to 1000\n");
                terminate = 1; // Exit on error
                break;
            }
            printf("Unlocking door\n");
            gpioDelay(500000); // Debounce delay
        }
        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    printf("Door lock control system stopped.\n");
    return 0;
}

