#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 4  // GPIO 7, BCM 4
#define LED_PIN 17 // GPIO 11, BCM 17

// Define constants
#define LED_ON_TIME 60 // seconds
#define POLL_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Read PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log events to file
int log_event(const char *event_type, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s: %s - %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_pir_sensor() == 1) {
            log_event("Motion Detected", "Motion detected by PIR sensor.");
            control_led(1); // Turn on LED
            gpioDelay(LED_ON_TIME * 1000); // Wait for LED_ON_TIME seconds
            control_led(0); // Turn off LED
            log_event("Motion Event", "Motion event completed.");
        }
        gpioDelay(POLL_INTERVAL); // Poll for motion every POLL_INTERVAL milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0); // Turn off LED
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

