#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_fd);
int mpr121_read_touch_status(int i2c_fd);
void relay_on(int gpio_pin);
void relay_off(int gpio_pin);
void debounce(int gpio_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_off(RELAY_GPIO);
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

// MPR121 Initialization function
int mpr121_init(int i2c_fd) {
    // Soft reset
    if (i2cWriteByteData(i2c_fd, 0x80, 0x63) < 0) {
        perror("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configuration
    if (i2cWriteByteData(i2c_fd, 0x5E, 0xC0) < 0) return -1; // MHD
    if (i2cWriteByteData(i2c_fd, 0x5F, 0x01) < 0) return -1; // NHD
    if (i2cWriteByteData(i2c_fd, 0x60, 0x01) < 0) return -1; // NCL
    if (i2cWriteByteData(i2c_fd, 0x61, 0x0E) < 0) return -1; // FDL

    if (i2cWriteByteData(i2c_fd, 0x5B, 0x06) < 0) return -1; // Debounce

    if (i2cWriteByteData(i2c_fd, 0x5D, 0x04) < 0) return -1; // FFI
    if (i2cWriteByteData(i2c_fd, 0x5C, 0x01) < 0) return -1; // SFI
    if (i2cWriteByteData(i2c_fd, 0x5A, 0x01) < 0) return -1; // CDT

    if (i2cWriteByteData(i2c_fd, 0x2B, 0x05) < 0) return -1; // ELE0_LRTL
    if (i2cWriteByteData(i2c_fd, 0x2C, 0x05) < 0) return -1; // ELE1_LRTL
    if (i2cWriteByteData(i2c_fd, 0x2D, 0x05) < 0) return -1; // ELE2_LRTL
    if (i2cWriteByteData(i2c_fd, 0x2E, 0x05) < 0) return -1; // ELE3_LRTL
    if (i2cWriteByteData(i2c_fd, 0x2F, 0x05) < 0) return -1; // ELE4_LRTL
    if (i2cWriteByteData(i2c_fd, 0x30, 0x05) < 0) return -1; // ELE5_LRTL
    if (i2cWriteByteData(i2c_fd, 0x31, 0x05) < 0) return -1; // ELE6_LRTL
    if (i2cWriteByteData(i2c_fd, 0x32, 0x05) < 0) return -1; // ELE7_LRTL
    if (i2cWriteByteData(i2c_fd, 0x33, 0x05) < 0) return -1; // ELE8_LRTL
    if (i2cWriteByteData(i2c_fd, 0x34, 0x05) < 0) return -1; // ELE9_LRTL
    if (i2cWriteByteData(i2c_fd, 0x35, 0x05) < 0) return -1; // ELE10_LRTL
    if (i2cWriteByteData(i2c_fd, 0x36, 0x05) < 0) return -1; // ELE11_LRTL

    if (i2cWriteByteData(i2c_fd, 0x2B, 0x0A) < 0) return -1; // ELE0_HRTL
    if (i2cWriteByteData(i2c_fd, 0x2C, 0x0A) < 0) return -1; // ELE1_HRTL
    if (i2cWriteByteData(i2c_fd, 0x2D, 0x0A) < 0) return -1; // ELE2_HRTL
    if (i2cWriteByteData(i2c_fd, 0x2E, 0x0A) < 0) return -1; // ELE3_HRTL
    if (i2cWriteByteData(i2c_fd, 0x2F, 0x0A) < 0) return -1; // ELE4_HRTL
    if (i2cWriteByteData(i2c_fd, 0x30, 0x0A) < 0) return -1; // ELE5_HRTL
    if (i2cWriteByteData(i2c_fd, 0x31, 0x0A) < 0) return -1; // ELE6_HRTL
    if (i2cWriteByteData(i2c_fd, 0x32, 0x0A) < 0) return -1; // ELE7_HRTL
    if (i2cWriteByteData(i2c_fd, 0x33, 0x0A) < 0) return -1; // ELE8_HRTL
    if (i2cWriteByteData(i2c_fd, 0x34, 0x0A) < 0) return -1; // ELE9_HRTL
    if (i2cWriteByteData(i2c_fd, 0x35, 0x0A) < 0) return -1; // ELE10_HRTL
    if (i2cWriteByteData(i2c_fd, 0x36, 0x0A) < 0) return -1; // ELE11_HRTL

    if (i2cWriteByteData(i2c_fd, 0x5C, 0x01) < 0) return -1; // Enable auto-config
    if (i2cWriteByteData(i2c_fd, 0x5B, 0x06) < 0) return -1; // Enable 12 electrodes

    return 0;
}

// MPR121 Read Touch Status function
int mpr121_read_touch_status(int i2c_fd) {
    int touch_status = i2cReadByteData(i2c_fd, 0x00);
    if (touch_status < 0) {
        perror("Failed to read touch status");
        return -1;
    }
    return touch_status;
}

// Relay ON function
void relay_on(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
}

// Relay OFF function
void relay_off(int gpio_pin) {
    gpioWrite(gpio_pin, 0);
}

// Debounce function
void debounce(int gpio_pin, int duration_ms) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    relay_off(RELAY_GPIO); // Ensure relay is off at startup

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 and Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, exiting.\n");
            break;
        }

        if (touch_status & 0x01) { // Check if electrode 0 is touched
            printf("Electrode 0 touched!\n");
            relay_on(RELAY_GPIO);
            debounce(RELAY_GPIO, DEBOUNCE_MS);
        } else {
            relay_off(RELAY_GPIO);
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    relay_off(RELAY_GPIO);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

