#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        syslog(LOG_ERR, "Invalid angle: %d", angle);
        return -1;
    }

    int pulse_width = 1000 + (angle * 1000 / 180); // Map angle to pulse width (1000-2000 us)
    gpioServo(SERVO_PIN, pulse_width);
    syslog(LOG_INFO, "Servo angle set to %d, pulse width: %d", angle, pulse_width);
    return 0;
}

int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        syslog(LOG_INFO, "Received: %s", buffer);

        if (strncmp(buffer, "SET_ANGLE", 9) == 0) {
            int angle;
            if (sscanf(buffer + 9, "%d", &angle) == 1) {
                if (set_servo_angle(angle) != 0) {
                    send(client_socket, "ERROR: Invalid angle\n", strlen("ERROR: Invalid angle\n"), 0);
                }
            } else {
                send(client_socket, "ERROR: Invalid format\n", strlen("ERROR: Invalid format\n"), 0);
            }
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            char response[10];
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
            send(client_socket, response, strlen(response), 0);
        } else {
            send(client_socket, "ERROR: Unknown command\n", strlen("ERROR: Unknown command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive error");
    }

    close(client_socket);
    syslog(LOG_INFO, "Client disconnected");
    return 0;
}

int main() {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Creating socket file descriptor
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        syslog(LOG_ERR, "Socket creation failed");
        perror("socket failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        syslog(LOG_ERR, "Bind failed");
        perror("bind failed");
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Bind done");

    // Listening for incoming connections
    if (listen(server_socket, 3) < 0) {
        syslog(LOG_ERR, "Listen failed");
        perror("listen");
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Listening on port %d", PORT);

    while (!terminate) {
        // Accepting incoming connection
        if ((client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len)) < 0) {
            syslog(LOG_ERR, "Accept failed");
            perror("accept");
            continue; // Continue listening even if accept fails
        }
        syslog(LOG_INFO, "Connection accepted");

        handle_client(client_socket);
    }

    // Cleaning up
    close(server_socket);
    gpioTerminate();
    closelog();

    return 0;
}

