#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL_MS 2000
#define SDA_PIN 2
#define SCL_PIN 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux(float *lux);
int control_relay(float lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_lux(float *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the grow-light relay
int control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Turn on relay
        printf("Turning on grow light (Lux: %.2f)\n", lux);
    } else {
        gpioWrite(RELAY_GPIO, 0); // Turn off relay
        printf("Turning off grow light (Lux: %.2f)\n", lux);
    }
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    float lux;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        result = read_lux(&lux);
        if (result == 0) {
            // Log data
            log_data(lux);

            // Control relay
            control_relay(lux);
        } else {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            fprintf(log_file, "Error reading lux value, retrying...\n");
            fflush(log_file);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

