#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 16
#define HX711_SCK 18
#define SOLENOID_PIN 22

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 5000

// Global variables
static int threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static volatile int running = 1;

// Function prototypes
int read_hx711();
float average_readings(int num_readings);
void activate_solenoid();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    closelog();
}

// Function to read HX711 data
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_SCK, 0);
    while (gpioRead(HX711_DOUT) == 1) {
        // Wait for DOUT to go LOW
        gpioDelay(1000); // Timeout after 1 second
        if (!running) return -1; // Exit if signal received
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to average readings
float average_readings(int num_readings) {
    int i;
    int sum = 0;
    for (i = 0; i < num_readings; i++) {
        int reading = read_hx711();
        if (reading == -1) return -1.0; // Propagate error
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }
    return (float)sum / num_readings;
}

// Function to activate solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(200);             // Wait for 200ms
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

int main(int argc, char *argv[]) {
    int opt;
    char *endptr;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = strtof(optarg, &endptr);
                if (*endptr != '\0') {
                    syslog(LOG_ERR, "Invalid scale factor: %s", optarg);
                    cleanup();
                    return 1;
                }
                break;
            case 'd':
