#define HX711_SCK 18
#define SOLENOID_PIN 22

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 5000

// Global variables
static int threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static volatile int running = 1;

// Function prototypes
int read_hx711();
float average_readings(int num_readings);
void activate_solenoid();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    closelog();
}

// Function to read HX711 data
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_SCK, 0);
    while (gpioRead(HX711_DOUT) == 1) {
        // Wait for DOUT to go LOW
        gpioDelay(1000); // Timeout after 1 second
        if (!running) return -1; // Exit if signal received
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

