float average_readings(int num_readings) {
    int i;
    int sum = 0;
    for (i = 0; i < num_readings; i++) {
        int reading = read_hx711();
        if (reading == -1) return -1.0; // Propagate error
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }
    return (float)sum / num_readings;
