#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define MQTT_TOPIC "home/lights/control"
#define RELAY_GPIO 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
    syslog(LOG_INFO, "Relay set to %s", state == 1 ? "ON" : "OFF");
}

// Callback function for handling incoming MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        payload[message->payloadlen] = '\0'; // Ensure null termination
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            set_relay_state(1);
        } else if (strcmp(payload, "OFF") == 0) {
            set_relay_state(0);
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty message received on topic %s", message->topic);
    }
}

// Callback function for MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        syslog(LOG_INFO, "Subscribed to topic: %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// Callback function for MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "MQTT disconnected unexpectedly with code %d", rc);
    }
    syslog(LOG_INFO, "MQTT disconnected");
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // Blocking call with a timeout
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

