// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths for each servo
#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

// Function to set the PWM pulse width for a given GPIO pin
void setServoPulseWidth(int pin, int pulseWidth) {
    // Ensure pulse width is within the valid range
    if (pulseWidth < MIN_PULSE_WIDTH) {
        pulseWidth = MIN_PULSE_WIDTH;
    } else if (pulseWidth > MAX_PULSE_WIDTH) {
        pulseWidth = MAX_PULSE_WIDTH;
    }

    // Set the PWM duty cycle (pulse width in microseconds)
    pwmWrite(pin, pulseWidth);
}

int main() {
    // Initialize wiringPi using the BCM GPIO numbering scheme
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi. Please check permissions and wiring.\n");
        return 1; // Exit with an error code
    }

    // Configure the GPIO pins as PWM outputs
    pinMode(SERVO1_PIN, PWM_OUTPUT);
    pinMode(SERVO2_PIN, PWM_OUTPUT);
    pinMode(SERVO3_PIN, PWM_OUTPUT);
    pinMode(SERVO4_PIN, PWM_OUTPUT);
    pinMode(SERVO5_PIN, PWM_OUTPUT);

    // Set the PWM mode to mark:space
    pwmSetMode(PWM_MODE_MS);

    // Set the PWM clock divider to achieve a 50Hz frequency (20ms period)
    pwmSetClock(192); // Adjust clock divider as needed.  Clock = 19.2 MHz / divider

    // Set the PWM range (resolution)
    pwmSetRange(1000000 / 20); // 1000000 / 20 = 50000.  Resolution is 50000.

    // Main loop
    while (1) {
        // Set the pulse widths for each servo
        setServoPulseWidth(SERVO1_PIN, SERVO1_TARGET);
        setServoPulseWidth(SERVO2_PIN, SERVO2_TARGET);
        setServoPulseWidth(SERVO3_PIN, SERVO3_TARGET);
        setServoPulseWidth(SERVO4_PIN, SERVO4_TARGET);
        setServoPulseWidth(SERVO5_PIN, SERVO5_TARGET);

        // Wait for three seconds
        sleep(3);

        // Stop the PWM signal on all pins
        pwmWrite(SERVO1_PIN, 0);
        pwmWrite(SERVO2_PIN, 0);
        pwmWrite(SERVO3_PIN, 0);
        pwmWrite(SERVO4_PIN, 0);
        pwmWrite(SERVO5_PIN, 0);

        // Small delay to ensure PWM stops
        delay(100);
    }

    return 0;
}

