#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5

// Encoder B
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Target RPM
#define TARGET_RPM 50

// Ticks per revolution
#define TICKS_PER_REVOLUTION 64

// PI controller parameters
#define KP 0.5
#define KI 0.1

// Stall detection time (seconds)
#define STALL_TIME 2

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;

// Last encoder values for stall detection
volatile int last_encoder_a_ticks = 0;
volatile int last_encoder_b_ticks = 0;

// PWM duty cycle clamp
#define PWM_CLAMP 255

// Structure to hold motor control parameters
typedef struct {
    int pwm_pin;
    int dir_pin;
    int current_duty_cycle;
    int last_duty_cycle;
} motor_t;

motor_t motor_a, motor_b;

// Function prototypes
void initialize_gpio();
void initialize_motors();
void initialize_encoders();
void set_motor_speed(motor_t *motor, int rpm);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
void stall_detection();
void signal_handler(int signal);

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO, motors, and encoders
    initialize_gpio();
    initialize_motors();
    initialize_encoders();

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_ticks);
        double rpm_b = calculate_rpm(encoder_b_ticks);

        // PI controller
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        double pi_a = KP * error_a + KI * (error_a - last_encoder_a_ticks);
        double pi_b = KP * error_b + KI * (error_b - last_encoder_b_ticks);

        // Clamp PWM duty cycle
        int duty_cycle_a = (int)pi_a;
        if (duty_cycle_a < 0) duty_cycle_a = 0;
        if (duty_cycle_a > PWM_CLAMP) duty_cycle_a = PWM_CLAMP;

        int duty_cycle_b = (int)pi_b;
        if (duty_cycle_b < 0) duty_cycle_b = 0;
