#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17 // BCM numbering
#define LUX_DAWN 200
#define LUX_DUSK 50
#define HYSTERESIS 10
#define POLL_INTERVAL_MS 5000 // 5 seconds
#define I2C_RETRY_COUNT 3

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_lux(int fd);
void control_relay(int gpio_pin, int state);
void log_data(int lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read lux value from BH1750
int read_lux(int fd) {
    int lux = -1;
    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        if (wiringPiI2CWrite(fd, CONTINUOUS_HIGH_RES_MODE) == -1) {
            fprintf(stderr, "Error setting mode: %s\n", strerror(errno));
            return -1;
        }
        delay(200); // Wait for measurement (at least 180ms)
        int msb = wiringPiI2CReadReg8(fd, 0x00);
        int lsb = wiringPiI2CReadReg8(fd, 0x01);
        if (msb == -1 || lsb == -1) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            delay(100); // Small delay before retry
            continue;
        }
        lux = (msb << 8 | lsb) / 1.2;
        return lux;
    }
    fprintf(stderr, "Failed to read lux after multiple retries.\n");
    return -1;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        // No specific I2C deinitialization function in wiringPi, but we can reset the pin
        // wiringPiI2CWrite(i2c_fd, 0x00); // Example: Send a reset command (if applicable)
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    digitalWrite(GPIO_PIN, LOW); // Turn off the relay
    pinMode(GPIO_PIN, INPUT); // Set pin to input mode (safer)
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize WiringPi with BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(BH1750_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = LOW; // Initially off
    int last_lux = 0;

    printf("Monitoring light levels and controlling LED strip...\n");

    while (!terminate) {
        int lux = read_lux(i2c_fd);
        if (lux == -1) {
            fprintf(stderr, "Error reading lux value. Logging error and continuing...\n");
            log_data(-1, relay_state); // Log error with -1 lux value
            delay(POLL_INTERVAL_MS);
            continue;
        }

        if (lux < LUX_DUSK && relay_state == LOW) {
            control_relay(GPIO_PIN, HIGH); // Turn on relay
            relay_state = HIGH;
            log_data(lux, relay_state);
            printf("Turning on relay (Lux = %d)\n", lux);
        } else if (lux > (LUX_DUSK + HYSTERESIS) && relay_state == HIGH) {
            control_relay(GPIO_PIN, LOW); // Turn off relay
            relay_state = LOW;
            log_data(lux, relay_state);
            printf("Turning off relay (Lux = %d)\n", lux);
        } else {
            log_data(lux, relay_state);
        }

        delay(POLL_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

