#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define flow rate thresholds (LPM)
#define FLOW_HIGH_THRESHOLD 5.0
#define FLOW_LOW_THRESHOLD 4.5

// Define pulse count timeout (seconds)
#define PULSE_COUNT_TIMEOUT 1

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
void control_solenoid(double flow_rate);
void log_data(double flow_rate, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine (ISR) for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate flow rate (LPM)
double calculate_flow_rate(int pulse_count)
{
    // YF-S201 sensor: 4.2 pulses per liter
    // Convert pulses to liters and then to LPM
    double liters = (double)pulse_count / 4.2;
    double flow_rate = liters * 60.0; // Liters per minute
    return flow_rate;
}

// Function to control the solenoid valve
void control_solenoid(double flow_rate)
{
    static int solenoid_state = 1; // 1 = open, 0 = closed
    static time_t last_state_change = 0;
    time_t current_time = time(NULL);

    if (flow_rate > FLOW_HIGH_THRESHOLD && solenoid_state == 1)
    {
        gpioWrite(SOLENOID_PIN, 0); // Close the valve
        solenoid_state = 0;
        log_data(flow_rate, solenoid_state);
        printf("Solenoid closed (Flow Rate: %.2f LPM)\n", flow_rate);
    }
    else if (flow_rate < FLOW_LOW_THRESHOLD && solenoid_state == 0)
    {
        gpioWrite(SOLENOID_PIN, 1); // Open the valve
        solenoid_state = 1;
        log_data(flow_rate, solenoid_state);
        printf("Solenoid opened (Flow Rate: %.2f LPM)\n", flow_rate);
    }
}

// Function to log data to a file
void log_data(double flow_rate, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, Flow Rate: %.2f LPM, Solenoid State: %s\n", timestamp, flow_rate, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    (void)signal; // unused
    printf("Signal received, shutting down...\n");
    running = 0;

    // Close the solenoid valve
    gpioWrite(SOLENOID_PIN, 1); // Open the valve (safe state)

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP);

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_PIN, 1);

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine (ISR)
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, PULSE_COUNT_TIMEOUT, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running)
    {
        // Disable interrupts temporarily to safely access the pulse count
        gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL); // Disable ISR
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&pulse_mutex);
        gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, PULSE_COUNT_TIMEOUT, flow_sensor_isr, NULL); // Re-enable ISR

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Control the solenoid valve
        control_solenoid(flow_rate);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 1); // Open the valve (safe state)
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

