#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA 23
#define HX711_SCK 24
#define SERVO_PIN 18

// Define TCP port
#define PORT 12345

// Define timeout values
#define DATA_TIMEOUT 1000

// Define servo pulse width range
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define calibration file
#define CALIBRATION_FILE "config.ini"

// Structure to hold calibration data
typedef struct {
    double calibration_factor;
} CalibrationData;

// Global variables
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int init_tcp_server();
void handle_client(int client_socket);
int read_hx711();
double calibrate_weight(int raw_value, double calibration_factor);
int map_weight_to_pulse_width(double target_weight, double actual_weight);
int dispense_ingredient(int pulse_width);
int load_calibration_data(CalibrationData *calibration);
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency for servo (50 Hz)
    gpioSetPWMfrequency(SERVO_PIN, 50);

    return 0;
}

// Initialize TCP server
int init_tcp_server() {
    struct sockaddr_in address;
    int opt = 1;

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 12345
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    printf("Listening on port %d...\n", PORT);
    return 0;
}

// Read raw value from HX711
int read_hx711() {
    int data = 0;
    int attempts = 0;

    gpioWrite(HX711_SCK, 0);

    while (gpioRead(HX711_DATA) == 1 && attempts < DATA_TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        attempts++;
    }

    if (attempts >= DATA_TIMEOUT) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // 1 us clock pulse
        data = data << 1;
        if (gpioRead(HX711_DATA)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // 1 us
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // 1 us

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Load calibration data from file
int load_calibration_data(CalibrationData *calibration) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file: %s, using default calibration factor\n", CALIBRATION_FILE);
        calibration->calibration_factor = 1.0; // Default calibration factor
        return -1;
    }

    if (fscanf(fp, "%lf", &calibration->calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file, using default calibration factor\n");
        fclose(fp);
        calibration->calibration_factor = 1.0; // Default calibration factor
        return -1;
    }

    fclose(fp);
    printf("Calibration factor loaded: %lf\n", calibration->calibration_factor);
    return 0;
}

// Calibrate weight
double calibrate_weight(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Map weight to servo pulse width
int map_weight_to_pulse_width(double target_weight, double actual_weight) {
    double error = target_weight - actual_weight;
    double proportional_gain = 0.1; // Adjust as needed
    double pulse_width = MIN_PULSE_WIDTH + proportional_gain * error * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);

    // Clamp pulse width to the valid range
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    return (int)pulse_width;
}

// Dispense ingredient
int dispense_ingredient(int pulse_width) {
    gpioPWM(SERVO_PIN, pulse_width);
    gpioDelay(1000); // Wait 1 second
    int raw_value = read_hx711();
    double actual_weight;

    if (raw_value == -1) {
        fprintf(stderr, "Error reading HX711 during dispensing\n");
        return -1;
    }

    actual_weight = calibrate_weight(raw_value, 1.0); // Using default calibration for dispensing

    char response[256];
    snprintf(response, sizeof(response), "Target: %.2f, Actual: %.2f\n", target_weight, actual_weight);
    send(new_socket, response, strlen(response), 0);

    log_dispensing_event(target_weight, actual_weight, "Dispensing successful");
    return 0;
}

// Log dispensing event
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);
    fflush(log_file);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    double target_weight;
    int pulse_width;
    int raw_value;
    double actual_weight;
    CalibrationData calibration;

    load_calibration_data(&calibration);

    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        log_dispensing_event(0.0, 0.0, "Network error");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);

    if (sscanf(buffer, "%lf", &target_weight) != 1) {
        fprintf(stderr, "Invalid target weight received\n");
        const char *error_message = "Invalid target weight";
        char response[256];
        snprintf(response, sizeof(response), "Error: %s\n", error_message);
        send(client_socket, response, strlen(response), 0);
        log_dispensing_event(0.0, 0.0, error_message);
        close(client_socket);
        return;
    }

    printf("Target weight: %.2f\n", target_weight);

    raw_value = read_hx711();
    if (raw_value == -1) {
        const char *error_message = "Sensor absent or not ready";
        char response[256];
        snprintf(response, sizeof(response), "Error: %s\n", error_message);
        send(client_socket, response, strlen(response), 0);
        log_dispensing_event(target_weight, 0.0, error_message);
        close(client_socket);
        return;
    }

    actual_weight = calibrate_weight(raw_value, calibration.calibration_factor);

    pulse_width = map_weight_to_pulse_width(target_weight, actual_weight);

    if (dispense_ingredient(pulse_width) != 0) {
        const char *error_message = "API call control failure";
        char response[256];
        snprintf(response, sizeof(response), "Error: %s\n", error_message);
        send(client_socket, response, strlen(response), 0);
        log_dispensing_event(target_weight, actual_weight, error_message);
    } else {
        const char *message = "Dispensing complete";
        char response[256];
        snprintf(response, sizeof(response), "Dispensing complete: Target=%.2f, Actual=%.2f\n", target_weight, actual_weight);
        send(client_socket, response, strlen(response), 0);
        log_dispensing_event(target_weight, actual_weight, message);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize TCP server
    if (init_tcp_server() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Dispensing system started\n");

    while (program_running) {
        // Accept incoming connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_dispensing_event(0.0, 0.0, "Socket accept error");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Handle client connection
        handle_client(new_socket);
    }

    // Clean up
    close(server_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Dispensing system stopped\n");
    return 0;
}

