#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4  // BCM GPIO 4
#define RELAY_PIN 17 // BCM GPIO 17

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main(int argc, char *argv[]) {
    int debounce_ms = 50;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: Debounce interval must be a positive integer.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring touch sensor on GPIO %d, relay on GPIO %d. Debounce: %d ms\n", TOUCH_PIN, RELAY_PIN, debounce_ms);

    while (running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 0) { // Assuming touch sensor outputs LOW when touched
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > debounce_ms * 1000) { // Convert ms to microseconds
                // Debounced rising edge detected
                gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN)); // Toggle relay state

                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                if (gpioRead(RELAY_PIN) == 1) {
                    printf("%s Relay: ON\n", timestamp);
                } else {
                    printf("%s Relay: OFF\n", timestamp);
                }

                last_touch_time = current_time;
            }
        }

        gpioDelay(1); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio

    return 0;
}

