#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <pigpio.h>

#define SERVO_PIN 18 // BCM GPIO 18, physical pin 12
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define MIN_PULSE_WIDTH 500 // us
#define MAX_PULSE_WIDTH 2500 // us
#define ANGLE_INCREMENT 10 // degrees

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int set_terminal_mode(int fd, int echo, int cbreak) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int restore_terminal_mode(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main() {
    int fd;
    int angle = 90;
    int pulse_width;
    int key;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 20000000; // 20ms

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000000)
    gpioSetPWMrange(SERVO_PIN, 1000000);

    // Open the terminal device
    fd = open("/dev/tty", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Restore terminal settings on exit
    atexit(restore_terminal_mode);

    // Set terminal to non-canonical mode
    if (set_terminal_mode(fd, 0, 1) != 0) {
        close(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Servo control. Press 'q' to quit.\n");

    while (!terminate) {
        fd_set rfds;
        struct timeval tv;

        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        tv.tv_sec = 0;
        tv.tv_usec = 10000; // 10ms timeout

        int select_result = select(fd + 1, &rfds, NULL, NULL, &tv);

        if (select_result == -1) {
            perror("select");
            break;
        } else if (select_result == 0) {
            // Timeout: no key press
            continue;
        } else {
            // Key press detected
            key = getchar();

            if (key == '+') {
                angle += ANGLE_INCREMENT;
                if (angle > 180) {
                    angle = 180;
                }
            } else if (key == '-') {
                angle -= ANGLE_INCREMENT;
                if (angle < 0) {
                    angle = 0;
                }
            } else if (key == 'q') {
                break;
            }

            // Calculate pulse width
            pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

            // Set PWM duty cycle
            gpioPWM(SERVO_PIN, pulse_width);

            printf("Angle: %d degrees, Pulse Width: %d us\n", angle, pulse_width);
        }

        nanosleep(&sleep_time, NULL);
    }

    // Stop PWM
    gpioPWM(SERVO_PIN, 0);

    // Restore terminal settings
    if (restore_terminal_mode(fd) != 0) {
        perror("restore_terminal_mode");
    }

    close(fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

