#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

volatile int pulse_count = 0;
volatile unsigned long last_interrupt_time = 0;

FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void print_rpm(double rpm);
void signal_handler(int signal);

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, DEBOUNCE_MS, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = 0;
    double rpm;

    while (1) {
        // Calculate RPM every 5 seconds
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 5) {
            rpm = calculate_rpm(pulse_count);
            log_rpm(rpm);
            print_rpm(rpm);
            pulse_count = 0; // Reset pulse count after logging
            last_log_time = current_time;
        }

        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

