    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO pin
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

