#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define TOUCH_DURATION_THRESHOLD 10 // seconds
#define POLL_INTERVAL_MS 50

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_touch_sensor();
void toggle_relay();
void force_relay_off();
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
    printf("Relay toggled to %d\n", !current_state);
}

// Function to force the relay off
void force_relay_off() {
    gpioWrite(RELAY_PIN, 0);
    printf("Relay forced OFF\n");
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for touch duration tracking
    time_t touch_start_time = 0;
    int touch_active = 0;

    printf("Touch sensor and relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            if (!touch_active) {
                touch_active = 1;
                touch_start_time = time(NULL);
                printf("Touch detected\n");
            } else {
                time_t current_time = time(NULL);
                double time_elapsed = difftime(current_time, touch_start_time);

                if (time_elapsed >= TOUCH_DURATION_THRESHOLD) {
                    force_relay_off();
                    touch_active = 0; // Prevent further toggles
                    printf("Touch duration exceeded threshold. Relay forced OFF.\n");
                } else {
                    toggle_relay();
                }
            }
        } else {
            touch_active = 0; // Reset touch active flag
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

