#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define target flow rate (L/min)
double target_flow_rate = 0.0;

// Define proportional gain (Kp)
double Kp = 1.0;

// Define pulse counting variables
volatile int pulse_count = 0;

// Define file pointer for logging
FILE *log_file = NULL;

// Function prototypes
void initialize_gpio();
void set_valve_enable(int enable);
void set_valve_pwm(int duty_cycle);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate();
double calculate_proportional_control(double error);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable the valve
    set_valve_enable(0);

    // Set PWM duty cycle to 0
    set_valve_pwm(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
void initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(VALVE_PWM_PIN, 255);

    // Set valve enable high initially
    set_valve_enable(1);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        exit(1);
    }
}

// Set valve enable pin
void set_valve_enable(int enable) {
    gpioWrite(VALVE_ENABLE_PIN, enable);
}

// Set valve PWM duty cycle
void set_valve_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Flow sensor interrupt service routine
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Calculate flow rate (L/min)
double calculate_flow_rate() {
    // Calibration factor: 1 pulse per 0.01 L/min
    // Adjust this based on your flow sensor's datasheet and calibration
    double flow_rate = (double)pulse_count * 0.01; // pulses/10ms * 0.01 L/min/pulse
    pulse_count = 0; // Reset pulse count after reading
    return flow_rate;
}

// Calculate proportional control output
double calculate_proportional_control(double error) {
    return Kp * error;
}

// Log data to CSV file
void log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to file immediately
}

int main(int argc, char *argv[]) {
    // Check for target flow rate argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
        return 1;
    }

    // Parse target flow rate argument
    char *token = strtok(argv[1], "=");
    if (token != NULL && strcmp(token, "-t") == 0) {
        token = strtok(NULL, "=");
        if (token != NULL) {
            target_flow_rate = atof(token);
            if (target_flow_rate <= 0) {
                fprintf(stderr, "Error: Target flow rate must be positive.\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Invalid target flow rate argument.\n");
            return 1;
        }
    } else {
        fprintf(stderr, "Error: Invalid target flow rate argument format.\n");
        return 1;
    }

    // Initialize GPIO
    initialize_gpio();

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    double error = 0.0;
    double proportional_output = 0.0;
    int valve_position = 0;
    double current_flow_rate = 0.0;

    while (1) {
        // Calculate error
        error = target_flow_rate - calculate_flow_rate();

        // Calculate proportional control output
        proportional_output = calculate_proportional_control(error);

        // Clamp proportional output to 0-255 range
        if (proportional_output < 0) proportional_output = 0;
        if (proportional_output > 255) proportional_output = 255;

        // Set valve position
        valve_position = (int)proportional_output;
        set_valve_pwm(valve_position);

        // Log data
        log_data(current_flow_rate, valve_position);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds

        // Calculate flow rate for logging
        current_flow_rate = calculate_flow_rate();
    }

    return 0;
}

