                fprintf(stderr, "Error: Target flow rate must be positive.\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Invalid target flow rate argument.\n");
            return 1;
        }
    } else {
        fprintf(stderr, "Error: Invalid target flow rate argument format.\n");
        return 1;
    }

    // Initialize GPIO
    initialize_gpio();

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    double error = 0.0;
    double proportional_output = 0.0;
    int valve_position = 0;
    double current_flow_rate = 0.0;

    while (1) {
        // Calculate error
        error = target_flow_rate - calculate_flow_rate();

        // Calculate proportional control output
        proportional_output = calculate_proportional_control(error);

        // Clamp proportional output to 0-255 range
        if (proportional_output < 0) proportional_output = 0;
        if (proportional_output > 255) proportional_output = 255;

        // Set valve position
        valve_position = (int)proportional_output;
        set_valve_pwm(valve_position);

        // Log data
        log_data(current_flow_rate, valve_position);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds

        // Calculate flow rate for logging
        current_flow_rate = calculate_flow_rate();
    }

    return 0;
}

