    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up button callback
    gpioSetAlertFunc(BUTTON_PIN, button_callback);

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Do other tasks here, if needed
        gpioDelay(100); // Reduce CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LOCK1_PIN, 1); // Engage Lock 1
    gpioWrite(LOCK2_PIN, 1); // Engage Lock 2
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

