#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// PID parameters
#define Kp 0.5
#define Ki 0.1
#define Kd 0.2

// Target speed (RPM)
#define TARGET_SPEED 60.0

// PID sample time (ms)
#define SAMPLE_TIME 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;

pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

double integral1 = 0.0;
double previous_error1 = 0.0;

double integral2 = 0.0;
double previous_error2 = 0.0;

double duty_cycle1 = 0.0;
double duty_cycle2 = 0.0;

FILE *log_file;

// Function prototypes
void set_motor_speed(int motor, double speed);
double calculate_pid(double speed, double target_speed);
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
void *encoder_thread(void *arg);
void signal_handler(int signal);

// Structure to pass arguments to the encoder thread
typedef struct {
    int gpio_a;
    int gpio_b;
    volatile int *count;
    pthread_mutex_t *mutex;
} encoder_args_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set edge events for encoders
    gpioSetAlertFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_isr);
    gpioSetAlertFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_isr);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_DutyCycle,Motor2_RPM,Motor2_P,Motor2_I,Motor2_D,Motor2_DutyCycle,PID_Output\n");
    fflush(log_file);

    // Create encoder threads
    pthread_t encoder1_thread, encoder2_thread;
    encoder_args_t encoder1_args = {ENCODER1_A, ENCODER1_B, &encoder1_count, &encoder1_mutex};
    encoder_args_t encoder2_args = {ENCODER2_A, ENCODER2_B, &encoder2_count, &encoder2_mutex};

    if (pthread_create(&encoder1_thread, NULL, encoder_thread, &encoder1_args) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&encoder2_thread, NULL, encoder_thread, &encoder2_args) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate motor speeds
        double speed1 = (double)encoder1_count / (SAMPLE_TIME / 60000.0); // Convert counts to RPM
        double speed2 = (double)encoder2_count / (SAMPLE_TIME / 60000.0);

        // Calculate PID outputs
        double pid_output1 = calculate_pid(speed1, TARGET_SPEED);
        double pid_output2 = calculate_pid(speed2, TARGET_SPEED);

        // Limit PID output to 0-1000
        if (pid_output1 < 0) pid_output1 = 0;
        if (pid_output1 > 1000) pid_output1 = 1000;
        if (pid_output2 < 0) pid_output2 = 0;
        if (pid_output2 > 1000) pid_output2 = 1000;

        // Set motor speeds based on PID output
        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp,
                speed1,
                Kp,
                Ki,
                Kd,
                pid_output1,
                speed2,
                Kp,
                Ki,
                Kd,
                pid_output2,
                pid_output1);
        fflush(log_file);

        // Sleep for sample time
        gpioDelay(SAMPLE_TIME * 1000); // Convert ms to us
    }

    return 0;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, double speed) {
    int duty_cycle;

    if (motor == 1) {
        duty_cycle = (int)speed;
    } else {
        duty_cycle = (int)(speed * 2); // Scale for Motor 2
    }

    if (duty_cycle > 1000) duty_cycle = 1000;
    if (duty_cycle < 0) duty_cycle = 0;

    if (motor == 1) {
        if (duty_cycle > 500) {
            gpioWrite(MOTOR1_IN1, 1);
            gpioWrite(MOTOR1_IN2, 0);
        } else {
            gpioWrite(MOTOR1_IN1, 0);
            gpioWrite(MOTOR1_IN2, 1);
        }
        gpioPWM(MOTOR1_ENA, duty_cycle);
    } else {
        if (duty_cycle > 500) {
            gpioWrite(MOTOR2_IN3, 1);
            gpioWrite(MOTOR2_IN4, 0);
        } else {
            gpioWrite(MOTOR2_IN3, 0);
            gpioWrite(MOTOR2_IN4, 1);
        }
        gpioPWM(MOTOR2_ENB, duty_cycle);
    }
}

// Function to calculate PID output
double calculate_pid(double speed, double target_speed) {
    double error = target_speed - speed;
    double p = Kp * error;
    integral1 += Ki * error * (SAMPLE_TIME / 1000.0);
    double i = integral1;
    double d = Kd * (error - previous_error1) / (SAMPLE_TIME / 1000.0);
    double output = p + i + d;

    previous_error1 = error;

    return output;
}

// Encoder 1 ISR
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_level = 0;
    static uint32_t last_tick = 0;

    if (gpio == ENCODER1_B) {
        uint32_t diff = tick - last_tick;
        if (diff > 0) {
            if (level == 1) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
        }
        last_tick = tick;
        last_level = level;
    }
}

// Encoder 2 ISR
void encoder2_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_level = 0;
    static uint32_t last_tick = 0;

    if (gpio == ENCODER2_B) {
        uint32_t diff = tick - last_tick;
        if (diff > 0) {
            if (level == 1) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count++;
                pthread_mutex_unlock(&encoder2_mutex);
            } else {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count--;
                pthread_mutex_unlock(&encoder2_mutex);
            }
        }
        last_tick = tick;
        last_level = level;
    }
}

// Encoder thread function
void *encoder_thread(void *arg) {
    encoder_args_t *args = (encoder_args_t *)arg;
    int gpio_a = args->gpio_a;
    int gpio_b = args->gpio_b;
    volatile int *count = args->count;
    pthread_mutex_t *mutex = args->mutex;

    while (1) {
        gpioSetAlertFuncEx(gpio_a, EITHER_EDGE, 0, encoder_a_isr);
        gpioSetAlertFuncEx(gpio_b, EITHER_EDGE, 0, encoder_b_isr);
        gpioDelay(10000); // Sleep for 10ms
        gpioSetAlertFuncEx(gpio_a, EITHER_EDGE, 0, NULL);
        gpioSetAlertFuncEx(gpio_b, EITHER_EDGE, 0, NULL);
    }

    return NULL;
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    // This ISR is not used in the main loop, but kept for completeness.
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    // This ISR is not used in the main loop, but kept for completeness.
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop motors
    gpioWrite(MOTOR1_ENA, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Close chip
    gpioTerminate();

    // Close log file
    fclose(log_file);

    exit(0);
}

