#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(uint16_t touch_status);
void log_relay_state(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        terminate = 1;
    }
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure filtering parameters
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x10) < 0) { //MHDR = 0x01
        fprintf(stderr, "Error: Failed to write MHDT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { //NHDT = 0x01
        fprintf(stderr, "Error: Failed to write NHDT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) { //NFDR = 0x01
        fprintf(stderr, "Error: Failed to write NFDR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x00) < 0) { //NDLR = 0x00
        fprintf(stderr, "Error: Failed to write NDLR\n");
        return -1;
    }

    // Set touch and release thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write ELEPROX_EN\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay
void control_relay(uint16_t touch_status) {
    int relay_state = 0;
    if (touch_status > 0) {
        relay_state = 1; // At least one electrode touched
    }
    gpioWrite(RELAY_GPIO, relay_state);
}

// Function to log relay state with timestamp
void log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay state: %d\n", timestamp, relay_state);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // Initial relay state

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            control_relay(touch_status);
            if (gpioRead(RELAY_GPIO) != relay_state) {
                relay_state = gpioRead(RELAY_GPIO);
                log_relay_state(relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }
        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW
    fclose(log_file);
    gpioTerminate();

    return 0;
}

