#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the solenoid valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Set GPIO HIGH to activate the relay (valve OPEN)
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio, 0); // Set GPIO LOW to deactivate the relay (valve CLOSED)
}

// Function to log an event to the log file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a"); // Open the log file in append mode
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Ensure both valves are initially closed (relays are off)
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        activate_valve(VALVE1_GPIO, 500);
        log_event("Valve 1 activated for 500ms");
        gpioDelay(5000000); // Pause for 5 seconds (5000000 microseconds)

        // Activate Valve 2
        activate_valve(VALVE2_GPIO, 1000);
        log_event("Valve 2 activated for 1000ms");
