// MPR121 I2C address
#define MPR121_ADDR 0x5A

// Register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x60
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ECR 0x5E
#define MPR121_MODE 0x80

// GPIO pin for relay control
#define RELAY_PIN 17

// I2C handle
int i2c_handle;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_toggle(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_MODE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 40) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 20) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00) < 0) return -1;

    // Set electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, MPR121_MODE, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status() {
    int touch_status_low, touch_status_high;

    touch_status_low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_low < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte\n");
        return -1;
    }

    touch_status_high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to toggle the relay
void relay_toggle(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    gpioDelay(50000);       // 50ms
    gpioWrite(gpio_pin, 0); // Set GPIO low
    gpioDelay(50000);       // 50ms
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
        } else {
            if (touch_status > 0) {
                relay_toggle(RELAY_PIN);
                printf("Relay toggled\n");
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

