#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_motion_time = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *event_type);
void unlock_door();
void rate_limit();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Cleanup GPIO pins and terminate pigpio
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Log an event to the door_events.log file
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s.%03ld: %s\n", buf, ts.tv_nsec / 1000000, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Unlock the door strike for a specified duration
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay in microseconds
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door Unlocked");
}

// Implement rate limiting
void rate_limit() {
    log_event("Rate Limited");
    gpioDelay(RATE_LIMIT_MS * 1000); // Delay in microseconds
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = gpioRead(PIR_SENSOR_PIN);

        if (motion_detected == 1) {
            unsigned long current_time = gpioTick();

            if (current_time - last_motion_time > RATE_LIMIT_MS * 1000) {
                unlock_door();
                last_motion_time = current_time;
            } else {
                rate_limit();
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    cleanup_gpio();
    return 0;
}

