#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the number of steps in a pattern
#define NUM_STEPS 15

// Structure to represent a step in the haptic pattern
typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} Step;

// Global flag to signal shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    shutdown_flag = 1;
    printf("\nCaught signal, shutting down gracefully...\n");
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    return 0;
}

// Function to generate a random haptic pattern
void generate_pattern(Step *pattern) {
    for (int i = 0; i < NUM_STEPS; i++) {
        pattern[i].motor1_duty_cycle = rand() % 256;
        pattern[i].motor2_duty_cycle = rand() % 256;
        pattern[i].duration_ms = rand() % 151 + 50; // Random duration between 50ms and 200ms
    }
}

// Function to play the haptic pattern
void play_pattern(Step *pattern) {
    for (int i = 0; i < NUM_STEPS; i++) {
        gpioPWM(MOTOR1_PIN, pattern[i].motor1_duty_cycle);
        gpioPWM(MOTOR2_PIN, pattern[i].motor2_duty_cycle);
        gpioDelay(pattern[i].duration_ms * 1000); // Convert ms to microseconds
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown_flag) {
        Step pattern[NUM_STEPS];
        generate_pattern(pattern);
        play_pattern(pattern);
    }

    // Stop motors and terminate pigpio
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

