#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0

// Weight threshold in kg
#define WEIGHT_THRESHOLD 10.0

// Number of calibration readings
#define NUM_CALIBRATION_READINGS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Calibration data structure
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
long read_hx711();
double calibrate_hx711();
double calculate_weight(long raw_value, double scale_factor, double offset);
void control_solenoid(double weight);
void log_data(long raw_value, double weight);
void write_calibration_data(double scale_factor, double offset);
void read_calibration_data(CalibrationData *data);
void signal_handler(int signal);

int main() {
    CalibrationData calibration_data;
    double scale_factor, offset;

    // Read calibration data from file
    read_calibration_data(&calibration_data);

    // If calibration file is missing or invalid, use default values
    if (calibration_file == NULL || (calibration_data.scale_factor == 0.0 && calibration_data.offset == 0.0)) {
        calibration_data.scale_factor = DEFAULT_SCALE_FACTOR;
        calibration_data.offset = DEFAULT_OFFSET;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Calibrate HX711 if calibration data is not available or outdated
    if (calibration_file == NULL || (calibration_data.scale_factor == 0.0 && calibration_data.offset == 0.0)) {
        printf("Performing one-time startup calibration...\n");
        calibration_data.offset = calibrate_hx711();
        printf("Calibration complete. Offset: %lf\n", calibration_data.offset);
        write_calibration_data(calibration_data.scale_factor, calibration_data.offset);
    }

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        long raw_value = read_hx711();
        if (raw_value != 0) {
            double weight = calculate_weight(raw_value, calibration_data.scale_factor, calibration_data.offset);
            control_solenoid(weight);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Timeout reading HX711.\n");
        }
        gpioDelay(500); // Read every 500ms
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Read raw data from HX711
long read_hx711() {
    long value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Wait for data line to go low (start of transmission)
    int timeout = 1000; // Timeout after 1000 attempts
    while (gpioRead(HX711_DATA_PIN) && timeout > 0) {
        gpioDelay(1); // Wait 1 us
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "HX711 timeout waiting for data.\n");
        return 0; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high for 1 us
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low for 1 us
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Calibrate HX711 to determine offset
double calibrate_hx711() {
    long sum = 0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        sum += read_hx711();
        gpioDelay(10); // Small delay between readings
    }
    return (double)sum / NUM_CALIBRATION_READINGS;
}

// Calculate weight from raw value
double calculate_weight(long raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Control solenoid based on weight
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Log data to file
void log_data(long raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %ld, Weight: %.2lf kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Write calibration data to file
void write_calibration_data(double scale_factor, double offset) {
    if (calibration_file != NULL) {
        fprintf(calibration_file, "%lf %lf\n", scale_factor, offset);
        fflush(calibration_file);
    }
}

// Read calibration data from file
void read_calibration_data(CalibrationData *data) {
    if (calibration_file != NULL) {
        if (fscanf(calibration_file, "%lf %lf", &data->scale_factor, &data->offset) != 2) {
            // File is empty or invalid, use defaults
            data->scale_factor = DEFAULT_SCALE_FACTOR;
            data->offset = DEFAULT_OFFSET;
        }
    } else {
        // File doesn't exist, use defaults
        data->scale_factor = DEFAULT_SCALE_FACTOR;
        data->offset = DEFAULT_OFFSET;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

