#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4  // BCM GPIO 4
#define MOTOR_IN1_PIN 17   // BCM GPIO 17
#define MOTOR_IN2_PIN 18   // BCM GPIO 18
#define MOTOR_PWM_PIN 27   // BCM GPIO 27

// Define motor control parameters
#define MOTOR_DURATION_MS 5000
#define MOTOR_FREQUENCY_HZ 1000
#define MOTOR_DUTY_CYCLE 150 // Out of 0-255

// Define debouncing parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int readRainSensor(int pin);
int debounceRainSensor(int pin, int numReadings, int delayMs);
void controlMotor(int in1Pin, int in2Pin, int pwmPin, int durationMs, int frequencyHz, int dutyCycle);
void logEvent(const char *message);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        logEvent("Received shutdown signal. Stopping motor and exiting.");
        // Stop the motor
        digitalWrite(MOTOR_IN1_PIN, LOW);
        digitalWrite(MOTOR_IN2_PIN, LOW);
        pwmWrite(MOTOR_PWM_PIN, 0);

        // Release GPIO resources
        wiringPiSetupGpio(); // Reset GPIO pins to input mode

        // Close syslog
        closelog();

        exit(0);
    }
}

// Function to read the rain sensor
int readRainSensor(int pin) {
    int value = digitalRead(pin);
    return value;
}

// Function to debounce the rain sensor
int debounceRainSensor(int pin, int numReadings, int delayMs) {
    int lowCount = 0;
    for (int i = 0; i < numReadings; i++) {
        int value = readRainSensor(pin);
        if (value == LOW) {
            lowCount++;
        }
        delay(delayMs);
    }
    return (lowCount >= numReadings / 2) ? LOW : HIGH; // Majority vote
}

// Function to control the motor
void controlMotor(int in1Pin, int in2Pin, int pwmPin, int durationMs, int frequencyHz, int dutyCycle) {
    // Set PWM frequency
    int range = 1000000 / frequencyHz; // Calculate PWM range
    pwmSetRange(range);
    pwmSetClock(192); // Adjust clock for desired frequency

    // Start PWM
    pwmWrite(pwmPin, dutyCycle);

    // Set motor direction
    digitalWrite(in1Pin, HIGH);
    digitalWrite(in2Pin, LOW);

    // Wait for the specified duration
    delay(durationMs);

    // Stop PWM
    pwmWrite(pwmPin, 0);

    // Stop the motor
    digitalWrite(in1Pin, LOW);
    digitalWrite(in2Pin, LOW);
}

// Function to log events to syslog
void logEvent(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main() {
    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        logEvent("Failed to initialize wiringPi. Exiting.");
        closelog();
        return 1;
    }

    // Set GPIO pins as output or input
    pinMode(RAIN_SENSOR_PIN, INPUT);
    pinMode(MOTOR_IN1_PIN, OUTPUT);
    pinMode(MOTOR_IN2_PIN, OUTPUT);
    pinMode(MOTOR_PWM_PIN, PWM_OUTPUT);

    logEvent("Window control program started.");

    while (program_running) {
        // Check for rain
        int rainDetected = debounceRainSensor(RAIN_SENSOR_PIN, DEBOUNCE_READINGS, DEBOUNCE_DELAY_MS);

        if (rainDetected == LOW) {
            logEvent("Rain detected!");
            logEvent("Closing window...");

            // Control the motor to close the window
            controlMotor(MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN, MOTOR_DURATION_MS, MOTOR_FREQUENCY_HZ, MOTOR_DUTY_CYCLE);

            // Wait before checking again
            delay(60000); // Wait 60 seconds
            logEvent("Waiting 60 seconds before next check...");
        } else {
            // Check for rain only once every 60 seconds
            delay(60000);
        }
    }

    // This point is reached only when program_running is set to 0 by the signal handler
    logEvent("Program exiting.");

    // Stop the motor
    digitalWrite(MOTOR_IN1_PIN, LOW);
    digitalWrite(MOTOR_IN2_PIN, LOW);
    pwmWrite(MOTOR_PWM_PIN, 0);

    // Release GPIO resources
    wiringPiSetupGpio(); // Reset GPIO pins to input mode

    // Close syslog
    closelog();

    return 0;
}

