        if (rainDetected == LOW) {
            logEvent("Rain detected!");
            logEvent("Closing window...");

            // Control the motor to close the window
            controlMotor(MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN, MOTOR_DURATION_MS, MOTOR_FREQUENCY_HZ, MOTOR_DUTY_CYCLE);

            // Wait before checking again
            delay(60000); // Wait 60 seconds
            logEvent("Waiting 60 seconds before next check...");
        } else {
            // Check for rain only once every 60 seconds
            delay(60000);
        }
    }

    // This point is reached only when program_running is set to 0 by the signal handler
    logEvent("Program exiting.");

    // Stop the motor
    digitalWrite(MOTOR_IN1_PIN, LOW);
    digitalWrite(MOTOR_IN2_PIN, LOW);
    pwmWrite(MOTOR_PWM_PIN, 0);

    // Release GPIO resources
    wiringPiSetupGpio(); // Reset GPIO pins to input mode

    // Close syslog
    closelog();

    return 0;
}

