#define WEIGHT_THRESHOLD 100.0 // grams
#define LOCK_DURATION 5 // seconds

// Define calibration factor (adjust this based on your setup)
#define CALIBRATION_FACTOR 100.0 // Example: raw reading per gram

// Global variables
