#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define TIMEOUT_MS 100
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION_S 5

// Global variables
static volatile int running = 1;
static float calibration_factor = 0.0;

// Function prototypes
int read_hx711();
float calibrate_hx711(float known_weight);
float calculate_weight(int raw_value, float calibration_factor);
void engage_solenoid();
void log_event(float weight);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Unlocking solenoid and exiting.\n");
        gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
        gpioTerminate(); // Terminate pigpio
        running = 0;
        exit(0);
    }
}

// Function to read raw data from HX711
int read_hx711() {
    int32_t value = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // 1 us delay
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calibrate HX711
float calibrate_hx711(float known_weight) {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 timeout during calibration.\n");
        return -1.0; // Indicate calibration error
    }
    calibration_factor = (float)raw_value / known_weight;
    printf("Calibration factor: %f\n", calibration_factor);
    return calibration_factor;
}

// Function to calculate weight
float calculate_weight(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Function to engage solenoid
void engage_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set solenoid pin high
    gpioDelay(SOLENOID_DURATION_S * 1000000); // Delay for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Set solenoid pin low
}

// Function to log event
void log_event(float weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", s, weight);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    // Calibration
    float known_weight;
    printf("Enter the known weight in kg: ");
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        gpioTerminate();
        return 1;
    }

    if (calibrate_hx711(known_weight) == -1.0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight = calculate_weight(raw_value, calibration_factor);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded. Engaging solenoid.\n");
                engage_solenoid();
                log_event(weight);
            }
        } else {
            fprintf(stderr, "Error: Failed to read from HX711.\n");
        }

        gpioDelay(100000); // Delay 0.1 seconds
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit
    gpioTerminate(); // Terminate pigpio

    return 0;
}

