#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading config file: empty or malformed line\n");
        return -1;
    }

    char *name = strtok(line, "=");
    char *value = strtok(NULL, "\n");

    if (name == NULL || value == NULL) {
        fclose(fp);
        fprintf(stderr, "Error parsing config file: invalid format\n");
        return -1;
    }

    if (strcmp(name, "duration") != 0) {
        fclose(fp);
        fprintf(stderr, "Error parsing config file: invalid name '%s'\n", name);
        return -1;
    }

    char *endptr;
    long dur = strtol(value, &endptr, 10);

    if (*endptr != '\0' || dur < MIN_DURATION || dur > MAX_DURATION) {
        fclose(fp);
        fprintf(stderr, "Error parsing config file: duration out of range\n");
        return -1;
    }

    *duration = (int)dur;
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(VALVE_GPIO, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duration;
    if (read_duration(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    while (!terminate) {
        gpioWrite(VALVE_GPIO, 1); // Activate valve (active low)
        printf("Valve ON\n");
        sleep(duration);
        gpioWrite(VALVE_GPIO, 0); // Deactivate valve (active low)
        printf("Valve OFF\n");
        sleep(60); // Wait before next watering cycle
    }

    gpioWrite(VALVE_GPIO, 0); // Ensure valve is off on exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

