    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        program_running = 0;
        set_motor_speed(LEFT_MOTOR_PIN, 0);
        set_motor_speed(RIGHT_MOTOR_PIN, 0);
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

