    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Line following robot started. Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Determine motor speeds based on sensor values
        int left_motor_speed = BASE_SPEED;
        int right_motor_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            // Drive straight
        } else if (left_sensor == 0) {
            // Turn right
            left_motor_speed = TURN_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            right_motor_speed = TURN_SPEED;
        } else {
            // Stop
            left_motor_speed = 0;
            right_motor_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(LEFT_MOTOR_PIN, left_motor_speed);
        set_motor_speed(RIGHT_MOTOR_PIN, right_motor_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(LEFT_MOTOR_PIN, 0);
    set_motor_speed(RIGHT_MOTOR_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

