// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read illuminance from BH1750 sensor
float read_bh1750(int i2c_handle) {
    unsigned char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

