#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pulse_width);
int read_button(int gpio_pin);
void lock_door();
void unlock_door();
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_button_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Check for button presses
        if (lock_button_pressed) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
        }
        if (unlock_button_pressed) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1ms delay
    }

    printf("Door lock control program exiting.\n");
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d). Must be between %d and %d.\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return;
    }

    gpioServo(SERVO_PIN, pulse_width);
    printf("Servo pulse width set to %d us\n", pulse_width);
}

// Function to read the state of a button
int read_button(int gpio_pin) {
    return (gpioRead(gpio_pin) == 0); // Active low
}

// Function to lock the door
void lock_door() {
    set_servo_pulse_width(SERVO_MIN_PULSE_WIDTH); // 0 degrees (locked)
    printf("Door locked\n");
}

// Function to unlock the door
void unlock_door() {
    set_servo_pulse_width(SERVO_MAX_PULSE_WIDTH); // 180 degrees (unlocked)
    printf("Door unlocked\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0; // Set flag to exit main loop

    // Set servo to a safe position (locked)
    set_servo_pulse_width(SERVO_MIN_PULSE_WIDTH);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

