#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    return 0;
}

// Function to activate a motor for a specified duration
void activate_motor(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) { // Turn motor ON
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
    }
    gpioDelay(duration_ms * 1000); // Delay for the specified duration
    if (gpioWrite(gpio_pin, 0) != 0) { // Turn motor OFF
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
    }
}

// Function to deactivate the motors
void deactivate_motors() {
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
}

// Function to cleanup the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate motor 1
        activate_motor(MOTOR1_GPIO, MOTOR1_DURATION);

        // Activate motor 2
        activate_motor(MOTOR2_GPIO, MOTOR2_DURATION);
    }

    // Deactivate the motors before exiting
    deactivate_motors();

    // Cleanup the pigpio library
    cleanup_gpio();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

