#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <zmq.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ port
#define ZMQ_PORT 5555

// Define alarm duration (seconds)
#define ALARM_DURATION 1

// Global variables for cleanup
static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
        return -1;
    }
    zmq_bind(publisher, "tcp://*:%d", ZMQ_PORT);

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        return -1;
    }
    zmq_connect(subscriber, "tcp://localhost:%d", ZMQ_PORT);
    zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));

    return 0;
}

// Function to publish sound alert
void publish_sound_alert() {
    char message[100];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    snprintf(message, sizeof(message), "%s SOUND_DETECTED", timestamp);
    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));
    zmq_msg_send(&zmq_message, publisher, 0);
    zmq_msg_close(&zmq_message);
}

// Function to activate the alarm LED
void activate_alarm_led() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(ALARM_DURATION * 1000000); // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

// Function to subscribe to sound alerts
void subscribe_to_sound_alerts() {
    while (running) {
        zmq_msg_t zmq_message;
        zmq_msg_init(&zmq_message);
        int rc = zmq_msg_recv(&zmq_message, subscriber, 0);

        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(errno));
            zmq_msg_close(&zmq_message);
            continue;
        }

        char *message_data = (char *)zmq_msg_data(&zmq_message);
        int message_size = zmq_msg_size(&zmq_message);
        char message[message_size + 1];
        strncpy(message, message_data, message_size);
        message[message_size] = '\0';

        printf("Received: %s\n", message);
        activate_alarm_led();
        zmq_msg_close(&zmq_message);
    }
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq() != 0) {
        gpioTerminate();
        return 1;
    }

    // Determine mode and execute
    if (argc > 1) {
        if (strcmp(argv[1], "sound_sensor") == 0) {
            printf("Sound sensor mode\n");
            while (running) {
                if (gpioRead(SOUND_SENSOR_PIN) == 0) { // Sound detected (LOW signal)
                    publish_sound_alert();
                    gpioDelay(100000); // Debounce delay (100ms)
                }
                gpioDelay(10000); // Polling interval (10ms)
            }
        } else if (strcmp(argv[1], "alarm_node") == 0) {
            printf("Alarm node mode\n");
            subscribe_to_sound_alerts();
        } else {
            fprintf(stderr, "Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
            gpioTerminate();
            zmq_ctx_destroy(context);
            return 1;
        }
    } else {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        gpioTerminate();
        zmq_ctx_destroy(context);
        return 1;
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    zmq_ctx_destroy(context);
    zmq_close(publisher);
    zmq_close(subscriber);

    return 0;
}

