    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        return -1;
    }
    zmq_connect(subscriber, "tcp://localhost:%d", ZMQ_PORT);
    zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));

    return 0;
}

// Function to publish sound alert
void publish_sound_alert() {
    char message[100];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    snprintf(message, sizeof(message), "%s SOUND_DETECTED", timestamp);
    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));
    zmq_msg_send(&zmq_message, publisher, 0);
    zmq_msg_close(&zmq_message);
}

// Function to activate the alarm LED
void activate_alarm_led() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(ALARM_DURATION * 1000000); // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

// Function to subscribe to sound alerts
void subscribe_to_sound_alerts() {
    while (running) {
        zmq_msg_t zmq_message;
        zmq_msg_init(&zmq_message);
        int rc = zmq_msg_recv(&zmq_message, subscriber, 0);

        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(errno));
            zmq_msg_close(&zmq_message);
            continue;
        }

        char *message_data = (char *)zmq_msg_data(&zmq_message);
        int message_size = zmq_msg_size(&zmq_message);
        char message[message_size + 1];
        strncpy(message, message_data, message_size);
        message[message_size] = '\0';

        printf("Received: %s\n", message);
        activate_alarm_led();
        zmq_msg_close(&zmq_message);
    }
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
