        return 1;
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    zmq_ctx_destroy(context);
    zmq_close(publisher);
    zmq_close(subscriber);

    return 0;
}

