#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Define GPIO pins for IR receivers
#define IR_PIN_1 17
#define IR_PIN_2 18
#define IR_PIN_3 19

// NEC timing constants (in microseconds)
#define NEC_MARK_SPACE_HEADER 9000
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_0 560
#define NEC_BIT_SPACE_1 1690

// Maximum number of pulses to store
#define MAX_PULSES 100

// Structure to store pulse timings
typedef struct {
    uint32_t timestamps[MAX_PULSES];
    int count;
} pulse_buffer_t;

// Structure to hold NEC frame data
typedef struct {
    uint32_t address;
    uint32_t command;
    uint8_t checksum;
} nec_frame_t;

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
void ir_callback(int gpio, int level, uint32_t tick, void *userdata);
int decode_nec(pulse_buffer_t *buffer, nec_frame_t *frame);
int validate_checksum(nec_frame_t *frame);
int publish_mqtt(const char *topic, const char *payload);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO pins
int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(IR_PIN_1, PI_INPUT);
    gpioSetMode(IR_PIN_2, PI_INPUT);
    gpioSetMode(IR_PIN_3, PI_INPUT);

    gpioSetAlertFuncEx(IR_PIN_1, ir_callback, (void*)(intptr_t)IR_PIN_1);
    gpioSetAlertFuncEx(IR_PIN_2, ir_callback, (void*)(intptr_t)IR_PIN_2);
    gpioSetAlertFuncEx(IR_PIN_3, ir_callback, (void*)(intptr_t)IR_PIN_3);

    return 0;
}

// IR receiver callback function
void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    static uint32_t last_tick[3] = {0, 0, 0};
    static int pin_index = 0;
    static pulse_buffer_t pulse_buffer[3];

    if (level == 0) { // Falling edge
        if (pulse_buffer[pin_index].count < MAX_PULSES) {
            pulse_buffer[pin_index].timestamps[pulse_buffer[pin_index].count++] = tick;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow for pin %d", gpio);
            pulse_buffer[pin_index].count = 0; // Reset buffer
        }
    } else if (level == PI_TIMEOUT) {
        // Timeout occurred, process the pulse buffer
        nec_frame_t frame;
        if (decode_nec(&pulse_buffer[pin_index], &frame) == 0) {
            char payload[256];
            snprintf(payload, sizeof(payload), "{\"address\":0x%08X, \"command\":0x%08X}", frame.address, frame.command);
            publish_mqtt("ir/decoded", payload);
            syslog(LOG_INFO, "Decoded NEC frame: Address=0x%08X, Command=0x%08X", frame.address, frame.command);
        } else {
            syslog(LOG_WARNING, "Failed to decode NEC frame for pin %d", gpio);
        }
        pulse_buffer[pin_index].count = 0; // Reset buffer

        // Rotate pin index
        pin_index = (pin_index + 1) % 3;
        last_tick[pin_index] = tick; // Update last tick
    }
}

// Decode NEC frame from pulse buffer
int decode_nec(pulse_buffer_t *buffer, nec_frame_t *frame) {
    if (buffer->count < 68) { // NEC frame has 68 pulses (header + 32 data bits + checksum)
        syslog(LOG_ERR, "Insufficient pulses in buffer");
        return -1;
    }

    // Check for valid header
    if (buffer->timestamps[0] < NEC_MARK_SPACE_HEADER - 200 || buffer->timestamps[0] > NEC_MARK_SPACE_HEADER + 200 ||
        buffer->timestamps[1] < NEC_MARK_SPACE_HEADER - 200 || buffer->timestamps[1] > NEC_MARK_SPACE_HEADER + 200) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    // Decode address and command
    frame->address = 0;
    frame->command = 0;
    frame->checksum = 0;

    for (int i = 0; i < 32; i++) {
        if (buffer->timestamps[2 + (i * 2)] < NEC_BIT_MARK - 100 || buffer->timestamps[2 + (i * 2)] > NEC_BIT_MARK + 100) {
            syslog(LOG_ERR, "Invalid bit mark");
            return -1;
        }

        if (buffer->timestamps[3 + (i * 2)] > NEC_BIT_SPACE_1 - 200) {
            frame->address |= (1UL << i);
        } else if (buffer->timestamps[3 + (i * 2)] < NEC_BIT_SPACE_0 + 200) {
            frame->command |= (1UL << i);
        } else {
            syslog(LOG_ERR, "Invalid bit space");
            return -1;
        }
    }

    // Decode checksum
    frame->checksum = 0;
    for (int i = 0; i < 8; i++) {
        if (buffer->timestamps[50 + (i * 2)] < NEC_BIT_MARK - 100 || buffer->timestamps[50 + (i * 2)] > NEC_BIT_MARK + 100) {
            syslog(LOG_ERR, "Invalid checksum bit mark");
            return -1;
        }
        if (buffer->timestamps[51 + (i * 2)] > NEC_BIT_SPACE_1 - 200) {
            frame->checksum |= (1UL << i);
        } else if (buffer->timestamps[51 + (i * 2)] < NEC_BIT_SPACE_0 + 200) {
            frame->checksum &= ~(1UL << i);
        } else {
            syslog(LOG_ERR, "Invalid checksum bit space");
            return -1;
        }
    }

    // Validate checksum
    if (!validate_checksum(frame)) {
        syslog(LOG_ERR, "Checksum validation failed");
        return -1;
    }

    return 0;
}

// Validate checksum
int validate_checksum(nec_frame_t *frame) {
    uint8_t address_inverted = ~frame->address & 0xFF;
    uint8_t command_inverted = ~frame->command & 0xFF;
    uint8_t checksum_calculated = 0;

    checksum_calculated = (address_inverted >> 0) ^ (address_inverted >> 1) ^ (address_inverted >> 2) ^ (address_inverted >> 3);
    checksum_calculated ^= (address_inverted >> 4) ^ (address_inverted >> 5) ^ (address_inverted >> 6) ^ (address_inverted >> 7);
    checksum_calculated ^= (command_inverted >> 0) ^ (command_inverted >> 1) ^ (command_inverted >> 2) ^ (command_inverted >> 3);
    checksum_calculated ^= (command_inverted >> 4) ^ (command_inverted >> 5) ^ (command_inverted >> 6) ^ (command_inverted >> 7);

    return (checksum_calculated == frame->checksum);
}

// Publish MQTT message
int publish_mqtt(const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

