#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

int i2c_handles[4];
int terminate = 0;

void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

float read_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error setting mode for I2C handle %d\n", i2c_handle);
        return -1.0;
    }
    gpioDelay(180000); // 180ms

    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading data from I2C handle %d\n", i2c_handle);
        return -1.0;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device %d at address 0x%02x\n", i, BH1750_ADDR + i);
            // Attempt to continue with other sensors
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        char data[256];
        data[0] = '\0'; // Initialize as an empty string

        for (int i = 0; i < 4; i++) {
            float lux = read_bh1750(i2c_handles[i]);
            if (lux != -1.0) {
                char sensor_data[50];
                snprintf(sensor_data, sizeof(sensor_data), "%d,%.2f", i + 1, lux);
                strcat(data, sensor_data);
                strcat(data, ";");
            } else {
                char sensor_data[50];
                snprintf(sensor_data, sizeof(sensor_data), "%d,NaN", i + 1);
                strcat(data, sensor_data);
                strcat(data, ";");
            }
        }

        // Remove the trailing semicolon
        data[strlen(data) - 1] = '\0';

        int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd < 0) {
            perror("socket");
            continue; // Try again next loop
        }

        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
        addr.sin_port = htons(MULTICAST_PORT);

        if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("sendto");
        }

        close(sockfd);

        sleep(1);
    }

    // Cleanup
    for (int i = 0; i < 4; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

