#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define LOG_FILE "airflow_log.txt"
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_airflow(uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read airflow data from the sensor
int read_airflow(uint16_t *raw_flow) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *raw_flow = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(100); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read airflow data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    // Mask the 14-bit flow value (bits 2-15)
    raw_flow = raw_flow & 0x3FFF;

    // Convert to SLPM (0.005 SLPM/LSB)
    float slpm = (float)raw_flow * 0.005;
    return slpm;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.4f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        if (read_airflow(&raw_flow) == 0) {
            float flow_rate = convert_to_slpm(raw_flow);
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0); // Sleep for 1 second
    }

    // Cleanup
    printf("Closing I2C bus and log file...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

