#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_ID 0x00
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x76
#define AS7341_F1DATAH 0x96

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the AS7341 sensor
int init_as7341() {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != 0x40) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure SMUX (no external driver)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00) < 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    return 0;
}

// Function to read spectral data from the AS7341 sensor
int read_spectral_data(uint16_t *data) {
    char buf[20];
    if (i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, buf, 20) < 0) {
        fprintf(stderr, "Error reading spectral data\n");
        return -1;
    }

    data[0] = (buf[1] << 8) | buf[0];
    data[1] = (buf[3] << 8) | buf[2];
    data[2] = (buf[5] << 8) | buf[4];
    data[3] = (buf[7] << 8) | buf[6];
    data[4] = (buf[9] << 8) | buf[8];
    data[5] = (buf[11] << 8) | buf[10];
    data[6] = (buf[13] << 8) | buf[12];
    data[7] = (buf[15] << 8) | buf[14];
    data[8] = (buf[17] << 8) | buf[16];
    data[9] = (buf[19] << 8) | buf[18];

    return 0;
}

// Function to calculate a simplified lux approximation
float calculate_lux(uint16_t *data) {
    // Simple lux approximation (replace with a more accurate formula if needed)
    return (float)(data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7] + data[8] + data[9]) / 10.0;
}

// Function to log data to a CSV file
int log_data(uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f", timestamp, lux);
    for (int i = 0; i < 10; i++) {
        fprintf(log_file, ",%u", data[i]);
    }
    fprintf(log_file, "\n");
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_as7341() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t spectral_data[10];
    float lux;

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux approximation
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(spectral_data, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

