#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;

// Function prototypes
int initialize_i2c(int i2c_address);
sensor_data_t read_sensor_data(int i2c_handle);
void log_data(FILE *fp, sensor_data_t data);
void log_error(FILE *fp, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c(int i2c_address) {
    int handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data from the D7S sensor
sensor_data_t read_sensor_data(int i2c_handle) {
    sensor_data_t data;
    char buf[6];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, 0x2A, buf, 6); // Read 6 bytes from register 0x2A
        if (result == 6) {
            // Combine high and low bytes for each axis
            data.x_g = (float)((short)((buf[1] << 8) | buf[0])) / 1000.0f; // Assuming sensitivity of 1000 counts/g
            data.y_g = (float)((short)((buf[3] << 8) | buf[2])) / 1000.0f;
            data.z_g = (float)((short)((buf[5] << 8) | buf[4])) / 1000.0f;
            return data;
        } else {
            fprintf(error_file, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            fflush(error_file);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }

    // If all retries failed, return default values and log an error
    data.x_g = data.y_g = data.z_g = 0.0f;
    log_error(error_file, "Failed to read sensor data after multiple retries.");
    return data;
}

// Function to log data to the CSV file
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
