#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_handle;
int udp_socket;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct sockaddr_in addr;
    char buffer[2];
    float lux;
    char lux_str[32];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error configuring BH1750: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Set TTL for multicast
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read light level
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
            fprintf(stderr, "Error reading light level: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        // Convert to lux
        unsigned int raw_value = (buffer[0] << 8) | buffer[1];
        lux = (float)raw_value / 1.2;

        // Format as string
        snprintf(lux_str, sizeof(lux_str), "%.2f", lux);

        // Send via UDP multicast
        if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

