#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B921600
#define MAGIC_WORD_SIZE 8
#define MAX_BUFFER_SIZE 2048

// Structure to hold radar data
typedef struct {
    uint32_t timestamp_sec;
    uint32_t timestamp_nsec;
    uint16_t object_index;
    float range_m;
    float velocity_mps;
} radar_data_t;

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *data_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize the UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;    // Read doesn't block
    tty.c_cc[VTIME] = 5;   // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART
int read_uart(int fd, uint8_t *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    } else if (bytes_read == 0) {
        //fprintf(stderr, "Timeout reading from UART\n"); //Commented out to reduce verbosity
        return 0;
    }
    return (int)bytes_read;
}

// Function to write data to the UART
int write_uart(int fd, const uint8_t *buffer, size_t size) {
    ssize_t bytes_written = write(fd, buffer, size);
    if (bytes_written == -1) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    return (int)bytes_written;
}

// Function to find the magic word in the buffer
int find_magic_word(const uint8_t *buffer, size_t size) {
    size_t i;
    for (i = 0; i <= size - MAGIC_WORD_SIZE; ++i) {
        if (buffer[i] == 0x02 && buffer[i + 1] == 0x01 &&
            buffer[i + 2] == 0x04 && buffer[i + 3] == 0x03 &&
            buffer[i + 4] == 0x06 && buffer[i + 5] == 0x05 &&
            buffer[i + 6] == 0x08 && buffer[i + 7] == 0x07) {
            return i;
        }
    }
    return -1;
}

// Function to parse TLV data
int parse_tlv(const uint8_t *buffer, size_t offset, size_t length, radar_data_t *data) {
    if (offset + 4 > length) {
        fprintf(stderr, "TLV header length exceeds buffer size\n");
        return -1;
    }

    uint16_t type = *((uint16_t *)(buffer + offset));
    uint16_t tlv_length = *((uint16_t *)(buffer + offset + 2));

    if (offset + 4 + tlv_length > length) {
        fprintf(stderr, "TLV length exceeds buffer size\n");
        return -1;
    }

    if (tlv_length != length - offset - 4) {
        fprintf(stderr, "TLV length mismatch\n");
        return -1;
    }

    switch (type) {
        case 1: // Detected Objects
        {
            // Assuming a simple format for detected objects:
            // Each object has range and velocity, followed by a header for the next object.
            // This is a simplified example and might need adjustments based on the actual AWR1642 data format.
            if (tlv_length >= 8) { // Ensure enough data for range and velocity
                data->range_m = *((float *)(buffer + offset + 4));
                data->velocity_mps = *((float *)(buffer + offset + 8));
                return 0; // Success
            } else {
                fprintf(stderr, "Insufficient data for detected objects TLV\n");
                return -1;
            }
        }
        default:
            fprintf(stderr, "Unknown TLV type: %u\n", type);
            return -1;
    }
}

// Function to log data to a CSV file
int log_data(FILE *file, const radar_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (fprintf(file, "%ld.%09ld,%u,%.2f,%.2f\n",
                ts.tv_sec, ts.tv_nsec, data->object_index, data->range_m, data->velocity_mps) < 0) {
        fprintf(stderr, "Error writing to data file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    // Open data file
    data_file = fopen("radar_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp_sec,timestamp_nsec,object_index,range_m,velocity_mps\n");
    }
    rewind(data_file);

    uint8_t buffer[MAX_BUFFER_SIZE];
    size_t buffer_size = 0;
    int magic_word_index = -1;

    fprintf(stderr, "Starting data acquisition...\n");

    while (program_running) {
        int bytes_read = read_uart(uart_fd, buffer + buffer_size, MAX_BUFFER_SIZE - buffer_size - 1);
        if (bytes_read > 0) {
            buffer_size += bytes_read;

            magic_word_index = find_magic_word(buffer, buffer_size);
            if (magic_word_index != -1) {
                // Magic word found, process the data
                uint8_t *data_start = buffer + magic_word_index + MAGIC_WORD_SIZE;
