                buffer_size--;
            }
        } else if (bytes_read < 0) {
            // UART read error, but continue running
            fprintf(stderr, "UART read error, continuing...\n");
        }

        // Small delay to avoid busy-waiting
        usleep(1000); // 1 ms
    }

