#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 500
#define SELECT_TIMEOUT_SEC 2
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout after 500ms (0.5 seconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0;
        }
        perror("read failed");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int parse_data(const char *data, size_t data_len, long *timestamp, float *range) {
    char *token;
    char *data_copy = strdup(data);
    if (data_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(data_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing comma)\n");
        free(data_copy);
        return -1;
    }
    *timestamp = strtol(token, NULL, 10);

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing range)\n");
        free(data_copy);
        return -1;
    }
    *range = strtof(token, NULL);

    free(data_copy);
    return 0;
}

int main() {
    char buffer[BUFFER_SIZE];
    long timestamp;
    float range;
    fd_set readfds;
    struct timeval timeout;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured successfully.\n");

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = SELECT_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        ret = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (ret == -1) {
            perror("select failed");
            break;
        } else if (ret == 0) {
            // Timeout occurred
            printf("UART read timeout.\n");
        } else {
            // Data is available
            int bytes_read = read_uart_data(uart_fd, buffer, BUFFER_SIZE);
            if (bytes_read > 0) {
                printf("Received: %s", buffer);

                if (parse_data(buffer, bytes_read, &timestamp, &range) == 0) {
                    time_t rawtime = (time_t)timestamp;
                    struct tm *timeinfo = localtime(&rawtime);
                    char timestamp_str[20];
                    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

                    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
                } else {
                    fprintf(stderr, "Error parsing data: %s\n", buffer);
                }
            }
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART closed.\n");
    }

    return EXIT_SUCCESS;
}

