#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4  // BCM GPIO 4, physical pin 7
#define MIDDLE_SENSOR_PIN 17 // BCM GPIO 17, physical pin 11
#define RIGHT_SENSOR_PIN 27 // BCM GPIO 27, physical pin 13

// Define UART port and baud rate
#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for UART handle
int uart_handle = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop(void);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close UART port if open
    if (uart_handle != -1) {
        serClose(uart_handle);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to handle emergency stop
void emergency_stop(void) {
    if (uart_handle != -1) {
        int result = serWrite(uart_handle, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n"));
        if (result < 0) {
            fprintf(stderr, "Error writing to UART: %d\n", result);
        }
    } else {
        fprintf(stderr, "UART not initialized, cannot send emergency stop message.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Initialize UART port
    uart_handle = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for 8N1
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART port: %d\n", uart_handle);
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int left_sensor_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor_value = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_sensor_value, middle_sensor_value, right_sensor_value);

        // Check for emergency stop condition
        if (left_sensor_value == 0 && middle_sensor_value == 0 && right_sensor_value == 0) {
            emergency_stop();
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

